window.__HRC_SHARD({"shard":"iimm-myanmar","builtAt":"2026-07-19T18:52:42+00:00","documents":[{"rec_id":"recf1rBRA5oLTuvjB","doc_id":"IIMM Myanmar - Official report - 07.08.2019","symbol":"A/HRC/42/66","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2019-08-07","year":2019,"bodies":["IIMM Myanmar"],"paragraphCount":63,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 07-08-2019 - Official report - A_HRC_42_66 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"reckBXvdas9z8Zrmr","doc_id":"IIMM Myanmar - Official report - 07.07.2020","symbol":"A/HRC/45/60","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2020-07-07","year":2020,"bodies":["IIMM Myanmar"],"paragraphCount":78,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - Official report - EN (5).md","extractor":"pdftotext -layout"},{"rec_id":"recsPy094rMybrP2T","doc_id":"IIMM Myanmar - Official report - 05.07.2021","symbol":"A/HRC/48/18","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2021-07-05","year":2021,"bodies":["IIMM Myanmar"],"paragraphCount":66,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 05-07-2021 - Official report - A_HRC_48_18 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recVrXMSNXCakBPmR","doc_id":"IIMM Myanmar - Official report - 12.07.2022","symbol":"A/HRC/51/4","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2022-07-12","year":2022,"bodies":["IIMM Myanmar"],"paragraphCount":69,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 12-07-2022 - Official report - A_HRC_51_4 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rectilX0jl7DQDMzZ","doc_id":"IIMM Myanmar - Official report - 30.06.2023","symbol":"A/HRC/54/19","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2023-06-30","year":2023,"bodies":["IIMM Myanmar"],"paragraphCount":71,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 30-06-2023 - Official report - A_HRC_54_19 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recKWfKgtbC3Wpj8x","doc_id":"IIMM Myanmar - Official report - 11.07.2024","symbol":"A/HRC/57/18","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2024-07-11","year":2024,"bodies":["IIMM Myanmar"],"paragraphCount":77,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 11-07-2024 - Official report - A_HRC_57_18 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recZB0W4o0x2Jd8kl","doc_id":"IIMM Myanmar - Official report - 16.06.2025","symbol":"A/HRC/59/57","title":"Situation of human rights in Myanmar — Report of the United Nations High Commissioner for Human Rights","type":"Official report","date":"2025-06-16","year":2025,"bodies":["IIMM Myanmar"],"paragraphCount":68,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 16-06-2025 - Official report - A_HRC_59_57 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recJayYM89kmPO81c","doc_id":"IIMM Myanmar - Official report - 14.07.2025","symbol":"A/HRC/60/18","title":"Report of the Independent Investigative Mechanism for Myanmar","type":"Official report","date":"2025-07-14","year":2025,"bodies":["IIMM Myanmar"],"paragraphCount":75,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/IIMM Myanmar - 14-07-2025 - Official report - A_HRC_60_18 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec6LDYqJvxyoH7to","doc_id":"IIMM Myanmar - Unofficial Annex - 29.09.2025","symbol":null,"title":"The Destruction and Dispossession of Rohingya Land and Property during the 2017 Clearance Operations","type":"Unofficial Annex","date":"2025-09-29","year":2025,"bodies":["IIMM Myanmar"],"paragraphCount":64,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/IIMM Myanmar - 29-09-2025 - Unofficial Annex - Land - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-42-66-u0000","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/42/66\nGeneral Assembly                                                           Distr.: General\n7 August 2019","unnumbered":true},{"id":"a-hrc-42-66-u0001","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":null,"seq":1,"section":null,"text":"Summary\nIn its resolution 39/2, the Human Rights Council established the Independent\nInvestigative Mechanism for Myanmar to collect, consolidate, preserve and analyse\nevidence of the most serious international crimes and violations of international law\ncommitted in Myanmar since 2011, and to prepare files in order to facilitate and expedite\nfair and independent criminal proceedings, in accordance with international law standards,\nin national, regional or international courts or tribunals that have or may in the future have\njurisdiction over these crimes, in accordance with international law. In resolution 39/2, the\nCouncil also decided that the Mechanism would, inter alia, report on its main activities on\nan annual basis to the Council as of the forty-second session. The present report is\nsubmitted to the Council pursuant to that request.\nThe General Assembly, in its resolution 73/264, welcomed the creation of the\nMechanism and called for its expeditious entry into operation and steps to secure its\neffective functioning as soon as possible.\nSince the Head of the Mechanism, Nicholas Koumjian, officially commenced his\nfunctions on 1 July 2019, he has focused on putting in place place a broad strategy and\nconcept of operations for the Mechanism with the assistance of the Secretariat, so that the\nMechanism will be operational and functional as soon as possible. In this regard, the\nMechanism has sought to learn from the experiences of international tribunals and other\ncomparable international accountability mechanisms to ensure effectiveness and efficiency.\nThe Mechanism has identified a number of initial priorities that will put in place the\ntechnical, logistical and administrative measures necessary for the effective functioning of\nthe Mechanism and the implementation of its mandate.\nThe Mechanism anticipates, however, that its substantive strategies will have to be\nflexible and in order to adjust in accordance with developments in its investigations and\nrealities on the ground.\nThe Mechanism is still at a very early stage of its operations and is fully cognizant","unnumbered":true},{"id":"a-hrc-42-66-u0002","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":null,"seq":2,"section":null,"text":"of the challenges it faces in becoming fully functional. In this regard, it emphasizes the\nimportance of cooperation with and the continued support of the international community,\nand looks forward to ongoing engagement with the Human Rights Council and the\ninternational community to that end.","unnumbered":true},{"id":"a-hrc-42-66-p0001","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"1","seq":3,"section":"I. Introduction","text":"The first report of the Independent Investigative Mechanism for Myanmar on the\nprogress of its work since the Head of the Mechanism officially commenced his functions\non 1 July 2019 is hereby submitted to the Human Rights Council."},{"id":"a-hrc-42-66-p0002","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"2","seq":4,"section":"I. Introduction","text":"In its resolution 39/2 on the situation of human rights of Rohingya Muslims and\nother minorities in Myanmar, adopted on 27 September 2018, the Human Rights Council\nestablished the Independent Investigative Mechanism for Myanmar with the mandate to\ncollect, consolidate, preserve and analyse evidence of the most serious international crimes\nand violations of international law committed in Myanmar since 2011, and to prepare files\nin order to facilitate and expedite fair and independent criminal proceedings, in accordance\nwith international law standards, in national, regional or international courts or tribunals\nthat have or may in the future have jurisdiction over these crimes, in accordance with\ninternational law."},{"id":"a-hrc-42-66-p0003","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"3","seq":5,"section":"I. Introduction","text":"The Human Rights Council also decided that the Mechanism would be able to make\nuse of the information collected by the independent international fact-finding mission,\nestablished by the Council in its resolution 34/22, and continue to collect evidence; have the\ncapacity to document and verify relevant information and evidence, including through field\nengagement and by cooperating with other entities, as appropriate; and report on its main\nactivities on an annual basis to the Human Rights Council as of its forty-second session and\nto the General Assembly as of its seventy-fourth session."},{"id":"a-hrc-42-66-p0004","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"4","seq":6,"section":"I. Introduction","text":"In its resolution 73/264, the General Assembly welcomed the creation of the\nMechanism and called for its expeditious entry into operation and steps to secure its\neffective functioning as soon as possible."},{"id":"a-hrc-42-66-p0005","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"5","seq":7,"section":"I. Introduction","text":"In letters dated 16 January 2019 addressed to the President of the General Assembly\n(A/73/716) and to the President of the Human Rights Council, the Secretary-General set out\nthe terms of reference of the Mechanism."},{"id":"a-hrc-42-66-p0006","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"6","seq":8,"section":"I. Introduction","text":"On 2 April 2019, the Secretary-General announced the appointment of Nicholas\nKoumjian (United States of America) as the Head of the Mechanism, who officially\ncommenced his functions on 1 July 2019. At the time of writing, the recruitment process for\nthe position of Deputy Head of the Mechanism was ongoing and at an advanced stage."},{"id":"a-hrc-42-66-p0007","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"7","seq":9,"section":"I. Introduction","text":"Pursuant to paragraph 42 of the terms of reference, the Secretary-General\ndetermined that the seat of the Mechanism would be located in Geneva, and informed the\nPresident of the Human Rights Council accordingly in a letter dated 7 June 2019."},{"id":"a-hrc-42-66-p0008","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"8","seq":10,"section":"II. Mandate and priorities of the Mechanism","text":"The mandate of the Mechanism is set out in Human Rights Council resolution 39/2\nand further elaborated in its terms of reference. As part of the initial start-up phase, the\nHead of the Mechanism, since his appointment, has worked towards developing a broad\nstrategy and concept of operations for the Mechanism with the assistance of the Secretariat,\nincluding the Office of the United Nations High Commissioner for Human Rights\n(OHCHR), the Office of Legal Affairs and the Department of Political and Peacebuilding\nAffairs. The broad strategy will include the identification of priorities for the Mechanism,\nand the mapping out of the steps necessary to implement the strategy."},{"id":"a-hrc-42-66-p0009","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"9","seq":11,"section":"II. Mandate and priorities of the Mechanism","text":"The Mechanism also anticipates that its substantive strategies willevolve flexibly\nover time in response to both developments in investigations and the operational realities of\nevents on the ground. Adjustments of the Mechanism’s strategy may become necessary in\norder to respond to the needs of national, regional or international prosecutorial or judicial\nauthorities seeking assistance with cases that fall within the mandate of the Mechanism.\nFurthermore, should serious international crimes that fall within the mandate of the\nMechanism be committed in the future, the Mechanism would likely need to adjust its\nactivities and staff planning to respond in an appropriate manner."},{"id":"a-hrc-42-66-p0010","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"10","seq":12,"section":"A. Selection of cases for investigation","text":"Like in the situation faced by international criminal tribunals and comparable\ninternational accountability mechanisms, the Mechanism will have to make difficult\nchoices of prioritization with regard to the allocation of its limited resources. The\nMechanism has a mandate to prepare files with regard to crimes that allegedly were\nperpetrated through the contributions of large numbers of individuals. Attempting to\nprepare a large number of individual case files simultaneously is neither efficient nor\npractical, and would likely result in poor quality results. Therefore, the leadership of the\nMechanism will develop strategies on the prioritization of case files, which will determine\nhow the limited resources available should be utilized in order to secure the greatest effect\non achieving accountability for serious international crimes, providing the victims of such\ncrimes with the best prospects of justice, contributing through its work to deterrence of\nfurther crimes, and seeking to ensure that all the peoples of Myanmar can live safely in\ntheir own home communities."},{"id":"a-hrc-42-66-p0011","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"11","seq":13,"section":"A. Selection of cases for investigation","text":"Certainly, the scale of the crimes, notably the number of victims affected by the\ncrime, is a paramount factor in case selection. The Mechanism is well aware of the large\nnumber of Rohingya now stranded in makeshift refugee camps and who have had to flee to\nBangladesh because of alleged international crimes committed against them. Accordingly,\nthe Mechanism, in close coordination with other relevant entities, will prioritize the\nanalysis and investigation of these alleged crimes."},{"id":"a-hrc-42-66-p0012","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"12","seq":14,"section":"A. Selection of cases for investigation","text":"The case selection strategy will also take into consideration the impartiality of the\nMechanism, namely, that it is concerned with obtaining justice for all those affected by\ninternational crimes, regardless of race, ethnicity, nationality, religion or political views.\nThe case-selection strategy will reflect the fact that the mandate of the Mechanism covers\nserious international crimes and violations of international law committed anywhere within\nthe entire territory of Myanmar, at any time since 2011. The Mechanism will thus seek to\nselect cases that are appropriately representative of the international crimes committed\nthroughout Myanmar, involving various victim groups within the period of its temporal\njurisdiction."},{"id":"a-hrc-42-66-p0013","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"13","seq":15,"section":"B. Accountability for crimes of sexual violence","text":"The Mechanism is aware of multiple reports alleging widespread crimes of sexual\nand gender-based violence, which would fall within the mandate of the Mechanism. Given\nthat societies often stigmatize the victims of sexual and gender-based violence, it is well\nestablished that such crimes are almost always significantly underreported, and at times,\nmassively so. The Mechanism will consider these facts within the specific context of its\nown mandate when selecting and prioritizing the incidents and cases to which it will devote\nresources. These cases also merit special, victim-centric handling in order to ensure that the\ninvestigation does not traumatize victims further, and best facilitates truth-seeking."},{"id":"a-hrc-42-66-p0014","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"14","seq":16,"section":"C. Investigations in order to prepare files","text":"In accordance with the way investigations are prioritized, strategies will be\ndeveloped on how to conduct investigations that would result in files meeting the high\nstandards for criminal prosecution, while still being effective and efficient: essentially,\nsituations whereby the evidence, if tested in fair and credible trials meeting international\nstandards, would be capable of proving the guilt of the accused beyond a reasonable doubt."},{"id":"a-hrc-42-66-p0015","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"15","seq":17,"section":"C. Investigations in order to prepare files","text":"A preliminary yet critical task for the Mechansim will certainly be the collection and\nanalysis of information, documentation and evidence provided by other entities, particularly\nfrom investigations conducted by international entities, non-governmental organizaions and\ncivil society organizations. The probative value of such information, documentation and\nevidence and the extent to which they establish the elements of a criminal offence having\nbeen committed by specific individuals can only be assessed once they are thoroughly\nanalysed by qualified criminal lawyers. The past experience of international courts and\ncomparable international accountability mechanisms suggests that it is likely that such\nevidence will not by itself be sufficient to build criminal case files that establish all\nelements of the applicable criminal offenses. Evidence collected by entities undertaking\nhuman rights investigations and reporting typically provides important leads with regard to\nrelevant witnesses, and can also be very useful in helping to establish whether international\ncrimes have been committed against a particular group and, on occasion, the identity of\ndirect perpetrators. By themselves, however, such investigations and reports often fall short\nof proving all elements of the charges to the standard of beyond reasonable doubt. This is\nparticularly true in the case of indirect perpetrators, namely, those that ordered, planned,\ninstigated or financed a particular crime, or of superiors who, having knowledge of the\ncrimes and the ability to take necessary and reasonable steps to prevent them, failed to do\nso. Thus, it is anticipated that it will be essential for the Mechanism to conduct its own\ninvestigative interviews and to collect further evidence in various forms."},{"id":"a-hrc-42-66-p0016","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"16","seq":18,"section":"C. Investigations in order to prepare files","text":"A further challenge is posed by the fact that, while the seat of the Mechanism is in\nGeneva, it will be essential for the Mechanism to conduct a significant portion of its\noperational and investigative work in the south-east Asian region closer to where the crimes\nwere committed and where numerous witnesses and most physical evidence are likely to be\nlocated."},{"id":"a-hrc-42-66-p0017","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"17","seq":19,"section":"C. Investigations in order to prepare files","text":"In preparing case files, the Mechanism will also ensure that it proceeds in an even-\nhanded fashion, and seeks the truth impartially. This would include collecting exculpatory\nevidence, including evidence of any efforts made by those in leadership roles to prevent\ncrimes or to punish those responsible for crimes, as well as any evidence that has an impact\non the credibility of witnesses."},{"id":"a-hrc-42-66-p0018","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"18","seq":20,"section":"C. Investigations in order to prepare files","text":"The Mechanism recognizes that such investigations will be very challenging. It lacks\npolice or judicial power to use its own authority to compel cooperation from individuals or\nentities. The Mechanism will seek the cooperation of the Government of Myanmar, and of\nStates both in the region and elsewhere, in order to gain access to crimes scenes, witnesses\nand relevant physical and electronic material. The Mechanism will pursue, within the limits\nof its mandate, all available avenues to obtain relevant evidence, and strive to be innovative\nin pursuing such evidence. It will seek to recruit a team of highly experienced and\ninnovative professionals with a variety of skills that can make use of all available strategies\nand technologies to overcome these challenges."},{"id":"a-hrc-42-66-p0019","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"19","seq":21,"section":"D. Cooperation","text":"The Mechanism acknowledges the important work of the fact-finding mission over\nits years of operation, and its contribution towards seeking accountability for the crimes\ncommited in Myanmar. The Mechanism is grateful for the efforts of the fact-finding\nmission to ensure the seamless transfer of the information, documentation and material in\nits possession to the Mechanism."},{"id":"a-hrc-42-66-p0020","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"20","seq":22,"section":"D. Cooperation","text":"In implementing its mandate, the Mechanism will engage with States, regional and\nintergovernmental organizations, United Nations entities, civil society and other\nstakeholders to obtain further evidence of crimes and other relevant information and\ndocumentation pertaining to its mandate. It will also establish modalities and protocols for\nsuch cooperation and information-sharing."},{"id":"a-hrc-42-66-p0021","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"21","seq":23,"section":"D. Cooperation","text":"The Mechanism will engage with States, regional and intergovernmental\norganizations, civil society and other stakeholders in order to encourage them to support its\nactivities and to contribute appropriate resources, including specialized personnel or\nservices, that would assist in the fulfilment of the Mechanism’s mandate. In doing so, the\nMechanism will take every precaution to ensure that its independence and its impartiality\nare fully preserved."},{"id":"a-hrc-42-66-p0022","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"22","seq":24,"section":"E. Sharing of information, documentation and evidence","text":"It is important to recall that the Mechanism is not a court or tribunal. It has no power\nto issue arrest warrants, conduct trials or impose punishments on its own; rather, it has the\nmandate to share relevant information, documentation and evidence with competent\ninvestigative, prosecutorial and judicial authorities in order to facilitate and expedite fair\nand independent criminal proceedings, in accordance with international law standards, in\nnational, regional or international courts or tribunals that have or may in the future have\njurisdiction over the crimes."},{"id":"a-hrc-42-66-p0023","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"23","seq":25,"section":"E. Sharing of information, documentation and evidence","text":"When sharing information, documentation and evidence with such authorities, the\nMechanism will ensure it is done in accordance with its terms of reference, including\nUnited Nations rules, regulations and policies, relevant international law, including\ninternational human rights law, and rules and standards and good practices of other\ncomparable international accountability mechanisms. In particular, it will ensure that it\ncomplies with the United Nations policy against international accountability mechanisms\nsharing evidence for use in criminal proceedings in which capital punishment could be\nimposed or carried out."},{"id":"a-hrc-42-66-p0024","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"24","seq":26,"section":"E. Sharing of information, documentation and evidence","text":"Furthermore, before sharing specific information, documentation or evidence with\nsuch authorities, the Mechanism must be satisfied that the disclosure is subject to the\nnecessary and appropriate protective conditions. Assurances must be obtained from the\nentity requesting the information that it will respect the scope of the consent expressed by\nsources of information, including victims, witnesses, Governments and non-governmental\nproviders of information. The Mechanism will only provide information once it is satisfied\nthat the entity receiving the information will take approporate measures, consistent with the\nrights of due process and fair trial, to ensure the protection of confidential information and\nthe security of all relevant persons."},{"id":"a-hrc-42-66-p0025","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"25","seq":27,"section":"E. Sharing of information, documentation and evidence","text":"Moreover, the Mechanism must be confident that the authorities requesting the\ninformation are willing and capable of conducting fair and independent criminal\nproceedings in accordance with international law standards. Any request for material from\nthe Mechanism will therefore be carefully studied before a decision is made on whether to\nprovide such material, and if so, that the sharing is conducted with the necessary modalities\nso that the aforementioned concerns are addressed."},{"id":"a-hrc-42-66-p0026","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"26","seq":28,"section":"E. Sharing of information, documentation and evidence","text":"At the initial stages of its operations, the Mechanism will largely focus on the\ncollection, preservation and analysis of information, documentation and evidence in order\nto extract the relevant evidence to prepare case files. Nonetheless, in anticipation of\nrequests for the sharing of information, documentation and evidence arising in the future,\nthe Mechanism will, at the initial stages, ensure the development of policies,\nmethodologies, protocols and procedures for the future sharing of information,\ndocumentation and evidence."},{"id":"a-hrc-42-66-p0027","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"27","seq":29,"section":"F. Sharing information, documentation and evidence for other purposes","text":"The terms of reference of the Mechanism provide that any other use of the\ninformation, documentation and evidence collected, preserved and stored by the\nIndependent Investigative Mechanism pursuant to its mandate to facilitate fair and\nindependent criminal proceedings in the future may be determined by the Mechanism on a\ndiscretionary case-by-case basis (A/73/716, annex, para. 19)."},{"id":"a-hrc-42-66-p0028","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"28","seq":30,"section":"F. Sharing information, documentation and evidence for other purposes","text":"In addition to the aforementioned policies, metholodgies, protocols and procedures\nfor the sharing of information, documentation and evidence, the Mechanism will also\nestablish policies and procedures for the exercise of its discretion regarding the sharing of\ninformation, documentation and evidence for such other uses. In this regard, the\nMechanism will, in accordance with its mandate, place utmost importance on evaluating\nwhether such disclosure could materially contribute to the interests of justice and the\ndeterrence of further crimes. The Mechanism will also need to carefully consider the\nrequest to ensure that the disclosure will not endanger victims, witnesses or information\nproviders, nor risk compromising assurances made by the Mechanism to treat information\nconfidentially."},{"id":"a-hrc-42-66-p0029","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"29","seq":31,"section":"G. Public outreach","text":"The Mechanism believes that regular and professional public outreach is essential to\nraise public awareness and understanding of the work of the Mechanism, and will be\ncritical in securing the confidence and cooperation of victims and witnesses. While key\naspects of the work of the Mechanism must necessarily remain confidential, it is also\nessential that accurate information about the mandate, goals, general activities and contact\nmodalities of the Mechanism be publicly available."},{"id":"a-hrc-42-66-p0030","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"30","seq":32,"section":"G. Public outreach","text":"Raising public awareness of the work of the Mechanism serves several purposes.\nFirstly, it can help to prevent victims from holding unrealistic expectations of the work of\nthe Mechanism and the possible or likely outcomes, which could also reduce the risks of\ndisillusionment. Secondly, it can help clarify the mandate of the Mechanism and how it\ndiffers from the diverse variety of other United Nations entities engaged in aspects of the\nsituation in Myanmar. Lastly, it is essential to convey to the public that the Mechanism is\nconcerned with all serious international crimes committed in Myanmar regardless of the\nrace, ethnicity, nationality, religion or political affiliation of either the perpetrators or of the\nvictims of such crimes."},{"id":"a-hrc-42-66-p0031","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"31","seq":33,"section":"G. Public outreach","text":"A key objective for seeking to raise public awareness of the Mechanism is to\nmaximize the potential deterrent effects on those contemplating the commission of such\nserious crimes. The files prepared by the Mechanism will not expire and will remain\navailable for use in criminal proceedings in any national, regional or international courts or\ntribunals that have, or may in the future have, jurisdiction over those crimes, no matter how\nmuch time has passed."},{"id":"a-hrc-42-66-p0032","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"32","seq":34,"section":"G. Public outreach","text":"The Mechanism plans to have a public website with as much information as is\npossible and appropriate, taking into account its confidentiality obligations and United\nNations rules, regulations and polices concerning the disclosure of information. The\ninformation would be made available in the relevant languages."},{"id":"a-hrc-42-66-p0033","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"33","seq":35,"section":"G. Public outreach","text":"The Mechanism will also maintain channels of communication with victim and\nsurvivor groups, members of civil society at the national, regional and international levels,\nand with relevant States and international organizations so as to facilitate dialogue."},{"id":"a-hrc-42-66-p0034","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"34","seq":36,"section":"H. Initial priorities of the Mechanism","text":"In order to collect, consolidate, preserve and analyse evidence of the most serious\ninternational crimes and violations of international law that fall within its mandate and to\nprepare files in order to facilitate and expedite fair and independent criminal proceedings,\nin accordance with international law standards, the Mechanism must first have in place the\nnecessary personnel and physical assets to ensure the integrity of the evidence collected, as\nwell as the security of its sources.\n2.     Information technology system"},{"id":"a-hrc-42-66-p0035","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"35","seq":37,"section":"H. Initial priorities of the Mechanism","text":"The Mechanism has prioritized the expeditious identification and acquisition of\nappropriate information technology as a key to efficiently carrying out its mandate. Such\ntechnology is necessary in order to safely preserve and appropriately analyse the\ninformation, documentation and evidence collected. Furthermore, the system should be\ncapable of dealing with the multiple languages and scripts used in Myanmar and large\nquantities of photographic, video and other digital evidence. It is also crucial that the\nsystem allow analysts to search through massive quantities of documents, photographs,\nvideo and audio evidence in order to identify the material relevant to a particular case file.\nEnsuring that the appropriate system is established early on will spare the Mechanism of\nhaving to adjust or transition between information systems in the future, which could lead\nto delays in its work and additional unnecessary costs. In building its information systems,\nthe Mechanism will hope to benefit from the experiences of international tribunals and\ncomparable international accountability mechanisms in order to identify and acquire the\nnecessary hardware and software for the system. While the Mechanism explores available\noptions for building such a system, it has also, in parallel, obtained the necessary basic\ninformation technology hardware that would already allow the Mechanism to begin to\nreceive information, documentation and evidence from certain information providers.\n3.   Development of policies, standards, protocals, procedures and methods\nof work"},{"id":"a-hrc-42-66-p0036","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"36","seq":38,"section":"H. Initial priorities of the Mechanism","text":"In the early stages of its work, the Mechanism will develop policies, standards,\nprotocals, procedures and methods of work to ensure it effectively, efficiently and\nconsistently fulfils its mandate. These would cover the entire implementation process of the\nMechanism’s mandate, from the collection, preservation, storage and analysis of\ninformation, documentation and evidence to the conduct of investigations and taking of\nwitness testimonies, the preparation of case files, and the sharing of information,\ndocumentation and evidence."},{"id":"a-hrc-42-66-p0037","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"37","seq":39,"section":"H. Initial priorities of the Mechanism","text":"In particular, it would include policies regarding the handling of physical and\nelectronic evidence to ensure its integrity and preservation, as well as protocols on\nprotecting the security and privacy of witnesses and obtaining the informed consent of\ncooperating witnesses before their identities are shared with anyone outside the\nMechanism. In addition, procedures and methods of work would be designed to minimize\nthe security risks of witnesses and interlocutors, as well their families, which may arise as a\nresult of their interaction with the Mechanism.\n4.   Frameworks for the transfer of information, documentation and\nevidence"},{"id":"a-hrc-42-66-p0038","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"38","seq":40,"section":"H. Initial priorities of the Mechanism","text":"In order to ensure that the Mechanism will be able to receive information,\ndocumentation and evidence from all relevant information providers, including Member\nStates, international and regional organizations, United Nations entities and civil society\norganizations, the Mechanism will also engage with such information providers in order to\nestablish the necessary and appropriate frameworks, including by entering into\narrangements or agreements for the transfer of relevant information, documentation and\nevidence from information providers. Such frameworks will be in accordance with United\nNations rules, regulations and established procedures and practices."},{"id":"a-hrc-42-66-p0039","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"39","seq":41,"section":"H. Initial priorities of the Mechanism","text":"The frameworks would necessarily take into consideration the possibility that such\ninformation, documentation and evidence received may become evidence in the\nMechanism’s preparation of case files to facilitate and expedite fair and independent\ncriminal proceedings in the future. Accordingly, the frameworks would seek to address,\ninter alia, issues of confidentiality, the uses of the information, documentation and\nevidence, and their possible sharing as evidence in case files with national, regional and\ninternational courts. The frameworks would also ensure that any transfer of information,\ndocumentation and evidence is in accordance with United Nations rules, regulations,\npolicies and procedures.\n5.   Collection, preservation and analysis of information, documentation\nand evidence"},{"id":"a-hrc-42-66-p0040","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"40","seq":42,"section":"H. Initial priorities of the Mechanism","text":"Before further investigative activities are carried out, the Mechanism plans to\nreceive, collect and analyse information, documentation and evidence held by other entities,\nand to identify which investigative activities are most likely to lead to prosecutable criminal\ncases."},{"id":"a-hrc-42-66-p0041","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"41","seq":43,"section":"H. Initial priorities of the Mechanism","text":"When accepting information, documentation and evidence from other entities, the\nMechanism will be most focused on verifiable facts concerning the events in question (such\nas witness statements, photographs and videos) rather than any analysis or legal conclusions\nthat the provider may have drawn, or sought to draw, from those facts. The Mechanism will\nmake its own analysis and draw its own legal conclusions with regard to potential criminal\ncases on the basis of a comprehensive, independent assessment of all available information,\ndocumentation and evidence using methodologies accepted in international criminal courts\nand in most national judicial systems. The Mechanism will also attempt to verify the\ninformation, documentation and evidence received through its own supplementary\ninvestigation, when deemed necessary or helpful."},{"id":"a-hrc-42-66-p0042","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"42","seq":44,"section":"H. Initial priorities of the Mechanism","text":"As part of the its collection of information, documentation and evidence, the\nMechanism will also collect witness and victim testimonies and undertake investigations in\nthe field. While the actual scope and needs of these activities will be developed\nsubsequently, an initial priority will be to ensure that the Mechanism has the expertise\nnecessary to handle sexual and gender-based violence crimes. The Mechanism will\ntherefore prioritize the recruitment of investigators, analysts and legal officers with\nspecialized training in or experience handling of cases of sexual and gender-based violence.\nIt will also provide specialized training to all staff dealing with victims of sexual violence,\nand prioritize the handling of these cases."},{"id":"a-hrc-42-66-p0043","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"43","seq":45,"section":"H. Initial priorities of the Mechanism","text":"As a core function, the Mechanism will ensure that the information, documentation\nand evidence that it collects and preserves, and the analyses produced by it, conform with\nrelevant United Nations rules, regulations, policies and procedures. This will\nrequire comprehensive and sustainable security and cybersecurity protocols to best ensure\nthe effective reception, cataloguing, storage and sorting of documents, materials or other\nevidentiary elements.\n6.     Consultations and cooperation"},{"id":"a-hrc-42-66-p0044","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"44","seq":46,"section":"H. Initial priorities of the Mechanism","text":"The Mechanism recognizes that it can benefit in many areas from the experience of\ninternational courts or comparable international accountability mechanisms, and has\nalready engaged in consultations with some relevant entities that have been generous in\ntheir assistance. The Mechanism believes it will particularly benefit from the experiences of\nthese entities in the areas of development of information technology systems; the\ndevelopment of protocols regarding witness interviews, confidentiality and protection; and\nthe standardization of the frameworks for the transfer of information, documentation and\nevidence from information providers."},{"id":"a-hrc-42-66-p0045","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"45","seq":47,"section":"H. Initial priorities of the Mechanism","text":"Necessarily, all such systems and protocols will be tailored to fit the actual\ncircumstances and needs of the Mechanism, which will differ in important respects from\nthat of international courts or tribunals or other international accountability mechanisms. In\nparticular, the many different languages that are spoken in Myanmar will pose specific\nchallenges, including in hiring or contracting with competent and independent interpreters\nand translators. In addition, database search systems must be capable of accommodating the\nvarious scripts in which these languages are written."},{"id":"a-hrc-42-66-p0046","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"46","seq":48,"section":"III. Key challenges","text":"The Mechanism is conscious that building a prosecutable criminal case requires\npresenting credible evidence that proves each element of the crime to the high evidentiary\nstandards required in various jurisdictions for a criminal conviction (for example, proving\neach element beyond a reasonable doubt or to the “intimate conviction” (conviction intime)\nof the judges). When convictions depend on inferences from circumstantial evidence, the\ninference consistent with guilt must be the only reasonable inference. Furthermore, the\nMechanism emphasizes that the evidence must not only prove that a crime has been\ncommitted; it must also establish the elements of the applicable mode of responsibility –\nincluding proof that the accused person held the required mental state to satisfy the mens\nrea element of the crime, as well as proof that the accused person’s acts or omissions fulfil\nthe actus reus elements necessary to make them criminally responsible."},{"id":"a-hrc-42-66-p0047","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"47","seq":49,"section":"III. Key challenges","text":"Taking into consideration the need for the Mechanism to collect evidence of such\nhigh standards, the Mechanism will have to ensure that it has the necessary policies,\nprotocols, procedures and methologies in place, and recruits and retains well-trained and\nexperienced investigators and analysts to ensure that its investigations are of the quality\ndemanded by its mandate."},{"id":"a-hrc-42-66-p0048","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"48","seq":50,"section":"III. Key challenges","text":"The distance of the seat of the Mechanism from relevant witnesses and the locations\nof alleged crimes poses a logistical and operational challenge that the Mechanism will seek\nto address with innovative and cost effective operational structures and processes. The\nMechanism will seek the cooperation of States in the region, including Myanmar."},{"id":"a-hrc-42-66-p0049","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"49","seq":51,"section":"III. Key challenges","text":"Where such cooperation is not available, the Mechanism will proceed with its\ninvestigative efforts and prepare case files, drawing on the experience of international\ncourts and tribunals, and of other comparable international accountability mechanisms.\nMany international courts and other international accountability mechanisms have faced the\nchallenge of a lack of State cooperation in investigations of serious international crimes,\nand have adopted a number of complementary strategies to compensate. Where cooperation\nis not forthcoming, the Mechanism will adopt strategies proven effective in other contexts,\nand will adopt its own innovations that allow it to pursue and have access to the best\nevidence available. At the same time, the Mechanism would benefit greatly from the\nongoing support of the Human Rights Council in encouraging Member States, including\nMyanmar and neighboring States, to cooperate fully with the Mechanism."},{"id":"a-hrc-42-66-p0050","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"50","seq":52,"section":"III. Key challenges","text":"Throughout the course of its operations, the Mechanism will work to ensure that its\ninteractions with victims and other witnesses do them no harm (namely, that any risk of re-\ntraumatizing victims or placing witnesses at risk of reprisal for cooperating with the\nMechanism is minimized). The Mechanism will adopt appropriate procedures and methods\nof work to minimize the security risks of witnesses and interlocutors, and of their families,\nwhich may arise as a result of their interaction with the Mechanism."},{"id":"a-hrc-42-66-p0051","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"51","seq":53,"section":"III. Key challenges","text":"Where witnesses or sources are deemed to be at risk during the course and as a result\nof such cooperation with the Mechanism, the Mechanism will seek to take all feasible steps\nwithin its means to protect their safety and security. Arrangements or agreements, as\nappropriate, with national Governments willing to cooperate in this regard will be desirable.\nGiven that witness protection can often involve significant expense, the Mechanism will\nfurther seek the cooperation of competent national, regional and international authorities\nwith well-developed witness protection programmes whenever possible."},{"id":"a-hrc-42-66-p0052","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"52","seq":54,"section":"IV. Practical steps taken for the operationalization and full","text":"Following the setting out of the terms of reference of the Mechanism, the United\nNations Secretariat worked to put in place the arrangements, personnel and budget\nnecessary for the operationalization and full functioning of the Mechanism. This included\nthe establishment of an administrative start-up team to facilitate prompt recruitment and\noperationalization processes once the Head of the Mechanism was appointed."},{"id":"a-hrc-42-66-p0053","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"53","seq":55,"section":"IV. Practical steps taken for the operationalization and full","text":"In parallel, the Mechanism is also proceeding with the recruitment a variety of other\nstaff positions in the Mechanism. In this regard, in line with the Mechanism’s mandate, and\nin order to establish the necessary infrastructure to receive information, documentation and\nevidence, priority has been given to recruiting personnel with the specific expertise to assist\nthe Mechanism in (a) establishing a system for the receipt, treatment, safe storage and\nconsolidation of information, documentation and evidence, particularly within a searchable\nelectronic database; (b) developing protocols for the receipt, treatment and storage of\ninformation, documentation and evidence; and (c) drafting and putting in place the\narrangements or agreements necessary for the receipt of information, documentation and\nevidence from identified providers. These capabilities are necessary in order for the\nMechanism to optimally collect and preserve evidence, which it will subsequently analyse\nand use to prepare case files."},{"id":"a-hrc-42-66-p0054","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"54","seq":56,"section":"IV. Practical steps taken for the operationalization and full","text":"Since the Secretary-General’s determination in June 2019 that the seat of the\nMechanism should be located in Geneva, the Mechanism has sought to identify potential\npermanent office space that is adequate for the number of staff members anticipated when\nall positions have been filled and which would fit the security needs of the Mechanism.\nConsultations in that regard are ongoing with both the host Government and the United\nNations Office at Geneva. Once the options available have been identified, the Mechanism\nwill compare the costs of each, including recurring costs such as security at the site, to\nidentify the most cost- and operationally efficient option. In the interim, the United Nations\nOffice at Geneva has provided temporary office space and identified facilities for the safe\nstorage of evidence received by the Mechanism until more permanent facilities become\navailable."},{"id":"a-hrc-42-66-p0055","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"55","seq":57,"section":"IV. Practical steps taken for the operationalization and full","text":"With regard to short-term storage needs, the Mechanism has also ensured the\navailability of a secure facility in the United Nations Office at Geneva to store physical\nevidence and electronic hardware for evidence received from the fact-finding mission and\nother entities."},{"id":"a-hrc-42-66-p0056","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"56","seq":58,"section":"IV. Practical steps taken for the operationalization and full","text":"Upon assuming his position on 1 July 2019, the Head of the Mechanism has\nconsulted with stakeholders in order to hear their concerns and suggestions, to explain his\nmandate, and to develop strategies further for the implementation by the Mechanism of its\nmandate. One of the key messages that the Head has sought to convey is that the unique\nand technical mandate of the Mechanism is to build case files, which differs from the\nmandates of the fact-finding mission, the Special Rapporteur on the situation of human\nrights in Myanmar and the Special Envoy of the Secretary-General on Myanmar."},{"id":"a-hrc-42-66-p0057","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"57","seq":59,"section":"V. Conclusions","text":"The Mechanism is at a very early stage of its operations. Many challenges lie\nahead on the its journey towards fulfilling the ambitious mandate conferred upon it\nby the Human Rights Council. The experience of courts and tribunals dealing with\ninternational crimes, as well as other comparable international accountability\nmechanisms, has shown that such investigations are complex, and that it can take time\nfor such information, documentation and evidence to be shaped into strong case files\nready for prosecution. Successful investigations require painstaking efforts to locate\nand obtain the testimony of individuals with knowledge of the crimes, particularly\nthose with evidence concerning the planning, preparation or orders that may have led\nto crimes, to collect any documentary or forensic evidence that may corroborate\nwitness accounts, and to gather and evaluate all evidence, both inculpatory and\nexculpatory."},{"id":"a-hrc-42-66-p0058","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"58","seq":60,"section":"V. Conclusions","text":"The Mechanism is, however, acutely aware that each day that passes without\naccountability for international crimes brings concomitant suffering for the hundreds\nof thousands of refugees stranded in makeshift refugee camps outside Myanmar, and\nhoping and waiting to be able to safely return to their homes, to those displaced from\ntheir homes to other locations within Myanmar, and to the many others who have\nthemselves been victimized or who have lost family members to international crimes\nwithin the Mechanism’s mandate. The voluntary and sustainable return of refugees to\ntheir home communities in Myanmar is likely to be dependant, to an important\nextent, on a process of accountability for those most responsible for the crimes that\nuprooted them from their homes. Few are likely to seek to return to a place where\nthose that perpetrated serious crimes against them, or their families, still reside with\nimpunity and retain the means or authority to inflict further harm."},{"id":"a-hrc-42-66-p0059","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"59","seq":61,"section":"V. Conclusions","text":"The Mechanism is keenly aware of victims’ expectations of its work and the\nweight of the responsibility that it has been given to pursue avenues towards justice.\nNonetheless, even when assisted by the brave efforts of victims and witnesses who seek\njustice for the serious international crimes committed in Myanmar since 2011, the\nefforts of the Mechanism alone will not be sufficient. States in the region should\ncooperate with the Mechanism, in order to maximize its effectiveness, and the\ninternational community as a whole should affirm its enduring commitment to\nseeking accountability for the most serious international crimes and violations of\ninternational law committed in Myanmar since 2011."},{"id":"a-hrc-42-66-p0060","rec_id":"recf1rBRA5oLTuvjB","symbol":"A/HRC/42/66","n":"60","seq":62,"section":"V. Conclusions","text":"Continued impunity for such crimes is only likely to lead to further violence\nand suffering, and accompanying risks to peace and security in the region and\nbeyond. The prospects for a peaceful and prosperous future for the people of\nMyanmar, where all its peoples share the benefit of development and its bountiful\nresources, depend on the clear demonstration that such crimes will not be tolerated.\nThe Mechanism looks forward to its ongoing engagement with the Human Rights\nCouncil towards that end."},{"id":"a-hrc-45-60-u0000","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":null,"seq":0,"section":null,"text":"United Nations                                                                              A/HRC/45/60\nGeneral Assembly                                                      Distr.: General\n7 July 2020","unnumbered":true},{"id":"a-hrc-45-60-u0001","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":null,"seq":1,"section":null,"text":"Summary\nFollowing the submission of the first report of the Independent Investigative\nMechanism for Myanmar to the Human Rights Council on 7 August 2019, the Secretary-\nGeneral deemed the Mechanism operational as at 30 August 2019. In its first year of\noperations, the Mechanism has been focused on ramping up its operations and activities on\nvarious fronts, including its operational and administrative processes, its engagement with\nrelevant entities and stakeholders, and the implementation of its substantive mandate.\nSignificant progress has been made in all of these areas, which will be elaborated upon in\nthe present report.\nAdjustments to the Mechanism’s plans became necessary, however, following the\nemergence of the global coronavirus disease (COVID-19) pandemic. The pandemic forced\ndisruptions in the Mechanism’s onboarding of staff and its operational plans for 2020. It\nhas also created some uncertainty regarding its operations for the remainder of 2020 and\n2021, particularly with respect to its ability to conduct missions for engagement and\nevidence-collection purposes. Nonetheless, since the onset of the pandemic, the Mechanism\nhas largely been able to continue its work by adjusting and adapting its operations and\nprocesses in accordance with the changes in circumstances. The Mechanism will continue\nto do so and will implement its mandate to the best of its ability despite ongoing restrictions\nand limitations.\nMoving forward, the Mechanism will seek to further expand its collection,\npreservation and analysis activities, which will be supported by missions if circumstances\nrelated to the COVID-19 pandemic allow. It will also seek to expand the procurement of\nthe necessary technical equipment, software and specialized capabilities. In addition, the\nMechanism will remain proactive in sharing evidentiary materials with courts and tribunals\nwhen all appropriate conditions, including the safety, security and privacy of information\nproviders, are satisfied. Finally, the Mechanism will continue to implement its engagement\nand public outreach strategy in order to provide up-to-date and accurate information\nregarding the Mechanism to its various stakeholders.\nIn order to deliver on its mandate, the Mechanism will continue to assess the\nrelevant circumstances, including with regard to the COVID-19 pandemic; review its\nmethodology and practices; and strengthen its operations through creative and flexible\nsolutions. Ultimately, the Mechanism aims to resolve the various challenges that are likely\nto arise and collect all relevant evidence in an efficient and effective manner, in order to\nenable perpetrators of serious international crimes in Myanmar to be brought to justice.","unnumbered":true},{"id":"a-hrc-45-60-p0001","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"1","seq":2,"section":"I. Introduction","text":"In its resolution 39/2, the Human Rights Council decided to establish an independent\nmechanism with the mandate to collect, consolidate, preserve and analyse evidence of the\nmost serious international crimes and violations of international law committed in\nMyanmar since 2011, and to prepare files in order to facilitate and expedite fair and\nindependent criminal proceedings, in accordance with international law standards, in\nnational, regional or international courts or tribunals that have or may in the future have\njurisdiction over those crimes, in accordance with international law. The terms of reference\nof the Independent Investigative Mechanism for Myanmar were attached as an annex to\nletters dated 16 January 2019 from the Secretary-General addressed to the President of the\nGeneral Assembly (A/73/716) and to the President of the Human Rights Council."},{"id":"a-hrc-45-60-p0002","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"2","seq":3,"section":"I. Introduction","text":"In a letter dated 27 August 2019 to the President of the Human Rights Council, the\nSecretary-General deemed the Mechanism operational as at 30 August 2019."},{"id":"a-hrc-45-60-p0003","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"3","seq":4,"section":"I. Introduction","text":"In its resolution 42/3, the Council welcomed the Mechanism’s entry into operation\nand called for close cooperation between the Mechanism and any ongoing or future\ninvestigations pertaining to serious international crimes and violations of international law\nin Myanmar by national, regional or international courts or tribunals."},{"id":"a-hrc-45-60-p0004","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"4","seq":5,"section":"I. Introduction","text":"In the same resolution, the Council also called upon the United Nations to ensure\nthat the Mechanism was afforded the necessary support and resources it needed in terms of\nstaffing, location and operational freedom so it could deliver as effectively as possible on\nits mandate, and urged Member States in the region to cooperate with the Mechanism, to\ngrant it access and to provide it with every assistance in the execution of its mandate."},{"id":"a-hrc-45-60-p0005","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"5","seq":6,"section":"I. Introduction","text":"On 15 November 2019, the Deputy Head of the Mechanism, Kaoru Okuizumi\n(Japan), officially commenced her functions."},{"id":"a-hrc-45-60-p0006","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"6","seq":7,"section":"I. Introduction","text":"Welcoming the operationalization of the Mechanism and the appointment of its\nHead, the General Assembly, in resolution 74/246, urged the Mechanism to swiftly advance\nits work and to ensure the effective use of evidence of the most serious international crimes\nand violations of international law collected by the independent international fact-finding\nmission on Myanmar. In the same resolution, the Assembly also expressed grave concern\nabout the increasing restrictions on humanitarian access, in particular in Rakhine State, and\nurged the Government of Myanmar to cooperate fully with and to grant full, unrestricted\nand unmonitored access to all United Nations mandate holders and human rights\nmechanisms, including the Mechanism."},{"id":"a-hrc-45-60-p0007","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"7","seq":8,"section":"I. Introduction","text":"In its resolution 74/246, the General Assembly also called upon the United Nations\nto ensure that the Mechanism was afforded the flexibility that it needed in terms of staffing,\nlocation and operational freedom so it could deliver as effectively as possible on its\nmandate."},{"id":"a-hrc-45-60-p0008","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"8","seq":9,"section":"I. Introduction","text":"In its resolution 43/26, the Council called for the Mechanism to continue to\ndischarge its mandate, making use of the information collected by the independent\ninternational fact-finding mission and other credible sources, and for close and timely\ncooperation between the Mechanism and any future investigations by national, regional or\ninternational courts or tribunals, including by the International Criminal Court or the\nInternational Court of Justice."},{"id":"a-hrc-45-60-p0009","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"9","seq":10,"section":"I. Introduction","text":"In the first quarter of 2020, the emergence of the coronavirus disease (COVID-19)\npandemic threatened the health, safety, travel and general movement of persons around the\nworld. Although the pandemic has affected its work, the Mechanism has been able to\ncontinue with the implementation of its mandate with some adjustments. This will be\nfurther elaborated upon below."},{"id":"a-hrc-45-60-p0010","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"10","seq":11,"section":"I. Introduction","text":"While it remains unclear how the Mechanism’s work may be affected during the\nremainder of 2020 and 2021 by the pandemic, in particular with regard to travel restrictions,\nthe Mechanism will continue to build on the momentum it has garnered since it became\noperational. It will strive to adapt to any new developments and continue to implement its\nmandate, while ensuring its ongoing commitment to maintaining the necessary protections\nfor its confidential and sensitive work at all times."},{"id":"a-hrc-45-60-p0011","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"11","seq":12,"section":"II. Progress made by the Mechanism in 2019 and 2020","text":"Since the Head of the Mechanism, Nicolas Koumjian, officially commenced his\nfunctions on 1 July 2019 and the Secretary-General deemed the Mechanism to be\noperational as at 30 August 2019, the Mechanism has been focused on ramping up its\noperations and activities on various fronts in order to be fully functional as soon as possible.\nThese efforts include operational and administrative processes, engagement with relevant\nentities and stakeholders, and the implementation of the Mechanism’s substantive mandate,\nall of which are ongoing simultaneously."},{"id":"a-hrc-45-60-p0012","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"12","seq":13,"section":"II. Progress made by the Mechanism in 2019 and 2020","text":"While significant progress has been made, the global COVID-19 pandemic has\nundeniably disrupted the Mechanism’s original plans for 2020. In this regard, while there\nhave been some disruptions, the Mechanism has largely continued its operations and has\nbeen able to accelerate progress in some areas as a result of needs related to remote\nworking arrangements. Nonetheless, the Mechanism has had to adapt its activities and the\nmanner in which it conducts its daily work in order to comply with various external and\ninternal restrictions that have been imposed as a result of the pandemic. In this regard, the\nMechanism also sought to ensure that there would be no compromises regarding the safety\nand security of: its information and operations, including that of its witnesses and relevant\nstakeholders; the information, documentation and evidence in the Mechanism’s possession;\nand the Mechanism’s personnel."},{"id":"a-hrc-45-60-p0013","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"13","seq":14,"section":"A. Operational and administrative processes","text":"As stated in the Mechanism’s previous report to the Council (A/HRC/42/66), one of\nthe first objectives of the Head of the Mechanism was to put in place a broad strategy and\nconcept of operations that would make the most efficient use of the available resources to\nmake concrete progress on the mandate. The Head identified the priorities, strategies, and\nshort- and long-term goals for the Mechanism, which have now been incorporated into the\nworkplan for each of its various components."},{"id":"a-hrc-45-60-p0014","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"14","seq":15,"section":"A. Operational and administrative processes","text":"The proposed programme plan and budget for 2021 reflects a number of changes to\nthe Mechanism’s previous budgets, which were developed before any of the leadership or\nstaff of the Mechanism had been recruited. It therefore represents the first opportunity for\nthe Mechanism to propose an allocation of resources that corresponds to its strategy for\nmandate implementation. In this regard, the Mechanism carefully assessed and adjusted its\nprogramme in order to propose a more streamlined and leaner budget for 2021, while still\nensuring that it would have the necessary resources to fully implement its mandate."},{"id":"a-hrc-45-60-p0015","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"15","seq":16,"section":"A. Operational and administrative processes","text":"One of the areas in which the Mechanism foresees higher substantive returns despite\nsignificant savings in 2021 is in relation to the expenditure incurred for office premises.\nFollowing the Secretary-General’s determination in June 2019 that the seat of the\nMechanism would be located in Geneva, the Mechanism commenced a study to identify the\nmost suitable option for office space. This study took into account many factors including\nthe estimated costs and other financial implications; security issues unique to the\nMechanism; occupancy timelines; hosting capacity; and the Mechanism’s requirements and\nresource needs. Ultimately, the Mechanism determined that the most cost-effective and\ntechnically acceptable option would be to build a prefabricated office facility inside the\npremises of the United Nations Office at Geneva."},{"id":"a-hrc-45-60-p0016","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"16","seq":17,"section":"A. Operational and administrative processes","text":"In designing the new office facility, the Mechanism took into consideration the\nrecommendations of the Department of Safety and Security and decided that the office\nspace would have its own dedicated video surveillance and access control systems. In\naddition, the design reflected the Mechanism’s requirements for the storage of physical\nevidence, the need to ensure the security and integrity of the information in its possession\nand the office’s proximity to the United Nations Office at Geneva as a service provider for\nthe set-up and use of information technology and other infrastructure."},{"id":"a-hrc-45-60-p0017","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"17","seq":18,"section":"A. Operational and administrative processes","text":"Construction for the Mechanism’s new premises began on 1 February 2020. On 20\nMarch 2020, the Government of Switzerland ordered the closure of all construction sites in\nthe Canton of Geneva owing to the COVID-19 pandemic, including all construction sites\nwithin the premises of the United Nations Office at Geneva. The construction of the\nMechanism’s office facility resumed on 18 May 2020. Barring any further delays, it is\nexpected that the facility will be ready for occupancy in late 2020."},{"id":"a-hrc-45-60-p0018","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"18","seq":19,"section":"A. Operational and administrative processes","text":"Another priority of the Mechanism in 2019 and 2020 has been to recruit a team of\nhighly experienced and innovative professionals with a variety of skills and expertise in\nseveral diverse and important areas. Such personnel will allow the Mechanism to make use\nof all available technologies and tools to address the challenges it faces, including the lack\nof access to the territory of Myanmar, the protection of witnesses and information providers,\ncybersecurity and information security risks, and the wide range of languages spoken by the\nrelevant interlocutors and stakeholders. To that end, the Mechanism developed a\nrecruitment schedule that sought to match the timing of recruitment of personnel with the\nskills or expertise needed according to its substantive workplan."},{"id":"a-hrc-45-60-p0019","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"19","seq":20,"section":"A. Operational and administrative processes","text":"As a result of its proactive approach towards recruitment, the Mechanism was on\ntarget to meet its recruitment objectives for 2020. As of March 2020, the Mechanism had\nrecruited personnel with expertise in the following areas, among others: international\ncriminal law; international human rights law; international humanitarian law; criminal\ninvestigation and prosecution; information system management; storage and preservation of\ninformation, documentation and evidence; military matters; sexual and gender-based crimes\nand violence; crimes against children; and information technology and security."},{"id":"a-hrc-45-60-p0020","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"20","seq":21,"section":"A. Operational and administrative processes","text":"As of June 2020, the Mechanism had filled over half of the total positions approved\nby the General Assembly for 2020 and had commenced the recruitment processes for a\nfurther quarter of them."},{"id":"a-hrc-45-60-p0021","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"21","seq":22,"section":"A. Operational and administrative processes","text":"The Mechanism has also developed an internal training programme, with the aim of\ncontinually deepening the expertise of its personnel in highly specialized and rapidly\nevolving technical areas. Given the present need for remote working, the Mechanism has\narranged online training sessions to keep its personnel updated on relevant developments in\nthose technical areas during the COVID-19 pandemic."},{"id":"a-hrc-45-60-p0022","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"22","seq":23,"section":"B. Engagement with relevant stakeholders and public outreach","text":"As stated in the Mechanism’s previous report to the Council, public outreach\nactivities are essential to raise awareness and understanding of the complex work of the\nMechanism. Regular communication can help to secure the confidence and cooperation of\nrelevant stakeholders, and greater awareness of the Mechanism’s work could deter some\nperpetrators from committing new crimes. Outreach activities are also important to prevent\nmisunderstandings and misinformation about the Mechanism and to manage expectations\nabout what the Mechanism can and cannot do. Among others, relevant stakeholders include\nany Member State, regional and intergovernmental organization, United Nations entity,\ncivil society actor, corporate and private sector entity and individual that possesses or is\nlikely to possess information, documentation and evidence that is relevant to the\nMechanism’s mandate or that can otherwise facilitate its work."},{"id":"a-hrc-45-60-p0023","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"23","seq":24,"section":"B. Engagement with relevant stakeholders and public outreach","text":"To that end, the Mechanism developed a strategy for its engagement and public\noutreach in order to raise awareness about the Mechanism, its mandate and its work among\nall relevant stakeholders. The strategy includes a multi-pronged approach to\ncommunications with the various categories of stakeholders and the dissemination of\ninformation regarding the Mechanism’s work. The Mechanism also conducted a survey of\nover 30 civil society actors in the Asia-Pacific region in order to assess the level of\nunderstanding among civil society actors vis-à-vis the mandate and work of the Mechanism."},{"id":"a-hrc-45-60-p0024","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"24","seq":25,"section":"B. Engagement with relevant stakeholders and public outreach","text":"As part of the Mechanism’s engagement and public outreach efforts, the Mechanism\nhas consistently engaged with and provided regular briefings to representatives of relevant\nstakeholders in Geneva and New York at the ambassadorial and working levels. The\nMechanism has also provided briefings to representatives of Member States in their capital\ncities and to regional and intergovernmental organizations, and it has engaged in dialogue\nwith United Nations entities and civil society actors and non-governmental organizations\nbased in the Asia-Pacific region and elsewhere."},{"id":"a-hrc-45-60-p0025","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"25","seq":26,"section":"B. Engagement with relevant stakeholders and public outreach","text":"In November and December 2019, the Head of the Mechanism led a delegation to\nthe Asia-Pacific region in order to meet with relevant national authorities and\nrepresentatives of United Nations entities, with a view to introducing the Mechanism’s\nmandate, identifying areas of potential cooperation and seeking operational support for its\nactivities."},{"id":"a-hrc-45-60-p0026","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"26","seq":27,"section":"B. Engagement with relevant stakeholders and public outreach","text":"In October 2019, the Mechanism issued a factsheet containing basic information\nabout the establishment of the Mechanism and its mandate. The factsheet also highlighted\nhow the Mechanism differs from the independent international fact-finding mission on\nMyanmar, established by the Council in its resolution 34/22, and the International Criminal\nCourt. The factsheet is available in print in the English, Myanmar and Jinghphaw languages,\nas well as in audio in the Rohingya language on the Mechanism’s website. The purpose of\nthe factsheet is to provide responses to frequently asked questions from interested\nstakeholders and to address common issues of confusion that stakeholders have about the\nMechanism."},{"id":"a-hrc-45-60-p0027","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"27","seq":28,"section":"B. Engagement with relevant stakeholders and public outreach","text":"In May 2020, the Mechanism issued its inaugural bulletin in the English and\nMyanmar languages, providing, inter alia, an explanation of the Mechanism’s mandate, an\nupdate on the progress of the work of the Mechanism and highlights of particular initiatives.\nIn July 2020, the Mechanism launched its official website in both the English and Myanmar\nlanguages to further bolster its public outreach efforts."},{"id":"a-hrc-45-60-p0028","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"28","seq":29,"section":"B. Engagement with relevant stakeholders and public outreach","text":"The Mechanism had initially planned to conduct more high-level engagement and\noutreach visits in 2020 to States where there may be relevant stakeholders and/or\ninformation present, or where the Mechanism foresees that it will conduct its activities.\nHowever, owing to the restrictions on movement and travel, the unavailability of flights,\nand the risks to the health and safety of interlocutors and Mechanism personnel posed by\nthe COVID-19 pandemic, the Mechanism has been unable to have meetings in person since\nmid-March 2020 and its staff members have been unable to travel."},{"id":"a-hrc-45-60-p0029","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"29","seq":30,"section":"B. Engagement with relevant stakeholders and public outreach","text":"Instead, the Mechanism has had to adapt and rely on technology, as well as on\ncreative and innovative methods, in order to continue its engagement with relevant\nstakeholders around the world. In this regard, the Mechanism has made every effort to\nensure that any such engagement would be conducted in a manner that was safe and secure\nfor both stakeholders and Mechanism personnel, and that any sensitive information that was\nexchanged as part of such engagement would remain confidential."},{"id":"a-hrc-45-60-p0030","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"30","seq":31,"section":"C. Implementation of its mandate","text":"Since its previous report to the Human Rights Council, the Mechanism has taken\nsignificant steps forward in implementing its mandate to collect, consolidate, preserve and\nanalyse evidence of the most serious international crimes and violations of international law\ncommitted in Myanmar since 2011, and to prepare files in order to facilitate and expedite\nfair and independent criminal proceedings, as well as the development of the necessary\ninfrastructure to support such activities."},{"id":"a-hrc-45-60-p0031","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"31","seq":32,"section":"C. Implementation of its mandate","text":"With regard to the Government of Myanmar, the Mechanism continues to seek\nopportunities to engage with the country’s Permanent Missions to the United Nations in\nGeneva and New York. The Mechanism has also transmitted written communications to the\nGovernment to seek information regarding matters within the Mechanism’s mandate.\nFurthermore, when visiting the Asia-Pacific region in December 2019, the Head of the\nMechanism requested to visit Myanmar in order to meet with government representatives\nbut did not receive any response in that regard. The Mechanism continues to reach out and\nseek a cooperative relationship with Myanmar.\nDevelopment of infrastructure to support its mandated activities"},{"id":"a-hrc-45-60-p0032","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"32","seq":33,"section":"C. Implementation of its mandate","text":"The Mechanism has been working on the development and adoption of internal\npolicies, protocols, procedures and methods of work, based on the highest possible\nstandards, consistent with: the Charter of the United Nations; United Nations rules,\nregulations, policies and best practices; relevant international law and standards, including\nhuman rights law, notably the right to a fair trial and other due process provisions; and\nrelevant jurisprudence. As required by its terms of reference, the Mechanism is also\ndrawing upon the good practices of other comparable international accountability\nmechanisms. The purpose is to ensure the broadest possible usability and admissibility of\nevidence and material in national, regional or international courts or tribunals."},{"id":"a-hrc-45-60-p0033","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"33","seq":34,"section":"C. Implementation of its mandate","text":"The COVID-19 pandemic has not disrupted the drafting and development of these\ninternal documents, and the Mechanism remains on track to complete and adopt them in\nline with its workplan."},{"id":"a-hrc-45-60-p0034","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"34","seq":35,"section":"C. Implementation of its mandate","text":"The Mechanism has also been taking measures to expand its physical and digital\nstorage capacity and to implement the most up-to-date information technology system with\nthe necessary protections for information security and cybersecurity."},{"id":"a-hrc-45-60-p0035","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"35","seq":36,"section":"C. Implementation of its mandate","text":"The Mechanism is in the process of developing its evidence management framework,\nin line with United Nations standards, which will govern the Mechanism’s handling of the\ninformation, documentation and evidence it receives and collects. As part of the\ndevelopment of this framework, the Mechanism has established an initial electronic\ninfrastructure to safely store material that it currently receives and collects. The Mechanism\nhas procured a suite of electronic discovery tools, which will equip the Mechanism with the\nnecessary capabilities to set up an information governance system that will facilitate the\nidentification, collection, preservation, processing, review, analysis and production of\nelectronically stored information."},{"id":"a-hrc-45-60-p0036","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"36","seq":37,"section":"C. Implementation of its mandate","text":"As part of its information security and cybersecurity efforts, the Mechanism has also\nacquired equipment and hardware that are secured by encryption and strict administrative\ncontrols. In addition, the Mechanism has established a cybersecurity programme that covers\nnot only the Mechanism’s information storage systems, but also the security of the\nequipment used by personnel. This programme includes the capability to respond quickly to\nany cybersecurity incidents as well as awareness-building and training programmes to\nensure that Mechanism personnel are regularly updated on cybersecurity issues and\nprotective measures. The progress of the cybersecurity programme is regularly monitored\nby an internal Risk Management Board."},{"id":"a-hrc-45-60-p0037","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"37","seq":38,"section":"C. Implementation of its mandate","text":"While the COVID-19 pandemic has disrupted some of the Mechanism’s ongoing\nprocesses, this was not the case for the information security and cybersecurity aspects of the\nMechanism’s work, which intensified in order to respond to the additional need for such\nservices owing to the pandemic. In early March 2020, when it became apparent that regular\naccess to its premises might not be possible for an extended period of time, the Mechanism\nquickly prepared the necessary infrastructure, assessed the security of its equipment, and\ndeveloped policies and modalities so that its personnel could work remotely in a secure\nmanner. When its premises closed in mid-March 2020 and a full-time remote working\narrangement was put in place for all personnel, the Mechanism was able to continue its\noperations in a secure manner, with little or no interruption.\nCollection, consolidation, preservation and analysis of information, documentation\nand evidence, and the building of case files"},{"id":"a-hrc-45-60-p0038","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"38","seq":39,"section":"C. Implementation of its mandate","text":"As regards the collection of information, documentation and evidence, in September\n2019, the Mechanism received copies of all material in the possession of the independent\ninternational fact-finding mission on Myanmar for which consent to share with the\nMechanism had been obtained from the providers of the information."},{"id":"a-hrc-45-60-p0039","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"39","seq":40,"section":"C. Implementation of its mandate","text":"In addition, the Mechanism has been identifying other entities and individuals that\nmay be in possession of relevant information or be in a position to provide support for the\nMechanism’s activities. Among them are any national authority, United Nations entity,\ninternational organization, non-governmental organization, civil society actor and entity\nthat is engaged in investigative, fact-finding and reporting activities. It is crucial that the\nMechanism engages with and receives the cooperation of such entities for the provision of\nrelevant information and support."},{"id":"a-hrc-45-60-p0040","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"40","seq":41,"section":"C. Implementation of its mandate","text":"In general, once such entities or individuals are identified, the Mechanism proceeds\nto make formal requests for specific categories or types of information relevant to its\nmandate. The Mechanism also engages in dialogue regarding the conditions under which\nthe information could be provided and potentially shared in the future with national,\nregional or international judicial authorities. If requested by the providing entity or if the\nMechanism foresees that it will make multiple requests for information to a particular entity,\nthe Mechanism may also negotiate frameworks for cooperation to set out the applicable\nmodalities."},{"id":"a-hrc-45-60-p0041","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"41","seq":42,"section":"C. Implementation of its mandate","text":"Since its previous report to the Council, the Mechanism has issued 18 formal\nrequests for information to a variety of entities and individuals and has received\ninformation and materials from several entities or individuals. As stated above, the\nindependent international fact-finding mission on Myanmar transferred information, which\nit had collected from witnesses and other information providers, to the Mechanism upon the\nmission’s completion of its mandate. In this regard, the Mechanism contacted a number of\nwitnesses and other information providers to obtain informed consent for the Mechanism to\npotentially share their information with relevant entities in the future. Additionally, the\nMechanism is currently in the process of negotiating two frameworks for cooperation,\nwhich would cover the provision of information to the Mechanism and the conduct of\ninterviews."},{"id":"a-hrc-45-60-p0042","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"42","seq":43,"section":"C. Implementation of its mandate","text":"It is important to note that the Mechanism seeks both inculpatory and exculpatory\nevidence. Exculpatory evidence could include: information that would indicate that events\ndid not amount to a serious international crime or a violation of international law; or\nevidence that impacts on the credibility of witnesses. It could also include evidence of any\nefforts by those in leadership roles to prevent crimes or to punish those responsible for\ncrimes through genuine investigations and, where appropriate, prosecutions of those\nresponsible for crimes. The Mechanism welcomes information from Myanmar on all such\ndomestic investigations and prosecutions relevant to its mandate and will continue to reach\nout and seek access."},{"id":"a-hrc-45-60-p0043","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"43","seq":44,"section":"C. Implementation of its mandate","text":"In addition, as part of its collection and consolidation work, the Mechanism\ncontinues to identify and gather relevant material from open sources, including from the\nInternet, news media, public reporting and social media. The Mechanism has also been\nbuilding up its expertise in open source investigations through partnerships with relevant\nprofessional and academic institutions, as well as through the specialized training of its\npersonnel."},{"id":"a-hrc-45-60-p0044","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"44","seq":45,"section":"C. Implementation of its mandate","text":"Given that its mandate is ongoing and covers any serious international crimes or\nviolations of international law committed in Myanmar since 2011, the Mechanism also\nconducts contemporaneous monitoring of developments in Myanmar that may be relevant\nto its mandate. This process enables the Mechanism to become quickly aware of specific,\npotentially relevant incidents and events as they occur in Myanmar, and to prioritize\nincidents that warrant continued monitoring or investigation. The monitoring process also\nfacilitates the formulation of the above-mentioned requests for information by enabling the\nprompt identification of potentially relevant information that may be in the possession of\ncertain Member States, individuals or entities."},{"id":"a-hrc-45-60-p0045","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"45","seq":46,"section":"C. Implementation of its mandate","text":"In addition to the ongoing processes discussed above, the Mechanism continues to\nreview and analyse the material in its possession in order to identify evidence for inclusion\nin case files that could be shared with national, regional or international courts or tribunals\nwith the requisite jurisdiction. One of the main priorities of the Mechanism thus far has\nbeen to analyse and assess the material it received from the independent international fact-\nfinding mission on Myanmar."},{"id":"a-hrc-45-60-p0046","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"46","seq":47,"section":"C. Implementation of its mandate","text":"As regards the impact of the COVID-19 pandemic on the Mechanism’s substantive\nmandate, the Mechanism was able to quickly adjust and adapt the majority of its collection,\nconsolidation, preservation, analysis and monitoring activities in order for them to be\nsecurely conducted by Mechanism personnel working remotely. Nonetheless, the\nmovement and travel restrictions, which were imposed worldwide as a result of the\npandemic, have caused significant uncertainty regarding the Mechanism’s ability to travel\nin the near future to locations where potential information sources and witnesses may be\nlocated and to meet directly with them. While the use of videoconferencing has been useful,\nthe Mechanism remains restricted by its need to ensure the safety and security of its\ninterlocutors, as well as the fact that not all interlocutors may have Internet access or\nsufficient data coverage in order to communicate with the Mechanism through such means."},{"id":"a-hrc-45-60-p0047","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"47","seq":48,"section":"C. Implementation of its mandate","text":"In light of the above, the Mechanism has focused its efforts during the COVID-19\npandemic on the identification of potential information sources that can be contacted\nsecurely via electronic means, and on the collection and consolidation of information,\ndocumentation and evidence through open source investigations and written requests for\ninformation. At the same time, the Mechanism continues to prepare and plan for\ninvestigative missions in the future. Before deploying on such missions, the Mechanism\nwill consider any restrictions related to the pandemic, any risk of Mechanism personnel on\nmission transmitting the virus, the safety and health of its potential interlocutors, and the\nhost State’s requirements and views.\nSharing of information, documentation and evidence"},{"id":"a-hrc-45-60-p0048","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"48","seq":49,"section":"C. Implementation of its mandate","text":"As regards the sharing aspect of its mandate, the Mechanism provided materials\nreceived from the independent international fact-finding mission on Myanmar, in response\nto a request from a prosecutorial authority. This was done in line with the Mechanism’s\nmandate and with the consent of the parties that had originally provided the information to\nthe mission."},{"id":"a-hrc-45-60-p0049","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"49","seq":50,"section":"C. Implementation of its mandate","text":"The Mechanism also received requests from two Member States for information and\ndocumentation to be used in ongoing proceedings before the International Court of Justice.\nIn accordance with the Mechanism’s mandate and its terms of reference, the Mechanism\nhas commenced the process of sharing materials relevant to these proceedings, with the\nconsent of the parties that provided the information and documentation."},{"id":"a-hrc-45-60-p0050","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"50","seq":51,"section":"III. Strategy and plans moving forward","text":"The Mechanism’s workplan strategizes, prioritizes and puts in sequence concrete\nsteps to advance the mandate, with both short-term goals for 2020 and 2021 and long-term\ngoals for the period beyond. This will be further elaborated below."},{"id":"a-hrc-45-60-p0051","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"51","seq":52,"section":"III. Strategy and plans moving forward","text":"In this regard, the Mechanism notes that its ability to carry out a key component of\nits work – that is, to conduct missions for engagement and evidence-collection purposes – is\nuncertain owing to the global COVID-19 pandemic. Despite the current restrictions and\nlimitations, the Mechanism continues to implement its mandate to the best of its ability, and\nit will seek to adjust and adapt its operations and processes in accordance with any changes\nin circumstances."},{"id":"a-hrc-45-60-p0052","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"52","seq":53,"section":"A. Further expansion of its collection, consolidation, preservation and","text":"In order to expand the Mechanism’s database of material related to crimes falling\nwithin its mandate, the Mechanism will increase its efforts and activities in the collection of\ninformation, documentation and evidence. Additionally, it will also expand the scope of its\nengagement with potential information sources and providers through the use of innovative\nand flexible solutions. Open source investigations and monitoring of events in Myanmar,\nincluding efforts by the authorities to prevent or punish crimes, will also continue."},{"id":"a-hrc-45-60-p0053","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"53","seq":54,"section":"A. Further expansion of its collection, consolidation, preservation and","text":"Through its collection and analysis work, the Mechanism will also continue to\nidentify and prioritize areas of investigation, incidents or cases, which will in turn guide the\nMechanism’s future collection efforts. In this regard, the Mechanism will take into\nconsideration a number of relevant factors, such as the scale and gravity of crimes; the\ncommission of sexual and gender-based crimes; the impact of crimes on particularly\nvulnerable groups, including children; the Mechanism’s likely access to the victims and\nwitnesses of the crimes, which is needed to build viable case files; and whether the\nMechanism’s case selection reflects the geographic and ethnic diversity of Myanmar. The\nstrategy will also seek to devote the Mechanism’s limited resources to activities where there\nis accessible evidence, which can lead to building viable case files proving individual\ncriminal responsibility."},{"id":"a-hrc-45-60-p0054","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"54","seq":55,"section":"A. Further expansion of its collection, consolidation, preservation and","text":"Based on its investigative priorities, the Mechanism will also continue to identify\nwitnesses who may have relevant information vis-à-vis those priorities. In this regard, the\nMechanism will seek to prioritize the conduct of interviews with witnesses who may have\nrelevant first-hand information regarding the commission of serious international crimes\nand violations of international law in Myanmar since 2011, but who have yet to provide\nwitness testimony to other entities involved in various accountability processes. In\nscreening and selecting the witnesses for interview, the Mechanism will also carefully\nassess each witness, taking into account various factors such as the potential relevance of\nthat testimony, the safety and security of the witness, and the risk of re-traumatizing the\nwitness."},{"id":"a-hrc-45-60-p0055","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"55","seq":56,"section":"A. Further expansion of its collection, consolidation, preservation and","text":"In support of the above-mentioned activities, the Mechanism will continue its efforts\nto negotiate and conclude cooperation frameworks or modalities with potential information\nproviders, which will set out streamlined and efficient channels and procedures for the\nprovision of material to the Mechanism."},{"id":"a-hrc-45-60-p0056","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"56","seq":57,"section":"A. Further expansion of its collection, consolidation, preservation and","text":"In addition to its collection activities, the Mechanism will similarly expand its\nanalysis of the material it already possesses and of new information, documentation and\nevidence that it receives. The Mechanism will use its new electronic discovery system to\ndetermine the relevance of the evidence in its possession, which will ultimately enable the\nMechanism to develop case files more efficiently and effectively."},{"id":"a-hrc-45-60-p0057","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"57","seq":58,"section":"B. Missions for engagement and collection of information, documentation","text":"Given that the seat of the Mechanism is located in Geneva, and that most of the\nevidence, witnesses and information sources are in or near the locations where the crimes\nwere committed – in particular in Myanmar or in the Asia-Pacific region – the Mechanism\nwill need to work with host States and devise strategies in order to gain access to persons\nwho can provide evidence safely and effectively."},{"id":"a-hrc-45-60-p0058","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"58","seq":59,"section":"B. Missions for engagement and collection of information, documentation","text":"As a first step, therefore, the Mechanism intends to continue conducting high-level\nmissions to relevant Member States in whose territories it expects to conduct its activities.\nThe main purpose of such missions will be to engage in a dialogue with Governments of\nMember States regarding the mandate of the Mechanism and its needs as regards any\nactivities conducted within their territories, as well as to encourage them to support and\nfacilitate the conduct of such activities. These engagements will be carried out in a manner\nthat takes into account the sensitive and confidential nature of the Mechanism’s work."},{"id":"a-hrc-45-60-p0059","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"59","seq":60,"section":"B. Missions for engagement and collection of information, documentation","text":"The Mechanism will also continue its efforts to engage with the Government of\nMyanmar, in seeking its cooperation with respect to the implementation of the\nMechanism’s mandate, in particular, granting the Mechanism access to the territory of\nMyanmar."},{"id":"a-hrc-45-60-p0060","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"60","seq":61,"section":"B. Missions for engagement and collection of information, documentation","text":"Building upon these high-level engagement missions and with the agreement of the\nhost State Governments, the Mechanism also intends to conduct substantive missions to\nrelevant Member States in order to collect information, documentation and evidence,\nincluding through interviews with witnesses who are located in those territories."},{"id":"a-hrc-45-60-p0061","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"61","seq":62,"section":"B. Missions for engagement and collection of information, documentation","text":"Before conducting any such missions, the Mechanism will develop clear objectives\nfor the mission, which will guide the priorities of the mission, as well as the specific\nactivities to be undertaken on the ground. Mission plans will also be accompanied by a\nsecurity assessment, which will take into account the safety and security of witnesses,\ninterlocutors and Mechanism personnel. Similarly, these missions will be conducted in a\ndiscreet manner, so as to ensure the confidentiality of the Mechanism’s activities and\ncollected information."},{"id":"a-hrc-45-60-p0062","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"62","seq":63,"section":"C. Sharing of information, documentation and evidence","text":"Moving forward, the Mechanism will continue to engage with the prosecution\nauthority and the two Member States, from which it had previously received requests for\nthe sharing of information, documentation and evidence. In this regard, the Mechanism will\ncontinuously assess how it may be of further assistance to these entities in line with its\nmandate and terms of reference."},{"id":"a-hrc-45-60-p0063","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"63","seq":64,"section":"C. Sharing of information, documentation and evidence","text":"As stated in the Mechanism’s previous report, it is important to reiterate that the\nMechanism is not a court. It is thus dependent upon competent authorities of national,\nregional and international courts or tribunals to commence criminal proceedings in relation\nto the most serious international crimes and violations of international law committed in\nMyanmar since 2011, and for those authorities to make a request to the Mechanism for the\nsharing of information, documentation and evidence. In order to maximize the use of the\nevidence it collects and to contribute to criminal accountability processes, the Mechanism\nwill proactively keep itself abreast of any ongoing activities, investigations or legal\nproceedings that may be relevant to its mandate. It will also provide briefings to any\ninterested and relevant entities as regards the Mechanism’s evidence system."},{"id":"a-hrc-45-60-p0064","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"64","seq":65,"section":"D. Procurement of necessary technical equipment, software and","text":"In order to expand on its activities above, the Mechanism will ensure that it has the\nnecessary technical equipment, software and capabilities to carry out its work in a safe and\nsecure manner. This pertains not only to the safety and security of its interlocutors and\nMechanism personnel, but also the integrity of its evidence and the protection of the\nevidence from any cyberattacks."},{"id":"a-hrc-45-60-p0065","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"65","seq":66,"section":"D. Procurement of necessary technical equipment, software and","text":"With regard to the processing of evidence, the Mechanism will procure the\nnecessary software and equipment to process and record all the new material it receives or\ncollects, as well as the relevant metadata. Specifically, the Mechanism will have a\ndedicated laboratory for the processing of forensic data in its newly constructed office\npremises, which will enable the performance of advanced analysis and processing of any\nmaterial it receives. The Mechanism is also assessing its needs with regard to its analysis\nwork so as to determine whether it will require any other enabling technology, for example,\nvideo and image analysis software."},{"id":"a-hrc-45-60-p0066","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"66","seq":67,"section":"D. Procurement of necessary technical equipment, software and","text":"As regards the preservation and storage of material, the Mechanism will have a\nsecure physical storage facility as part of its newly constructed office premises, with\nvarious layers of security protections, for its physical and digital evidence. This facility will\ncomplement the electronic discovery system that the Mechanism is currently using."},{"id":"a-hrc-45-60-p0067","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"67","seq":68,"section":"D. Procurement of necessary technical equipment, software and","text":"In addition, in order to support the sharing aspect of its mandate, the Mechanism is\nin the process of procuring a secured data storage solution. Once in place, it will bolster the\ninformation security and cybersecurity of the incoming and outgoing flows of material.\nThis will allow the Mechanism to ensure the confidentiality and security of the material it\nreceives from information sources; the material it shares with any recipient entities; and any\nidentifying information related to any transfer of such material."},{"id":"a-hrc-45-60-p0068","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"68","seq":69,"section":"D. Procurement of necessary technical equipment, software and","text":"To support its substantive work, the Mechanism has sought to streamline and adjust\nits organigram and positions so as to ensure that it will have the necessary expertise to\nimplement its mandate in line with its vision and priorities. The Mechanism aims to become\nfully staffed as soon as possible, which will further bolster the Mechanism’s collection,\nanalysis and case-building capabilities. Being fully staffed will also increase its specific\nexpertise, including with regard to victim and witness protection, forensics, and the security\nand safety of its personnel. In line with its terms of reference, due consideration will be\ngiven to the representation of different legal traditions, geographic diversity, gender balance,\nregional expertise and relevant language skills."},{"id":"a-hrc-45-60-p0069","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"69","seq":70,"section":"D. Procurement of necessary technical equipment, software and","text":"In line with its training policy, the Mechanism will also ensure that its personnel\nreceive relevant training on a regular basis so that their skills are up-to-date and further\nenhanced to support the implementation of the Mechanism’s mandate. Such training will\ncover new modes of evidence collection as well as new technology relevant to its\nsubstantive mandate."},{"id":"a-hrc-45-60-p0070","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"70","seq":71,"section":"E. Engagement with relevant stakeholders and public outreach","text":"The Mechanism will continue to implement its engagement and public outreach\nstrategy and to adjust it accordingly, in order to ensure that it is capable of providing up-to-\ndate and accurate information regarding the Mechanism to its various stakeholders."},{"id":"a-hrc-45-60-p0071","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"71","seq":72,"section":"E. Engagement with relevant stakeholders and public outreach","text":"The Mechanism will continue to issue its bulletin periodically. The Mechanism will\nalso regularly update its website in order to inform interested stakeholders of recent\ndevelopments about the Mechanism. Taking into account the common platforms that are\nfavoured by relevant stakeholders and by the people of Myanmar, the Mechanism will also\nassess the need for a social media presence."},{"id":"a-hrc-45-60-p0072","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"72","seq":73,"section":"E. Engagement with relevant stakeholders and public outreach","text":"In addition to high-level missions for engagement in the Asia-Pacific region, the\nMechanism will engage regularly with representatives of Member States in Geneva and\nNew York, as well as in their capital cities. Furthermore, the Mechanism will update\nrelevant regional organizations regarding its progress and seek their continued support for\nits work. The Mechanism will also provide briefings, as requested, to interested Member\nStates and to regional and international organizations."},{"id":"a-hrc-45-60-p0073","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"73","seq":74,"section":"IV. Conclusion","text":"In the year since its establishment, the Mechanism has made significant progress in\nsetting up its core infrastructure and ramping up its substantive activities in support of the\nimplementation of its mandate, despite the global COVID-19 pandemic. The Mechanism\nwill build upon its foundation and the momentum it has achieved so far, in order to forge\nahead with its planned activities. The main objective of the Mechanism in the next year will\nbe to expand and deepen its substantive work on all fronts, in particular by identifying\npriority cases and conducting missions to interview and collect evidence from witnesses\nand other information sources."},{"id":"a-hrc-45-60-p0074","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"74","seq":75,"section":"IV. Conclusion","text":"As the Mechanism’s substantive activities increase, the risks with respect to the\nintegrity, safety and security of its operations and personnel, its interlocutors, and the\nevidence in its possession will naturally increase as well. It is crucial that the Mechanism\nhas the necessary resources to continue recruiting personnel with the necessary expertise to\nminimize the risks associated with its mandated activities. The Mechanism will also require\nthe cooperation and support of relevant Member States."},{"id":"a-hrc-45-60-p0075","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"75","seq":76,"section":"IV. Conclusion","text":"While the Mechanism will remain guided by its strategy and priorities for the near\nfuture, the world has been in a constant state of flux as a result of the COVID-19 pandemic.\nThe impact and consequences of the pandemic will certainly continue to linger and\nnegatively affect the territories, communities and entities that the Mechanism will work in\nor with. As a result, the Mechanism will continuously assess the relevant circumstances,\nreview its methods, identify areas where it can improve and adopt creative and flexible\nsolutions to remove any obstacles in its way and collect all relevant evidence in an efficient\nand effective manner."},{"id":"a-hrc-45-60-p0076","rec_id":"reckBXvdas9z8Zrmr","symbol":"A/HRC/45/60","n":"76","seq":77,"section":"IV. Conclusion","text":"The Mechanism is fully cognizant of how important the pursuit of accountability for\nthe crimes committed in Myanmar is to the victims of those crimes. It is thus crucial that\nthe Mechanism continue to fulfil its mandate and play its significant role in the criminal\naccountability process by facilitating and supporting criminal proceedings. However, the\nMechanism cannot do this alone. It will require the continued support and assistance of all\nparts of the international community, in order to ensure it can fully achieve the purpose for\nwhich it was established."},{"id":"a-hrc-48-18-u0000","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":null,"seq":0,"section":null,"text":"United Nations                                                                                A/HRC/48/18\nGeneral Assembly                                                        Distr.: General\n5 July 2021","unnumbered":true},{"id":"a-hrc-48-18-u0001","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":null,"seq":1,"section":null,"text":"Summary\nThe present document is the third report submitted by the Independent Investigative\nMechanism for Myanmar to the Human Rights Council pursuant to resolution 39/2 of 27\nSeptember 2018, in which the Council established the Mechanism. The report covers\nactivities from 8 July 2020 (the date of the previous report to the Council) to 15 June 2021.\nThe Mechanism has laid a strong foundation for its work since it became operational\non 30 August 2019. Surmounting operational challenges arising from the coronavirus disease\n(COVID-19) pandemic and restrictions owing to liquidity constraints, it has reached a critical\nlevel of functionality and built a team and infrastructure capable of effectively and efficiently\nimplementing its complex and technical mandate. The Mechanism has established a secure\nand sophisticated electronically stored information management system to electronically\ncollect, preserve, process and analyse evidence; significantly expanded its collection of\ninformation and evidence using specialized and the most up-to-date technological tools;\nengaged in outreach to key stakeholders; and recruited personnel with a diverse range of\nexpertise and specializations. To address ongoing challenges and new circumstances, the\nMechanism adopted alternative measures and innovations, making use of technology,\ncreative strategies and flexible work arrangements.\nWithin the scope of its mandate, the Mechanism has been closely monitoring the\nsituation in Myanmar following the military’s seizure of power on 1 February 2021,\nparticularly reports of widespread instances of arbitrary arrest, torture, enforced\ndisappearance, extrajudicial killing and use of force against peaceful protestors. While\nadjustments to planned activities have been necessary in order to cope with the consequent\ninflux of information and rapidly evolving events, the Mechanism has continued to make\nprogress in collecting evidence relating to earlier events. It has ensured that its resources and\ncapacities continue to be used strategically to advance investigations on all priority\nsituations, including information regarding the situation of the Rohingya population and\nother situations throughout Myanmar. This is in line with the Mechanism’s commitment to\nits core principles of independence and impartiality, pursuing all situations, incidents,\npersons and entities within its mandate.\nBuilding on its achievements to date, the Mechanism will continue to expand its\nsubstantive work, intensify its engagements, and bolster its operations to make it possible to\nbring to justice the perpetrators of the most serious international crimes in Myanmar.","unnumbered":true},{"id":"a-hrc-48-18-p0001","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"1","seq":2,"section":"I. Introduction","text":"In its resolution 39/2 of 27 September 2018, the Human Rights Council established\nthe Independent Investigative Mechanism for Myanmar with a mandate to collect,\nconsolidate, preserve and analyse evidence of the most serious international crimes and\nviolations of international law committed in Myanmar since 2011, and to prepare files in\norder to facilitate and expedite fair and independent criminal proceedings, in accordance with\ninternational law standards, in national, regional or international courts or tribunals. In its\nresolution 73/264 of 22 December 2018, the General Assembly welcomed the establishment\nof the Mechanism. In a letter dated 27 August 2019 to the President of the Human Rights\nCouncil, the Secretary-General deemed the Mechanism to be operational as of 30 August\n2019. The Council, in its resolution 42/3 of 26 September 2019, and the Assembly, in its\nresolution 74/246 of 27 December 2019, welcomed the Mechanism’s entry into operation. In\nits resolution 43/26 of 22 June 2020, the Council specifically called for the Mechanism to\nengage in close and timely cooperation on future investigations by, among others, the\nInternational Criminal Court or the International Court of Justice."},{"id":"a-hrc-48-18-p0002","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"2","seq":3,"section":"I. Introduction","text":"In less than two years, the Mechanism has developed crucial substantive and\noperational capabilities to enable it to make important progress in implementing its mandate\nand advancing the priorities articulated in the strategy set out in its previous report to the\nHuman Rights Council.1 Yet ongoing challenges and new developments in Myanmar have\nsignificantly shaped these priorities, requiring rapid adjustments to operations and creative\nsolutions. The coronavirus disease (COVID-19) pandemic has continued to restrict the\nMechanism’s activities, including its ability to travel to engage with relevant stakeholders to\ncollect and verify evidence, enable cooperation, and advance its outreach efforts, especially\nto witness and victim groups. Reports of widespread instances of arbitrary arrest, torture,\nenforced disappearance, extrajudicial execution and use of force against peaceful protesters\nfollowing the military’s seizure of power on 1 February 2021 in Myanmar have given rise to\nan unprecedented influx of information related to alleged crimes within the Mechanism’s\nmandate that warrant careful monitoring, collection, verification and analysis."},{"id":"a-hrc-48-18-p0003","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"3","seq":4,"section":"I. Introduction","text":"The Mechanism has been following with deep concern the recent events in Myanmar\nand has reiterated calls expressed by the Secretary-General and other United Nations\nrepresentatives for an end to the violence. The recent events are a stark reminder of the\ndangers of impunity and the need to ensure accountability for all those who have committed\nserious international crimes, in order to break the cycle of violence and protect all the peoples\nof Myanmar. The Mechanism is committed to fulfilling its unique role and will continue to\nactively engage with all parts of the international community, in particular Member States in\nthe region, in order to fully achieve the purpose for which it was created to facilitate justice\nand accountability for past serious crimes within its mandate and contribute to the deterrence\nof further atrocities."},{"id":"a-hrc-48-18-p0004","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"4","seq":5,"section":"II. Progress on the strategic priorities of the Mechanism","text":"In 2020, the Mechanism adopted a comprehensive strategy to ensure that it was well\npositioned to achieve full functionality and deliver on its mandate. As detailed in its previous\nreport to the Council, the strategy focused the Mechanism’s available resources and\ncapabilities on the following institutional priorities: expanding the collection and analysis of\ninformation and evidence; increasing the availability of evidence and analytical documents\nfor sharing with courts and tribunals; advancing the development of cooperation frameworks\nwith new information and assistance providers; and increasing the visibility of the\nMechanism and strengthen the understanding of its mandate by relevant stakeholders, in\nparticular witness and victims’ groups. Despite the effects of the COVID-19 pandemic, the\nMechanism made important progress in multiple areas."},{"id":"a-hrc-48-18-p0005","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"5","seq":6,"section":"A. Expansion of the collection and preservation of evidence","text":"The Mechanism aims to conduct the collection of information and evidence\nobjectively and professionally, pursuing all situations, incidents, persons and entities within\nits mandate. To date, the Mechanism has collected and processed for potential sharing over\n1.3 million information items from a broad range of sources and covering a variety of formats,\nincluding documents, photographs, videos, geospatial imagery, witness statements and open-\nsource materials. The Mechanism collected and processed the majority of this information –\nover 900,000 information items – after 1 January 2021. Several factors contributed to these\nresults, including a strategic orientation of investigative priorities, targeted identification of\npotential information providers, continued monitoring of ongoing developments in Myanmar,\nthe development of capabilities for open-source investigations, and the establishment of a\nsecure and state-of-the-art electronically stored information management system.\nInvestigative priorities"},{"id":"a-hrc-48-18-p0006","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"6","seq":7,"section":"A. Expansion of the collection and preservation of evidence","text":"Taking into account the scope, complexity and diversity of the Myanmar context and\ncontinuing constraints, the Mechanism continued to develop its investigative activities in a\nmanner that focused on accessible information and evidence while also building the\nfoundation for longer-term collection and verification efforts. Given the impossibility of\ninvestigating all of the crimes committed in Myanmar, the Mechanism developed a specific\nstrategy for prioritizing the collection and verification of evidence concerning selected\nsituations, incidents and individuals and groups suspected of perpetrating crimes. The\nobjective is to deploy limited resources in a manner that will allow the Mechanism to build\nviable case files proving individual criminal responsibility that are representative of the\ncrimes committed against various groups in Myanmar. Investigations are prioritized on the\nbasis of several substantive and operational criteria. These include the scale, nature, manner\nof commission and impact of the crimes, including sexual and gender-based crimes and\ncrimes against children; the degree of responsibility of alleged perpetrators; the prospect of\nan investigation meeting international criminal standards; and the likelihood of a court or\ntribunal taking jurisdiction over the crime(s) in question."},{"id":"a-hrc-48-18-p0007","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"7","seq":8,"section":"A. Expansion of the collection and preservation of evidence","text":"The strategy helps to guide the targeted identification of potential information sources\nand providers and the collection of information and evidence that is necessary to demonstrate\nindividual criminal responsibility. Based on an assessment of the materials received from the\nindependent international fact-finding mission on Myanmar, the Mechanism has already\nselected certain incidents and situations as priorities."},{"id":"a-hrc-48-18-p0008","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"8","seq":9,"section":"A. Expansion of the collection and preservation of evidence","text":"Investigating sexual and gender-based crimes and crimes against children is a priority\nfor the Mechanism. These crimes are among the gravest of international crimes and require\ntargeted outreach and dedicated expertise. The Mechanism’s investigation strategy ensures\nthat these crimes continue to be integrated in all investigations, are given particular attention\nfrom the outset, and that their full range of criminality, gravity and impact is holistically\naddressed alongside other conduct, incidents and patterns of crimes, such as the Rohingya\ncrisis and ethnic conflicts prevailing in northern Myanmar."},{"id":"a-hrc-48-18-p0009","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"9","seq":10,"section":"A. Expansion of the collection and preservation of evidence","text":"The COVID-19 pandemic continued to have an impact on the implementation of the\ninvestigation strategy, most notably by preventing the Mechanism from travelling to\nlocations where potential information providers and witnesses are located. This has curtailed\na vital element of the investigative process: verification of existing information and evidence\nin the Mechanism’s possession and the conduct of in-person data collection and interviews\nof witnesses who may have first-hand information regarding the commission of crimes falling\nwithin the Mechanism’s mandate. Where possible, the Mechanism continued to place\nemphasis on the identification of potential information sources that could be contacted\nthrough secure electronic means, scaling up the collection and consolidation of information\nand evidence through open-source investigations and identifying potential witnesses for\nfuture in-person interviews."},{"id":"a-hrc-48-18-p0010","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"10","seq":11,"section":"A. Expansion of the collection and preservation of evidence","text":"In this regard, the Mechanism has made every effort to ensure that any such\nengagement is conducted in a safe and secure manner for both stakeholders and Mechanism\npersonnel, and that any sensitive information that may be exchanged remains confidential. In\nidentifying potential witnesses for interview at a later date, the Mechanism continues to\ncarefully assess each individual, taking into account various factors, such as the potential\nrelevance of the individual’s testimony, the individual’s safety and security and the risk of\nretraumatizing the individual."},{"id":"a-hrc-48-18-p0011","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"11","seq":12,"section":"A. Expansion of the collection and preservation of evidence","text":"However, with respect to the forensic value of witness statements, there is no\nsubstitute for in-person interviews. Face-to-face interactions are the best method to ensure\nthe integrity of witness statements. They help build trust between the interviewer and the\nwitness and allow the interviewer to confirm that the witness is not under any duress or undue\ninfluence from outside parties. In-person interviews also guarantee the confidentiality of the\nprocess. They provide an opportunity for Mechanism personnel to address any concerns that\nwitnesses may have about their safety and security and to explain to witnesses how the\ninformation provided will be used. In-person interviews that result in a signed witness\nstatement are by far the best method to ensure the information’s usefulness and its broadest\npossible admissibility in national, regional and international courts or tribunals.\nTargeted identification of information providers"},{"id":"a-hrc-48-18-p0012","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"12","seq":13,"section":"A. Expansion of the collection and preservation of evidence","text":"The Mechanism continues to engage with a broad range of information and evidence\nproviders, including national authorities, United Nations entities, international organizations,\nnon-governmental organizations, civil society actors, corporate entities and individuals, with\nthe aim of securing the most relevant materials and information capable of advancing its\nmandate. Adjusting for the pandemic, most of these engagements were facilitated through\nsecure remote means."},{"id":"a-hrc-48-18-p0013","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"13","seq":14,"section":"A. Expansion of the collection and preservation of evidence","text":"Since it began operations, the Mechanism made dozens of formal requests for\ninformation to a variety of such entities and individuals. The majority of those to whom the\nrequests have been addressed have either provided information to the Mechanism or are\ncurrently in discussions about doing so. In addition, the Mechanism has continued its efforts\nto initiate cooperation with Member States that may be in possession of information relevant\nto the Mechanism’s mandate, including the authorities of Myanmar. Where applicable, the\nMechanism may negotiate cooperation arrangements to enable streamlined processes for the\nprovision of the material to the Mechanism, as set out below.\nMonitoring of developments in Myanmar"},{"id":"a-hrc-48-18-p0014","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"14","seq":15,"section":"A. Expansion of the collection and preservation of evidence","text":"As the Mechanism’s mandate is ongoing, the Mechanism also conducts\ncontemporaneous monitoring of developments in Myanmar that may constitute serious\ninternational crimes or violations of international law."},{"id":"a-hrc-48-18-p0015","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"15","seq":16,"section":"A. Expansion of the collection and preservation of evidence","text":"Since the military seized power on 1 February 2021, the Mechanism has experienced\nan exponential increase in communications from individuals and organizations seeking to\nshare information about alleged crimes and human rights violations in Myanmar. From these\nsubmissions, the Mechanism has collected over 210,000 information items, including videos,\nphotographs and documents. While the Mechanism was able to temporarily adjust and\nmobilize critical resources to address this unprecedented influx of information and work, the\nsituation exposed the need for additional resources and capacity, especially for the\ncollection and analysis of information and evidence gathered from open sources.\nScaling up open-source investigations"},{"id":"a-hrc-48-18-p0016","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"16","seq":17,"section":"A. Expansion of the collection and preservation of evidence","text":"The critical need to collect and analyse open-source information, such as videos,\nphotographs and geospatial imagery publicly available on the Internet or social media,\nconcerns both recent events in Myanmar and earlier incidents that appear to constitute serious\ninternational crimes and violations of international law. Open-source information is\nparticularly valuable for the Mechanism, as the authorities in Myanmar have consistently\ndenied the Mechanism access to its territory, preventing on-the-ground investigations in the\ncountry where the crimes were allegedly committed."},{"id":"a-hrc-48-18-p0017","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"17","seq":18,"section":"A. Expansion of the collection and preservation of evidence","text":"Given that the availability of open-source information is extensive and has continued\nto grow, especially after 1 February 2021, the Mechanism is mobilizing extrabudgetary\nresources in order to enhance its capacity to conduct open-source investigations. Specialized\ncapacity in open-source investigations will enable the Mechanism to use the most advanced\ntechniques to collect and analyse such information with efficiency, thoroughness and\naccuracy, as well as to systematically document investigative methods and preserve evidence\nin accordance with international best practices. It will also allow the Mechanism to keep\nabreast of some of the most innovative and ground-breaking advances taking place in\ninternational criminal law in the field of open-source investigations.\nElectronically stored information management systems and cybersecurity"},{"id":"a-hrc-48-18-p0018","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"18","seq":19,"section":"A. Expansion of the collection and preservation of evidence","text":"To facilitate the processing of the growing collection of information and evidence in\nthe Mechanism’s procession, the Mechanism took concrete steps to expand its physical and\ndigital storage capacity and to develop a state-of-the art electronically stored management\nsystem in line with United Nations standards and industry best practices. The system governs\nthe entire chain of the Mechanism’s processing of information and evidence in its possession,\nfrom collection to organization, preservation, review, analysis and preparation of files for\npotential sharing with third parties. This includes a robust system for the management of\npotential evidence, materials and information providers that facilitates the tracking of all\ninformation requested and collected by the Mechanism and/or shared with third parties. The\nMechanism has also improved the processing and accessibility of digital evidence, including\nthrough the use of analytical tools and technology services to facilitate the processing of\nspecialized videos and natural language material. Such tools will enhance the Mechanism’s\ncapacity to handle more complex data and evidence formats, such as documents, videos,\ndigital images and audio, including open-source materials."},{"id":"a-hrc-48-18-p0019","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"19","seq":20,"section":"A. Expansion of the collection and preservation of evidence","text":"The Mechanism has prioritized the protection of its information storage system,\nequipment and tools, which in turn contributes to the protection of its personnel and, crucially,\nthe individuals and organizations engaged by the Mechanism. It has implemented\nmethodologies and processes within the system to ensure the necessary information security\nand cybersecurity, the integrity of the evidence and the required chain of custody. The\nMechanism’s cybersecurity framework, which continues to evolve as new threats are\nidentified, combines responsive and preventive approaches. It allows the Mechanism to\nrespond quickly to all known cybersecurity threats. Through regular training and internal\nnotifications, the Mechanism is also carrying out its work in line with the latest developments\nin cybersecurity and protective measures."},{"id":"a-hrc-48-18-p0020","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"20","seq":21,"section":"A. Expansion of the collection and preservation of evidence","text":"Building these technology and cybersecurity capacities from the outset has been\ninstrumental in ensuring that the Mechanism has been able to continue its operations in a\nsecure manner with little to no disruption during the COVID-19 pandemic. Furthermore,\nthese efforts have equipped the Mechanism with the ability to share relevant materials in an\nefficient manner as and when requested by national, regional and international courts and\ntribunals.\nLooking ahead"},{"id":"a-hrc-48-18-p0021","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"21","seq":22,"section":"A. Expansion of the collection and preservation of evidence","text":"Notwithstanding the continuing uncertainties related to COVID-19, the Mechanism\nexpects that the progressive relaxation of travel restrictions will enable the resumption of\nessential activities that were suspended during the pandemic. This includes the in-person\ncollection and verification of information and evidence, as well as high-level engagement\nmissions to facilitate the negotiation of cooperation arrangements and advance the\nMechanism’s outreach efforts. The Mechanism will ensure that security considerations are\nintegrated into all aspects of its mission planning."},{"id":"a-hrc-48-18-p0022","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"22","seq":23,"section":"A. Expansion of the collection and preservation of evidence","text":"In addition, and to complement other specialized investigative capacities, the\nMechanism is seeking to enhance its capacities to collect and analyse financial information\nas part of its broader investigations into crimes within its mandate. Such information is\nexpected to complement the Mechanism’s criminal investigations in several ways, including\nin identifying potential perpetrators, criminal motives and modes of liability, and in\nestablishing jurisdictional elements."},{"id":"a-hrc-48-18-p0023","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"23","seq":24,"section":"B. Analysis and sharing of information","text":"While still in the early stages, the Mechanism has put much effort into ensuring that\nits analytical work is keeping pace with its growing collection of information and evidence.\nThe Mechanism organizes the evidence collected from many different types of sources and\nanalyses both specific incidents and broader situations. Through a rigorous assessment, the\nMechanism seeks to determine what facts can be proven, whether these facts fulfil the\nelements of crimes within the Mechanism’s mandate, and whether the facts establish the\ncriminal responsibility of individual perpetrators. This includes situations, incidents and\npersons/entities related to the events occurring after 1 February 2021, in addition to situations\nrelated to the Rohingya crisis and ethnic conflicts prevailing in northern Myanmar.\nDeveloping analytical tools and sharing packages"},{"id":"a-hrc-48-18-p0024","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"24","seq":25,"section":"B. Analysis and sharing of information","text":"Based on its analytical work, the Mechanism has increased the volume of information\nand evidence that can be shared for use in national, regional and international courts or\ntribunals willing or able to hold accountable persons responsible for crimes in the\nMechanism’s mandate. In line with its investigative strategy, the Mechanism has been\nassessing and further developing its analytical capacities and tools covering the broad range\nof alleged crimes and perpetrators in the context of Myanmar. Through this process, the\nMechanism has determined that information needs to be well organized, collated into\ncoherent files pertaining to a specific situation, incident or person/entity, and tied together by\nclear analysis, to ensure that the information will be relevant and useful to investigative,\nprosecutorial or judicial authorities to the best extent possible. In order to ensure that each\ncase file is specific and of a manageable size, the Mechanism is producing compilations, with\nsupporting information and analysis, that meet the requests of entities for the relevant\ncriminal or legal proceedings. As at 30 June 2021, the Mechanism has prepared 11\ncompilations of evidence and analysis available for potential sharing."},{"id":"a-hrc-48-18-p0025","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"25","seq":26,"section":"B. Analysis and sharing of information","text":"Furthermore, the Mechanism is developing analytical tools and products that address\ncross-cutting elements, structures and patterns of crimes within its mandate, covering\nmultiple situations and incidents that have occurred since 2011. These tools are being\ndesigned to be used and applied to multiple case files that the Mechanism is preparing for\npotential sharing."},{"id":"a-hrc-48-18-p0026","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"26","seq":27,"section":"B. Analysis and sharing of information","text":"In addition, the Mechanism has also continued to ensure close and timely cooperation\nwith the International Criminal Court and the International Court of Justice, as called for by\nthe Human Rights Council in its resolution 43/26. In The Gambia v. Myanmar, the\nInternational Court of Justice is currently considering the complaint of the Gambia that\nMyanmar is in violation of its obligations under the Convention on the Prevention and\nPunishment of the Crime of Genocide. The Mechanism continues to share relevant materials\nwith the parties in the case, after ensuring that it has the consent of the information provider(s)\nand determining that the information will not affect the security or privacy rights of those\nwhom the materials concern.\nAnalysis of events in Myanmar since the military’s seizure of power"},{"id":"a-hrc-48-18-p0027","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"27","seq":28,"section":"B. Analysis and sharing of information","text":"As noted above, the Mechanism’s mandate covers the most serious international\ncrimes and violations of international law committed in Myanmar since 2011. The temporal\nscope is therefore ongoing and the mandate to collect evidence continues to apply to events\nsince the military seizure of power in February of 2021."},{"id":"a-hrc-48-18-p0028","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"28","seq":29,"section":"B. Analysis and sharing of information","text":"The Mechanism has consistently explained that the constitutional process in Myanmar,\nfair elections and democracy are not part of its subject matter mandate. The terms of reference\nfor the Mechanism state that the reference in the mandate to violations of international law\ninclude violations of international human rights law and international humanitarian law.\nTherefore, issues related to violations of the Constitution or the laws of Myanmar, the\noverturning or fairness of elections, and who should be recognized as the legal government\nof Myanmar are not within the legal competence of the Mechanism. However, serious\ninternational crimes and human rights violations can occur in the context of disputes over\npolitical processes within a country. Since the coup, the Mechanism has been carefully\nfollowing developments to determine whether recent events constitute crimes that fall within\nits mandate."},{"id":"a-hrc-48-18-p0029","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"29","seq":30,"section":"B. Analysis and sharing of information","text":"In addition to preserving and analysing thousands of communications collected from\nindividuals and organizations concerning events in Myanmar, the Mechanism has also\nclosely followed public reporting, contacted individuals and entities who have information\nabout events, including those who were eyewitnesses, and consulted with persons having\nspecialized expertise to assist in the analysis of the information collected."},{"id":"a-hrc-48-18-p0030","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"30","seq":31,"section":"B. Analysis and sharing of information","text":"The Mechanism’s preliminary analysis of collected information concerning events in\nMyanmar since the 1 February 2021 military coup indicates that crimes against humanity\nfalling within the Mechanism’s mandate, including murder, persecution, imprisonment,\nsexual violence, enforced disappearance and torture, have likely been committed."},{"id":"a-hrc-48-18-p0031","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"31","seq":32,"section":"B. Analysis and sharing of information","text":"A crime against humanity requires an act committed as part of a widespread or\nsystematic attack on a civilian population. Such an attack does not need to be a military attack.\nRather, it is defined as a course of conduct involving the multiple commission of acts against\nany civilian population,2 and it may be carried out in a single location3 or across a broader\nswath of territory.4 Acts of violence5 or any serious mistreatment of a civilian population can\nconstitute an attack for the purposes of establishing a crime against humanity.6"},{"id":"a-hrc-48-18-p0032","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"32","seq":33,"section":"B. Analysis and sharing of information","text":"The attack must also be either “widespread” or “systematic”. Determining whether an\nattack is widespread requires an examination of the scale of the attack and the number of\nvictims. When assessing whether an attack is widespread, one must look to the cumulative\neffect of the criminal acts in question, or the impact of a single act of extraordinary\nmagnitude.7 The geographical scale, temporal scope and number of targeted persons of the\nattack are all relevant in determining whether an attack was “widespread”.8"},{"id":"a-hrc-48-18-p0033","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"33","seq":34,"section":"B. Analysis and sharing of information","text":"Preliminary information collected and analysed by the Mechanism indicates that\nhundreds of civilians have been killed by security forces across Myanmar, including in\nYangon, Nay Pyi Taw, Bago, Mandalay, Magway and Sagaing. The available information,\nincluding public statements by the military authorities, indicate that thousands of individuals\nhave been arbitrarily detained. Credible reports and video evidence indicate that security\nforces have carried out acts of torture and sexual violence. From the totality of the\ninformation the Mechanism has collected to date, it appears that the events in recent months\nconstitute a widespread attack on a civilian population."},{"id":"a-hrc-48-18-p0034","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"34","seq":35,"section":"B. Analysis and sharing of information","text":"The attack is similarly systematic in nature. The term “systematic” refers to the\norganized nature of the acts of violence and the improbability of their random occurrence. 9\nPreliminary information collected and analysed by the Mechanism indicates that security\nforces have acted in a coordinated manner across the country. Specific groups of individuals\nappear to have been targeted for arbitrary detention based on their political affiliation,\nprofession (such as medical worker, teacher and journalist) and exercise of political rights.\nShortly following the military seizure of power, protests against the coup erupted across the\ncountry. During the initial weeks following the military seizure of power, there were few\nreports of violent responses by security forces and it appears that the security forces avoided\nthe use of lethal force at public protests. However, within a few weeks, there was a noticeable\nchange of tactics, as security forces started employing lethal force, including the use of live\nammunition, against protesters in multiple locations."},{"id":"a-hrc-48-18-p0035","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"35","seq":36,"section":"B. Analysis and sharing of information","text":"All of the preliminary information available to the Mechanism requires further\nverification and analysis. The Mechanism continues to collect and analyse evidence relevant\nto these matters and welcomes further submissions of information. However, in determining\nwhether the recent events in Myanmar fall within its mandate, the Mechanism is of the\npreliminary view, based on its analysis of the available information summarized above, that\nMyanmar security forces have committed serious international crimes since seizing power\non 1 February 2021. The available information indicates that security forces have carried out\na widespread and systematic attack on the civilian population. In this context, the reports of\nmurders, sexual assaults, arbitrary detentions, enforced disappearances, torture and\npersecution collected by the Mechanism, if substantiated, would amount to crimes against\nhumanity. Therefore, the Mechanism will continue to collect, attempt to verify, and analyse\ninformation on specific serious international crimes and human rights violations that may\nhave been committed. In accordance with its mandate, it will also seek the crucial evidence\nthat can be used in courts or tribunals to prove, to the high standards of proof necessary for\nconviction in criminal cases, which individuals bear criminal responsibility for these serious\ninternational crimes.\nLooking ahead"},{"id":"a-hrc-48-18-p0036","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"36","seq":37,"section":"B. Analysis and sharing of information","text":"The Mechanism will continue to refine its analytical tools, mainstreaming best\npractices and developing new products that cover cross-cutting contextual elements, patterns\nand structures or particular incidents and situations. In this regard, it is important to recall\nthat the Mechanism is not a prosecutorial body or a court. Thus, it is dependent upon\ncompetent national, regional and international authorities to commence criminal proceedings\nin relation to the most serious international crimes and violations of international law\ncommitted in Myanmar since 2011. In order to maximize the use of the evidence it collects\nand contribute to criminal accountability processes, the Mechanism will engage with the\nauthorities of jurisdictions that may potentially use its information and files, and proactively\nkeep itself abreast of any ongoing activities, investigations or legal proceedings that may be\nrelevant to its mandate."},{"id":"a-hrc-48-18-p0037","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"37","seq":38,"section":"C. Cooperation arrangements and modalities","text":"The Mechanism has continued to engage with a variety of relevant entities and actors\nto negotiate and conclude cooperation arrangements or modalities to facilitate the\nimplementation of the Mechanism’s mandate. These arrangements concern the collection of\ninformation and evidence, the provision of logistical support or specialized services, and the\nconduct of its activities. This has included a diverse range of actors, including national\nauthorities, United Nations partners, civil society actors, non-governmental organizations\nand business enterprises. Since it became operational, the Mechanism has concluded 38\ncooperation arrangements for the collection, preservation and storage of information,\ndocumentation and evidence related to its mandate. In addition, the Mechanism has\nconcluded agreements setting out modalities for the provision of specialized services and\nlogistical support."},{"id":"a-hrc-48-18-p0038","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"38","seq":39,"section":"C. Cooperation arrangements and modalities","text":"With regard to cooperation with Member States, the Mechanism continues to engage\nwith States and intergovernmental organizations that may have relevant information and/or\nmay be involved in legal proceedings within the Mechanism’s mandate. As recognized by\nthe Human Rights Council and the General Assembly, the cooperation of Member States, in\nparticular those from the Asia-Pacific region, remains particularly important for the\nMechanism’s investigative activities, including to gain access to and interview witnesses in\na manner that ensures their security and privacy. The cooperation of Member States is also\nneeded in order to facilitate the protection of witnesses and prevent any reprisals for\ncooperation with the Mechanism."},{"id":"a-hrc-48-18-p0039","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"39","seq":40,"section":"C. Cooperation arrangements and modalities","text":"Due to the significant constraints placed on travel and in-person meetings as a result\nof the COVID-19 pandemic, the Mechanism has been unable to progress as planned in its\nobjectives to conduct in-person high-level missions to relevant Member States in whose\nterritories it expects to conduct its activities. Nevertheless, the Mechanism has supplemented\nsuch engagements through regular contacts with Member States and relevant authorities in a\nmanner that ensures the confidentiality of the Mechanism’s activities and the safety and\nsecurity of its interlocutors and personnel."},{"id":"a-hrc-48-18-p0040","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"40","seq":41,"section":"C. Cooperation arrangements and modalities","text":"The Mechanism continues to seek the cooperation of the authorities of Myanmar to\nobtain access to witnesses, victims and other sources of information, and access to locations\nwhere alleged crimes have occurred. The Mechanism will continue to reach out and seek a\ncooperative relationship with Myanmar, in light of General Assembly resolution 75/238 of\n31 December 2020, in which the Assembly called upon Myanmar to cooperate and\nmeaningfully engage with the Mechanism, including by granting unrestricted access for its\nactivities, and with Human Rights Council resolution 46/21 of 24 March 2021, in which the\nCouncil made a similar call to relevant actors in Myanmar."},{"id":"a-hrc-48-18-p0041","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"41","seq":42,"section":"C. Cooperation arrangements and modalities","text":"With regard to inter-agency cooperation, coordination and liaison, the Mechanism\nvalues the cooperation of a diverse set of United Nations partners and entities, both their\nheadquarters in New York or in Geneva and their relevant field offices, including those\nworking on issues related to Myanmar. The Mechanism continues to consult with\ninternational courts and other international accountability mechanisms to learn from their\nexperiences and best practices, in line with the respective mandates of each entity. In\naccordance with its terms of reference, and to the extent synergies are possible, the\nMechanism coordinates closely with these entities in the areas of mutual concern, such as\ninformation technology systems and data management, witness protection and support, and\nwitness interviews, including on issues related to informed consent.\nLooking ahead"},{"id":"a-hrc-48-18-p0042","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"42","seq":43,"section":"C. Cooperation arrangements and modalities","text":"Resuming in-person high-level dialogue with key Member States will be a critical\npriority of the Mechanism for the upcoming reporting period. Cooperation with the\nMechanism will depend in part on its ability to build and sustain trusting relationships with\nessential partners. While remote means will continue to facilitate ongoing engagements, such\nmeans would not be an appropriate modality for the dedicated and multilayered negotiations\nthat such arrangements require. The Mechanism will also continue its systematic efforts to\nengage with the authorities of Myanmar in seeking its cooperation with respect to the\nimplementation of its mandate."},{"id":"a-hrc-48-18-p0043","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"43","seq":44,"section":"D. Engagement with relevant stakeholders and public outreach","text":"Public outreach remains a priority of the Mechanism. Communication and public\noutreach activities continued to play an essential role in promoting a greater understanding\nof the complex work of the Mechanism and fostering cooperation. In line with the\nmultipronged approach set out in its communications and public outreach strategy of 2020,\nthe Mechanism continued to develop and use various communication tools to explain its\nmandate, activities and outputs to relevant stakeholders, in particular witnesses and victims."},{"id":"a-hrc-48-18-p0044","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"44","seq":45,"section":"D. Engagement with relevant stakeholders and public outreach","text":"As in-person travel and direct contacts with relevant stakeholders were significantly\nreduced due to the pandemic, the Mechanism adjusted its communications strategy, adapting\nit to new circumstances. In view of maintaining an uninterrupted flow of information about\nits activities, the Mechanism made increasing use of its website, social media and periodic\nbulletins to communicate effectively with relevant stakeholders. The Mechanism also\nengaged in dialogue with various groups through virtual means and contacts."},{"id":"a-hrc-48-18-p0045","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"45","seq":46,"section":"D. Engagement with relevant stakeholders and public outreach","text":"The Mechanism’s website and social media platform have become powerful vehicles\nfor the dissemination of accurate and timely information about the Mechanism’s work and\nmandate. Monitoring by the Mechanism shows that tens of thousands of people are visiting,\nsharing and amplifying this information in Myanmar and around the world. The Mechanism\nregularly updates its official website in the English and Myanmar languages. Since issuing\nits inaugural bulletin in May 2020, the Mechanism has issued several subsequent editions.\nThe bulletins continue to serve as a key tool to provide more in-depth updates about the\nprogress of the work of the Mechanism, highlighting particular initiatives and answering\nfrequently asked questions about various topics of interest within the Mechanism’s mandate.\nIn October 2020, the Mechanism launched a page on Facebook to further bolster its outreach\nefforts and to share information more widely with civil society actors and the public in\nMyanmar. This was one of the key recommendations of the survey of civil society actors that\nthe Mechanism conducted in 2019."},{"id":"a-hrc-48-18-p0046","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"46","seq":47,"section":"D. Engagement with relevant stakeholders and public outreach","text":"Recent developments in Myanmar have significantly increased public interest in the\nwork of the Mechanism. In order to explain how the Mechanism’s ongoing mandate relates\nto current events in Myanmar, the Head of the Mechanism has participated in various\ninterviews with national and international media. In a highly fluid situation, managing\nexpectations about what the Mechanism can and cannot do within its mandate has been an\nessential component of these outreach efforts."},{"id":"a-hrc-48-18-p0047","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"47","seq":48,"section":"D. Engagement with relevant stakeholders and public outreach","text":"In parallel, the Mechanism has consistently engaged with and provided in-person or\nonline briefings to representatives of Member States in Geneva at the ambassadorial and\nworking levels. The Mechanism has also provided online briefings to representatives of\nMember States in New York and in their capital cities and to regional and intergovernmental\norganizations. It has maintained regular dialogue with United Nations entities and civil\nsociety actors based in the Asia-Pacific region and elsewhere. The Mechanism has also\nparticipated in several high-level public online events organized by Member States, civil\nsociety actors and United Nations entities on topics related to justice and accountability."},{"id":"a-hrc-48-18-p0048","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"48","seq":49,"section":"D. Engagement with relevant stakeholders and public outreach","text":"The safety of those with whom the Mechanism interacts continues to be of the utmost\nimportance. In this regard, the Mechanism has used its public communication platforms to\nconvey the importance of secure means of communications to help ensure the safety and\nsecurity of both stakeholders and Mechanism personnel, and the confidentiality of the\ninformation exchanged or its engagements.\nLooking ahead"},{"id":"a-hrc-48-18-p0049","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"49","seq":50,"section":"D. Engagement with relevant stakeholders and public outreach","text":"For the upcoming reporting period, the Mechanism will seek to expand its engagement\nwith civil society stakeholders working on issues related to Myanmar to better understand\ntheir needs and to facilitate more in-depth and structured dialogue with the Mechanism. This\nwill enable civil society stakeholders to engage more meaningfully with the work of the\nMechanism, thereby promoting greater understanding and confidence in the Mechanism’s\ncontribution to international criminal accountability processes."},{"id":"a-hrc-48-18-p0050","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"50","seq":51,"section":"D. Engagement with relevant stakeholders and public outreach","text":"For 2022, the Mechanism seeks to make more information available in the languages\nof Myanmar, to work closer with local partners on providing accurate information about the\nMechanism and to try to reach a broader and more diverse audience by utilizing different\nmedia channels, such as radio and television."},{"id":"a-hrc-48-18-p0051","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"51","seq":52,"section":"III. Operational developments enabling mandate implementation","text":"The Mechanism continued to develop robust governance framework, technology\ninfrastructure and administrative and operational support systems to enable concrete progress\non the substantive priorities set out above. During the reporting period, the Mechanism\ncontinued to implement the concept of operations put in place by the Head of the Mechanism\nin 2019, adapting it as necessary in response to the continuing impact of COVID-19. In line\nwith a more streamlined and leaner budget approved by the General Assembly for 2021, the\nMechanism continued to build its infrastructure and expertise, refine its administrative\nprocesses and consolidate its capacities."},{"id":"a-hrc-48-18-p0052","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"52","seq":53,"section":"A. Foundational policies, protocols and procedures","text":"The Mechanism remained on track to develop a comprehensive set of foundational\npolicies, protocols and procedures to guide its activities in line with its strategic priorities. In\nthis regard, the Mechanism has adopted over 50 policies, protocols, procedures, guidelines\nand directives covering a wide range of activities, including case selection and prioritization;\ninvestigations and witness interviews; informed consent of information providers and\nwitnesses; information processing; classification and handling of sensitive information; and\nsecurity and administration. The perspectives of diverse victims/survivors’ groups have been\ncarefully integrated, and the Mechanism is developing specialized policies for addressing\nvictims/survivors of sexual and gender-based crimes and crimes against children. Important\nprogress has also been made on the preparation of security procedures relating to operations\nboth at the Mechanism’s premises and in the field."},{"id":"a-hrc-48-18-p0053","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"53","seq":54,"section":"A. Foundational policies, protocols and procedures","text":"In line with its terms of reference, these foundational documents are based on the\nhighest possible standards, consistent with the Charter of the United Nations, United Nations\nrules, regulations, policies and best practices, relevant international law and standards,\nincluding human rights law, notably the right to a fair trial and other due process provisions,\nas well as relevant jurisprudence. Demonstrating a continuing commitment to learning, the\nMechanism continues to draw upon and integrate the good practices of other comparable\ninternational accountability mechanisms, where applicable and relevant to its mandate. The\nMechanism plans to finalize its core foundational documents by the end of 2021."},{"id":"a-hrc-48-18-p0054","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"54","seq":55,"section":"B. Infrastructure and technology","text":"In December 2020, the Mechanism moved into its new office facility located at the\npremises of the United Nations Office at Geneva. As stated in its previous report to the\nCouncil, the prefabricated office facility was constructed after the Mechanism determined\nthat it was the most cost-effective and technically acceptable option, accruing significant\nsavings for the Organization, yet ensuring the fulfilment of the Mechanism’s requirements\nfor mandate implementation, including with regard to the storage of physical evidence, safety\nand the security and confidentiality of operations and activities. The Mechanism’s new\npremises and its office layout were designed to ensure access by and inclusion of persons\nwith disabilities, and the Mechanism will ensure that the management of its facilities will\nfurther advance inclusion to facilitate easy access and use by persons with disabilities."},{"id":"a-hrc-48-18-p0055","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"55","seq":56,"section":"B. Infrastructure and technology","text":"As noted above, the Mechanism has also made significant progress in the definition,\ndesign and implementation of its core specialized technology and infrastructure for handling\nthe information, evidence and material that it receives and collects. With regard to the\nprocessing of collected material, the Mechanism has continued to procure and operationalize\nadditional necessary software and equipment to process and record all new material. In\naddition to the suite of enabling technologies noted above, the Mechanism has also\nestablished a dedicated forensic data processing laboratory in its newly constructed office\npremises, which will enable the performance of advanced analysis and processing of any\nmaterial it receives. To complement the electronically stored information management\nsystem, the Mechanism has established a secure physical storage facility, with various layers\nof security protections, for the preservation of its physical and digital evidence. As part of\nthe development of its core technology requirements, the Mechanism has established a data\nstorage solution that facilitates the incoming and outgoing flows of material provided to and\nfrom the Mechanism in a secure and confidential manner."},{"id":"a-hrc-48-18-p0056","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"56","seq":57,"section":"B. Infrastructure and technology","text":"Looking ahead, the Mechanism is assessing technology solutions, in conjunction with\na suitable information governance framework, to establish a comprehensive information\nmanagement system that covers the entire repository of its materials, including through the\ndevelopment of appropriate procedures for the long-term storage of and access to such\nmaterial and records, in line with its terms of reference. Furthermore, the Mechanism is in\nthe process of procuring multiple secure cloud-based platforms to bolster its forensic\ncapabilities."},{"id":"a-hrc-48-18-p0057","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"57","seq":58,"section":"C. Administrative and operational support","text":"The Mechanism has made important progress in establishing administrative and\noperational support structures that enable essential activities related to the administration of\nits resources and infrastructure, the recruitment and selection of personnel, the coordination\nof security services, the provision of language services and the protection and support of\nwitnesses and victims."},{"id":"a-hrc-48-18-p0058","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"58","seq":59,"section":"C. Administrative and operational support","text":"Another critical priority of the Mechanism over the reporting period has been the\nfinalization of the recruitment of a team of highly experienced and innovative professionals\nwith a diverse range of expertise and specializations. In this regard, the Mechanism has\nredoubled efforts to expeditiously recruit personnel in line with its priority schedule, which\nmatches the timing of the recruitment of personnel with the substantive strategy. While most\nrecruitment efforts were delayed or postponed in 2020 due to the United Nations hiring freeze,\nbarring any unforeseen circumstances or additional liquidity constraints the Mechanism\nexpects to meet its recruitment objectives for 2021."},{"id":"a-hrc-48-18-p0059","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"59","seq":60,"section":"C. Administrative and operational support","text":"As of June 2021, the Mechanism has filled nearly 75 per cent of the total positions\napproved by the General Assembly for 2021 and is well advanced in the recruitment process\nfor many of the remaining positions. The recruited personnel bring expertise in the areas of\ninternational criminal law, international human rights law, international humanitarian law,\ncriminal investigation and prosecution, legal cooperation, information systems management,\nstorage and preservation of information, military matters, sexual and gender-based crime and\nviolence, crime against children, information technology and security, witness protection and\nsupport, and language support. In line with the terms of reference, due consideration is given\nto the representation of different legal traditions, geographic diversity, gender balance,\nregional expertise and relevant language skills."},{"id":"a-hrc-48-18-p0060","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"60","seq":61,"section":"C. Administrative and operational support","text":"The Mechanism has also developed an internal training programme, with the aim of\ncontinually deepening the expertise of its personnel in highly specialized and rapidly\nevolving technical areas. Given the remote-working situation, the Mechanism arranged\nonline training sessions to keep its personnel updated on the relevant areas during the\nCOVID-19 pandemic period. With a view to leveraging opportunities and maximizing\nefficiencies, the Mechanism collaborates regularly with other accountability mechanisms on\nthe organization of training and other learning activities."},{"id":"a-hrc-48-18-p0061","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"61","seq":62,"section":"C. Administrative and operational support","text":"In the area of language support, the Mechanism is continually seeking to increase its\nspecialized capacities in the many languages spoken in Myanmar to ensure that it can engage\nwith interlocutors and stakeholders in their language(s). In this regard, the Mechanism is both\ndeveloping internal language capacities to support collection and analytical work and\ndeploying external support to cover the Mechanism’s extensive translation and interpretation\nneeds."},{"id":"a-hrc-48-18-p0062","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"62","seq":63,"section":"IV. Conclusion","text":"In less than two years, the Mechanism has made concrete progress to swiftly\nadvance its substantive activities and set up foundational and core infrastructure to\nenable the longer-term implementation of its mandate. With remarkable agility for a\nnew institution, the Mechanism quickly adapted to new challenges and contextual\ndevelopments, adjusting working methods and strategically allocating its lean resources."},{"id":"a-hrc-48-18-p0063","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"63","seq":64,"section":"IV. Conclusion","text":"The Mechanism will continue to build on the momentum it has achieved to date\nin order to further deepen its substantive work on all fronts, in particular by conducting\nmissions to interview and collect evidence from witnesses and other information\nproviders. As demonstrated by the recent events in Myanmar, the Mechanism’s\nsubstantive activities are only expanding. It is therefore crucial that the Mechanism, as\ncalled for by the General Assembly in its resolution 74/246, is afforded the flexibility\nthat it needs in terms of staffing, location and operational freedom so it can deliver as\neffectively as possible on its mandate."},{"id":"a-hrc-48-18-p0064","rec_id":"recsPy094rMybrP2T","symbol":"A/HRC/48/18","n":"64","seq":65,"section":"IV. Conclusion","text":"The full and meaningful cooperation of all parts of the international community,\nespecially Member States, will remain essential. Without such support, the Mechanism\nwill be hindered from fully delivering on its mandate and playing a unique role in\nfacilitating and supporting criminal proceedings that advance accountability and help\nrender justice for the people of Myanmar."},{"id":"a-hrc-51-4-u0000","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":null,"seq":0,"section":null,"text":"United Nations                                                                               A/HRC/51/4\nGeneral Assembly                                                      Distr.: General\n12 July 2022","unnumbered":true},{"id":"a-hrc-51-4-u0001","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":null,"seq":1,"section":null,"text":"Summary\nThe present document is the fourth report submitted by the Independent Investigative\nMechanism for Myanmar to the Human Rights Council pursuant to resolution 39/2 of 27\nSeptember 2018, and it covers the Mechanism’s activities from 16 June 2021 to 30 June\n2022.\nIn August 2022, the Mechanism will complete its third year of operations. August\nwill also mark the five-year commemoration of the 2017 clearance operations in Rakhine\nState, which led to the displacement of nearly 1 million Rohingya people. Tragically for the\nRohingya and all the peoples of Myanmar, progress on ending impunity and ensuring\naccountability for crimes committed remains limited. Established for the purpose of\nfacilitating justice and accountability efforts, the Mechanism continues to collect and analyse\na substantial amount of information on the most serious international crimes committed in\nMyanmar since 2011, including sexual and gender-based crimes and crimes against and\naffecting children. The information collected and analysed thus far includes evidence that\nreinforces the Mechanism’s assessment in its previous annual report that crimes against\nhumanity continue to be systematically committed in Myanmar. Furthermore, the\ninformation includes evidence of intensified and sustained violence and the existence of\nvarious armed conflicts within Myanmar.\nDespite increasing challenges, the Mechanism seized opportunities to further deepen\nits collection and analytical activities, increase testimonial evidence, enhance specialized\ncapacities, deploy cutting-edge technology and strengthen engagement with a range of\nstakeholders. Having made over 120 formal requests for information and assistance and\nengaged with nearly 200 sources and information providers, the Mechanism’s repository now\nconsists of nearly 3,000,000 information items, including interview statements,\ndocumentation, videos, photographs, geospatial imagery and social media material. The\nevidence collected will facilitate the Mechanism’s efforts to build files that prove the\ncommission of serious international crimes related to priority incidents and in relation to the\nindividuals most responsible for the crimes. The Mechanism aims to facilitate justice for the\npeople of Myanmar, including in proceedings before the International Court of Justice,\nongoing investigations before the International Criminal Court, the ongoing investigation by\njudicial authorities of Argentina and future relevant jurisdictions.","unnumbered":true},{"id":"a-hrc-51-4-u0002","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":null,"seq":2,"section":null,"text":"The Mechanism remains steadfast in its commitment to engage with all parts of the\ninternational community, in particular Member States in the Asia-Pacific region, in order to\ndemonstrate its value as an effective contributor to justice and accountability for the most\nserious international crimes committed in Myanmar.","unnumbered":true},{"id":"a-hrc-51-4-p0001","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"1","seq":3,"section":"I. Introduction","text":"In its resolution 39/2 of 27 September 2018, the Human Rights Council established\nthe Independent Investigative Mechanism for Myanmar with a mandate to collect,\nconsolidate, preserve and analyse evidence of the most serious international crimes and\nviolations of international law committed in Myanmar since 2011, and to prepare files in\norder to facilitate and expedite fair and independent criminal proceedings, in accordance with\ninternational law standards, in national, regional or international courts or tribunals. In its\nresolution 73/264 of 22 December 2018, the General Assembly welcomed the establishment\nof the Mechanism. In its resolution 43/26 of 22 June 2020, the Council specifically called for\nthe Mechanism to engage in close and timely cooperation on future investigations by, among\nothers, the International Criminal Court and the International Court of Justice."},{"id":"a-hrc-51-4-p0002","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"2","seq":4,"section":"I. Introduction","text":"The Mechanism is now fully operational. Since its last annual report, the Mechanism\nhas continued to collect substantial evidence of serious international crimes committed\nthroughout Myanmar since 2011, including crimes committed against the Rohingya and\ncrimes committed since the military takeover in February 2021. The Mechanism deploys\ncutting-edge technologies and innovative tools and methodologies to advance its\ninvestigations in order to overcome the difficult and complex landscape in which it operates."},{"id":"a-hrc-51-4-p0003","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"3","seq":5,"section":"I. Introduction","text":"The Mechanism continues to make requests for cooperation to authorities in Myanmar\nto share relevant information and to grant the Mechanism access to crime scenes and potential\nwitnesses inside the country. To date, none of these requests have elicited any response. The\nMechanism also continues its efforts to deepen cooperation and engagement with relevant\nStates, particularly within the Asia-Pacific region, where much of the evidence and many of\nthe witnesses are located."},{"id":"a-hrc-51-4-p0004","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"4","seq":6,"section":"I. Introduction","text":"August 2022 will mark the five-year commemoration of the clearance operations\nagainst the Rohingya people in 2017. Most of the Rohingya who were deported or forcibly\ndisplaced at that time are still in camps for refugees or internally displaced persons. While\nthe Rohingya consistently express their desire for a safe and dignified return, it is apparent\nthat their voluntary return depends in substantial part on ensuring accountability for the\natrocities committed against them, including through prosecutions of the individuals most\nresponsible for those crimes. Yet progress on ending impunity and ensuring accountability\nfor serious international crimes committed in Myanmar remains limited. The continued plight\nof the Rohingya and the sustained violence in Myanmar illustrate the important role of the\nMechanism to facilitate justice and accountability for serious international crimes committed\nin Myanmar and to contribute to the deterrence of further atrocities."},{"id":"a-hrc-51-4-p0005","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"5","seq":7,"section":"II. Preliminary findings related to post-coup events","text":"During the reporting period, the Mechanism refined and recalibrated its investigative\npriorities in response to ongoing events in light of substantial new information and evidence\nthat it has collected and analysed. The Mechanism has taken account of reports and\ninformation it has collected of very grave and widespread crimes committed since the\nmilitary takeover in February 2021. In response, the Mechanism has expanded efforts to\ncollect and preserve evidence related to these fast-developing events while also deepening its\ninvestigations and analysis of earlier crimes, particularly those committed in the context of\nthe “clearance operations” of 2016 and 2017 in Rakhine State. All of the Mechanism’s\ninvestigations are informed by thematic and cross-cutting issues, such as investigation and\nanalysis of organizational structures to identify those responsible for specific crimes, sexual\nand gender-based crimes, and crimes against and affecting children."},{"id":"a-hrc-51-4-p0006","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"6","seq":8,"section":"II. Preliminary findings related to post-coup events","text":"During the reporting period, the scope of potential international crimes taking place\nin Myanmar has broadened dramatically. This has posed a substantial challenge given the\nrelatively limited resources of the Mechanism. Specific events since the military takeover in\nFebruary 2021, defined geographically and temporally, are now a major focus of the\nMechanism’s investigations. These events have been prioritized for investigation on the basis\nof a preliminary assessment of the gravity of the crimes concerned, including their scale,\nnature, manner of commission and impact on victims; the degree of responsibility of alleged\nperpetrators; the strength of the available evidence; the importance the Mechanism’s thematic\npriorities concerning sexual and gender-based crimes and crimes against children; and the\nlikelihood of a court or tribunal taking jurisdiction over the crime(s) in question. The scope\nand prioritization of these investigations has necessarily evolved in response to unfolding\nevents and will continue to do so."},{"id":"a-hrc-51-4-p0007","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"7","seq":9,"section":"II. Preliminary findings related to post-coup events","text":"As stated in the Mechanism’s previous annual report, based on reports and evidence\ncollected to date, there are ample indications that since the military takeover in February 2021,\ncrimes have been committed in Myanmar on a scale and in a manner that constitutes a\nwidespread and systematic attack against a civilian population. 1 The available evidence\nsuggests that the crimes against humanity of murder; torture; deportation and forcible transfer;\nrape and other forms of sexual violence; persecution; and imprisonment have been committed.\nThe geographic scope of the potential crimes has expanded since the Mechanism’s previous\nannual report. In addition to Yangon, Nay Pyi Taw, Bago, Mandalay, Magway and Sagaing,\nthere are credible reports of crimes having been, and continuing to be, committed in Chin,\nKayin, and Kayah States and elsewhere."},{"id":"a-hrc-51-4-p0008","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"8","seq":10,"section":"II. Preliminary findings related to post-coup events","text":"The nature of the potential criminality is also expanding. The Myanmar military\nannounced on 3 June 2022 that it intends to execute four individuals sentenced to death by\nmilitary courts. None of the trial proceedings were public and the judgments are not publicly\naccessible. A fundamental attribute of a fair trial under international law is that it be held in\npublic to the greatest extent possible, with exceptions tailored as narrowly as possible to the\njustification, such as national security considerations. Yet the imposition of sentences on the\nbasis of secret proceedings is indicative of the commission of the crime of imprisonment and,\nin the case of the imposition of the death penalty, could constitute the crime of murder, openly\ncarried out by an organ of government."},{"id":"a-hrc-51-4-p0009","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"9","seq":11,"section":"II. Preliminary findings related to post-coup events","text":"The information collected by the Mechanism this past year indicates that several\narmed conflicts are ongoing and intensifying on the territory of Myanmar. This triggers the\napplication of international humanitarian law and obligates all parties to the conflicts to\nensure that their forces comply with the applicable laws of war. A non-international armed\nconflict exists under customary international law whenever there is protracted armed violence\nbetween governmental authorities and organized armed groups or between such groups\nwithin a State.2 The Mechanism notes that the intensity and sustained nature of the violence\nand the degree of the organization of the armed groups fighting against the Myanmar security\nforces appear to satisfy the threshold for the existence of an armed conflict."},{"id":"a-hrc-51-4-p0010","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"10","seq":12,"section":"II. Preliminary findings related to post-coup events","text":"The Mechanism is also collecting evidence of specific war crimes committed in\nconnection with those armed conflicts. Information has been collected and case files are being\ndeveloped in respect of specific incidents of war crimes, including but not limited to\nintentional attacks directed against the civilian population as such, or against civilians not\ntaking part in hostilities; violence to life against persons taking no active part in hostilities;\nrape; cruel treatment and torture; the carrying out of executions without previous judgment\npronounced by a regularly constituted court; and ordering the displacement of the civilian\npopulation. The Mechanism has collected substantial evidence in respect of the widespread\nburning of villages and towns, and of targeted or indiscriminate killing of civilians, and is\ndeveloping case files on these incidents."},{"id":"a-hrc-51-4-p0011","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"11","seq":13,"section":"II. Preliminary findings related to post-coup events","text":"In addition to, and as part of, its geographically and temporally defined investigations,\nthe Mechanism continues to collect and analyse evidence concerning detention-related\ncrimes. This includes indiscriminate arrests; prolonged detention without appropriate due\nprocess; mistreatment and torture in detention, including sexual violence; and the\ncontinuation of detention and imposition of sentences on the basis of proceedings that do not\ncomport with fundamental rights under international law."},{"id":"a-hrc-51-4-p0012","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"12","seq":14,"section":"II. Preliminary findings related to post-coup events","text":"As part of its work developing case files to establish the commission of specific crimes,\nthe Mechanism continues its efforts to identify individuals criminally responsible for those\ncrimes. The Mechanism applies the well-established principles of criminal liability in\ninternational criminal law in identifying such persons. In fulfilment of its mandate and terms\nof reference, the Mechanism is prepared to consider any requests by relevant authorities to\nshare information regarding specific individuals who may be involved in crimes within\nMyanmar, or any incidents that may be of investigative interest to such authorities.\nSexual and gender-based crimes and crimes against and affecting children"},{"id":"a-hrc-51-4-p0013","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"13","seq":15,"section":"II. Preliminary findings related to post-coup events","text":"As described above, the scope of the Mechanism’s investigations includes sexual and\ngender-based crimes, and crimes against and affecting children. These crimes, which can be\na challenge to investigate even under ideal conditions, are further hindered by the lack of\ndirect access to the territory of Myanmar and other locations where victims and witnesses of\nsuch crimes are present."},{"id":"a-hrc-51-4-p0014","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"14","seq":16,"section":"II. Preliminary findings related to post-coup events","text":"Despite these obstacles, since the military takeover on 1 February 2021, the\nMechanism has collected information relating to the commission of sexual and gender-based\ncrimes against women, girls, men, boys and members of the lesbian, gay, bisexual,\ntransgender and intersex community, including crimes perpetrated by members of the\nsecurity forces. This information indicates that ongoing conflicts in Myanmar severely\nimpacted upon women, children and members of the lesbian, gay, bisexual, transgender and\nintersex community in Myanmar and exacerbated their already vulnerable situation. The\nMechanism has also collected information indicating that children in Myanmar have been\nkilled; tortured; seriously injured; arbitrarily detained, including as proxies for their parents;\nsubjected to sexual and gender-based violence; and conscripted and trained by security forces\nand armed groups. Such crimes are among the gravest international crimes but are also\nhistorically underreported or underinvestigated, warranting targeted outreach, collection and\ndedicated expertise to be properly investigated and, ultimately, prosecuted."},{"id":"a-hrc-51-4-p0015","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"15","seq":17,"section":"II. Preliminary findings related to post-coup events","text":"Obtaining the testimonies of the victims of such crimes requires a sensitive approach,\nand such interviews are best conducted in person. To fulfil its mandate to collect evidence of\nthese crimes, the Mechanism must be afforded the opportunity to enter the territory where\nvictims of serious international crimes, including sexual and gender-based crimes, or child\nvictims are present."},{"id":"a-hrc-51-4-p0016","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"16","seq":18,"section":"III. Progress on the activities of the Mechanism","text":"In line with its strategy as set out in its previous annual report to the Human Rights\nCouncil, the Mechanism continued to expand the collection and analysis of information and\nevidence; increase the availability of evidence and analytical documents for sharing with\ncourts and tribunals; advance the development of cooperation frameworks with new\ninformation and assistance providers; and heighten the visibility of the Mechanism and\nstrengthen the understanding of its mandate by relevant stakeholders, in particular witness\nand victim groups. Despite the ongoing effects of the coronavirus disease (COVID-19)\npandemic in 2021 and early 2022, the Mechanism made important progress in multiple areas."},{"id":"a-hrc-51-4-p0017","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"17","seq":19,"section":"A. Collecting and processing information and evidence","text":"In accordance with principles of impartiality and confidentiality, the Mechanism\ncontinued to collect information and evidence relating to all situations, incidents, persons and\nentities within its mandate. The Mechanism’s collection activities have also been informed\nby lessons learned and best practices identified through an internal evaluation of the\nMechanism’s collection strategy. In line with these findings, the Mechanism has adopted a\nmulti-tiered approach to evidence collection, focusing on information and evidence\npertaining to priority situations and incidents, contextual and overview information relevant\nto Myanmar, and information pertaining to specific individuals, groups and structures\nsuspected of perpetrating crimes."},{"id":"a-hrc-51-4-p0018","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"18","seq":20,"section":"A. Collecting and processing information and evidence","text":"The Mechanism applies a targeted approach to requesting and receiving information\nand evidence. It seeks information and evidence from a wide range of providers, including\ncivil society and documentation organizations, national authorities, United Nations entities,\ninternational organizations, non-governmental organizations, business entities, and\nindividual sources and witnesses. During the reporting period, the Mechanism made over one\nhundred formal requests for information to a variety of such entities and individuals. These\nrequests resulted in the collection of a vast and diverse range of information and evidence\npertaining to its ongoing investigations. Complementing this targeted approach, the\nMechanism continues to collect publicly available open source information to enrich its vast\nevidence repository. To date, the Mechanism has collected and processed for potential\nsharing nearly 3 million information items, including documents, photographs, videos,\ngeospatial imagery, witness statements and open source materials. The repository of\ninformation collected to date includes over 700,000 documents in the Myanmar language\n(Burmese), estimated to total over 12 million pages."},{"id":"a-hrc-51-4-p0019","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"19","seq":21,"section":"A. Collecting and processing information and evidence","text":"The collection also includes large data sets from a variety of sources, including social\nmedia and other types of businesses, as well as a range of dedicated documentation actors\nthat identify or compile data pertaining to significant events in Myanmar. The Mechanism is\nintegrating these large data sets into its state-of-the-art, electronically stored information\nmanagement system for further processing and analysis. They are also being analysed to\nidentify or generate additional investigative opportunities and to support its preliminary\nassessments on the commission of serious international crimes and other violations of\ninternational law and on the responsibility of individuals for the commission of these offences.\nContinued monitoring of relevant developments in Myanmar"},{"id":"a-hrc-51-4-p0020","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"20","seq":22,"section":"A. Collecting and processing information and evidence","text":"As its mandate is ongoing, the Mechanism continues to conduct contemporaneous\nmonitoring of relevant developments in Myanmar that may constitute serious international\ncrimes or violations of international law. Since the military seized power on 1 February 2021,\nthe Mechanism experienced an exponential increase in communications from individuals and\norganizations seeking to share information about alleged serious international crimes and\nhuman rights violations in Myanmar. Communications of this nature have continued\nthroughout 2022. The quantity and, more importantly, the probative value of the information\nreceived, namely the extent to which the information helps prove that serious international\ncrimes were committed or helps identify persons responsible for such crimes, increased\nsignificantly. The Mechanism is very grateful to the many individuals who provided such\ninformation, in many cases at significant risk to their safety and security. The information\nsubmitted to the Mechanism through these communications continues to be fully integrated\ninto the Mechanism’s processing and analytical platforms. From these submissions, the\nMechanism has collected a significant amount of information items, including videos,\nphotographs and documents potentially indicative of crimes against humanity and war\ncrimes committed across Myanmar by various individuals since February 2021."},{"id":"a-hrc-51-4-p0021","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"21","seq":23,"section":"A. Collecting and processing information and evidence","text":"The Mechanism further continues to actively monitor the situation in Rakhine State.\nThis includes the conditions of the Rohingya population that remains in Rakhine State.\nSpecifically, the Mechanism is closely following reports of rising cases of movement\nrestrictions combined with a significant increase in arrests and detentions of Rohingya in the\npast year. The Mechanism is further monitoring the impact that clashes and tensions between\nthe Myanmar military and the Arakan Army have had on the civilian population of Rakhine\nState.\nEnhanced specialized capabilities"},{"id":"a-hrc-51-4-p0022","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"22","seq":24,"section":"A. Collecting and processing information and evidence","text":"The unprecedented volume of information pertaining to events in Myanmar identified\nand collected by the Mechanism required it to secure additional resources and specialized\ncapacities through the support of extrabudgetary resources. These include capacities to\ncollect and analyse information and evidence gathered from open sources, such as social\nmedia, videos, photographs and geospatial imagery publicly available on the Internet, as well\nas to collect and review information of a thematic or specialized nature, such as financial\ninformation. Open source information, when such information is collected in line with\ninternational best practices and verified and analysed by experts, is increasingly recognized\nas a probative form of evidence in criminal proceedings. Moreover, such information helps\nto partially compensate for the Mechanism’s inability to access the territory where crimes\nhave been and continue to be committed."},{"id":"a-hrc-51-4-p0023","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"23","seq":25,"section":"A. Collecting and processing information and evidence","text":"In the past year, the Mechanism has also commissioned a number of historical and\ncultural experts to prepare focused thematic reports on various ethnic groups in Myanmar.\nThese reports, which serve to add further depth to the Mechanism’s own historical\nunderstanding and cultural awareness relevant to Myanmar and to inform the Mechanism’s\ninvestigative activities, may be shared with requesting jurisdictions.\nIncreased engagement with witnesses"},{"id":"a-hrc-51-4-p0024","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"24","seq":26,"section":"A. Collecting and processing information and evidence","text":"Despite the challenges posed by the COVID-19 pandemic, the Mechanism intensified\nefforts to collect testimonial evidence and substantially increased its engagement with\nwitnesses during the past year. The Mechanism conducted numerous screenings and\ninterviews with a range of witnesses, including individuals who possess contextual and\noverview information and “insider” witnesses who possess detailed, first-hand knowledge of\nthe structure and operations of various organizations of interest. Using secure communication\nmethods, the Mechanism collected and preserved a vast trove of documents as well as audio\nand visual files from such witnesses."},{"id":"a-hrc-51-4-p0025","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"25","seq":27,"section":"A. Collecting and processing information and evidence","text":"The Mechanism also conducted investigative missions to carry out in-person\ninterviews in the territories of Member States. Face-to-face interactions help build trust\nbetween the interviewer and the witness, facilitating the best possible setting for a witness to\nspeak openly and allowing the Mechanism to confirm that the witness is not under any duress\nor influence, and thus ensuring the integrity and confidentiality of the interviewing process.\nIn-person interviews that result in a signed witness statement are by far the best method of\nobtaining the most complete, reliable and probative information and ensure its broadest\npossible admissibility in national, regional and international courts or tribunals. In this regard,\nthe Mechanism acknowledges with appreciation the support provided to its investigative\nactivities by the relevant national authorities and other stakeholders."},{"id":"a-hrc-51-4-p0026","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"26","seq":28,"section":"A. Collecting and processing information and evidence","text":"The Mechanism has continued to make every effort to ensure that engagements with\nwitnesses and other information providers are conducted in a safe and secure manner for both\nstakeholders and Mechanism personnel, and that any sensitive information that is collected\nremains confidential. In identifying potential witnesses, the Mechanism continues to\ncarefully assess each individual, taking into account various factors, such as the potential\nrelevance of the individual’s testimony, the individual’s safety and security, and the risk of\nretraumatizing the individual.\nLeveraging information technology and cybersecurity"},{"id":"a-hrc-51-4-p0027","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"27","seq":29,"section":"A. Collecting and processing information and evidence","text":"The Mechanism has continued to expand its information technology toolset to\nfacilitate the collection, processing and analysis of its growing repository of information and\nevidence. Ongoing expansion of digital storage capacity is necessary to accommodate the\nlarge volumes of information collected. The Mechanism also continued to refine its\nelectronically stored information management system in line with United Nations standards\nand industry best practices. The system provides an end-to-end, fully integrated process for\nevidence intake, processing and review; management of all information providers and\nwitnesses; case management planning; and tracking of all information shared by the\nMechanism with third parties. However, new challenges arise constantly as the digital\ninformation landscape continues to evolve and the Mechanism’s collection grows. To this\nend, the Mechanism is not only responsive to new challenges but forward-looking in its\napproach, with the goal of integrating evolving cutting-edge solutions to manage and analyse\ndigital material now and into the future."},{"id":"a-hrc-51-4-p0028","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"28","seq":30,"section":"A. Collecting and processing information and evidence","text":"The Mechanism is also exploring the feasibility of utilising machine translation\nsoftware to translate key materials both into English for the Mechanism’s internal analysis\nand into the languages of relevant jurisdictions interested in using the materials. Given the\nhigh cost and limited capacity for human translation of the material, the Mechanism is\ncurrently testing translation software with the capability of machine learning. Furthermore,\nas machine translation software for the Myanmar language (Burmese) does not exist, the\nMechanism is seeking to develop such capability to facilitate the translation of millions of\ninformation items collected in the Myanmar language (Burmese)."},{"id":"a-hrc-51-4-p0029","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"29","seq":31,"section":"A. Collecting and processing information and evidence","text":"The protection of its information storage system, equipment and tools is a priority of\nthe Mechanism. This in turn contributes to the protection of its personnel and, crucially, the\nindividuals and organizations with whom it engages. The Mechanism continued to refine its\nmethodologies and processes for information security and cybersecurity, safeguarding the\nintegrity of the evidence and the required chain of custody. At the same time, the Mechanism\nremains keenly aware of cybersecurity challenges, both in terms of digital surveillance and\npotential risks to its own information and communication systems. The Mechanism has\nmaintained a high level of vigilance in this regard, implementing additional protections and\nprecautions as necessary. Its cybersecurity framework has evolved through continuous\ntraining and internal initiatives that ensure that both electronic systems and personnel are\ncapable of resisting and responding to cyberattacks. Cybersecurity measures are devised and\nimplemented at the foundational level of all new information and technology systems before\nthey become operational."},{"id":"a-hrc-51-4-p0030","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"30","seq":32,"section":"B. Analysis and sharing of information","text":"The Mechanism continues to ensure that its analytical work is keeping pace with its\nvast and growing collection of information and evidence. To date, the Mechanism has\nprepared over 67 packages with supporting information and analysis available for sharing\nwith relevant authorities, utilizing technology to enhance its analytical methods and products.\nSpecifically, the Mechanism is developing its technology capabilities in several essential\nareas, including in computer-aided translations and in computer vision and context\nmanagement solutions, as well as in accessing and extracting of patterns and connections in\nlarge amounts of data, to analyse, categorize and manage digital media files and geospatial\nimagery. These tools will be integrated into a powerful database equipped with the capacity\nto handle the large quantities of data collected and will be utilized to provide actionable\ninformation to advance the analytical and sharing activities of the Mechanism.\nAnalysing information and evidence"},{"id":"a-hrc-51-4-p0031","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"31","seq":33,"section":"B. Analysis and sharing of information","text":"The Mechanism has identified new areas and methodologies for detailed and\nmeaningful analysis of the vast information it has collected. Such analyses serve a dual\nfunction: to inform and drive forward the Mechanism’s ongoing investigations and to\nproduce analytical reports that can be shared with requesting jurisdictions. Areas for analysis\nare identified both within the Mechanism’s identified situations and incidents spanning the\nfull temporal scope of its mandate from 2011 to the present day, as well as in relation to\ncross-cutting, contextual or thematic areas."},{"id":"a-hrc-51-4-p0032","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"32","seq":34,"section":"B. Analysis and sharing of information","text":"This includes analysis of social media and communications information; military\nstructures and chains of command; financial structures and connections between persons and\ngroups of interest; and digital analysis techniques, including geolocation of sites of interest.\nIncreased expertise in the collection and analysis of open source and financial information in\nthe past year has played an important role in boosting analytical results. The Mechanism has\nalso increased its capacity for Rohingya language translation and evidence review, which has\nbeen vital in analysing large swathes of audiovisual material that was produced during and\nin the wake of the 2017 clearance operations in Rakhine State. The availability of\ncontemporaneous photographs and video footage taken during the clearance operations,\ncombined with geospatial imagery, provides an opportunity for geolocation and cross-\ncorroboration of evidence."},{"id":"a-hrc-51-4-p0033","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"33","seq":35,"section":"B. Analysis and sharing of information","text":"The Mechanism’s commitment to applying cutting-edge technologies to its\ninvestigations extends to its analytical products. The Mechanism has invested in world-\nleading software capable of performing advanced analytics on organized data sets and is\ncustomizing an in-house platform for evidence review, gap analysis and legal classification.\nThe Mechanism also continued its work on an integrated mapping tool that will aggregate\ninformation and evidence, including geospatial imagery, photographs, videos and witness-\nsourced information, onto a secured, cloud-based platform that can both geographically and\ntemporally demonstrate evidence relating to the commission of crimes. Simultaneously, the\nMechanism has embarked on a computer vision project to develop software capable of\nenhancing human analysis by deriving meaningful information from a vast pool of evidence,\nparticularly in relation to the automatic detection and categorization of photographs and\nvideos."},{"id":"a-hrc-51-4-p0034","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"34","seq":36,"section":"B. Analysis and sharing of information","text":"In conceptualizing these analytical products, the Mechanism aims to be responsive to\nthe needs of requesting jurisdictions, taking into account feedback about the specific types of\nanalytical products that will be most useful to the jurisdictions or institutions with which the\nMechanism shares information.\nSharing information and evidence with relevant entities and jurisdictions"},{"id":"a-hrc-51-4-p0035","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"35","seq":37,"section":"B. Analysis and sharing of information","text":"The Mechanism continued to increase the volume of information and evidence that\ncan be shared for use in national, regional and international courts or tribunals willing or able\nto hold persons to account for crimes in the Mechanism’s mandate. During the past year, the\nMechanism has shared geospatial imagery and documentary and witness-related evidence\nwith requesting jurisdictions. Simultaneously, this has also laid the groundwork for increased\nsharing in the years to come. To facilitate the sharing process, the Mechanism has held a\nnumber of meetings and working sessions with sharing partners to better understand the\nspecific scope of their investigations or proceedings and the applicable rules of procedure in\ntheir respective jurisdictions relevant to the admissibility and the weight accorded to different\ntypes of evidence; and to discuss how the Mechanism can best provide relevant and probative\ninformation to support relevant judicial processes."},{"id":"a-hrc-51-4-p0036","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"36","seq":38,"section":"B. Analysis and sharing of information","text":"The Mechanism has also explored other ways to coordinate with sharing partners that\nare also carrying out independent investigations, to ensure, in particular, that vulnerable or\nhigh-risk victims and witnesses are not approached by multiple jurisdictions for witness\ninterviews. This is particularly salient in relation to the concurrent investigations and judicial\nproceedings concerning alleged crimes against the Rohingya population. The Mechanism has\nalso fine-tuned its methodologies for obtaining informed consent from witnesses for the\nonward sharing of witness screenings, statements and associated evidence. This includes\nproviding clear information concerning the potential use and disclosure of their information\nin requesting jurisdictions. In parallel, the Mechanism has finalized its internal procedures\nfor the secure sharing of material with requesting jurisdictions."},{"id":"a-hrc-51-4-p0037","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"37","seq":39,"section":"B. Analysis and sharing of information","text":"Given the various simultaneous investigations or judicial proceedings currently under\nway pertaining to the situation of the Rohingya, the Mechanism has continued to ensure close\nand timely cooperation with the International Criminal Court and the proceedings before the\nInternational Court of Justice. The Mechanism has also engaged with judicial authorities in\nArgentina with a view to supporting the latter’s investigation into crimes against the\nRohingya based on universal jurisdiction. The Mechanism continues to share information\nwith the Office of the Prosecutor of the International Criminal Court that is relevant to the\nlatter’s investigation into alleged crimes against the Rohingya and continues to identify\nfurther opportunities for sharing in this regard, ranging from witness-related materials to\naudiovisual and documentary items as well as analytical products and expert reports. In The\nGambia v. Myanmar, the International Court of Justice is currently considering the\napplication filed by the Gambia, which claims that Myanmar is in violation of its obligations\nunder the Convention on the Prevention and Punishment of the Crime of Genocide. The\nMechanism continues to share relevant materials with the parties in the case, after ensuring\nthat it has the consent of the information provider(s) and determining that the information\nwill not affect the security or privacy rights of those whom the materials concern."},{"id":"a-hrc-51-4-p0038","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"38","seq":40,"section":"C. Cooperation arrangements and modalities","text":"During the reporting period, the Mechanism intensified its efforts to engage with a\nvariety of relevant entities and actors to establish arrangements and cooperation frameworks\nor modalities to facilitate the implementation of its mandate. The Mechanism has actively\nengaged and developed arrangements with a large network of actors, including nearly 200\ncivil society organizations, businesses, national authorities, international organizations and\nUnited Nations entities to facilitate the collection, preservation and storage of information.\nThe majority of these arrangements have been concluded with civil society and\ndocumentation actors, which remain a crucial source of information and evidence regarding\ncrimes committed in Myanmar."},{"id":"a-hrc-51-4-p0039","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"39","seq":41,"section":"C. Cooperation arrangements and modalities","text":"Resuming in-person high-level dialogue and consultations with Member States and\nother actors was a critical priority of the Mechanism during the reporting period. While\nvirtual contacts have continued, in-person engagements, especially with Member States, have\nbeen essential to enable the dedicated and multilayered negotiations required to advance\ncooperation so that the Mechanism is able to carry out evidence collection and witness\ninterviews in their territories."},{"id":"a-hrc-51-4-p0040","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"40","seq":42,"section":"C. Cooperation arrangements and modalities","text":"The Mechanism continues to seek the cooperation of the authorities of Myanmar to\nobtain access to witnesses, victims and other sources of information, and access to locations\nwhere alleged crimes have occurred. The Mechanism has made 10 requests to the Myanmar\nauthorities, both for access to the territory and to information in the possession of the\nGovernment or the security forces. For example, the Mechanism requested information on\nthe targets and casualties pertaining to the alleged attacks carried out by the Arakan Rohingya\nSalvation Army on 25 August 2017, which were reported by Myanmar authorities to be the\nimmediate precursor of the 2017 clearance operations. The Mechanism has requested access\nto prisons and detention sites, as well as areas housing internally displaced persons in\nRakhine State. The Mechanism also requested that the authorities of Myanmar provide the\nfull report of the Independent Commission of Enquiry into events in Rakhine State, as only\nsummary information has been publicly released to date. The Mechanism has also requested\ninformation concerning the identities of persons detained since the military takeover of 1\nFebruary 2021, the charges against them and the results of any judicial proceedings. The\nMyanmar authorities have not responded to these requests and none of the information has\nbeen received."},{"id":"a-hrc-51-4-p0041","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"41","seq":43,"section":"C. Cooperation arrangements and modalities","text":"The Mechanism will continue to reach out and seek information from the current\nMyanmar authorities, in line with relevant Human Rights Council and General Assembly\nresolutions that call upon Myanmar to cooperate and meaningfully engage with the\nMechanism, including by granting unrestricted access for its activities. The Mechanism will\nalso continue to seek information from all relevant parties regarding potential international\ncrimes committed in Myanmar. The Mechanism seeks both incriminating and exonerating\ninformation relevant to serious international crimes within its mandate."},{"id":"a-hrc-51-4-p0042","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"42","seq":44,"section":"C. Cooperation arrangements and modalities","text":"The Mechanism continued its efforts to deepen cooperation and engagement with\nother Member States to enable collection activities and witness interviews in their territories,\nparticularly within the Asia-Pacific region where much of the evidence and many of the\nwitnesses are located. To date, the Mechanism has established several cooperation\nframeworks with Member States to enable investigative activities in their territories and the\nprovision of specialized services and logistical support. The Human Rights Council and the\nGeneral Assembly have continuously reaffirmed the centrality of such cooperation to the\neffective and efficient implementation of the Mechanism’s mandate. It is only with such\ncooperation that the Mechanism will be able to gain access to valuable witnesses and to\ngather testimonial evidence that meets the exigent standard of proof in a criminal proceeding,\nand in a manner that ensures the witnesses’ security and privacy. The cooperation of Member\nStates is also needed in order to facilitate the protection and support of witnesses and prevent\nany reprisals for cooperation with the Mechanism."},{"id":"a-hrc-51-4-p0043","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"43","seq":45,"section":"C. Cooperation arrangements and modalities","text":"Discussions with several States on how the Mechanism can access their territory in\norder to carry out its mandated activities have been slow. This has substantially impacted the\nMechanism’s ability to obtain signed statements from those who witnessed or experienced\nevents relevant to proving serious international crimes. Detailed signed witness statements\nobtained by trained and experienced investigators in face-to-face interviews are critical\nproducts that the Mechanism aims to share with judicial authorities, so that they have the best\nevidence available in their search for the truth. As the International Criminal Court and\nArgentine investigations are ongoing and the proceedings at the International Court of Justice\nare well advanced, the Mechanism does not have unlimited time to collect and analyse\nevidence for sharing with these institutions. Accordingly, the Mechanism will redouble\nefforts to obtain permission from all relevant States for the cooperation necessary to fulfill\nits mandate."},{"id":"a-hrc-51-4-p0044","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"44","seq":46,"section":"C. Cooperation arrangements and modalities","text":"The Mechanism highly appreciates the cooperation and coordination of a diverse set\nof United Nations entities, both at their headquarters and their relevant field offices. The\nMechanism has been consulting regularly with various United Nations entities regarding the\nsituation in Myanmar and leveraging their knowledge and expertise that is relevant and useful\nto the Mechanism’s operations. The Mechanism has also benefited from general support\nservices provided by the Secretariat and other United Nations entities, both at Headquarters\nand in the field, including with regard to security requirements and logistical support. The\nMechanism will also continue its efforts to seek the cooperation of other United Nations\nactors that have not yet executed the Mechanism’s requests for assistance."},{"id":"a-hrc-51-4-p0045","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"45","seq":47,"section":"C. Cooperation arrangements and modalities","text":"As its operations and policy frameworks mature, the Mechanism continues to consult\nwith international courts and other international accountability mechanisms to learn from\ntheir experiences and good practices, in line with the respective mandates of each entity. The\nMechanism coordinates closely with these entities in areas of mutual concern, including staff\ntraining, legal cooperation, and information technology systems and data management."},{"id":"a-hrc-51-4-p0046","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"46","seq":48,"section":"D. Engagement with relevant stakeholders and public outreach","text":"Outreach to victims, survivors, civil society groups and other stakeholders is a priority\nfor the Mechanism in order to raise awareness of its complex mandate, explain its methods\nof work and clarify what can and cannot be expected from its efforts. The Mechanism makes\nevery effort to reach out to the many diverse communities that have a stake in its work, and\nregular communications through both public and confidential channels have helped to\nestablish and maintain trustworthy and cooperative relationships and to promote ongoing\ndialogues."},{"id":"a-hrc-51-4-p0047","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"47","seq":49,"section":"D. Engagement with relevant stakeholders and public outreach","text":"With the easing of COVID-19 travel restrictions, the Mechanism has been able to\nresume in-person outreach activities. Notably, a delegation led by the Head of the Mechanism\ntravelled to Bangladesh in May 2022 for the first time since late 2019. In addition to meeting\nwith government authorities to discuss the country’s ongoing cooperation with the\nMechanism, the Head of the Mechanism held several interactive dialogues with more than\n150 Rohingya representatives in Cox’s Bazar, including women’s organizations, to raise\nawareness about the Mechanism’s purpose and methods of work. The delegation also met\nwith relevant civil society organizations, and the Head of the Mechanism conducted an\ninterview with a Rohingya language radio service based in Cox’s Bazar in order to reach the\nbroadest possible audience of forcibly displaced Rohingya in the area. In these presentations,\nthe Mechanism sought to convey what the Rohingya population could expect to see the\nMechanism accomplish, and, importantly, what is outside the mandate of the Mechanism and\ncould not realistically be expected. Furthermore, through dialogues with victim groups, the\nMechanism sought to better understand their desires and concerns. Repeatedly, the message\nreceived was that the victims hoped for conditions to allow their safe return to their homes in\nMyanmar."},{"id":"a-hrc-51-4-p0048","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"48","seq":50,"section":"D. Engagement with relevant stakeholders and public outreach","text":"The Mechanism’s website has proven to be a highly effective platform for\ndisseminating timely information and providing answers to frequently asked questions. It\nreaches a range of audiences in English and the Myanmar language (Burmese). The website\nalso includes information in audio form in the Rohingya language. The bulletin that the\nMechanism produces approximately three times per year highlights institutional updates and\noutreach efforts. It is featured on the website and is broadly distributed so that civil society\ngroups, Member States and other key stakeholders are kept aware of the Mechanism’s\nactivities. Social media platforms, which are widely consumed within Myanmar and in the\ndiaspora, are an essential vehicle for sharing information. The Mechanism’s Facebook page\nhas a following of more than 70,000 people who amplify the Mechanism’s messages on other\nplatforms. As the Mechanism’s mandate is complex, and its key audiences speak a variety of\nlanguages with varying levels of literacy, it is essential that information about the Mechanism\nbe easy to understand and be able to be shared organically across communication channels.\nIn the upcoming reporting period, the Mechanism will simplify its messaging and present it\nin visual and audio formats to ensure that the content is accessible, memorable and shareable."},{"id":"a-hrc-51-4-p0049","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"49","seq":51,"section":"D. Engagement with relevant stakeholders and public outreach","text":"The Mechanism has actively engaged with civil society groups through in-person and\nvirtual meetings. This has facilitated ongoing dialogues and increased understanding about\nthe Mechanism’s mandate, which has helped to gain confidence in its work and to secure\nincreased cooperation. The Mechanism has also participated in public events organized by\nMember States and civil society organizations on topics related to justice and accountability\nin Myanmar. The Mechanism has continued to use its public communication platforms to\nconvey the importance of secure means of communications for the safety and security of both\nstakeholders and Mechanism personnel, and the confidentiality of the information exchanged\nor its engagements."},{"id":"a-hrc-51-4-p0050","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"50","seq":52,"section":"D. Engagement with relevant stakeholders and public outreach","text":"Media and public interest in the work of the Mechanism continues. Interviews, press\nreleases, statements and media briefings have resulted in regular coverage by influential\nglobal, regional and national media outlets, including media in the languages used in\nMyanmar, which has reached broad audiences. In particular, a United Nations media briefing\nby the Head of the Mechanism in New York in November 2021 resulted in extensive\ncoverage with positive sentiment by global news agencies and top-tier media outlets."},{"id":"a-hrc-51-4-p0051","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"51","seq":53,"section":"IV. Operational and administrative support","text":"As it commences its fourth year of operations, the Mechanism has made important\nprogress in establishing the full set of operational and administrative systems to enable the\nimplementation of the Mechanism’s core priorities. Such systems involve matters related to\ninformation management and technology; witness and victim protection and support; security;\nand staffing, including language assistance.\nTechnology and infrastructure"},{"id":"a-hrc-51-4-p0052","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"52","seq":54,"section":"IV. Operational and administrative support","text":"During the reporting period, the Mechanism continued to solidify its core and\nspecialized technology and infrastructure for handling the information and evidence that it\nreceives and collects. The Mechanism has continued to procure and operationalize additional\nnecessary software and equipment to facilitate the processing, management and review and\nanalysis of its repository. The Mechanism has partnered with United Nations computing and\ndata centres to leverage and adopt existing tools and platforms to enable the Mechanism to\ncollect, preserve and analyse a vast trove of information and data, while always ensuring\naccessibility, including in remote locations. The Mechanism has developed custom-made\nsolutions to extract and preserve data from a variety of social media and messaging\napplications. Furthermore, the Mechanism has procured multiple secure cloud-based\nplatforms to bolster its forensic capabilities. These solutions and platforms have enabled the\nMechanism to collect and analyse additional data previously not possible. As the Mechanism\nresumes in-person investigative activities, information technology, management and security\nare essential ingredients to ensure that investigative teams can reliably communicate and\naccess the Mechanism’s electronically stored information management system and the\ninformation and data therein, in line with confidentiality and security requirements of its\noperations. In this regard, the Mechanism has procured travel kits and communication\ndevices to support its field missions.\nWitness protection and support"},{"id":"a-hrc-51-4-p0053","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"53","seq":55,"section":"IV. Operational and administrative support","text":"The Mechanism has further increased its witness support and protection capabilities\nto ensure that vulnerable witnesses receive protection and psychosocial services in a manner\nconsistent with the Mechanism’s mandate and a victim/survivor-centred approach. As the\nMechanism has expanded the scope of its interactions with witnesses, particularly among\nvictim communities, Mechanism investigators have been faced with the challenge of\ncollecting detailed and probative evidence in line with the highest standards in criminal\ninvestigations, while simultaneously ensuring that traumatized witnesses receive the\nnecessary psychosocial support before, during and after their engagement with the\nMechanism. The addition of dedicated witness support capacities has bolstered the\nMechanism’s ability to apply a survivor-centric approach in all of its engagements with\nwitnesses. Drawing on the best practices of international criminal accountability mechanisms,\nthe Mechanism is developing standard operating procedures as well as witness protection and\nsupport services tailored to the specific context of its activities. In preparation for\ninvestigative activities in different locations, the Mechanism is working with various partners\non the ground to identify and develop referral pathways to ensure safe interventions and\ncontinuous support to the witnesses with whom it interacts."},{"id":"a-hrc-51-4-p0054","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"54","seq":56,"section":"IV. Operational and administrative support","text":"The Mechanism has also developed a comprehensive approach to witness protection\nbased on the potential assistance by Member States and other partners to support its effective\nimplementation. Lastly, and to complement the Mechanism’s existing but limited capacities,\nthe Mechanism is mobilizing extrabudgetary resources in order to be able to refer witnesses\nwho require medical and/or psychosocial assistance to those who can competently provide\nsuch services and to allow the Mechanism to meet the support needs of witnesses or\ninformation providers at significant risk.\nPhysical security"},{"id":"a-hrc-51-4-p0055","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"55","seq":57,"section":"IV. Operational and administrative support","text":"The Mechanism incorporates physical security needs and considerations into all\naspects of its operations. The Mechanism’s security coordination officer supports Mechanism\npersonnel on all collection, analysis and sharing activities. The Mechanism has established\nrobust communication channels with United Nations system entities and other security\ninterlocutors in the field to support the planning and conduct of future field missions. In\nconsultation and coordination with United Nations security actors, the Mechanism\nundertakes security risk assessments to identify threats and risks associated with its activities\nor missions; ensures technical oversight and support related to travel; establishes and\nmanages an internal security clearance system for travel, including mission tracking; and\ncoordinates emergencies, including medical evacuations.\nStaffing and specialized capacities"},{"id":"a-hrc-51-4-p0056","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"56","seq":58,"section":"IV. Operational and administrative support","text":"At nearly full staffing levels, the Mechanism redoubled its efforts during the reporting\nperiod to expeditiously recruit personnel in line with its schedule and substantive strategy.\nThe Mechanism continued to prioritize the recruitment of personnel with a diverse range of\nexpertise and specializations in criminal investigations and prosecutions. In line with its\nterms of reference, due consideration is given to the representation of different legal traditions,\ngeographic diversity, gender balance, regional expertise and relevant language skills. As\nnoted above, the Mechanism has further enhanced its capacities, particularly in highly\nspecialized areas of expertise such as collection and analysis of open source and financial\ninformation and the investigation of sexual and gender-based crimes and crimes against and\naffecting children."},{"id":"a-hrc-51-4-p0057","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"57","seq":59,"section":"IV. Operational and administrative support","text":"As the Mechanism continues to expand its collection and analysis activities, the\nvolume of information and evidence in its possession is heightening challenges arising from\nlanguage-related needs, particularly for material originating in the various languages used in\nMyanmar. To respond to these challenges, the Mechanism is taking concrete steps to increase\nits language capacities and support, continuously evaluating its internal language needs to\ndetermine what language support and tools would be most appropriate and, where possible,\nto deploy innovative technological solutions, including machine-learning translation tools.\nThe Mechanism is also seeking to further improve its in-house interpretation and translation\ncapabilities, with a view to supporting investigative missions and other activities."},{"id":"a-hrc-51-4-p0058","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"58","seq":60,"section":"IV. Operational and administrative support","text":"Underpinning the Mechanism’s operational and administrative structures is a\ncomprehensive set of foundational policies, protocols and procedures, covering a wide range\nof activities, including investigations; information management and technology;\nclassification and handling of sensitive information; mission planning and support; witness\nprotection and support; security; and administration. These policies and procedures form part\nof a well-integrated toolset ensuring accountability and consistent practices across the\nMechanism’s activities. Where applicable and relevant to the Mechanism’s context, they also\ndraw upon and incorporate the good practices of other comparable international\naccountability mechanisms."},{"id":"a-hrc-51-4-p0059","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"59","seq":61,"section":"V. Challenges and areas for additional support","text":"To carry out its mandate, the Mechanism needs the full cooperation and engagement\nof Member States, United Nations entities and other actors to advance its substantive work,\ninterview witnesses in different locations, and increase the amount of forensically valuable\ntestimony in its repository so that it can further contribute to ongoing proceedings before the\nInternational Criminal Court, the International Court of Justice and others relevant to its\nmandate."},{"id":"a-hrc-51-4-p0060","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"60","seq":62,"section":"V. Challenges and areas for additional support","text":"Such support is especially required to overcome persistent challenges affecting the\nMechanism’s ability to gather information, interview witnesses and operate in the territories\nof Member States, particularly in the Asia-Pacific region, where the majority of information\nproviders and witnesses are located. The authorities in Myanmar have consistently denied\nthe Mechanism access to its territory, preventing on-the-ground investigations in the country\nwhere the crimes were allegedly committed. In this context, the cooperation and support of\nother Member States will be a decisive factor in the success of the Mechanism’s efforts.\nFollowing the military takeover in February 2021, a complex interplay of local, regional and\ninternational dynamics has further contributed to increasing challenges in this regard."},{"id":"a-hrc-51-4-p0061","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"61","seq":63,"section":"V. Challenges and areas for additional support","text":"In addition, even States that have expressed strong support for the work of the\nMechanism do not always have in place the internal legal and regulatory procedures to\nfacilitate the Mechanism’s access to their territories. The Mechanism welcomes\ncommitments made by several Member States to expedite the timely adoption and approval\nof their respective legal cooperation frameworks with the Mechanism that are currently under\nway. While the Mechanism greatly values the pragmatic and proactive cooperation of some\nMember States, the cooperation of all Member States is necessary for the Mechanism to\neffectively discharge the mandate set out by the Council and endorsed by the General\nAssembly. During the next reporting period, the Mechanism will continue to make concerted\nefforts to strengthen cooperation with Member States so that it may access information and\nwitnesses and operate on more territories. The Mechanism will also continue its systematic\nefforts to engage with the authorities of Myanmar in seeking its cooperation with respect to\nthe implementation of its mandate."},{"id":"a-hrc-51-4-p0062","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"62","seq":64,"section":"V. Challenges and areas for additional support","text":"As the Mechanism has substantially increased its level of engagement with witnesses,\nthe safety and security of potential witnesses has also become a core and pressing concern\nduring the reporting period. The Mechanism is in contact with many potential witnesses who\nappear to have credible information that could advance investigations of crimes within the\nMechanism’s mandate. However, the most unique and critical evidence is held by a category\nof witnesses called “insiders”. Some of these witnesses have information that is of very high\nvalue to efforts to ensure accountability for serious international crimes in Myanmar, and\nsuch witnesses are at very serious risk of harm. The Mechanism has developed a\ncomprehensive approach to witness protection and is engaging with cooperating States and\nother international organizations in order to coordinate and identify assistance and access to\nsafe and quality services. Cooperation and operational support from a broader group of States\nwill be a decisive factor in the success of these efforts."},{"id":"a-hrc-51-4-p0063","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"63","seq":65,"section":"V. Challenges and areas for additional support","text":"Likewise, for the Mechanism to fulfil its mandate, engagement with civil society\nrepresentatives working on justice and accountability issues related to Myanmar, as well as\nindividuals who can provide information to the Mechanism, is essential. More personal\ninteractions to build trust and increase confidence in the Mechanism’s ability to contribute to\ninternational criminal accountability processes are critical factors in these efforts. With the\neasing of COVID-19 restrictions, which curtailed in-person interactions, the Mechanism will\ninitiate a structured and regular forum that will bring together relevant individuals and\norganizations to deepen collaboration and information-sharing."},{"id":"a-hrc-51-4-p0064","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"64","seq":66,"section":"VI. Conclusion","text":"In three years, the Mechanism has made concrete progress to advance its\ninvestigative activities and set up foundational and core infrastructure to enable the\nlonger-term implementation of its mandate. It has responded with equal vigour to\nopportunities and challenges, quickly adapting to new contextual developments,\nadjusting working methods and strategically allocating its lean resources."},{"id":"a-hrc-51-4-p0065","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"65","seq":67,"section":"VI. Conclusion","text":"Navigating increased challenges and building on the momentum it has achieved,\nthe Mechanism will continue to use all possible strategies and innovations to gather and\nverify evidence to build strong case files that can facilitate justice for the people in\nMyanmar. To this end, the Mechanism will continue to increase the interviewing of\nwitnesses and other individuals of interest in different locations; seek to deepen\ncooperation and engagement with States to enable the Mechanism to carry out\ncollection activities, particularly in States within the Asia-Pacific region; implement a\nrobust programme for the protection and support of witnesses; and continue to deploy\nadvanced technology and software to support complex collection and analytical\nprocesses, including the review and processing of the vast quantity of documentation,\ndigital and social media material. It remains crucial that the Mechanism, as called for\nby the Human Rights Council and the General Assembly, is given unrestricted access\nto the territory of Myanmar and that of other Member States where witnesses and\nevidence is located and afforded the flexibility that it needs in terms of staffing, location\nand operational freedom so it can deliver as effectively as possible on its mandate."},{"id":"a-hrc-51-4-p0066","rec_id":"recVrXMSNXCakBPmR","symbol":"A/HRC/51/4","n":"66","seq":68,"section":"VI. Conclusion","text":"The full and meaningful cooperation of all parts of the international community,\nespecially Member States in the Asia-Pacific region, will remain essential. Without such\nsupport, the Mechanism will be hindered from fully delivering on its mandate and\nplaying its role in facilitating and supporting criminal proceedings that advance\naccountability and help bring some justice for the people of Myanmar."},{"id":"a-hrc-54-19-u0000","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":null,"seq":0,"section":null,"text":"Summary\nThe present document is the fifth report submitted by the Independent Investigative\nMechanism for Myanmar to the Human Rights Council pursuant to resolution 39/2 of 27\nSeptember 2018. It covers the activities carried out by the Mechanism between 1 July 2022\nand 30 June 2023.\nFour years after it began operations, the Mechanism continues to actively monitor and\ninvestigate the deteriorating situation in Myanmar. Armed conflicts substantially intensified\nduring the reporting period. The Mechanism reiterates its previous assessment that there is\nstrong evidence indicating that serious international crimes are being inflicted against the\npeople in Myanmar. With no foreseeable end to the violence, the work of the Mechanism to\nfacilitate justice and accountability is more relevant and necessary than ever.\nThe Mechanism has made consistent and notable progress in fulfilling its mandate. It\nsignificantly increased the amount of first-hand testimonial evidence collected, by\nconducting several investigative missions to refugee camps and other locations and by\ncarrying out screenings and in-person interviews with witnesses, survivors and defectors.\nThe Mechanism also continued to collect additional evidence, such as photographs, videos,\naudio material, documents, maps, geospatial imagery, social media posts and forensic\nevidence. By the end of the reporting period, the Mechanism had collected millions of\ninformation items, and engaged with over 700 sources and information providers. The\nevidence collected will enable the Mechanism to continue building case files and analytical\nproducts to prove individual criminal responsibility for serious international crimes in\nMyanmar.\nThe Mechanism is sharing evidence it has collected and its analysis for use in ongoing\njudicial processes. During the reporting period, the Mechanism completed three major\nanalytical reports to be shared with national and international courts or tribunals, focusing\non the structure and reporting lines within the Myanmar military; the failure of Myanmar\nauthorities to investigate or punish sexual and gender-based crimes; and the organized spread\nof hate speech content on Facebook by the Myanmar military before, during and after the\n2017 “clearance operations”.","unnumbered":true},{"id":"a-hrc-54-19-u0001","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":null,"seq":1,"section":null,"text":"The Mechanism made significant strides in expanding and diversifying its\ncollaboration with civil society organizations, which make critical contributions to its work\nowing to their access to on-the-ground information and contacts with potential witnesses. In\nthe second quarter of 2023, the Mechanism held its first civil society dialogue, bringing\ntogether representatives from relevant civil society organizations to deepen partnerships and\nstrengthen processes for ongoing cooperation and information-sharing. The civil society\ndialogues will be a regular and important component of the Mechanism’s increased\nengagement and collaboration with civil society organizations.","unnumbered":true},{"id":"a-hrc-54-19-p0001","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"1","seq":2,"section":"I. Introduction","text":"The present report covers the activities carried out by the Independent Investigative\nMechanism for Myanmar between1 July 2022 and 30 June 2023."},{"id":"a-hrc-54-19-p0002","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"2","seq":3,"section":"I. Introduction","text":"In its resolution 39/2 of 27 September 2018, the Human Rights Council established\nthe Mechanism with a mandate to collect, consolidate, preserve and analyse evidence of the\nmost serious international crimes and violations of international law committed in Myanmar\nsince 2011, and to prepare files in order to facilitate and expedite fair and independent\ncriminal proceedings, in accordance with international law standards, in national, regional or\ninternational courts or tribunals. In its resolution 73/264 of 22 December 2018, the General\nAssembly welcomed the establishment of the Mechanism. In its resolution 43/26 of 22 June\n2020, the Council specifically called for the Mechanism to engage in close and timely\ncooperation on future investigations by, among others, the International Criminal Court and\nthe International Court of Justice."},{"id":"a-hrc-54-19-p0003","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"3","seq":4,"section":"I. Introduction","text":"Four years after it became operational, the Mechanism continues to actively monitor\nthe deteriorating situation in Myanmar and to collect, analyse and share evidence of the most\nserious international crimes committed in Myanmar. The military continues to carry out\nwidespread and systematic attacks on the civilian population and the armed conflict\nsubstantially intensified during the reporting period. In this context, the Mechanism is\nstrategically focusing its investigations on specific incidents where the impact on victims is\nthe most severe. A major focus remains on investigating crimes against the Rohingya,\nespecially those committed during the 2016 and 2017 “clearance operations” carried out by\nMyanmar security forces in Rakhine State."},{"id":"a-hrc-54-19-p0004","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"4","seq":5,"section":"I. Introduction","text":"The Mechanism operates in a challenging environment with no physical access to\ncrime sites or witnesses inside Myanmar and has serious witness protection concerns. To\ncompensate, the Mechanism is adopting innovations and leveraging the use of advanced\ntechnologies and modern investigative approaches to enable the collection of evidence. The\nMechanism continues to reach out to authorities in Myanmar to seek their cooperation as\ncalled for by the Human Rights Council and the General Assembly, but to date, all requests\nfor access to the territory, cooperation and information have gone unanswered."},{"id":"a-hrc-54-19-p0005","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"5","seq":6,"section":"I. Introduction","text":"During the reporting period, the Mechanism significantly increased the number of\ninvestigative missions and direct engagements with witnesses and survivors. The\ninvestigation of sexual and gender-based crimes and crimes against children remains a high\npriority. The Mechanism is also fully integrating the collection and analysis of open source\nand financial information and evidence in all of the Mechanism’s investigations. Throughout\nthe year, the Mechanism engaged closely with a wide range of stakeholders, including\nwitnesses, survivors, civil society organizations, Member States, United Nations entities and\nbusiness entities, in order to strengthen partnerships and cooperation in support of justice and\naccountability for the crimes committed in Myanmar. The Mechanism is very grateful for the\ncooperation received from witnesses and survivor groups, which reflects the courage and\ndedication of the people of Myanmar to the fight against impunity."},{"id":"a-hrc-54-19-p0006","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"6","seq":7,"section":"II. Collecting, analysing and managing information and","text":"During the reporting period, the Mechanism collected an unprecedented and\nunanticipated amount of information and evidence. This has required the utilization of more\ncomplex and sophisticated processes for the collection of material, and for the preservation,\nanalysis and management of the material collected. In accordance with the principles of\nimpartiality and confidentiality, the Mechanism applies a multifaceted approach to evidence\ncollection, focusing on information and evidence pertaining to priority situations and\nincidents, contextual and overview information relevant to Myanmar, and information\npertaining to specific individuals, groups and structures suspected of perpetrating crimes. The\nMechanism seeks both incriminating and exonerating information from all relevant parties\nregarding potential serious international crimes committed in Myanmar within its mandate."},{"id":"a-hrc-54-19-p0007","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"7","seq":8,"section":"II. Collecting, analysing and managing information and","text":"Through its targeted approach to requesting and receiving information and evidence,\nthe Mechanism has collected substantial information from a wide range of over 700\ninformation providers and sources. These include civil society and documentation\norganizations, national authorities, United Nations entities, international organizations, non-\ngovernmental organizations, business entities and individual sources and witnesses. In order\nto collect first-hand, high-value testimony that is essential to building criminal cases, the\nMechanism has significantly increased the direct collection of witness testimony from\nsurvivors, eyewitnesses and defectors, resulting in over 200 witness statements and screening\nnotes as well as over 200 investigation notes to date. Investigative missions to different States\nenabled in-person interviews and the collection of other highly valuable and probative\ninformation. The Mechanism acknowledges with appreciation the support provided to its\ninvestigative activities by several relevant national authorities and other stakeholders."},{"id":"a-hrc-54-19-p0008","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"8","seq":9,"section":"II. Collecting, analysing and managing information and","text":"Since it became operational, the Mechanism has made over 170 formal requests for\ninformation to a variety of entities and individuals. These requests resulted in the collection\nof a vast and diverse range of information and evidence pertaining to its ongoing\ninvestigations. To partially compensate for the Mechanism’s inability to access the territory\nwhere crimes have been and continue to be committed, open source and financial information\ncontinues to be harvested from a diversity of sources and forms an integral part of the\nMechanism’s repository."},{"id":"a-hrc-54-19-p0009","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"9","seq":10,"section":"II. Collecting, analysing and managing information and","text":"To date, the Mechanism has collected and processed for potential sharing over 23\nmillion information items. These include documents, photographs, videos, audio material,\ngeospatial imagery, forensic evidence, witness statements and social media posts and other\nopen source materials. The majority of the collection is in the Myanmar language (Burmese),\nwhich has created a challenge given that the number of Mechanism personnel that have skills\nin that language is limited. Further, the collected material is in different Myanmar language\nscripts and file formats, which presents a challenge in making the material searchable in the\nMechanism’s electronically stored information management system."},{"id":"a-hrc-54-19-p0010","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"10","seq":11,"section":"II. Collecting, analysing and managing information and","text":"The Mechanism is constantly working to leverage the most current information\nmanagement technologies in order to ensure that the evidence it has collected is accessible\nand searchable and that the material is preserved in a manner that allows it to retain value for\nuse in future legal proceedings. As the digital information landscape continues to evolve and\nthe Mechanism’s collection of digital materials grows, the Mechanism has continued to\nintegrate new solutions to improve the intake, preservation and analysis of such material."},{"id":"a-hrc-54-19-p0011","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"11","seq":12,"section":"II. Collecting, analysing and managing information and","text":"These tools are increasingly enabling the Mechanism to expand the amount of\ninformation and evidence available for sharing with relevant authorities and entities. To date,\nthe Mechanism has prepared over 135 packages with supporting information and analysis\navailable for sharing with relevant authorities, of which 27 packages (comprising over 5,000\ninformation items) have already been shared with requesting authorities. The Mechanism’s\nsharing processes have also been informed by lessons learned and best practices identified\nthrough an internal evaluation of the Mechanism’s sharing activities. In line with these\nfindings, the Mechanism has identified areas for increased efficiencies and automation in\nreviewing, analysing and preparing materials for sharing, updated policies and protocols\nrelated to sharing, and developed guidance for requesting authorities and entities regarding\nthe process for submitting requests for assistance to the Mechanism."},{"id":"a-hrc-54-19-p0012","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"12","seq":13,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"The need to respond to atrocities committed against the Rohingya population of\nMyanmar was a principal factor in the decision made by the Human Rights Council to\nestablish the Mechanism. The Mechanism has therefore prioritized the investigations and\nfacilitation of ongoing justice proceedings for those crimes. Building on the information it\nhas already collected, the Mechanism made important progress during the reporting period\nwith respect to conducting an increasing number of in-person witness interviews, identifying\nkey lines of inquiry and developing tailored analytical products that can be shared with\nrelevant authorities in ongoing legal proceedings that concern those crimes."},{"id":"a-hrc-54-19-p0013","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"13","seq":14,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"The Mechanism has established a regular cycle of investigative missions to locations\nwhere survivors of serious international crimes in Myanmar have taken refuge. These\nmissions involve very detailed and methodical interviews, resulting in signed witness\nstatements of high forensic value. In previous reporting periods such missions were not yet\npossible because of travel restrictions related to the coronavirus disease (COVID-19)\npandemic and/or the need to reach cooperation agreements with the States concerned. The\nMechanism conducted dozens of investigative meetings, screenings and detailed interviews\nduring the reporting period, particularly with members of the Rohingya community. The\nMechanism has now laid the foundation for more investigative missions, having established\nand fine-tuned effective and efficient operational methodologies."},{"id":"a-hrc-54-19-p0014","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"14","seq":15,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"Witness security is a paramount concern that the Mechanism is integrating into all\naspects of witness interview planning and operations. The psychological well-being of\nwitnesses is also a major concern in all of the Mechanism’s operations. The Mechanism has\nestablished relationships with psychologists and psychosocial experts who are available to\nbe present for interviews when victims are asked to recall and recount their traumatic\nexperiences."},{"id":"a-hrc-54-19-p0015","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"15","seq":16,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"The Mechanism’s commitment to investigating sexual and gender-based crimes and\ncrimes against children has been at the forefront of these investigative missions. While the\nMechanism has sought to specifically identify and interview survivors of sexual and gender-\nbased crimes, it is notable that such crimes were so pervasive in the context of the clearance\noperations that most witnesses interviewed to date have relevant evidence in this regard. The\nMechanism has also sought to identify witnesses of sexual and gender-based crimes who\nhave not previously been approached by other fact-finding or documentation entities and\nwhose plight is often overlooked, including individuals with divergent gender identities and\nsexual orientations. In this regard, the Mechanism has commenced a dedicated line of inquiry\nfocusing on the experiences of the hijra (transgender) Rohingya community."},{"id":"a-hrc-54-19-p0016","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"16","seq":17,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"Throughout its engagements with the Rohingya community, the Mechanism has also\nplaced an emphasis on collecting information and documentation relevant to financial lines\nof inquiry, such as by examining the liability not only of direct perpetrators or commanders,\nbut also those who may have aided and abetted the commission of crimes within the\nMechanism’s mandate. As part of this effort, the Mechanism is concentrating its financial\ninvestigations on issues that have had a direct impact on victim communities, such as the\ndispossession and appropriation of land and personal property. For the Rohingya, the\ndispossession of land has significance beyond a simple abrogation of property rights. The\nunlawful taking of their land may constitute an attack on their identity as a people descended\nfrom a lineage that is based in Myanmar. To bolster its evidence, the Mechanism is also\npursuing these lines of inquiry through open source research and analysis, and the collection\nof information compiled by other entities. While the Mechanism has prioritized its inquiries\ninto the 2016 and 2017 clearance operations, it has also collected evidence concerning the\nethnic violence that occurred between 2012 and 2014, which led to the internal displacement\nof hundreds of thousands of Rohingya within Myanmar."},{"id":"a-hrc-54-19-p0017","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"17","seq":18,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"Accountability for crimes depends on proving individual criminal responsibility. The\nMechanism therefore places high priority on collecting “linkage evidence” that can\ndemonstrate the responsibility of specific individuals, particularly those at higher levels of\nauthority bearing greater responsibility for criminal campaigns. A fruitful source for such\nevidence is the testimony of “insider” witnesses, such as former members of the Myanmar\nsecurity forces, who have provided information concerning military operations and\nstructures, including during the clearance operations in northern Rakhine State."},{"id":"a-hrc-54-19-p0018","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"18","seq":19,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"The Mechanism has also advanced its analysis of the evidence collected relating to\ncrimes against the Rohingya, through the preparation of three analytical reports. The first of\nthese reports focuses on the structure and reporting lines within the Myanmar military,\nincluding the relevant units on the ground during the 2017 clearance operations. The second\nreport provides a compilation of evidence identified by the Mechanism that demonstrates the\nfailure of Myanmar authorities to investigate or punish sexual and gender-based crimes\ncommitted against the Rohingya by Myanmar security forces. The third report contains the\nfindings of a major review and analysis on the promulgation of hate speech content against\nthe Rohingya on Facebook by segments of the Myanmar military. The report examines the\nconnection between particular official Myanmar military pages and accounts and other\nseemingly non-official pages that were primary drivers of anti-Rohingya messaging around\nthe time of the 2017 clearance operations. The intention of the Mechanism is to share these\nanalytical reports with prosecutorial and judicial authorities conducting investigations or\nproceedings related to crimes against the Rohingya in Myanmar, namely the International\nCriminal Court, Federal Prosecutor’s Office No. 9 in Argentina, and the International Court\nof Justice (The Gambia v. Myanmar)."},{"id":"a-hrc-54-19-p0019","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"19","seq":20,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"The Mechanism also continues to identify relevant information and evidence it has\ncollected concerning crimes against the Rohingya and shares it with the three above-\nmentioned jurisdictions, provided it has received informed consent from the providers of the\ninformation. Those jurisdictions have different rules and procedures regarding the\nadmissibility of evidence, the protection and privacy of witnesses, and the language of\ndocuments and evidence they can consider. They also have different focus areas regarding\nthe targets of and the elements of the crimes and violations relating to their respective\ninvestigations and proceedings. The Mechanism intensified regular communication and\ndialogue with its sharing partners during the reporting period to better understand the needs\nof these different jurisdictions and to tailor its evidence and analytical packages accordingly."},{"id":"a-hrc-54-19-p0020","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"20","seq":21,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"Notably, the Mechanism has continued its close coordination with the Office of the\nProsecutor of the International Criminal Court and has increased the volume of witness-\nrelated information, including screenings and statements, shared with that Office during the\nreporting period. The Mechanism has also shared a substantial volume of information with\nFederal Prosecutor’s Office No. 9 in Argentina and has established a close dialogue with that\nOffice, to determine how the Mechanism can best continue to identify and share information\npertinent to the universal jurisdiction investigation presently under way in the country. Lastly,\nthe Mechanism is preparing to share additional material with the parties to The Gambia v.\nMyanmar proceedings before the International Court of Justice, which is currently\nconsidering claims by the Gambia that Myanmar is in violation of its obligations under the\nConvention on the Prevention and Punishment of the Crime of Genocide."},{"id":"a-hrc-54-19-p0021","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"21","seq":22,"section":"III. Investigating and facilitating judicial proceedings for crimes","text":"Through the sharing of evidence and analytical material, the Mechanism hopes to\ncontribute to the ongoing concurrent efforts to seek justice for the Rohingya, hold\naccountable those most responsible for the crimes committed and deter further atrocities."},{"id":"a-hrc-54-19-p0022","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"22","seq":23,"section":"IV. Investigating post-coup crimes","text":"Since the military coup on 1 February 2021, there has been a dramatic increase in the\nnumber of incidents bearing the hallmarks of serious international crimes and warranting\ninvestigation by the Mechanism. Tragically, the number of such incidents has only increased\nduring the reporting period. In accordance with the principles of impartiality and\nconfidentiality, the Mechanism is endeavouring to collect and analyse all relevant\ninformation in relation to these incidents and potential perpetrators, while necessarily\nfocusing its resources on the serious international crimes of the greatest gravity and on\npersons bearing the greatest responsibility for those crimes."},{"id":"a-hrc-54-19-p0023","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"23","seq":24,"section":"IV. Investigating post-coup crimes","text":"In its fourth annual report, the Mechanism stated that, based on the evidence it had\ncollected as the time of reporting, there were ample indications that widespread and\nsystematic attacks had been committed against the civilian population since February 2021,\nand that multiple armed conflicts were taking place on the territory of Myanmar. 1 This\nsituation continues, and the Mechanism has collected further and credible information from\nnumerous sources substantiating these findings."},{"id":"a-hrc-54-19-p0024","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"24","seq":25,"section":"IV. Investigating post-coup crimes","text":"The Myanmar authorities continue to disregard the Mechanism’s requests for\ninformation and for access to the territory of Myanmar. The Mechanism has nevertheless\nbeen able to obtain a substantial volume of information concerning ongoing events inside\nMyanmar from a variety of independent sources. The Mechanism is also harvesting open\nsource information almost contemporaneously with events as they occur. In addition,\nspecialized and targeted data, such as geospatial and geothermal imagery, have provided\n1   A/HRC/51/4, paras. 7 and 9.\nspecific and objective information concerning the impact of attacks on locations, particularly\nevidence of the burning of villages. Digital imagery from a wide array of open and non-open\nsources and recorded through various means, such as by drones and personal mobile\ntelephones, has in some cases provided direct evidence of specific crimes and the identity of\nperpetrators, including in relation to mass killings."},{"id":"a-hrc-54-19-p0025","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"25","seq":26,"section":"IV. Investigating post-coup crimes","text":"The Mechanism has opened investigations into events that have taken place during\nthe reporting period according to the same prioritization criteria set out in the Mechanism’s\nprevious reports, namely: the gravity of the crimes concerned, including their scale, nature,\nmanner of commission and impact on victims; the degree of responsibility of alleged\nperpetrators; the strength of the available evidence; the importance of the Mechanism’s\nthematic priorities concerning sexual and gender-based crimes and crimes against children;\nand the likelihood of a court or tribunal taking jurisdiction. The Mechanism’s mandate covers\nnot only war crimes committed by the security forces, but also any such crimes as may be\ncommitted by armed groups in connection with the armed conflict. Furthermore, the\nMechanism’s investigations are informed by thematic and cross-cutting elements, including\nthe investigation and analysis of organizational structures to identify those responsible for\nspecific crimes."},{"id":"a-hrc-54-19-p0026","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"26","seq":27,"section":"IV. Investigating post-coup crimes","text":"Based on the evidence collected to date, there is strong evidence that the Myanmar\nmilitary and its affiliate militias have committed three types of combat-related war crimes\nwith increasing frequency and brazenness: (a) indiscriminate or disproportionate targeting of\ncivilians using bombs; (b) killings of civilians or combatants detained during operations; and\n(c) large-scale and intentional burning of civilian dwellings and other civilian buildings."},{"id":"a-hrc-54-19-p0027","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"27","seq":28,"section":"IV. Investigating post-coup crimes","text":"The Myanmar military has attempted to justify several aerial bombardments that have\nled to substantial loss of civilian life, on the basis that there was a military target in the vicinity\nof the attack. However, the Mechanism has collected evidence indicating that the military\nshould have known, or did know, that large numbers of civilians were present in or around\nalleged military targets at the time of some of those attacks. The circumstances are manifestly\nindicative of a pattern of indiscriminate or disproportionate attacks, which is a war crime.\nThe Myanmar military has not announced investigations into any of these extremely grave\nincidents."},{"id":"a-hrc-54-19-p0028","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"28","seq":29,"section":"IV. Investigating post-coup crimes","text":"The Mechanism has also collected eyewitness accounts of mass executions of\ncivilians or fighters hors de combat in the custody of the Myanmar military forces or their\naffiliates that occurred during the reporting period. These accounts are often supported by\ncorroborating visual and documentary evidence collected by the Mechanism. The incidents\nhave occurred in disparate locations, such as the village of Tartaing, in Sagaing Township,\nSagaing Region; the village of Mon Taing Pin, in Ye-U Township, Sagaing Region; and the\nvillage of Nyaung Bin Tha, in Htantabin Township, Bago Region. The Myanmar military has\nnot announced investigations into any of these extremely grave incidents."},{"id":"a-hrc-54-19-p0029","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"29","seq":30,"section":"IV. Investigating post-coup crimes","text":"The evidence collected by the Mechanism further indicates that the large-scale\nburning and destruction of civilian objects by the Myanmar military forces and their affiliates\nhas continued during the reporting period. These events have occurred across several areas,\nparticularly in Sagaing, Magway, Chin, Kayin and Kayah, and typically involve civilian\nobjects such as shops, places of worship and civilian vehicles. In some cases, entire villages\nhave been destroyed. The evidence collected indicates that the fires were deliberately set by\nmilitary forces on the ground or were caused by artillery strikes. The documented cases of\nburning often have taken place alongside incidents of detentions and killings and have\ncontributed to the massive displacement of persons across Myanmar. The Myanmar military\nhas not announced investigations into any of these extremely grave incidents."},{"id":"a-hrc-54-19-p0030","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"30","seq":31,"section":"IV. Investigating post-coup crimes","text":"The Myanmar military’s failure to investigate or to otherwise curtail the pattern of\ncombat-related war crimes described above is significant. Military commanders have a duty\nunder international law to prevent or repress war crimes committed by those under their\ncommand. The failure to do so may make them criminally responsible under the principle of\ncommand responsibility; repeatedly ignoring such crimes may indicate that the higher\nauthorities intended the commission of these crimes."},{"id":"a-hrc-54-19-p0031","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"31","seq":32,"section":"IV. Investigating post-coup crimes","text":"Reliable evidence has been collected of the commission of other war crimes, such as\nrape, murder, mutilation and cruel treatment. There is also strong evidence that crimes against\nhumanity have been committed, including rape in detention; persecution; enforced\ndisappearance; and imprisonment, the passing of sentences and the carrying out of executions\nwithout having upheld fundamental fair trial rights and judicial guarantees."},{"id":"a-hrc-54-19-p0032","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"32","seq":33,"section":"IV. Investigating post-coup crimes","text":"Important progress has also been made on existing investigations, in particular in\nrelation to mass detentions and the non-observance of fundamental fair trial rights since\nFebruary 2021. The Mechanism has collected more and more evidence concerning torture,\nsexual violence and other forms of severe mistreatment at numerous detention facilities.\nSome of these facilities are run by the military, others by the police or the Myanmar Prisons\nDepartment. The Mechanism has in some cases identified specific abusers or those\nresponsible for running certain detention facilities."},{"id":"a-hrc-54-19-p0033","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"33","seq":34,"section":"IV. Investigating post-coup crimes","text":"Despite the obstacles to the investigation of such crimes arising from the non-\ncooperation of Myanmar, the Mechanism continues to collect substantial information relating\nto the commission of sexual and gender-based crimes committed against women, girls, men,\nboys and persons with diverse gender identities, including crimes committed by members of\nthe security forces. The Mechanism has collected evidence of such crimes being committed\nwith the highest levels of cruelty and harm to the victims, including rape with objects, other\nforms of humiliation, mutilation, gang or serial rape and sexual enslavement. The Mechanism\nhas received no information from the Myanmar authorities indicating that any military or\ncivilian official has been investigated, let alone prosecuted, for these crimes, which could be\ncharacterized as war crimes, crimes against humanity or both, depending on the\ncircumstances."},{"id":"a-hrc-54-19-p0034","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"34","seq":35,"section":"IV. Investigating post-coup crimes","text":"Evidence collected by the Mechanism indicates that children continue to be victimized\nby the same crimes to which adults are subjected. Further, there is evidence that children\nbelow 15 years of age are being enlisted, conscripted or used to participate actively in\nhostilities by various armed actors. Such crimes are particularly acute when committed\nagainst children because of the disproportionate harm likely to be caused, and the advantage\ntaken of their vulnerability in order to have them commit crimes. The Mechanism is thus\nparticularly committed to pursuing further evidence of such crimes."},{"id":"a-hrc-54-19-p0035","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"35","seq":36,"section":"IV. Investigating post-coup crimes","text":"The Mechanism has also received credible information of civilians being summarily\nkilled because they were suspected of being informers to, or collaborators with, the military\nregime. Such killings may constitute a war crime and the Mechanism is evaluating whether\nsuch incidents satisfy the chapeau elements of serious international crimes."},{"id":"a-hrc-54-19-p0036","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"36","seq":37,"section":"IV. Investigating post-coup crimes","text":"The Mechanism is also preparing evidence regarding post-coup crimes that can be\nshared with national, regional or international courts that may one day exercise jurisdiction\nover these crimes. Such evidence will be used to develop case files to establish the\ncommission of specific crimes and to also identify individuals criminally responsible for\nthose crimes."},{"id":"a-hrc-54-19-p0037","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"37","seq":38,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism acknowledges with gratitude the support extended to the\nMechanism’s mandate and investigative efforts by many Member States, United Nations\nentities, organizations, private and public information providers and other partners. This\nsupport remains crucial for the Mechanism to effectively carry out its mandate."},{"id":"a-hrc-54-19-p0038","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"38","seq":39,"section":"A. Cooperation with Member States and other partners","text":"During the reporting period, the Mechanism held several in-person high-level\ndialogues and consultations with Member States and other actors in Geneva, New York and\nnumerous capitals in order to promote the mandate of the Mechanism. These engagements\nenabled the Mechanism to advance important cooperation arrangements to carry out evidence\ncollection and witness interviews in the territories of Member States. To date, the Mechanism\nhas concluded around a dozen cooperation frameworks or arrangements with national\nauthorities, and is currently in the process of negotiating several other frameworks that will\nfurther enable and strengthen the Mechanism’s investigative activities."},{"id":"a-hrc-54-19-p0039","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"39","seq":40,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism continued to reach out to and seek information from the Myanmar\nauthorities, in accordance with relevant Human Rights Council and General Assembly\nresolutions in which the Council and the Assembly call upon Myanmar to cooperate and\nengage meaningfully with the Mechanism. During the reporting period, the Mechanism made\nan additional six requests to the Myanmar authorities to obtain access to the territory and to\ninformation in the possession of the authorities. For example, the Mechanism requested all\nrecords of criminal proceedings against the four democracy activists executed on 25 July\n2022. The Mechanism has also requested information from Myanmar regarding several\nincidents, among them the attack on a school in Let Yet Kone, in Tabayin Township, Sagaing\nRegion, that took place on or around 16 September 2022. The Mechanism continued to\nrequest information related to events in northern Rakhine State, including on the\ncommencement of activities of the military court of inquiry, to obtain evidence in relation to\nthe proceedings before the International Court of Justice. The Mechanism continued to\nrequest access to prisons, detention sites and other areas. The Myanmar authorities have not\nresponded to these requests and none of the information requested has been received."},{"id":"a-hrc-54-19-p0040","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"40","seq":41,"section":"A. Cooperation with Member States and other partners","text":"Lack of access to the territory of Myanmar highlights the importance of strong\ncooperation of States in the Asia-Pacific region, where much of the evidence and many of\nthe witnesses are located. In this context, the Mechanism acknowledges with appreciation\nthe continued strong support extended by some States in the region for the Mechanism’s\ninvestigative activities. The Mechanism appreciates the complex context in which many of\nthe States neighbouring Myanmar operate and seeks further engagements with Member\nStates in the region to enable investigative activities in their territories. The Mechanism also\nseeks the cooperation of all Member States, within and outside of the Asia-Pacific region, in\norder to facilitate the protection and support of high-value at-risk witnesses and to prevent\nany reprisals for cooperation with the Mechanism."},{"id":"a-hrc-54-19-p0041","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"41","seq":42,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism has also focused on establishing strong arrangements with civil\nsociety organizations and other actors, which remain a critical source of information and\nevidence regarding serious crimes committed in Myanmar. As such organizations often have\nimmediate access to crime scenes and survivors, they have invaluable victim/survivor\nperspectives. With their extensive and precise knowledge, they are well placed to deepen the\nMechanism’s understanding of the context in which serious crimes are being committed, the\nprotection and security issues facing individuals or the community, and the availability of\nsupport resources. Given their proximity, knowledge and contacts, the Mechanism regularly\nengages with such organizations to seek information and evidence that they may have\ngathered or to facilitate access to witnesses who possess first-hand knowledge of the crimes\nunder investigation. The Mechanism has actively engaged and developed both informal and\nformal arrangements with a large network of civil society groups, both in and outside of the\nAsia-Pacific region. The Mechanism expresses its profound appreciation to the many\nindividuals and organizations who provide information and support to the Mechanism, in\nmany cases at significant risk to their safety and security."},{"id":"a-hrc-54-19-p0042","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"42","seq":43,"section":"A. Cooperation with Member States and other partners","text":"During the reporting period, the Mechanism also continued to seek the support and\ncooperation of United Nations entities that are in possession of information relevant to the\nMechanism’s mandate. The Mechanism welcomes Human Rights Council resolution 52/31,\nadopted in April 2023, in which the Council urged all United Nations bodies to collaborate\nfully with the Mechanism, where possible, and to share evidence to be used in future\nprosecutions. Pursuant to that resolution, and fully cognizant of the challenging operational\nenvironment that the United Nations system is currently facing in Myanmar, the Mechanism\nwill redouble its efforts to seek additional cooperation and support from United Nations\nactors that have not yet executed the Mechanism’s requests for assistance."},{"id":"a-hrc-54-19-p0043","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"43","seq":44,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"The Mechanism believes that conveying a greater understanding of its purpose and\nprocedures among its very diverse set of stakeholders is critical to its effectiveness. The\nMechanism uses numerous channels to engage with the diverse communities who have a\nstake in its activities to ensure they have a clear understanding of what the Mechanism can\nand cannot do, its working methods and the most secure and confidential ways to share\ninformation with it. Regular outreach to victims, survivors and local or regional civil society\norganizations is therefore a high priority. The Mechanism uses a range of public and private\nchannels to reach these diverse audiences, including its website and Facebook page,\nnewsletters, events and confidential briefings."},{"id":"a-hrc-54-19-p0044","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"44","seq":45,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"The Mechanism places equal importance on listening to its stakeholders about their\nconcerns, views and hopes about the Mechanism. In this regard, the Mechanism held its first\ncivil society dialogue during the reporting period. The dialogues will be regularly held in-\nperson events that will bring together different groups of representatives of civil society\norganizations representing diverse communities within and outside the Asia-Pacific region.\nThe first dialogue brought together representatives from 20 civil society organizations to\nbuild stronger relationships and increase mutual trust and understanding. Civil society\norganizations are on the front line of efforts to gather information and evidence regarding\nserious international crimes committed in Myanmar. They are therefore crucial sources of\ninformation, and the Mechanism values its engagement with them."},{"id":"a-hrc-54-19-p0045","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"45","seq":46,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"Over three days of discussions, Mechanism personnel shared detailed information\nabout the current accountability landscape, the Mechanism’s mandate and methods of work,\nand how the information that civil society organizations share with the Mechanism is used to\nbuild case files. Civil society participants discussed the realities and challenges they faced in\nconducting their work, and how that affected their engagement with the Mechanism.\nParticipants conveyed their concerns regarding security, psychosocial support and other\nchallenges, which will help inform the Mechanism’s working methods and support improved\ncollaboration. Following the event, the participants expressed a strong willingness to\ncooperate with the Mechanism and a far deeper understanding of the Mechanism’s mandate\nand its limitations. The participants also indicated an increased understanding of international\njustice and accountability processes. Going forward, the dialogues will be a regular\ncomponent of the Mechanism’s outreach work with various relevant organizations. The\nMechanism acknowledges with strong appreciation the strong support of certain Member\nStates in hosting, financing and facilitating the dialogue."},{"id":"a-hrc-54-19-p0046","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"46","seq":47,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"In addition to direct engagement with various stakeholders, the Mechanism’s website\nand Facebook page continue to serve as the primary platforms for disseminating information\nand public outreach. Both are available in English and the Myanmar language (Burmese),\nwith information in audio form in the Rohingya language. The website has been effective for\ndisseminating timely statements and media releases, sharing information on how to contact\nthe Mechanism securely and confidentially, and providing answers to frequently asked\nquestions about the Mechanism’s mandate and activities. With more than 75,000 followers,\nthe Mechanism’s Facebook page is also vital for engaging regularly with a predominantly\nMyanmar audience, providing an opportunity to share informal updates and information on\nthe complexities of the Mechanism’s legal work and explaining aspects of the Mechanism’s\nmandate and working methods."},{"id":"a-hrc-54-19-p0047","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"47","seq":48,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"The Mechanism recognizes the complexity of its mandate and the need to simplify its\nmessaging so that it is more accessible and memorable for a range of audiences who speak\ndifferent languages and have varied literacy levels. Therefore, in the upcoming reporting\nperiod the Mechanism will focus on simplifying the language and messaging on its website\nand on producing visual outreach products to ensure that information about the Mechanism\nis easily understood by diverse audiences and shareable across numerous communication\nchannels."},{"id":"a-hrc-54-19-p0048","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"48","seq":49,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"There has been continued media and public interest in the Mechanism. Press releases,\nstatements, media briefings and interviews have resulted in regular coverage in influential\nglobal and regional media outlets, including in the languages used in Myanmar. The\nMechanism has also participated in numerous public events organized by Member States and\ncivil society groups on topics related to its mandate. The Mechanism’s biannual newsletter,\nBulletin, highlights institutional updates and key activities, and is broadly distributed to\nMember States and other key stakeholders."},{"id":"a-hrc-54-19-p0049","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"49","seq":50,"section":"B. Enhancing dialogue with relevant stakeholders and public outreach","text":"In accordance with its commitment in the 2022 budget submission to the General\nAssembly, 2 the Mechanism completed a self-evaluation of its public outreach and\ncommunications strategy, analysing the effectiveness of its outreach and communication\nwork over the 2021–2022 period. Based on a series of internal and external consultations, the\nresulting analysis and recommendations will inform the Mechanism’s updated strategy on\ncommunications and outreach, to be completed in the next reporting period."},{"id":"a-hrc-54-19-p0050","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"50","seq":51,"section":"C. Witness protection and support","text":"The Mechanism is keenly aware of the psychological trauma suffered by victims and\nsurvivors of atrocities and the potential for retraumatization when victims/survivors are asked\nto recall and recount such events. Accordingly, and consistent with its terms of reference, the\nMechanism is building partnerships with professionals and organizations that can offer\nassistance to those survivors engaging with the Mechanism. Similarly, repeatedly listening\nto survivors of atrocities recount the events that led to their trauma and reviewing voluminous\ndocuments, imagery and videos depicting gruesome crime scenes can potentially have a\nserious impact on staff well-being. Within the framework of the Mechanism’s plan on staff\nwell-being, the Mechanism launched a secondary-trauma programme in 2023 to address the\nrisks associated with Mechanism personnel’s exposure to traumatic material. The programme\nis aimed at increasing awareness about secondary trauma through briefings with managers,\nfirst reporting officers and workshops with personnel."},{"id":"a-hrc-54-19-p0051","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"51","seq":52,"section":"C. Witness protection and support","text":"Building on lessons learned since the previous annual report and best practices from\nother international criminal accountability mechanisms, the Mechanism continues to further\nenhance its witness support and protection capabilities. The Mechanism developed bespoke\nwitness support and protection structures during recent investigative missions, ensuring that\nhigh-risk and vulnerable witnesses receive protection and psychosocial services in a manner\nconsistent with the Mechanism’s mandate and a victim/survivor-centred approach. In\nresponse to the Mechanism’s increased engagement with a high number of witnesses,\nincluding many in volatile locations, the Mechanism’s witness protection needs have\nincreased significantly. To date, the Mechanism has conducted over 350 contact threat\nassessments to identify potential security risks to witnesses before initiating contact.\nImportantly, the Mechanism continues to work with various partners on the ground to identify\nand develop referral pathways to ensure safe interventions and ongoing support to the\nwitnesses with whom it interacts. The Mechanism has also enhanced its policies and\nprocedures related to witness protection and support services tailored to the specific context\nof its activities."},{"id":"a-hrc-54-19-p0052","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"52","seq":53,"section":"C. Witness protection and support","text":"Member States remain invaluable partners for the Mechanism, particularly in respect\nto providing access to important witness protection measures and support-related services.\nExtrabudgetary resources from Member States have also allowed the Mechanism to\nstrengthen its witness protection and support capabilities, particularly for high-value\nwitnesses in serious danger as a result of their cooperation with the Mechanism and for\nwitnesses who require medical support and/or psychosocial assistance."},{"id":"a-hrc-54-19-p0053","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"53","seq":54,"section":"D. Security of personnel, assets and information technology","text":"The Mechanism is undertaking more investigative missions and interviewing more\nwitnesses amid a worsening security situation where many of its witnesses are located. The\nMechanism is also engaging with a growing number of at-risk and vulnerable witnesses in\nMyanmar and other locations. In this context, the Mechanism’s activities have become more\noperationally complex and have resulted in an increase in the Mechanism’s activities and\nassessments related to the safety and security of personnel and assets as well as information\nand communications technology. Security assessments and measures in all three areas\ncontinue to be an integral part in the Mechanism’s daily work."},{"id":"a-hrc-54-19-p0054","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"54","seq":55,"section":"D. Security of personnel, assets and information technology","text":"The Mechanism works to ensure that required safety and security arrangements, based\non the Mechanism’s specific security risk assessment, are integrated into all aspects of its\noperations, both in Geneva and during missions. Those responsibilities include monitoring\nand analysing an increasing number of threat actors and their activities and producing\ncomprehensive and regularly updated country or area-specific situation threat and risk\nassessments. Utilizing its well-established communications channels, the Mechanism\nmaintained close coordination and advance planning with United Nations system entities and\nsecurity interlocutors in various locations. This contributed to the safety and security of\nseveral investigative missions and other activities during the reporting period."},{"id":"a-hrc-54-19-p0055","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"55","seq":56,"section":"D. Security of personnel, assets and information technology","text":"The Mechanism remains keenly aware of cybersecurity challenges, both in terms of\ndigital surveillance and potential risks to its own information and communication systems.\nThe Mechanism maintains a high level of vigilance about the security of its information and\ncommunications technology, requiring ongoing training and initiatives to ensure that both its\ninformation management system and personnel are capable of preventing and responding to\ncyberattacks. The Mechanism rolled out software to strengthen its capabilities to monitor and\nprotect its systems from attack and intrusion, and also continues to devise and implement\ncybersecurity measures for all new information and technology systems before they become\noperational."},{"id":"a-hrc-54-19-p0056","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"56","seq":57,"section":"D. Security of personnel, assets and information technology","text":"With the increase of investigative activities and a deteriorating security situation,\ninformation and communications technology security is essential for investigative teams to\ncommunicate and access the Mechanism’s information systems in line with confidentiality\nand security requirements. In this regard, the Mechanism procured mission kits and\ncommunication devices to better accommodate the needs of investigative teams while on\nmission in challenging operational environments."},{"id":"a-hrc-54-19-p0057","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"57","seq":58,"section":"E. Technology and infrastructure","text":"During the reporting period, the Mechanism continued to refine its core and\nspecialized technology and infrastructure to collect and preserve information and evidence\nin its electronic information management system in an accessible, searchable and secure\nmanner. The Mechanism conferred with other United Nations entities facing similar\nchallenges and actively sought out the technologies that best fit the Mechanism’s evolving\nneeds. The Mechanism’s open source and financial investigators and analysts have been\nequipped with the latest industry-leading technology available to facilitate their collection\nand analysis of large amounts of information. The Mechanism, through its partnerships with\nUnited Nations computing and data centres, is also expanding its computing capabilities to\nsupport newly identified needs for virtual and specialist computing."},{"id":"a-hrc-54-19-p0058","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"58","seq":59,"section":"E. Technology and infrastructure","text":"The Mechanism continued to enhance its electronically stored information\nmanagement system through increased automation to enable more efficient internal\nworkflow processes for the secure intake, management and review of the information it\ncollects. The system provides an end-to-end, fully integrated process for evidence intake,\nprocessing and review; management of all information providers and witnesses; case\nmanagement planning; and tracking of all information shared by the Mechanism with third\nparties. Some processes that previously required more than a week to complete can now be\ncompleted in a few days, due to efficiencies resulting from increased automation."},{"id":"a-hrc-54-19-p0059","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"59","seq":60,"section":"E. Technology and infrastructure","text":"During the reporting period, the Mechanism also made progress in further developing\nseveral critical solutions in response to its analytical needs. The Mechanism completed the\ninstallation of a data analytics platform required for performing contextual analysis of the\nMechanism’s textual materials. This will allow investigative teams to utilize the text-rich\ndata collected to date to prepare more tailored and comprehensive analytical products. The\nMechanism also completed the installation of a media analysis platform that will allow the\nextraction of patterns and connections in large amounts of data and facilitate the analysis,\ncategorization and management of digital media files and geospatial imagery.\nSimultaneously, the Mechanism has continued to develop a computer vision software capable\nof enhancing human analysis by deriving meaningful information from a vast pool of\nevidence, particularly in relation to the categorization of, and automatic detection in,\nphotographs and videos."},{"id":"a-hrc-54-19-p0060","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"60","seq":61,"section":"E. Technology and infrastructure","text":"The Mechanism also continued work towards the development of a machine\ntranslation capability from the Myanmar language (Burmese) into English. Existing off-the-\nshelf solutions are insufficient for the Mechanism’s needs and significant work is required to\nrefine the accuracy of those tools. Once developed, such a tool would enable the Mechanism\nto obtain at least a rough translation of millions of information items collected in the\nMyanmar language (Burmese) for both internal analysis and external sharing. It is also\nanticipated that machine translations could be utilized to provide material to sharing partners\nthat meets the language requirements of their jurisdictions, subject to the available resources\nand capacities of the Mechanism."},{"id":"a-hrc-54-19-p0061","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"61","seq":62,"section":"E. Technology and infrastructure","text":"Finally, the Mechanism continued to evolve the previously developed custom solution\nto extract and preserve data from a variety of social media, communication and messaging\napplications as the complexity of the data being collected and preserved evolves with the\ntechnologies that support them. These solutions and platforms have enabled the Mechanism\nto collect and analyse additional data that previously were not accessible to it."},{"id":"a-hrc-54-19-p0062","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"62","seq":63,"section":"VI. Challenges and areas for additional support","text":"As described above, the Mechanism increasingly operates in a challenging\nenvironment involving different layers of complexity. Such challenges include the lack of\naccess to the locations of the crimes and to witnesses, and security and safety concerns for\nthe individuals who provide information to the Mechanism. In the upcoming reporting period,\nthe Mechanism will continue to closely monitor developments in the country and to reach\nout to the current authorities in Myanmar with requests for information, assistance and access\nto the country."},{"id":"a-hrc-54-19-p0063","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"63","seq":64,"section":"VI. Challenges and areas for additional support","text":"The lack of access to Myanmar intensifies the Mechanism’s need for cooperation from\nMember States in the Asia-Pacific region. People leaving Myanmar due to the intensified\nviolence will often go to or through neighbouring countries; they potentially have very\nvaluable and timely information that would add value to the Mechanism’s investigations. The\nMechanism welcomes support from all Member States in the Asia-Pacific region to allow the\nMechanism to conduct investigative activities on their territory, in accordance with, inter alia,\nGeneral Assembly resolution 76/180 and Council resolutions 49/23, 50/3 and 52/31. The\nMechanism operates in a highly discreet and confidential manner as agreed upon with\nMember States. The Mechanism would welcome further engagements with representatives\nof Member States in Geneva, in New York and in the respective countries."},{"id":"a-hrc-54-19-p0064","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"64","seq":65,"section":"VI. Challenges and areas for additional support","text":"The Mechanism also relies on the support of Member States for critical assistance in\nwitness protection and support. The Mechanism is in contact with many defectors from the\nsecurity services, some of whom appear to have valuable “insider” evidence that could\nadvance investigations of crimes within the Mechanism’s mandate. Many have been forced\nto flee Myanmar, and have crossed into neighbouring countries without any legalized\nimmigration status. These at-risk potential witnesses are vulnerable to arrest and deportation\nto Myanmar, where they are likely to face persecution and detention. The Myanmar military\nhas demonstrated its readiness to remove potential threats to the regime through\nimprisonment and in some cases executions. Access to witness protection and support-related\nservices requires the vital support of the neighbouring countries and other Member States."},{"id":"a-hrc-54-19-p0065","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"65","seq":66,"section":"VI. Challenges and areas for additional support","text":"Ensuring language translation and interpretation capabilities for Myanmar languages\nis a critical challenge to the Mechanism’s collection and analytical functions. To adequately\nreview and analyse collected material, especially considering the volume of such material in\nthe Myanmar languages, the Mechanism will need to increase its language capacity in the\nupcoming reporting period. This can partly be done through additional resources, and partly\nthrough the continuing development of machine translation technology. The translation of\ndigital Burmese text into English using artificial intelligence technology is a challenge, as\nsuch technology is not available for Myanmar languages, or is not as developed as it is for\nother languages."},{"id":"a-hrc-54-19-p0066","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"66","seq":67,"section":"VI. Challenges and areas for additional support","text":"Finally, to carry out the complex work of the Mechanism, the Mechanism will\ncontinue to require personnel with specialized expertise in areas such as information\ntechnology, open source research and analysis, and financial investigations. Sustained\nvoluntary contributions for these activities, which are integral to the Mechanism’s\ninvestigative strategy, will be essential. The Mechanism will continue to mobilize\nextrabudgetary funding to be able to sustain these activities in the future and welcomes the\nsupport of diverse Member States and partners."},{"id":"a-hrc-54-19-p0067","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"67","seq":68,"section":"VII. Conclusion","text":"During the reporting cycle, the Mechanism continued to make important\nprogress towards its objective of ensuring the accountability of perpetrators and justice\nfor victims of the most serious international crimes and violations of international law\ncommitted in Myanmar since 2011. The Mechanism is now supporting three\njurisdictions pursuing investigations or proceedings related to crimes committed\nagainst the Rohingya population. Despite significant cooperation and operational\nchallenges, and the dramatic increase in serious international crimes committed in\nMyanmar since the military takeover in 2021, the Mechanism’s collection efforts have\nkept pace as it strives to collect and analyse all relevant information in relation to\nserious international crimes of the greatest gravity and persons bearing the greatest\nresponsibility for those crimes."},{"id":"a-hrc-54-19-p0068","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"68","seq":69,"section":"VII. Conclusion","text":"With the cooperation and support of a diverse number of partners and\nstakeholders, including witnesses, victims, survivors, civil society organizations,\nMember States, United Nations entities and private entities, the Mechanism has made\nevery effort to strategically utilize its limited resources effectively and efficiently.\nLooking ahead, the Mechanism plans to accelerate its collection of evidence of the most\nserious international crimes committed in Myanmar and intensify its preparation of\nanalytical products to be shared with investigative, prosecutorial and judicial\nauthorities willing and able to pursue accountability for such crimes. The Mechanism\nwill continue to explore innovative technologies that will enable the analysis of\ninformation and evidence more efficiently and effectively to support national, regional\nand international judicial authorities. The Mechanism will also continue to strengthen\nits capacities to work in the various Myanmar languages in order to review and analyse\nthe materials collected; ensure the safety and well-being of witnesses; analyse social\nmedia and other open source and financial information; investigate sexual and gender-\nbased crimes and crimes against children; and engage more systematically with\nsurvivor and victims’ groups and local civil society organizations."},{"id":"a-hrc-54-19-p0069","rec_id":"rectilX0jl7DQDMzZ","symbol":"A/HRC/54/19","n":"69","seq":70,"section":"VII. Conclusion","text":"In order to achieve these goals, and in line with the resolutions of the Human\nRights Council and General Assembly, the Mechanism will continue to pursue all\navailable opportunities to strengthen cooperation with Member States, United Nations\nentities and other stakeholders. The full and meaningful cooperation of Member States,\nespecially those in the Asia-Pacific region, will remain essential to pursuing justice for\nthe people of Myanmar and the stated goals of these States regarding the achievement\nof sustainable solutions to the escalating violence and conflict in Myanmar."},{"id":"a-hrc-57-18-u0000","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/57/18\nGeneral Assembly                                                          Distr.: General\n11 July 2024","unnumbered":true},{"id":"a-hrc-57-18-u0001","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":null,"seq":1,"section":null,"text":"Summary\nThe present document is the sixth report submitted by the Independent Investigative\nMechanism for Myanmar to the Human Rights Council pursuant to resolution 39/2. It covers\nthe activities carried out by the Mechanism between 1 July 2023 and 30 June 2024,\nhighlighting progress on investigations, approaches and methodologies, challenges and areas\nfor additional support.\nDuring the reporting period, the conflict in Myanmar escalated substantially, with\nreports of more frequent and brutal crimes committed across the country. The Mechanism\npossesses substantial evidence that a variety of war crimes and crimes against humanity have\nbeen committed. While the great majority of information collected by the Mechanism\nconcerns crimes committed by the Myanmar security forces or affiliated militias, the\nMechanism has also received credible information regarding crimes committed by some\narmed groups fighting against the military. The Mechanism is examining evidence of alleged\ncrimes regardless of the affiliation or ethnicity of the perpetrators or victims.\nDespite the complex and evolving situation in the country, the Mechanism made\nimportant progress across its various investigations, with almost 28 million items of\ninformation and evidence collected from over 900 sources by the end of the reporting period,\nincluding: witness statements; photographs; videos; audio materials; documents; maps;\ngeospatial imagery; social media posts; and forensic evidence. To enable these vast quantities\nof material to be searched, analysed and utilized to build case files, the Mechanism has\ndeveloped and optimized innovative technologies.\nDuring the reporting period, the Mechanism made significant strides in its\ninvestigations into crimes committed following the military takeover in February 2021.\nEvidence has been collecting related to the violent suppression of protests; torture and other\nabuses in detention, including sexual and gender-based crimes; unlawful imprisonment of\nperceived opponents of the military regime, including arbitrary detention and manifestly\nunfair trials; indiscriminate or intentional artillery and aerial attacks against civilians or\ncivilian objects; killings of civilians or fighters detained during operations; and the\nintentional burning of civilian dwellings and other civilian buildings.\nIn relation to the clearance operations carried out by the Myanmar security forces in\n2016 and 2017, which forced almost three quarters of a million Rohingya to flee to","unnumbered":true},{"id":"a-hrc-57-18-u0002","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":null,"seq":2,"section":null,"text":"Bangladesh, the Mechanism has conducted numerous witness interviews and screenings and\nhas produced a number of confidential analytical reports, including on movements of military\nunits during clearance operations. The Mechanism is making efforts to gather information\non the current conflict in Rakhine State between the Myanmar security forces and the Arakan\nArmy and serious allegations of crimes committed against both Rohingya and Rakhine\ncivilians in Buthidaung, Maungdaw and surrounding areas.\nThe ultimate goal of the Mechanism is to enable national and international authorities\nto deliver justice for the victims of serious international crimes committed in Myanmar.\nDuring the reporting period, the Mechanism shared a significantly higher volume of evidence\nand analysis than ever before. The evidence is for use in three ongoing investigations and\njudicial proceedings related to crimes against the Rohingya that are being conducted by the\nInternational Court of Justice, the International Criminal Court and the Federal Prosecutor’s\nOffice No. 9 in Argentina. To date, the Mechanism has prepared over 260 packages with\nevidentiary materials and analytical products available for sharing with relevant authorities,\nof which 80 packages have already been shared.","unnumbered":true},{"id":"a-hrc-57-18-p0001","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"1","seq":3,"section":"I. Introduction","text":"The present report covers the activities carried out by the Independent Investigative\nMechanism for Myanmar between 1 July 2023 and 30 June 2024."},{"id":"a-hrc-57-18-p0002","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"2","seq":4,"section":"I. Introduction","text":"The Human Rights Council, by its resolution 39/2, created the Mechanism and\nmandated it to collect, consolidate, preserve and analyse evidence of the most serious\ninternational crimes and violations of international law committed in Myanmar since 2011\nand to prepare files to facilitate and expedite fair and independent criminal proceedings in\nnational, regional or international courts or tribunals. In its resolution 73/264, the General\nAssembly welcomed the establishment of the Mechanism. Subsequently, in its\nresolution 43/26, the Council specifically called upon the Mechanism to engage in close and\ntimely cooperation on any future investigations, including those conducted by the\nInternational Criminal Court and the International Court of Justice."},{"id":"a-hrc-57-18-p0003","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"3","seq":5,"section":"I. Introduction","text":"During the reporting period, the conflict in Myanmar significantly intensified. The\nMyanmar military lost territory in outlying regions to ethnic armed organizations and the\nPeople’s Defence Force, increasingly relying on aerial and artillery bombardments of\npopulated areas, resulting in numerous injuries and fatalities among the civilian population.\nPeople of various ethnicities and religions have been injured and killed in their homes,\nschools and places of worship. Villages have been burned and houses destroyed. Thousands\nhave been arrested and killed or tortured in detention. In the past six months, it is estimated\nthat over three million people have been forced to flee their homes. The number, complexity\nand geographic scope of serious crimes committed in Myanmar have expanded on a\nsubstantial scale. No one has yet been held accountable for these crimes, which continues to\ndeepen the culture of impunity in the country. Additional restrictions recently placed by the\nMyanmar military on access to digital communications and Internet connectivity could make\ninteraction with the outside world and access to information even more difficult."},{"id":"a-hrc-57-18-p0004","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"4","seq":6,"section":"I. Introduction","text":"In this context, the Mechanism believes that its efforts to collect evidence that can be\nused to hold perpetrators to account is ever more critical. Despite operating in an increasingly\ncomplex environment, including lack of access to Myanmar and other locations where\nwitnesses are located, the Mechanism has made important progress during the past year\nacross its various investigations. The Mechanism continues to closely monitor the\ndeteriorating situation as it relates to the growing number of alleged violations and incidents\nthroughout Myanmar and to collect information and evidence regardless of the ethnicity or\naffiliation of the perpetrators or the victims. The Mechanism has accumulated and analysed\na diverse range of evidence probative of serious international crimes committed in Myanmar,\nincluding evidence bearing on the criminal responsibility of specific individuals."},{"id":"a-hrc-57-18-p0005","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"5","seq":7,"section":"II. Progress on investigations","text":"The clearance operations carried out by the Myanmar security forces in Rakhine State\nin 2017 forced almost three-quarters of a million Rohingya to flee to Bangladesh. Nearly all\nremain in refugee camps today, awaiting conditions that would allow their return to\nMyanmar. While the plight of the Rohingya was undoubtedly a major motivation for the\ncreation of the Mechanism, the Human Rights Council recognized that the Rohingya were\nnot the only civilians in Myanmar targeted in the many internal conflicts in the country and\nthat progress in resolving conflicts and achieving justice depended upon breaking the cycle\nof impunity for military leaders that had long plagued the country. Accordingly, the mandate\nof the Mechanism covers the entire territory of Myanmar and includes the most serious\ninternational crimes committed since 2011, regardless of the race, ethnicity, religion or\naffiliation of the victims or the perpetrators."},{"id":"a-hrc-57-18-p0006","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"6","seq":8,"section":"II. Progress on investigations","text":"Since the military coup in February 2021, the number of serious international crimes\nin Myanmar has continued to increase in frequency and scale. These crimes occur throughout\nthe country, including almost all border regions and within areas of the central lowlands.\nAccess to victims in those areas is extremely difficult. However, the evolution of the\npolitical/military situation has also brought new opportunities. A significant number of\nofficers and soldiers from the security forces have defected, although obtaining and\npreserving their information safely has presented additional challenges."},{"id":"a-hrc-57-18-p0007","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"7","seq":9,"section":"II. Progress on investigations","text":"To maximize the efficiency of its investigations, the Mechanism has divided its\ninvestigative personnel into two teams: one that focuses on crimes committed against the\nRohingya (both historical and ongoing crimes); and another that focuses on crimes committed\nagainst all other groups, which includes almost all of the crimes committed since the military\ncoup in February 2021. These two lines of investigation, crimes against the Rohingya and\npost-coup violence, have distinct characteristics, including: the time period under\ninvestigation; the history and causes of the violence; the location and availability of\nwitnesses; and the investigative or judicial authorities who are currently investigating or\nadjudicating these crimes or are likely to do so (as detailed below, all three of the ongoing\nproceedings that the Mechanism is currently supporting deal only with violence against the\nRohingya)."},{"id":"a-hrc-57-18-p0008","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"8","seq":10,"section":"II. Progress on investigations","text":"The Mechanism also continues to actively monitor the ongoing situation throughout\nMyanmar. As the situation in Rakhine State has deteriorated significantly in recent months,\nthe Mechanism has opened new investigative lines of inquiry into the current conflict in\nRakhine State between the Myanmar security forces and the Arakan Army and alleged crimes\nagainst the civilian population, including the Rohingya. In the last few months, there are\nstrong indications that serious international crimes have been committed in Buthidaung,\nMaungdaw and the surrounding areas against both the Rohingya and other civilians in\nRakhine State. The Mechanism is also investigating allegations concerning the forcible\nconscription of Rohingya youth into armed groups."},{"id":"a-hrc-57-18-p0009","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"9","seq":11,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"In relation to its investigation of crimes against the Rohingya, the Mechanism’s\npriority lines of inquiry include: (a) crimes against Rohingya civilians related to the 2012\nviolence, including the internal displacement and confinement of Rohingya into internally\ndisplaced persons’ camps near Sittwe; (b) crimes associated with the 2016 and 2017\nclearance operations conducted by the Myanmar security forces, which form the focus of the\nongoing investigations by the Office of the Prosecutor of the International Criminal Court\nand the Federal Prosecutor’s Office No. 9 in Argentina, as well as the judicial proceedings at\nthe International Criminal Court that the Mechanism is supporting; and (c) more recent\ncrimes committed in northern Rakhine State, in particular since May 2024. The evidence that\nthe Mechanism has collected to date includes both crime-base evidence (establishing the\nelements of an international crime) and linkage evidence (evidence that tends to establish a\nlink between the actions of specific persons and such crimes). For example, the Mechanism\ncontinues to collect and analyse evidence on the prevalence and coordinated dissemination\nof hate speech against the Rohingya, which was a signature feature of the crimes against the\nRohingya, to assess potential criminal liability.\nCollection of evidence"},{"id":"a-hrc-57-18-p0010","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"10","seq":12,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"The Mechanism has collected and analysed a substantial amount of evidence\nconcerning the 2016 and 2017 clearance operations. Mechanism investigators have\nconducted numerous in-person screenings and interviews of witnesses in refugee camps and\nother locations, collecting documentary and other evidence and conducting open-source\ninvestigations using advanced techniques."},{"id":"a-hrc-57-18-p0011","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"11","seq":13,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"The Mechanism has continued its regular cycle of investigative missions to locations\nwhere survivors of serious international crimes committed in Myanmar have taken refuge or\nhave relocated. In accordance with best practices, the Mechanism has conducted hundreds of\nin-person screenings (preliminary interviews) and detailed witness interviews with members\nof the Rohingya community, producing signed statements of high forensic value. In doing\nso, the Mechanism has engaged with individuals hailing from a wide range of locations across\nnorthern Rakhine State and individuals of varying ages, backgrounds and genders, ensuring\nthe investigation not only of the most notorious and “highly documented” incidents, but also\nthose in “underdocumented” regions. In all of its witness interactions, the Mechanism has\nprioritized the collection of information concerning sexual and gender-based crimes and\ncrimes against and affecting children, since such crimes are so often underreported and\nunderdocumented in criminal investigations."},{"id":"a-hrc-57-18-p0012","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"12","seq":14,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"The Mechanism has mapped out and engaged with Rohingya diaspora communities\nin several countries. In certain locations, and in coordination with national authorities, the\nMechanism has carried out investigative missions to those States to conduct detailed witness\ninterviews. The Mechanism considers that engaging with members of the Rohingya\ncommunity in a range of different countries where they have taken refuge or have relocated\nensures the inclusion of a broader range of members of the affected community in its\ninvestigations and increases the pool of witnesses in stable security situations who may be\navailable to testify in judicial proceedings."},{"id":"a-hrc-57-18-p0013","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"13","seq":15,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"Aside from engaging with survivors from the Rohingya community, the Mechanism\ncontinues to pursue evidentiary information from individuals who may possess “inside\nknowledge” relevant to the perpetration of crimes against the Rohingya by the Myanmar\nsecurity forces, including the chain of command within the Myanmar security forces or other\narmed groups. The Mechanism also continues to engage with a wide range of witnesses who\nmay provide contextual, overview or other information pertaining to crimes against the\nRohingya. Such witnesses range from medical professionals and other first responders who\nprovided immediate care to the Rohingya survivors and victims as they fled Myanmar to\ndiplomatic representatives and officials of international organizations who engaged with the\nMyanmar military and civilian authorities around the time of the 2016 and 2017 clearance\noperations.\nAnalysis and sharing"},{"id":"a-hrc-57-18-p0014","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"14","seq":16,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"In accordance with its mandate, the Mechanism dedicates considerable resources to\nthe analysis of evidence to fulfil the mandate to facilitate and expedite criminal accountability\nprocesses in national or international courts. The Mechanism’s evidence repository includes\na vast amount of material in the Myanmar language (Burmese). Guided by the priority lines\nof inquiry discussed above, as well as by the needs and requirements of ongoing\ninvestigations and proceedings related to those crimes, the Mechanism has produced in-depth\nanalytical products on salient aspects of the investigation during the reporting period. While\nmost of its work remains confidential, in order to preserve the integrity of the investigations\nand to safeguard the security of witnesses and sources, the Mechanism exceptionally released\ntwo such reports to the public in March 2024. The first report concerns the failure of the\nMyanmar authorities to address widespread allegations of sexual and gender-based violence\nagainst the Rohingya population; the second report demonstrates how the Myanmar military\nused a covert network of Facebook accounts to propagate hate speech against the Rohingya\nprior to and during the 2017 clearance operations."},{"id":"a-hrc-57-18-p0015","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"15","seq":17,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"In addition, the Mechanism has produced and shared with judicial authorities a\nnumber of confidential analytical reports focusing on various matters of high contextual and\nevidentiary value to the ongoing investigations and proceedings about crimes against the\nRohingya. This includes analyses of evidence harvested by its team of specialists and open-\nsource and financial investigators and analysts. Such analyses cover issues such as: the\nhistory of official laws and pronouncements issued by the Myanmar authorities and the effect\nof such laws and pronouncements on the fundamental rights of the Rohingya population; the\nmovements of military units during the clearance operations, as garnered from social media\nposts of the Myanmar authorities; resettlement practices and policies intended to attract the\nmigration of non-Rohingya people to Rakhine State; and the quantities and qualities of\nweapons in the possession of Arakan Rohingya Salvation Army at the time of the clearance\noperations. The Mechanism continues to develop additional analytical reports on other\nthematic priorities, including on the loss and expropriation of Rohingya property prior to,\nduring and after the clearance operations and on individuals and/or corporate structures\npotentially involved in the provision of material assistance to the Myanmar security forces\nduring the clearance operations. Beyond the analysis already conducted with respect to\nFacebook, the Mechanism continues to examine the role that hate speech has played\nthroughout the time period of its investigations, including through other forms of social\nmedia, print materials and speeches. The Mechanism’s investigations also seek to identify\nthe broader political, historical and contextual developments that have led to the systematic\npersecution of the Rohingya over time."},{"id":"a-hrc-57-18-p0016","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"16","seq":18,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"During the reporting period, the Mechanism shared an unprecedented volume of\nevidence and analysis with three ongoing investigations and judicial proceedings, two of\nwhich are criminal investigations focusing on the individual responsibility of perpetrators of\ncrimes committed against the Rohingya. The first investigation is being conducted by the\nOffice of the Prosecutor of the International Criminal Court. The second criminal\ninvestigation is being conducted by the Federal Prosecutor’s Office No. 9 in Argentina. The\nthird proceeding is The Gambia v. Myanmar case before the International Court of Justice,\nwhich concerns State responsibility under the Convention on the Prevention and Punishment\nof the Crime of Genocide. The Mechanism is proactively identifying information and\nevidence that could be relevant to these investigations and proceedings and is also responding\nto targeted requests from these authorities for specific information or analysis. The authorities\nhave expressed their strong appreciation for the evidence and analyses shared by the\nMechanism."},{"id":"a-hrc-57-18-p0017","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"17","seq":19,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"The current support provided by the Mechanism for the above proceedings is of a\ntime-sensitive nature. The proceedings at the International Court of Justice are reaching the\nconclusion of the written submissions phase and oral hearings on the merits are expected to\nbegin in 2025. The investigations in Argentina and at the International Criminal Court are\nboth active and advancing."},{"id":"a-hrc-57-18-p0018","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"18","seq":20,"section":"A. Investigating and facilitating proceedings for crimes against the","text":"As a fundamental principle, the Mechanism only shares materials when individuals or\nentities have consented to the sharing of their materials with the specific judicial authorities\nconcerned. In addition, the Mechanism conducts its own further review of such materials to\nensure that sharing will not compromise the safety or privacy rights of any persons identified.\nAs the three jurisdictions with which the Mechanism is currently sharing each have their own\ndistinct rules and procedures regarding the admissibility of evidence and the protection and\nprivacy of witnesses, the Mechanism carries out an informed consent analysis for all\nmaterials that it shares. This requires regular and ongoing engagement with the Mechanism’s\nwitnesses and sources. The Mechanism also coordinates closely with the relevant\njurisdictions to facilitate the direct provision of testimony by witnesses in the proceedings\nand to “deconflict” witnesses to ensure that sensitive and vulnerable individuals are not\napproached or asked to be interviewed again by multiple justice institutions."},{"id":"a-hrc-57-18-p0019","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"19","seq":21,"section":"B. Investigating post-coup crimes","text":"The Mechanism’s other priority area of investigation concerns crimes committed\nagainst other groups in Myanmar since 2011, which increased in brutality and intensity\nfollowing the military coup in February 2021. As described in the Mechanism’s previous\nannual reports, the Mechanism has collected significant volumes of credible evidence and\ninformation indicating the commission of war crimes in connection with armed conflict and\ncrimes against humanity as part of a widespread and systematic attack against the civilian\npopulation. This pattern has been escalating and spreading across the country and the\nMechanism has been collecting credible reports of brutal atrocities being committed at an\nalarming rate. In this context, the Mechanism has sought to prioritize its investigations of\nnew incidents according to its case prioritization policy, while continuing to investigate\ncrimes that may have been committed prior to the reporting period.\nCrimes related to the suppression of dissent following the military coup"},{"id":"a-hrc-57-18-p0020","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"20","seq":22,"section":"B. Investigating post-coup crimes","text":"The Mechanism has made important progress in the collection and analysis of\ninformation related to: (a) the violent suppression of protests during the period following\nFebruary 2021; (b) torture and other abuses in detention, including sexual and gender-based\ncrimes; and (c) unlawful imprisonment of perceived opponents of the military regime,\nincluding arbitrary detention and manifestly unfair trials."},{"id":"a-hrc-57-18-p0021","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"21","seq":23,"section":"B. Investigating post-coup crimes","text":"In relation to the violent suppression of protests, the Mechanism has accumulated\nsubstantial evidence indicating that security forces applied disproportionate force against\ncivilians protesting the military coup in February 2021. The security forces consisted not only\nof police but also military forces, sometimes dressed as police. Such forces applied lethal or\nnear-lethal force to suppress protests in circumstances where it was not justified, causing\ncivilian deaths and serious bodily injury. The Mechanism has obtained reliable evidence of\nsecurity forces using live ammunition against protesters in Yangon, Mandalay, Bago,\nTanintharyi, Kachin and Magway. Measures were often taken by security forces to prevent\nor delay injured persons from receiving medical assistance. Furthermore, the Mechanism has\ncollected credible information that security forces sought to conceal the cause of death of\nprotesters, including by falsifying autopsy reports and using other means to provide false\ninformation to the family members of those killed."},{"id":"a-hrc-57-18-p0022","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"22","seq":24,"section":"B. Investigating post-coup crimes","text":"The Mechanism has collected abundant evidence of systematic torture of individuals\nin detention, particularly in military detention facilities. The means of torture included:\nbeatings with bamboo sticks; inflicting electric shocks; pulling out fingernails with pliers;\nburning skin with a cigarette lighter; sleep-deprivation and long periods in stress positions;\ndousing detainees in petrol and setting them alight; waterboarding; strangulation with plastic\nbags or other materials; breaking fingers; and forcing detainees to punch each other or to\nwitness violence against other detainees. The Mechanism has also received credible\ninformation that some individuals were killed in detention. Detainees were held in inhumane\nconditions, deprived of food and water and often did not receive medical care following their\nmistreatment. Physical abuse of detainees was often accompanied by severe mental abuse,\nincluding death threats or threats of serious violence, including rape, against detainees or\nfamily members."},{"id":"a-hrc-57-18-p0023","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"23","seq":25,"section":"B. Investigating post-coup crimes","text":"The Mechanism has also collected reliable evidence of sexual and gender-based\ncrimes in detention committed against all genders, including children under age 18,\nincluding: rape (gang rape and multiple rapes), inter alia, through the insertion of objects into\nanal and genital openings; burning of sexual body parts with cigarettes; injury to reproductive\nbody parts; sexualized touching; forced full or partial nudity; invasive body searches\naccompanied by sexual humiliation; the use of sexualized, misogynist or homophobic slurs;\nand threats of sexual violence or violence based on gender or sexual orientation."},{"id":"a-hrc-57-18-p0024","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"24","seq":26,"section":"B. Investigating post-coup crimes","text":"The Mechanism has found that physical and mental torture was often used to induce\ndetainees to provide information or purported confessions or to affirm statements that they\nwere not even allowed to read. These statements were then relied upon in subsequent judicial\nproceedings to convict detainees. Attempts by lawyers or the accused to object to the reliance\non such “confessions” on the basis that they had been elicited through torture were summarily\ndismissed by judges or not even considered. Those arrested included protesters, politicians,\njournalists, political activists, civil servants participating in strikes, persons associated with\nthe civil disobedience movement or suspected of having any affiliation or involvement with\narmed groups opposed to the military regime, suggesting that the authorities aimed to convict\nopponents of the military regime."},{"id":"a-hrc-57-18-p0025","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"25","seq":27,"section":"B. Investigating post-coup crimes","text":"In sum, the Mechanism possesses substantial evidence that a variety of crimes against\nhumanity have been committed in relation to the suppression of post-coup dissent, including:\ntorture; rape and other forms of sexual violence; persecution based on intersecting grounds,\nincluding gender, sexual orientation, perceived political affiliation, religion and ethnicity;\nenforced disappearance; imprisonment; murder; and other inhumane acts.\nCrimes committed in relation to ongoing armed conflict"},{"id":"a-hrc-57-18-p0026","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"26","seq":28,"section":"B. Investigating post-coup crimes","text":"The Mechanism continues to collect and analyse evidence of crimes connected to\nvarious ongoing armed conflicts throughout Myanmar, including in Sagaing and Magway\nRegions and in Shan, Chin, Kachin, Kayah, Kayin and northern Rakhine States.\nInvestigations of past and new incidents involve, in particular: (a) indiscriminate or\nintentional artillery and aerial attacks against civilians or civilian objects; (b) killings of\ncivilians or fighters detained during operations; and (c) the intentional burning of civilian\ndwellings and other civilian buildings. The Mechanism has collected evidence of the\ncontinued frequent use of air-to-surface bombs, causing significant numbers of civilian\ncasualties without any apparent military target in the vicinity. The objects of such attacks\nhave included internally displaced persons’ camps, schools, religious buildings and health\nfacilities. The reporting period has also been marked by continued acts of physical mutilation\nagainst victims killed in detention, such as beheadings, the display of disfigured and sexually\nmutilated bodies. The Mechanism has received credible information that such acts of\nmutilation have been committed by soldiers in civilian or military attire and/or\nmilitary-affiliated militias."},{"id":"a-hrc-57-18-p0027","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"27","seq":29,"section":"B. Investigating post-coup crimes","text":"The Mechanism has also received credible evidence of rape and other forms of sexual\nand gender-based crimes against civilians in connection with armed conflict. Civilians of all\nages and genders have been subjected to abduction, rape, including with objects, gang rape,\nrape leading to or followed by murder, attempted rape, sexualized torture, sexual mutilation,\nsexual assault at military checkpoints, forced full or partial nudity and sexual slavery. The\nevidence collected by the Mechanism indicates that the crimes were committed with an intent\nto punish and induce terror in the civilian population and that victims were often targeted on\none or more discriminatory grounds, including gender, ethnicity, religion, perceived political\naffiliation or sexual identity."},{"id":"a-hrc-57-18-p0028","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"28","seq":30,"section":"B. Investigating post-coup crimes","text":"The Mechanism continues to examine information indicating that children below age\n15 have been enlisted, conscripted or used as participants in hostilities by various armed\nactors. While children of all ages are subjected to the same international crimes as adults,\nthey bear unique consequences of those crimes, in particular an enduring impairment of the\nexercise of their rights to education, health care and family life that almost always results\nfrom forced displacement and other such crimes."},{"id":"a-hrc-57-18-p0029","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"29","seq":31,"section":"B. Investigating post-coup crimes","text":"The abundance of widely available information was sufficiently alarming to put\nMyanmar military commanders on notice of the need to take measures to prevent and punish\nconflict-related crimes. Despite repeated requests for information to the Myanmar military,\nincluding questions concerning any investigations or disciplinary measures taken in respect\nof suspected crimes, the Mechanism has not received information that any military or civilian\nofficial has been investigated, let alone prosecuted, for these grave crimes. Military\ncommanders have a duty under international law to prevent or repress war crimes committed\nby those under their command. The systematic failure to do so may not only give rise to\nsuperior responsibility but may also indicate that the crimes were intended by those in\ncommand at the highest levels of the military."},{"id":"a-hrc-57-18-p0030","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"30","seq":32,"section":"B. Investigating post-coup crimes","text":"While the vast majority of information collected by the Mechanism concerns crimes\ncommitted by the Myanmar security forces or affiliated militias, the Mechanism has also\nreceived credible information regarding crimes committed by some armed groups fighting\nagainst the military. In particular, the Mechanism continues to collect information concerning\nenforced disappearances, as well as the summary and sometimes brutal execution of civilians\nsuspected of being informers or collaborators with the military. The Mechanism has also\nreceived reports of sexual violence in detention by armed groups, including rape. The\nMechanism is aware that the National Unity Government has announced investigations into\nsome of these crimes and that some armed groups have publicly announced that they consider\nthemselves bound by international humanitarian law. The Mechanism will continue to\nevaluate the gravity and extent of the crimes committed in accordance with its case\nprioritization policy.\nPotential sharing with future jurisdictions"},{"id":"a-hrc-57-18-p0031","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"31","seq":33,"section":"B. Investigating post-coup crimes","text":"While the Mechanism is currently sharing information with three jurisdictions in\nrelation to serious international crimes committed against the Rohingya, there are currently\nno national or international investigations or proceedings related to crimes committed since\nthe military coup. To date, several complaints regarding post-coup crimes have been filed on\nthe basis of universal jurisdiction, including in Germany, the Philippines and Türkiye. In\nSeptember 2023, the Federal Prosecutor of Germany declined to investigate a complaint\nregarding genocide, war crimes and crimes against humanity in Myanmar filed by a human\nrights group. The authorities in the other jurisdictions where complaints have been filed have\nnot yet announced a response. In addition, the Metropolitan Police Service in the United\nKingdom of Great Britain and Northern Ireland has opened structured investigations into\neach of the situations under investigation by the International Criminal Court, including the\nforcible deportation of Rohingya from Myanmar to Bangladesh. The Mechanism has been\ninformed that this could include the identification of potential witnesses and the examination\nof alleged crimes."},{"id":"a-hrc-57-18-p0032","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"32","seq":34,"section":"B. Investigating post-coup crimes","text":"Despite the absence of investigations or proceedings in relation to post-coup crimes,\nthe Mechanism is preparing files and analytical products on the “chapeau elements” of crimes\nagainst humanity and war crimes, which will be made available to jurisdictions that have\nopened or are considering opening investigations in relation to crimes committed on the\nterritory of Myanmar. Specifically, the Mechanism is using evidence of various crimes to:\n(a) substantiate files in relation to specific incidents and locations; (b) develop a cross-cutting\nanalysis demonstrating the existence of a “widespread or systematic attack against a civilian\npopulation”, which is the threshold for establishing crimes against humanity; and (c) prepare\nan analytical product demonstrating the intensity of armed conflicts and the level of\norganization of the parties to those conflicts in Myanmar, which is relevant to any\ndetermination as to whether crimes took place in the context of an armed conflict and which\nis required to establish the commission of war crimes."},{"id":"a-hrc-57-18-p0033","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"33","seq":35,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"Despite facing many challenges owing to the lack of access to crime scenes and\ndifficulties in contacting witnesses, the Mechanism succeeded in collecting large quantities\nof information and evidence during the reporting period. Its approach has been to combine\ntraditional investigative techniques with modern investigative technologies. The Mechanism\nhas collected many different types of evidence, ranging from detailed signed statements of\nindividuals with first-hand knowledge relevant to serious crimes, to the harvesting,\nverification and analysis of social media, open-source and financial information. To enable\nthe vast quantities of data collected to be searched, analysed and utilized, the Mechanism has\noptimized complex and sophisticated information management technologies. In all of its\ncollection efforts, the Mechanism seeks to ensure that a survivor/victim-centred, gender-\nsensitive and trauma-informed approach underpins its methodologies, processes and systems,\nparticularly in its interactions with witnesses, sources and information providers."},{"id":"a-hrc-57-18-p0034","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"34","seq":36,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"In accordance with the principles of impartiality, confidentiality and informed\nconsent, the Mechanism applies a multifaceted approach to evidence collection, focusing on\ninformation and evidence pertaining to priority situations and incidents, contextual and\noverview information relevant to Myanmar and information pertaining to specific\nindividuals, groups and structures suspected of perpetrating crimes. In accordance with its\nterms of reference, the Mechanism seeks both inculpatory and exculpatory information from\nall relevant parties regarding potential serious international crimes committed in Myanmar."},{"id":"a-hrc-57-18-p0035","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"35","seq":37,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"Through its targeted approach to requesting and receiving information and evidence,\nthe Mechanism has collected and processed for potential sharing nearly 28 million items of\ninformation and evidence. Most of the materials have been collected through formal requests\nfor information. To date, the Mechanism has made nearly 200 formal requests to a variety of\nentities and individuals, which have resulted in the collection of a vast and diverse range of\ninformation and evidence pertaining to its ongoing investigations. Such information and\nevidence includes documents, photographs, videos, audio material, geospatial imagery,\nforensic evidence, witness statements, social media posts and other open-source materials.\nSince beginning its work, the Mechanism has collected information and evidence from over\n900 sources and information providers, including from 320 sources and information\nproviders during the reporting period. The vast majority of the information and evidence is\ncollected from victims, individuals and representatives of civil society organizations who, at\ngreat risk, are in the front line of efforts to gather information and evidence regarding serious\ninternational crimes committed in Myanmar. Other sources of information and evidence\ninclude national authorities, United Nations entities, international organizations,\nnon-governmental organizations and business entities."},{"id":"a-hrc-57-18-p0036","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"36","seq":38,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"The Mechanism places great importance on the collection of first-hand, high-value\nwitness testimony that is essential to building criminal cases. To that end, the Mechanism has\ncontinued to engage with an increasing number of victims and individuals who witnessed the\ncommission, planning or ordering of serious crimes, resulting in the collection of over\n400 witness statements and screening notes to date. In addition to the statements and\nscreening notes, the Mechanism has prepared over 400 investigation notes documenting\ninformation collected from various sources and leads. Investigative missions to various\nStates, in particular, enabled in-person interviews and the collection of other valuable and\nprobative information. The Mechanism acknowledges with appreciation the support provided\nto its investigative activities by relevant national authorities and other stakeholders."},{"id":"a-hrc-57-18-p0037","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"37","seq":39,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"The Mechanism’s methodology and processes for collecting witness statements have\nalso been informed by lessons learned and best practices identified through an internal\nevaluation carried out in 2023. The findings of the evaluation affirmed the effectiveness and\nimportance of taking signed witness statements of high forensic value with the broadest\npossible admissibility in national and international courts and tribunals. Through this\nevaluation, the Mechanism also identified areas for efficiencies and improvement, including\nthe importance of utilizing more culturally informed interviewing techniques and focusing\nthe interviews on the core elements of crimes and evidence of the identity and responsibility\nof suspected perpetrators."},{"id":"a-hrc-57-18-p0038","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"38","seq":40,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"The Mechanism is constantly working to leverage the most current information\nmanagement technologies to ensure that the evidence collected is accessible and searchable\nand that materials are preserved in a manner that will allow their use in future legal\nproceedings. These tools are enabling the Mechanism to expand the amount of information\nand evidence available for sharing with relevant international and national authorities and\nentities. To date, the Mechanism has prepared over 260 packages with supporting information\nand analysis available for sharing with relevant authorities, of which 80 packages, comprising\nover a million information items, have already been shared with such authorities.\nLanguage and translation of the Mechanism’s repository"},{"id":"a-hrc-57-18-p0039","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"39","seq":41,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"Investigating serious international crimes in a country with a large diversity of ethnic\nand linguistic groups such as Myanmar brings an added a layer of complexity to the\nMechanism’s collection and analytical functions. In the majority, the materials the\nMechanism has collected are in the Myanmar language (Burmese) and other languages used\nin Myanmar and are written in different scripts used in Myanmar and in different file formats.\nSimilarly, the majority of the Mechanism’s witnesses, sources and other civil society\nstakeholders speak only in the Myanmar language (Burmese), Rohingya or other languages\nused in Myanmar. As a result, the Mechanism requires timely and accurate language\ntranslation and interpretation capabilities in order to carry out its collection and analytical\nactivities as well as to interact and engage on a regular and meaningful basis with its wide\nrange of beneficiaries and stakeholders."},{"id":"a-hrc-57-18-p0040","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"40","seq":42,"section":"A. Approaches and methodologies for collecting, analysing and managing","text":"During the reporting period, the Mechanism has taken concrete steps to further\nstrengthen its language capacity and support capabilities, both for translation and\ninterpretation. The Mechanism is continuously evaluating its internal language needs to\ndetermine which types of language support and tools are required and identifying steps to\naddress those needs. These steps included the recruitment and specialized training of\nadditional language professionals, which has been particularly effective in increasing direct\nengagement with witnesses, information providers and civil society stakeholders. The\nMechanism has also launched a digitalized translation request system for the management\nand prioritization of translations of collected materials, further facilitating the review,\nassessment and use of such materials in ongoing investigations. The Mechanism is also\nexploring the use of artificial intelligence technologies to develop a machine translation\nsystem capable of producing accurate translations of large volumes of materials from the\nMyanmar language (Burmese) into English."},{"id":"a-hrc-57-18-p0041","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"41","seq":43,"section":"B. Technology and infrastructure","text":"As the digital information landscape continues to evolve and the Mechanism’s\ncollection of digital materials grows, the Mechanism has continued to refine existing\ntechnologies and to integrate new solutions to improve the intake, preservation and analysis\nof its evidence repository. During the reporting period, the Mechanism continued to develop\nits core and specialized technology and infrastructure to enable the collection, preservation\nand analysis of information and evidence in an accessible, searchable and secure manner."},{"id":"a-hrc-57-18-p0042","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"42","seq":44,"section":"B. Technology and infrastructure","text":"In this regard, the Mechanism deploys automation to enable more efficient internal\nworkflow processes. Automation has enabled the Mechanism to produce sharing packs more\nefficiently, in line with the rapid pace of requests for information and evidence by competent\nauthorities. To ensure the integrity of the evidence shared and the security of information,\neach page carries a number unique to the document being shared with the specific authority.\nEnhanced automation in information technologies has also resulted in efficiencies in other\nareas, including the processing of collected materials, which has been reduced from days to\nhours, including the extraction and preservation of data from a variety of social media,\ncommunication and messaging applications."},{"id":"a-hrc-57-18-p0043","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"43","seq":45,"section":"B. Technology and infrastructure","text":"In preparation for the development of a machine translation capability from the\nMyanmar language (Burmese) into English, the Mechanism has devised a tool to standardize\nthe character sets used in the digital materials across the evidence and information\nmanagement system. In addition, the Mechanism has enhanced its optical character\nrecognition capabilities by deploying an advanced optical character recognition platform to\nextract text from evidentiary items that normally have no extractable text. These tools will\ncontribute to an eventual improvement of machine translations."},{"id":"a-hrc-57-18-p0044","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"44","seq":46,"section":"B. Technology and infrastructure","text":"Simultaneously, the Mechanism has continued the development of computer vision\ntechnology in order to analyse the photos and videos that it has collected. The technology\nwill enable the Mechanism to deduplicate, group, retrieve and analyse the large volume of\nphotographs and videos it has collected, including the capability to detect scenes and objects\n(such as villages or weapons) and cluster similar images to facilitate easier analysis. Once it\nhas been fully developed, the technology will enable the Mechanism to carry out more\nadvanced analytics and sharing of information."},{"id":"a-hrc-57-18-p0045","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"45","seq":47,"section":"B. Technology and infrastructure","text":"The Mechanism’s policies and procedures on information systems and information\nmanagement have also been informed by lessons learned and best practices identified through\nan internal evaluation carried out in 2023. In line with the findings of the evaluation, the\nMechanism has taken steps to update its information and technology governance and policy\nframework to better fit its requirements and operations in the wake of the coronavirus disease\n(COVID-19) pandemic. Recognizing the ever-changing technical environment and uses of\ntechnology, an enhanced framework will better respond to improving and evolving\ntechnology systems, better align with the needs of the Mechanism relating to cybersecurity\nand safety and improve compliance by Mechanism personnel. The enhanced framework\nincludes a strengthened information governance programme for all non-evidentiary materials\nand an improved system of labelling and managing physical evidence and regular\ninformational campaigns to keep all personnel informed of technical innovations and their\npotential effects on the work of the Mechanism."},{"id":"a-hrc-57-18-p0046","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"46","seq":48,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"The Mechanism engages in extensive outreach and dialogue with a multitude of\nrelevant stakeholders through its public outreach. Its efforts aim to increase understanding of\nthe Mechanism’s complex mandate and to build trust among those with a stake in its work.\nThe Mechanism uses a range of communication channels and tools to help stakeholders better\nunderstand what it can and cannot do, explain its working methods and increase support and\ncooperation for its investigations. During the reporting period, the Mechanism focused on\noptimizing the impact of its website, Facebook page, media engagements, outreach materials\nand public and closed-door events and briefings."},{"id":"a-hrc-57-18-p0047","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"47","seq":49,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"Two-way communication is vital for the Mechanism to ensure understanding of its\nwork and to respond to feedback from its stakeholders. In this regard, the Mechanism held\nits second in-person civil society dialogue with representatives from 18 civil society\norganizations from diverse communities working on issues related to accountability and\njustice in Myanmar. Civil society organizations provide the Mechanism with valuable\ninformation, documentation, access to witnesses and leads for its investigations. It is one of\nthe Mechanism’s priorities to deepen its engagement with relevant civil society organizations\nin order to increase mutual understanding and to facilitate its understanding of the realities\nand challenges that these organizations face in the course of their work."},{"id":"a-hrc-57-18-p0048","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"48","seq":50,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"Over three days of frank and open discussions, Mechanism personnel shared\ninformation about its mandate and limitations, procedures and investigative priorities as well\nas how information shared by civil society organizations is used in its investigations. Civil\nsociety participants shared their challenges and frustrations and highlighted some of the\ndifficulties they encounter in their work and how this impacts their engagement with the\nMechanism. Many organizations shared concerns relating to security and psychosocial needs,\nInternet blackouts, funding issues and fatigue. They made valuable suggestions on how to\nimprove their cooperation with the Mechanism, which is considering how to modify its\nworking methods in response. Before the dialogue, 57 per cent of participants indicated that\nthey had a good understanding of the Mechanism and its mandate. This increased to 100 per\ncent by the end of the event. The number of civil society representatives who indicated an\ninterest in cooperating with the Mechanism almost doubled following their participation in\nthe dialogue."},{"id":"a-hrc-57-18-p0049","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"49","seq":51,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"In addition to the dialogue, the Mechanism engaged with a range of stakeholders\ninterested in justice for crimes committed in Myanmar. During the reporting period, this\nincluded participation in close to 40 public and closed-door events as well as virtual and in-\nperson briefings, the majority of which included engagements with survivors, civil society\ngroups and information providers. Since security is a serious concern for the Mechanism, a\nrange of measures were put in place for virtual briefings to enable participants based in\nMyanmar and other locations to engage as safely as possible."},{"id":"a-hrc-57-18-p0050","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"50","seq":52,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"In addition to such direct engagement, the Mechanism has prioritized the development\nof outreach materials with simplified messaging that is accessible and memorable for a range\nof audiences. In this regard, the Mechanism produced visual outreach materials that explain\nhow the Mechanism works, how to share confidential information with it, what happens to\ninformation once it is shared and how the Mechanism works with victims of sexual and\ngender-based crimes. These materials have been produced both in English and the Myanmar\nlanguage (Burmese) and have been distributed through various communication channels and\nby global and regional partners. In the next reporting period, the materials will also be\nproduced in several ethnic languages, including animated videos in the Rohingya language."},{"id":"a-hrc-57-18-p0051","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"51","seq":53,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"The Mechanism has also focused on improving the design and content on its website\nto make the information more accessible in English and the Myanmar language (Burmese).\nThe updated website will be launched later in 2024. The Mechanism has also intensified its\nengagement through social media by producing visual and shareable content on Facebook\nand encouraging greater interactivity with its almost 75,000 followers through regular\nquestion and answer sessions. The public release of two analytical reports on hate speech and\nsexual and gender-based crimes further galvanized interactivity on these platforms. This was\nthe first time that the Mechanism had released such reports on an exceptional basis in the\ninterest of transparency and with the intention that they could be used widely for other justice\nand accountability efforts."},{"id":"a-hrc-57-18-p0052","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"52","seq":54,"section":"C. Dialogue with relevant stakeholders and public outreach","text":"There has been continued media interest in the work of the Mechanism. Press releases,\nstatements, media briefings and interviews have resulted in regular coverage in influential\nglobal, regional and national media outlets, including in the languages used in Myanmar. In\nthe next reporting period, the Mechanism aims to target the media working in minority ethnic\nlanguages to reach more communities within Myanmar. The Mechanism also increased the\npublication of its bulletin from twice to three times a year to provide more regular updates\non its activities to Member States, civil society organizations and other stakeholders."},{"id":"a-hrc-57-18-p0053","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"53","seq":55,"section":"D. Witness protection and support","text":"The protection and support of witnesses and information providers, both in Myanmar\nand outside its borders, continues to be a top priority for the Mechanism. The Mechanism\nhas continued its efforts to adopt appropriate procedures and methods of work for the\nprotection of witnesses, taking all feasible steps within its means to protect their safety and\nsecurity, both during and resulting from their cooperation with the Mechanism. Such\nmeasures extend to all areas of the Mechanism’s operations, from collection to sharing, to\nensure that individuals and entities that cooperate with the Mechanism do not suffer harm."},{"id":"a-hrc-57-18-p0054","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"54","seq":56,"section":"D. Witness protection and support","text":"To enable the Mechanism’s investigative activities, the Mechanism conducted over\n330 contact assessments during the reporting period to identify security risks and ensure that\nwitnesses can engage safely with the Mechanism. As the Mechanism does not have the power\nto provide physical security or guarantee the safety of witnesses or to grant anyone the right\nto travel or enter any country, the cooperation of Member States remains crucial for the\nprotection of witnesses, particularly the most at-risk individuals. The Mechanism relies on\nthe assistance of Member States to be able to timely and adequately respond to threat actors\nin areas where witnesses reside and to ensure that they are safe and that important evidence\nis preserved."},{"id":"a-hrc-57-18-p0055","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"55","seq":57,"section":"D. Witness protection and support","text":"Survivors of all crimes, including sexual and gender-based crimes, often suffer lasting\nphysical and psychological injuries. The Mechanism continues working to ensure that all of\nits interactions with witnesses, both remote and in person, adopt a survivor-centred, gender-\nsensitive and trauma-informed approach, including through appropriate evaluation and\nsupport for all vulnerable witnesses, in particular children and survivors of sexual and gender-\nbased violence. The Mechanism provides psychosocial assistance during interviews to ensure\nthe well-being of witnesses and to facilitate support through referral services. During the\nreporting period, the Mechanism developed a system for follow-up engagements with\nwitnesses who have been interviewed by the Mechanism, to check on their well-being and\nsecurity and to seek their feedback on their engagement with the Mechanism. While many\nsuch witnesses continue to live in very difficult circumstances, their feedback has been\npositive. Witnesses have overwhelmingly indicated that they felt that their engagement with\nthe Mechanism gave them a meaningful opportunity to contribute to efforts to ensure\naccountability for serious international crimes."},{"id":"a-hrc-57-18-p0056","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"56","seq":58,"section":"D. Witness protection and support","text":"With the aim of strengthening culturally informed and survivor-centred practices, the\nMechanism continued to enhance its support capacities, including through the addition of a\nmental health professional who speaks the Myanmar language (Burmese) as well as\npartnerships with psychosocial experts fluent in one of the Myanmar languages. The\nMechanism also broadened its referral network for psychosocial support across different\nlocations, despite significant challenges in identifying and establishing referral organizations\nand in finding available professionals in areas impacted by political unrest, socioeconomic\nfactors and security threats, where resources are scarce. To improve planning and\nimplementation of witness support, the Mechanism regularly evaluates trends in support\nneeds and refines available support services. During the reporting period, the Mechanism\nprovided in-house support to nearly 50 witnesses, assessing their vulnerabilities and\nidentifying their needs in order to reduce the risk of possible negative impact on their\nwell-being as a result of their cooperation with the Mechanism. Eight individuals have been\nreferred to external service providers to receive medical and psychosocial support, as\nprovided for in the Mechanism’s term of reference."},{"id":"a-hrc-57-18-p0057","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"57","seq":59,"section":"E. Security of personnel, information assets and operations","text":"The Mechanism is closely monitoring the worsening security situation in areas\ndirectly affecting its operations as it places the highest priority on ensuring the security of its\npersonnel, information assets and operations. The Mechanism’s activities, including\ninvestigative missions and other interactions with witnesses in vulnerable situations and at\nhigh-risk, require complex security arrangements for its personnel. The Mechanism aims to\nensure that required safety and security arrangements, based on the Mechanism’s specific\nsecurity needs and risk assessments, are integrated into all aspects of its operations, both in\nGeneva and during missions. This has included monitoring and analysing an increasing\nnumber of threat actors and their activities and producing comprehensive and regularly\nupdated country or area-specific situation threat and risk assessments. Utilizing its\nwell-established communications channels, the Mechanism maintains close coordination and\nadvance planning with entities of the United Nations system and with security interlocutors\nin various locations. This has contributed to the safety and security of investigative missions\nand other activities, such as the Mechanism’s civil society dialogues, despite a challenging\nsecurity landscape."},{"id":"a-hrc-57-18-p0058","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"58","seq":60,"section":"E. Security of personnel, information assets and operations","text":"In addition, the Mechanism works hard to maintain high standards of cybersecurity in\norder to protect its communications with sources and witnesses and the information and data\nwith which it is entrusted. Technological advances by threat actors that could compromise\nthe security of digital communications in Myanmar threaten the Mechanism’s ability to\nprotect its information assets as well as access sources and information securely. The\nMechanism is continuously reviewing and refining its cybersecurity measures and practices\nacross its operations, focusing equally on mitigation as well as response preparedness\nmeasures. The Mechanism continued to enhance its cybersecurity on devices and services\nbeing deployed, allowing for better and more secure connectivity and access to systems, both\nin Geneva and during missions. The Mechanism also plans responses in order to safely\nmanage the effects of third-party cybersecurity incidents. The Mechanism’s specialists\nregularly conduct dedicated training and awareness programmes for personnel on\ninformation security and cyberthreats."},{"id":"a-hrc-57-18-p0059","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"59","seq":61,"section":"IV. Cooperation with Member States and other partners","text":"The Mechanism continued to reach out to and seek information from the Myanmar\nauthorities, in accordance with relevant resolutions in which the Human Rights Council and\nthe General Assembly called upon Myanmar to cooperate and engage meaningfully with the\nMechanism. To date, the Mechanism has made numerous requests to the Myanmar\nauthorities for information in its possession and for access to its territory. The Myanmar\nmilitary has continued to ignore such requests. Most recently, the Mechanism issued a public\nstatement on its latest request for information concerning the capture and burning alive of\ntwo young men in Magway Region, in the hope that publicizing the request about such a\nheinous crime might lead to a response."},{"id":"a-hrc-57-18-p0060","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"60","seq":62,"section":"IV. Cooperation with Member States and other partners","text":"The Mechanism requires the cooperation of numerous entities, including States,\ninternational organizations, civil society organizations, business entities and victims, in order\nto collect information and evidence on the most serious international crimes committed in\nMyanmar. Many States require the negotiation of formal arrangements regulating the\nparameters of their cooperation, for example, in order for the Mechanism to conduct witness\ninterviews in their territory. Some international organizations, civil society organizations and\ncorporate providers also require formal cooperation arrangements before sharing information\nwith the Mechanism. The conclusion of formal cooperation arrangements is consequently\ncritical to the effective implementation of the Mechanism’s mandate. To date, the\nMechanism’s proactive engagement with States and other stakeholders have contributed to\nthe negotiation and conclusion of 36 cooperation arrangements, in the forms of treaties,\nmemorandums of understanding, exchanges of letters or other instruments. Fourteen such\ncooperation arrangements have been concluded with Member States, covering States in Asia,\nEurope, Oceania and North America. These arrangements have allowed the Mechanism to\ncarry out several dozen witness interviews and the collection of millions of evidentiary items\nin various countries."},{"id":"a-hrc-57-18-p0061","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"61","seq":63,"section":"IV. Cooperation with Member States and other partners","text":"In an effort to strengthen cooperation by all relevant stakeholders, during the reporting\nperiod, the Mechanism continued its high-level dialogues and consultations with Member\nStates and other actors in Geneva, New York and numerous capitals. These engagements\nenabled the Mechanism to promote its work and to advance important cooperation\narrangements to carry out evidence collection and witness interviews in the territories of\nMember States. In parallel, the Mechanism continued to actively engage and develop both\ninformal and formal arrangements with a large network of civil society organizations, both\nin and outside the Asia-Pacific region, to build trust and to foster cooperation."},{"id":"a-hrc-57-18-p0062","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"62","seq":64,"section":"IV. Cooperation with Member States and other partners","text":"During the reporting period, the Mechanism also continued to rely on the support and\ncooperation of United Nations entities that might have information relevant to the\nMechanism’s mandate or that could provide support in other areas of its operations. Fully\ncognizant of the challenging operational environment that the United Nations system is\ncurrently facing in Myanmar, the Mechanism highly values the continued cooperation and\nsupport of many United Nations actors, in line with the Human Rights Council resolution\n52/31, in which the Council urged all United Nations bodies to collaborate fully with the\nMechanism, where possible, and to share evidence that may be used in future prosecutions."},{"id":"a-hrc-57-18-p0063","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"63","seq":65,"section":"V. Challenges and areas for additional support","text":"As highlighted throughout the present report, the Mechanism faces a number of\ncomplex challenges, including: the lack of direct access to victims and witnesses in Myanmar\nand other States in the region; threats to the safety and security of personnel, witnesses and\ninterlocutors; cybersecurity threats to communications and limitations in secure access to\ninformation; and the need for adequate capacity and resources to reinforce language and\ntranslation capabilities, technological innovations and specialized expertise. These\nchallenges have been compounded by the liquidity crisis facing the United Nations during\nthe reporting period."},{"id":"a-hrc-57-18-p0064","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"64","seq":66,"section":"V. Challenges and areas for additional support","text":"The full cooperation of Member States in the Asia-Pacific region remains essential to\nending the spiralling violence in Myanmar and ultimately pursuing justice for its people. For\nthat reason, expanding cooperation with States in the region, where much of the evidence and\nmany of the witnesses are located, continues to be a significant challenge and a high priority\nof the Mechanism. The Mechanism greatly values the continued strong support extended by\nsome States for its investigative activities. It hopes that additional States that wish to end the\nhorrendous violence that has engulfed Myanmar and to help the country towards a path to\nsustainable peace will cooperate with the Mechanism and send a strong and united message\non the commitment of the international community to fight impunity for serious international\ncrimes in Myanmar."},{"id":"a-hrc-57-18-p0065","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"65","seq":67,"section":"V. Challenges and areas for additional support","text":"The Mechanism’s ability to address risks related to the safety of its witnesses,\npersonnel and information assets also requires the cooperation of Member States where such\npersons are located or seek to relocate. The security situation of potential witnesses has\nbecome increasingly complex with the deteriorating security situation both in Myanmar as\nwell as in some other locations hosting refugees. Many of the Mechanism’s witnesses and\nsources face serious risks both inside and outside Myanmar. Many have been forced to flee\nMyanmar and have crossed into neighbouring countries without any legalized immigration\nstatus, placing them in vulnerable situations, sometimes including the risk of arrest and\ndeportation to Myanmar, where they may face persecution, detention and even execution.\nThe developing security situation in the areas where the Mechanism’s witnesses are located\nalso requires constant monitoring to assess the presence of threat actors and their capabilities.\nAs the Mechanism’s investigations intensify, the need for increased capacity to monitor risks\nand threats affecting the safety and security of witnesses will also grow. The Mechanism is\nalso expanding its engagement with civil society organizations, including through the civil\nsociety dialogue, which requires tailored risk and threat assessments for each civil society\norganization and the identification and implementation of corresponding mitigation\nmeasures, including through support from Member States."},{"id":"a-hrc-57-18-p0066","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"66","seq":68,"section":"V. Challenges and areas for additional support","text":"As the Mechanism’s activities grow, its personnel also face increased risks as a result\nof continued attacks against organizations and individuals working for justice and\naccountability in Myanmar. These risks have been compounded by greater awareness that\nthe Mechanism’s work may lead to criminal prosecutions against perpetrators of serious\ninternational crimes in Myanmar."},{"id":"a-hrc-57-18-p0067","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"67","seq":69,"section":"V. Challenges and areas for additional support","text":"As Myanmar becomes increasingly more difficult to access, the possibility of digital\nsurveillance and other potential threats to its information and communication systems has\nalso grown. Many of the Mechanism’s information sources, particularly those inside\nMyanmar, have legitimate fears that they are under surveillance or that their communications\nmight be intercepted. In order to maintain a high level of vigilance about the security of its\ninformation and communications technology, the Mechanism is continuously adapting to\nevolving technologies and strengthening its incident response system to prevent and respond\nto cyberattacks."},{"id":"a-hrc-57-18-p0068","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"68","seq":70,"section":"V. Challenges and areas for additional support","text":"While the political and operational support of Member States is critical, the\nMechanism also needs adequate resources in order to address the above challenges and to\ndeliver on its mandate as effectively as possible. Inadequate resources affect other critical\nareas of the Mechanism’s operations. For example, the Mechanism requires resources to\nensure effective translation and interpretation capabilities, especially considering the volume\nof collected material in the Myanmar language (Burmese). The Mechanism will need to\nfurther increase its language capacity in the upcoming reporting period. This can partly be\nachieved through additional resources, including the recruitment and additional training of\ninterpreters and translators, and partly through the continuing development of machine\ntranslation technology and solutions. The translation of digital texts from the languages\nspoken in Myanmar, in particular the Myanmar language (Burmese), into English using\nartificial intelligence technology remains a challenge as the technology is not yet as advanced\nfor those languages as it is for others; development in this field will require significant\nadditional financial resources. Furthermore, addressing the complexities related to Myanmar\nlanguage (Burmese) character sets and fonts will require collaboration with specialist\nlanguage scientists in order to develop this capability further."},{"id":"a-hrc-57-18-p0069","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"69","seq":71,"section":"V. Challenges and areas for additional support","text":"The liquidity crisis facing the United Nations has not spared the Mechanism, placing\nsignificant restrictions on both staff and non-staff resources, affecting recruitment, essential\nconsultancies, investigative mission travel, training and the acquisition of information\ntechnology equipment and software. The Mechanism has been obliged to leave a number of\nregular budget positions vacant, including in critical areas such as witness protection. Some\ninvestigative travel has also been curtailed to manage costs. The Mechanism prioritizes\ninterviewing witnesses in person to ensure that interviews are accurate, free of any potential\nallegations of outside influence and are conducted to high standards that preserve the integrity\nof witness testimony. Travel cuts have therefore greatly impacted the gathering of crucial\nevidence from certain witnesses."},{"id":"a-hrc-57-18-p0070","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"70","seq":72,"section":"V. Challenges and areas for additional support","text":"In light of these resource challenges, the Mechanism continues to actively seek\nvoluntary contributions from Member States for discrete projects and highly specialized\nexpertise. The complex work of the Mechanism requires specialized personnel and\ntechnologies that were not envisioned in the early stages of its establishment, including open-\nsource research and analysis, financial investigations and innovative technologies. The\nMechanism will continue to mobilize extrabudgetary funding to sustain its activities in the\nfuture and welcomes the support of diverse Member States and partners."},{"id":"a-hrc-57-18-p0071","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"71","seq":73,"section":"VI. Conclusion","text":"The Mechanism acknowledges with gratitude the support extended to its\ninvestigative efforts by many Member States, United Nations entities, civil society\norganizations, private and public information providers and other partners. Their\nsupport remains crucial for the Mechanism to effectively carry out its mandate. The\nMechanism is particularly grateful for the cooperation received from witnesses and\nsurvivor groups, which reflects the courage and dedication of the people of Myanmar\nto the fight against impunity."},{"id":"a-hrc-57-18-p0072","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"72","seq":74,"section":"VI. Conclusion","text":"While the number of serious international crimes committed in Myanmar is\nmounting, so is the evidence against the perpetrators. The Mechanism’s team of\nanalysts, investigators and lawyers are working hard and working smart to find, collect\nand analyse relevant evidence. The Mechanism will continue to combine well-tested\ninvestigative techniques with new and evolving technologies to piece together evidence\nto prove the commission of serious international crimes and the role played by those\nwho bear personal responsibility."},{"id":"a-hrc-57-18-p0073","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"73","seq":75,"section":"VI. Conclusion","text":"Going forward, the Mechanism will continue to: prioritize investigations of the\ngravest crimes where the impact on victims is most severe, including sexual and gender-\nbased crimes and crimes against children; seek cooperation from critical Member\nStates to carry out investigative missions, including in new locations where relevant\nwitnesses are located; explore innovative methodologies that will enable it to\nsystematically analyse significant volumes of evidentiary material, with a focus on\nlinking specific perpetrators to the crimes; and prepare and share evidentiary and\nanalytical products that will have a high value to national and international\njurisdictions. The above efforts will require the continued advancement of the\nMechanism’s information and technology systems to propel analytical and translation\ncapabilities and to improve textual and image analytics. Identifying creative solutions\nthat make the Mechanism’s interactions and missions safer for personnel, interlocutors\nand information will also remain a high priority."},{"id":"a-hrc-57-18-p0074","rec_id":"recKWfKgtbC3Wpj8x","symbol":"A/HRC/57/18","n":"74","seq":76,"section":"VI. Conclusion","text":"The Mechanism stands ready to support relevant authorities from national,\nregional or international courts or tribunals willing and able to pursue accountability\nfor serious international crimes committed in Myanmar. In solidarity with the people\nof Myanmar, and with the continued support of the international community, the\nMechanism hopes that the evidence it collects will one day be presented in a court of\nlaw and that those responsible will face justice."},{"id":"a-hrc-59-57-u0000","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":null,"seq":0,"section":null,"text":"United Nations                                                                                     A/HRC/59/57\nGeneral Assembly                                                            Distr.: General\n16 June 2025","unnumbered":true},{"id":"a-hrc-59-57-u0001","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":null,"seq":1,"section":null,"text":"Human Rights Council\nFifty-ninth session\n16 June–11 July 2025\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nHuman rights situations that require the Council’s attention","unnumbered":true},{"id":"a-hrc-59-57-u0002","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":null,"seq":2,"section":null,"text":"Summary\nThe present report is submitted pursuant to Human Rights Council\nresolution 55/20, in which the Council requested the United Nations High Commissioner\nfor Human Rights to, among other things, monitor and assess the overall situation of\nhuman rights in Myanmar and to report on pathways to fulfil the aspirations of the people\nof Myanmar for human rights protection, accountability, democracy and a civilian\ngovernment. The report, which is based on extensive consultations, presents the main\npathways towards achieving this vision and the key constituencies that are working for\nchange on the ground.","unnumbered":true},{"id":"a-hrc-59-57-p0001","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"1","seq":3,"section":"I. Introduction","text":"In its resolution 55/20, the Human Rights Council requested the United Nations High\nCommissioner for Human Rights to monitor and assess the overall situation of human rights\nin Myanmar and to submit to the Council, at its fifty-ninth session, a comprehensive report\nthereon, including on pathways to fulfil the aspirations of the people of Myanmar for human\nrights protection, accountability, democracy and a civilian government."},{"id":"a-hrc-59-57-p0002","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"2","seq":4,"section":"I. Introduction","text":"The present report builds on the observations made by the High Commissioner at the\nfifty-fifth session of the Human Rights Council on the need for a visioning exercise\nencapsulating the aspirations of the people of Myanmar, particularly youth."},{"id":"a-hrc-59-57-p0003","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"3","seq":5,"section":"I. Introduction","text":"The report provides an overview of the dire human rights situation, including the\npolitical economy that enables the Myanmar military to continue its repression, and the\nwidening regional impacts of the situation in Myanmar. The report subsequently presents\nsome of the key constituencies that are striving to promote positive changes and build a\npeaceful, sustainable, democratic and diverse Myanmar grounded in human rights. In the\nlight of the information gathered through extensive consultations with diverse sections of\nsociety in Myanmar, the report presents four main pathways towards achieving this vision –\naccountability, good governance, sustainable development and actions by international and\nregional stakeholders – and provides positive examples of efforts to that end that are\nemerging or already under way."},{"id":"a-hrc-59-57-p0004","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"4","seq":6,"section":"I. Introduction","text":"Lastly, the report presents recommendations on actionable measures to address the\nroot causes of the crisis, which include the unchecked political and economic power of the\nmilitary, impunity, the instrumentalization of laws and institutions and an overall system\nbased on racial discrimination and division. The report contains details on how Member\nStates, including States members of the Association of Southeast Asian Nations (ASEAN),\ncan support the free and effective participation of the people of Myanmar in building a new\nfuture for the country in which their rights are protected and respected."},{"id":"a-hrc-59-57-p0005","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"5","seq":7,"section":"I. Introduction","text":"At the time of writing, Myanmar was still suffering from the devastating effects of the\ncatastrophic earthquake of 28 March 2025 in its central regions, in particular in Mandalay\nand Sagaing. Thousands died and the destruction of property and infrastructure was\nwidespread. In the period following the earthquake, the military maintained its policy of\nrestrictive control over humanitarian access, including to affected areas, and, notwithstanding\nceasefires announced by the military and anti-military armed groups, military operations\ncontinued, inflicting further suffering on the civilian population. The High Commissioner\nexpresses the utmost solidarity with the people of Myanmar and reiterates that responses to\nthe overall crisis must uphold human rights principles and address the needs of the civilian\npopulation without discrimination.1"},{"id":"a-hrc-59-57-p0006","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"6","seq":8,"section":"II. Methodology","text":"To gather views and recommendations for the drafting of the present report, between\nSeptember 2024 and March 2025, the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR) carried out 126 in-person and online consultations with 36 groups\nand 391 people, including at least 176 women. Those consultations built upon the interviews\nconducted with hundreds of victims and witnesses of human rights violations in Myanmar\nthat have been reflected in previous reports.2"},{"id":"a-hrc-59-57-p0007","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"7","seq":9,"section":"II. Methodology","text":"Participants in the consultations included representatives of many different facets of\nsociety in Myanmar, including village leaders, students, lawyers, artists, teachers, displaced\npersons, political prisoners, military defectors and humanitarian, health and media workers.\nConsultations also involved human rights defenders, representatives of civil society\norganizations, including organizations promoting the rights of women and LGBTQI+\npersons, environmental researchers, members of the civil disobedience movement and trade\nunionists, among others. The consultations cut across a wide range of religious beliefs,\nincluding representatives of Buddhist, Christian, Muslim and Hindu religious communities,\nas well as other ethnic, linguistic and religious groups, including the Kuki, Lisu, Pa’O and\nRohingya communities."},{"id":"a-hrc-59-57-p0008","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"8","seq":10,"section":"II. Methodology","text":"In addition, OHCHR submitted questionnaires to duty bearers, including the\nPermanent Mission to the United Nations Office and other international organizations in\nGeneva, affiliated with the military, and the Permanent Mission to the United Nations in New\nYork, affiliated with the National Unity Government. OHCHR also gathered the views of\nrepresentatives of political entities in Myanmar, including committees of the National Unity\nConsultative Council, local governance structures, anti-military armed groups and several\nethnic armed organizations. OHCHR also consulted with United Nations entities, received\nwritten contributions from think tanks, analysts and thematic experts and undertook extensive\ndesk reviews of laws, policies, reports and data from local and international organizations."},{"id":"a-hrc-59-57-p0009","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"9","seq":11,"section":"III. Current human rights context and political economy of","text":"In 2011, Myanmar initiated a democratic transition that led to landslide victories for\nthe National League for Democracy during the 2015 and 2020 elections, confirming the\naspirations of the people of Myanmar for a fully democratic system. However, in February\n2021, that democratic transition ended abruptly when the military launched a coup. Since\nthen, a human rights crisis characterized by violence and atrocities has affected every single\naspect of life in Myanmar. According to credible sources,3 as at 31 March 2025, at least 6,473\ncivilians had been killed at the hands of the military, including 1,487 women and 748\nchildren. Some 28,961 had been arrested, 22,165 remained in detention and 172 had been\nsentenced to death by military-controlled courts that do not ensure any respect for judicial\nguarantees and fair trial rights.4 Violence has displaced more than 3.5 million people and,\nwhile nearly 20 million are in need of assistance, 5 the military has persistently blocked\nhumanitarian access, even in the wake of natural disasters, including the recent earthquake. 6\nEstimates suggest that more than 1.5 million people have sought safety by crossing\ninternational borders by land or by sea, through both regular and irregular channels, creating\nfurther regional human rights and humanitarian challenges. 7 The crisis has made other\ntransnational problems, including health concerns related to cholera or other transmissible\nillnesses,8 transboundary environmental harm and natural disasters, more difficult to manage."},{"id":"a-hrc-59-57-p0010","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"10","seq":12,"section":"III. Current human rights context and political economy of","text":"Since the previous comprehensive report, 9 anti-military armed groups have made\nsignificant advances, gaining control over large swathes of territory. Retaliation by the\nmilitary has often been in the form of air strikes and artillery shelling on populated areas,\nkilling more civilians in 2024 than in previous years. Fighting was particularly intense in\nRakhine, where the Arakan Army took control of the regional military headquarters and\nnumerous bases, obtaining almost full control of the state. Rohingya civilians were caught\nbetween the military and the Arakan Army, regularly facing killings, disappearances,\nmutilations, arbitrary arrests, torture, destruction of villages and widespread displacement.\nThere are also reports of the involvement of Rohingya armed groups and armed elements in\nhostilities. At the time of writing, conditions remained unconducive to the safe and\nsustainable return of members of the Rohingya community to Rakhine.\n3 See www.aappb.org/.\n4 Ibid.\n5 See www.humanitarianaction.info/plan/1275/document/myanmar-humanitarian-needs-and-response-\nplan-2025.\n6 See www.reliefweb.int/report/myanmar/myanmar-earthquake-flash-update-2-31-march-2025.\n7 See https://thailand.iom.int/sites/g/files/tmzbdl1371/files/documents/2024-10/overview-of-myanmar-\nnationals-in-thailand-october-24.pdf.\n8 See www.reliefweb.int/report/myanmar/myanmar-health-cluster-bulletin-february-2025."},{"id":"a-hrc-59-57-p0011","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"11","seq":13,"section":"III. Current human rights context and political economy of","text":"Myanmar has also been engulfed in a profound economic crisis, further exacerbating\nthe negative impacts of the conflict at both the national and regional levels. Comparative\nperformance analysis showed massive economic losses and the diversion of resources away\nfrom development.10 Gross domestic product estimates suggest a $93.9 billion loss since the\ncoup,11 with recovery to the pre-pandemic level not expected before 2028.12 Inflation rose\nsharply, with further increases to 30 per cent expected in the period 2024–2025, and the kyat\ndepreciated 40 per cent against the United States dollar. Foreign direct investment\ncommitments decreased: data showed a 50 per cent contraction in the first half of 2024\ncompared with 2023. Military spending was prioritized over investment in civilian\ninfrastructure and services, and public debt increased to 62 per cent in 2024–2025. More than\nhalf the population now lives below the poverty line and food insecurity is widespread.13 The\nprice of commodities, including rice, vegetables, edible oils, fish, meat and beans, increased\nsignificantly: by up to 30 per cent on average nationally in 2024.14 In addition, restrictions on\nthe import of essential goods, such as cooking oil, medical supplies, pharmaceuticals, seeds\nand fertilizers, have had a detrimental impact on a population already devastated by poverty."},{"id":"a-hrc-59-57-p0012","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"12","seq":14,"section":"III. Current human rights context and political economy of","text":"Underpinning the economic crisis is the military’s control of the central bank and\nState-owned enterprises, including in the extractive sector. While targeted international\nsanctions have slowed some military revenue streams, these institutions remained key\nsources of revenue, sustaining the military’s attempts to consolidate control. In addition,\nfinancial measures enabling continued military spending, such as import substitution, foreign\nexchange controls, forced conversion and taxation of remittances at an artificial rate\nfavouring the military, as well as a crackdown on informal money transfers, have further\nenriched the military and impoverished the civilian population.15"},{"id":"a-hrc-59-57-p0013","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"13","seq":15,"section":"III. Current human rights context and political economy of","text":"Under the military, illicit economies have thrived, far outpacing the formal economy.\nSince 2023, Myanmar has remained the world’s largest producer of opium and synthetic\ndrugs. 16 It has become a major hub for transnational criminal activities, including online\nscamming operations, human trafficking, forced labour and other modern forms of slavery,\nand the unregulated and illegal exploitation of natural resources. Neighbouring countries\nhave also suffered, with an ever increasing number of their citizens falling prey to scammers\nand their territories becoming staging grounds for further illicit activities. Under military rule,\nregional crime groups have exploited the lack of rule of law, expanding their influence and\ncontrol.17"},{"id":"a-hrc-59-57-p0014","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"14","seq":16,"section":"III. Current human rights context and political economy of","text":"The economic crisis has had broader negative economic effects, particularly in the\nregion, including disruptions in cross-border trade and investment, disruptions in supply\nchains and inflationary pressure. Estimates indicate that the region also bears the opportunity\ncosts of the coup: the combined potential loss in gross domestic product of neighbouring\ncountries between 2022 and 2026 is estimated to be $162.4 billion.18"},{"id":"a-hrc-59-57-p0015","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"15","seq":17,"section":"IV. Constituencies for change","text":"Amid the crisis caused by the military, there have been some positive developments,\none of the most significant of which is the emergence of “constituencies for change”. These\nconstituencies have shown steadfast courage and resilience in the face of military violence\nwhile advocating for new and transformative visions of the future. As in previous decades of\nmilitary rule, grass-roots and civil society organizations have continued to support the people\nof Myanmar in countering military repression. Religious institutions and community-based\norganizations have sought to fill gaps left by failing State services, such as healthcare and\neducation. Human rights defenders and civil society have maintained attention on violations\nthrough strengthened cooperation with regional and international advocacy networks. In\nlong-standing conflicts in the border regions of Myanmar, ethnic armed organizations have\nenabled varying forms of local administration to assist those in need. Over the previous\ndecade, and particularly since the 2021 coup, a new generation of human rights defenders\nhas emerged, promoting new thinking on identity, human rights, the economy and the\nenvironment through the innovative use of communication and new technologies, and\ninspired by the country’s history of gradual, if fragile, opening up and democratization."},{"id":"a-hrc-59-57-p0016","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"16","seq":18,"section":"IV. Constituencies for change","text":"Meanwhile, various political actors and ethnic organizations have begun to embrace\nnew ideas shaped by their experience in local governance, democracy and military-led peace\nnegotiations. These new ideas have included a growing recognition of past mistakes and\nunrealized opportunities, the importance of partnership with civil society, the nature and scale\nof past human rights violations, the need for genuine accountability and a vision that is\ninclusive of all ethnic communities. Changing narratives on members of the Rohingya\ncommunity, in which the Rohingya are acknowledged as being part of Myanmar and there is\nrecognition of the need for profound legal reforms, including laws on citizenship, race and\nreligion, have been encouraging."},{"id":"a-hrc-59-57-p0017","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"17","seq":19,"section":"IV. Constituencies for change","text":"The following sections identify some of the key constituencies that are creating the\nconditions for an inclusive and democratic future for Myanmar. These constituencies for\nchange have made enormous sacrifices and commitments, individually and collectively, to\npreserve civic space and advance democracy and human rights. They provide a shining\nexample of hope for what a peaceful and democratic future can be.\n1.         Women"},{"id":"a-hrc-59-57-p0018","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"18","seq":20,"section":"IV. Constituencies for change","text":"Women from diverse communities and backgrounds, including women from urban\nand rural communities, grass-roots activists, academics, industry workers, doctors, nurses,\nteachers, politicians and advocates have been at the forefront of pro-democracy campaigns,\nin living fulfilment of the women and peace and security agenda.19 They have staged various\nforms of protest to express peaceful dissent. More than 4,200 women remain deprived of\nliberty for their opposition to military rule and there are widespread and systematic reports\nof sexual violence against women in detention.20"},{"id":"a-hrc-59-57-p0019","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"19","seq":21,"section":"IV. Constituencies for change","text":"Women’s groups, organizations and networks, notwithstanding enormous constraints\nand personal security risks, have emerged alongside existing networks and have been critical\nin ensuring that the civilian population receives life-saving assistance and has access to\nhealthcare, essential services and economic opportunities. Women’s groups have continued\nto be a key resource for the civilian population, alleviating their suffering by providing\nconflict-affected communities with food, water, medicine, hygiene kits and mental health\nassistance. They have supported families of political prisoners and participants in the civil\ndisobedience movement. Women’s groups have also played a critical role in documenting\nand reporting on human rights violations and in supporting survivors of sexual and gender-\nbased violence, including domestic and intimate partner violence."},{"id":"a-hrc-59-57-p0020","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"20","seq":22,"section":"IV. Constituencies for change","text":"Although women in Myanmar have played crucial societal and political roles for\ndecades, the coup brought into sharp focus the need to change the patriarchal fabric of\nMyanmar and promote women to leadership roles. By working as fighters, drone operators\nand medics on the front line, women have rejected patriarchal norms, challenged exclusion\nand advocated against the maintenance of traditional gender roles, including through the\nestablishment of effective mechanisms to prevent and address violence."},{"id":"a-hrc-59-57-p0021","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"21","seq":23,"section":"IV. Constituencies for change","text":"Women have demanded inclusion in decision-making and representation in new\ngovernance charters and systems, propelling bottom-up and inclusive local governance\nmechanisms. In Kayah, for example, women have played a pivotal role in the Karenni State\n19   See dppa.un.org/en/women-peace-and-security.\n20   See www.aappb.org/.\nInterim Executive Council since its establishment, as underscored by the election in June\n2023 of the second Joint General Secretary of the Burmese Women’s Union to the post of\nFirst Secretary of the Executive Council. In addition, the terms of the interim arrangement\nfor reestablishing the foundations of Kayah State provide for a minimum of 30 per cent\nwomen’s representation in public administration.\n2.        Youth"},{"id":"a-hrc-59-57-p0022","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"22","seq":24,"section":"IV. Constituencies for change","text":"The group most affected by the military coup has been the youth of Myanmar, who\nare defined as individuals between 18 and 35 years of age. These people came of age during\na period of political and economic opening up and rapid social change in Myanmar that was\nbrutally interrupted by the military coup. Once the peaceful expression of dissent became too\ndangerous, many young people left family, education and employment behind and joined\narmed resistance with little or no training or equipment. Military violence, killings, arrests,\ntorture, disappearances, conscription and forced recruitment, restrictions on movement and\naccess to online information, and displacement within and outside Myanmar have\ndisproportionately affected the younger generation. Loss of educational and livelihood\nopportunities will have longer-term generational impacts, exacerbating poverty and\ninstability."},{"id":"a-hrc-59-57-p0023","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"23","seq":25,"section":"IV. Constituencies for change","text":"Meanwhile, youth have played key roles such as establishing alert and reporting\nnetworks for protection, contributing to humanitarian efforts, supporting communities in\nresisting unlawful evictions and addressing the adverse environmental effects of mining\nactivities. Youth have also contributed to the formation and development of local governance\nstructures, including by providing financial support and expertise from abroad. This\ngeneration is shaping a new political vision for Myanmar by overcoming racial barriers,\nchallenging norms of gender identity and empowering one another through advocacy and\npolitical participation. As to the future of Myanmar, youth remain the country’s single most\nprecious resource and every effort must be made to sustain and harness their energy and\nsecure their life opportunities.\n3.        Civil society organizations and grass-roots networks"},{"id":"a-hrc-59-57-p0024","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"24","seq":26,"section":"IV. Constituencies for change","text":"Notwithstanding limited resources, crippling financial cuts, challenges in receiving\nfunds and the direct dangers posed by the military, local organizations and community-led\ninitiatives have contributed massively to strengthening resilience and saving lives by taking\naction to effectively meet the humanitarian, health, education, food, hygiene and shelter\nneeds of the violence-affected population, including in the aftermath of natural disasters such\nas the recent earthquake. As highlighted in a previous report, persons with disabilities and\norganizations working to protect their rights, including in relation to mental health, will\ncontinue to have vital roles to address the massive needs caused by military violence. 21"},{"id":"a-hrc-59-57-p0025","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"25","seq":27,"section":"IV. Constituencies for change","text":"Civil society organizations have also continued to play an essential role in building\ntrust among communities and promoting social cohesion, including by undertaking\nadvocacy, documenting and reporting on human rights violations and abuses and countering\ndisinformation and military propaganda. They have also assumed the role of intermediary\nbetween international actors and local communities and have been instrumental in grounding\nemerging governance systems in human rights. Civil society voices, from those at the grass-\nroots level to the policymakers, must therefore be heard and included in decision-making\nwhile rebuilding Myanmar.\n4.        Pro-democracy actors"},{"id":"a-hrc-59-57-p0026","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"26","seq":28,"section":"IV. Constituencies for change","text":"Resolute rejection of military rule was clearly expressed by civil servants from across\npublic institutions who resigned en masse to join the civil disobedience movement.\nSacrificing their jobs, homes and life security, many protested against the military seizure of\npower and are now helping to organize alternative governance mechanisms. Persons with\nspecialized skills, including doctors, lawyers, teachers and engineers, have applied their\nknowledge and expertise in areas outside military control. Trade unionists have been forced\nunderground but have continued their advocacy and support for workers in Myanmar and\nhave maintained links with international trade union networks."},{"id":"a-hrc-59-57-p0027","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"27","seq":29,"section":"IV. Constituencies for change","text":"The Federal Democratic Charter, proclaimed in March 2021, 22 has provided a\ncommon framework for the democratic movement and created the basis for institutions such\nas the National Unity Government and the National Unity Consultative Council. The Council\nis a positive example of cooperation between civilian and military actors towards the\ndevelopment of democratic institutions, even if additional efforts are needed to ensure the\neffective representation and participation of diverse communities.\n5.         Media"},{"id":"a-hrc-59-57-p0028","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"28","seq":30,"section":"IV. Constituencies for change","text":"Without the courageous work of those endeavouring to shine a spotlight on the\nsituation inside Myanmar, the crisis could have been forgotten. These people include human\nrights defenders, documenters, journalists, photographers, social media professionals, editors\nand all media workers. Since the coup, 15 media outlets have had their licences suspended,23\n221 media workers have been arrested, of whom at least 48 remain languishing in detention, 24\nand many journalists, including women and professionals from ethnic communities, have\nbeen forced to relocate abroad. At great personal risk, and notwithstanding restrictions,\nInternet shutdowns and surveillance, the media in Myanmar have continued to provide\ncommunities with life-saving information, including during natural disasters. The reporting\nby independent media on violations and abuses committed by all parties has laid the basis for\nfuture accountability."},{"id":"a-hrc-59-57-p0029","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"29","seq":31,"section":"IV. Constituencies for change","text":"During the process of shaping post-crisis Myanmar, a robust civic space with\nindependent media will be of primary importance to democracy, transparency and\naccountability at all levels. Contributions by the media will be essential both to overcome\nnarratives that have been imposed by the military and that foster ethnic and religious\ndivisions, discord and discrimination, and to promote rights, equality and inclusion. Strong\nindependent media will strengthen democracy and justice, promote reconciliation and play\nan important role in healing society from decades of disinformation spread by the military."},{"id":"a-hrc-59-57-p0030","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"30","seq":32,"section":"V. Pathways to change","text":"In the following section, ideas and recommendations gathered through consultations\nconducted by OHCHR on key pathways to fulfil the aspirations of the people of Myanmar\nare summarized under four broad pathways: accountability, good governance, sustainable\ndevelopment, and international and regional action.\n1.         Accountability"},{"id":"a-hrc-59-57-p0031","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"31","seq":33,"section":"V. Pathways to change","text":"Having suffered decades of military violations, interlocutors resoundingly centred\ntheir vision for the future democratic transformation of Myanmar around accountability and\njustice. Given that impunity has been a defining feature of military rule, interlocutors\nunanimously underscored the fact that peace requires accountability and reconciliation.\nFreeing all political prisoners, including Aung San Suu Kyi, was consistently indicated as\nnecessary. Interlocutors adamantly stressed that perpetrators from all sides must be brought\nto justice and emphasized the importance of criminal accountability, whether through\ndomestic, international or hybrid legal systems. Examples of progress at the international\nlevel include an application for an arrest warrant in November 2024 by the Prosecutor of the\nInternational Criminal Court,25 which, at the time of writing, was pending before the Pre-Trial\nChamber, and the conclusion of written proceedings in the contentious case before the\nInternational Court of Justice between the Gambia and Myanmar. Furthermore, a court in\n22 See https://mofua.nugmyanmar.org/uploads/publications/WmSsxrT486Vd6jGq2o6CJ7XzUL7mAX\np32rGrAGoq.pdf.\n23 See www.bnionline.net/en/news/myanmars-internet-freedom-and-press-freedom-worsen.\n24 See http://www.icnl.org/wp-content/uploads/Myanmar-journalists-report-updated-April-2025.pdf.\n25 See www.icc-cpi.int/bangladesh-myanmar.\nArgentina 26 issued arrest warrants under the principle of universal jurisdiction. Many\ninterlocutors called for broader and more incisive efforts, including the referral of the entire\nsituation in Myanmar to the International Criminal Court."},{"id":"a-hrc-59-57-p0032","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"32","seq":34,"section":"V. Pathways to change","text":"Interlocutors highlighted the fact that human rights defenders, anti-military armed\ngroups and pro-democratic actors are already seeking knowledge and further resources to lay\nthe foundation for transitional justice initiatives. While the development of comprehensive\ntransitional justice processes may require time, it is clear that there is a rising level of\nopenness within society in Myanmar to truth-telling, the recognition of crimes, including past\nviolations against ethnic groups such as the Rohingya, Rakhine, Kachin, Chin and Karen,\nand the development of new narratives free of ethnic chauvinism. Interlocutors also\nemphasized the compelling needs for reparation, return to places of origin, respect for cultural\nrights, including minority language rights, and an end to discrimination as central guarantees\nof non-recurrence. These processes will need to be owned and led by the people of Myanmar\nand ensure full inclusion of victims and all communities."},{"id":"a-hrc-59-57-p0033","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"33","seq":35,"section":"V. Pathways to change","text":"Former political prisoners emphasized the role of the judiciary in human rights\nviolations, with judges systematically failing to exercise independent authority, sentencing\nindividuals without evidence and imprisoning tens of thousands of innocent civilians on\npolitical grounds. During consultations, lawyers unanimously denounced the judicial system\nas having become entirely subsumed by the military, where defence counsel have to work\nunder the constant fear of being arrested and in the absence of any fair trial guarantees.\nTherefore, following the end of the crisis, it will be paramount to ensure the reconstitution of\na judiciary based on the principles of human rights and rule of law.27 Pathways to judicial\nindependence will require cultural and institutional changes, including new laws, full vetting\nof judicial actors, the recruitment of new professionals, representation of diversity and the\nintroduction of procedures to ensure the fair administration of justice in accordance with\ninternational standards."},{"id":"a-hrc-59-57-p0034","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"34","seq":36,"section":"V. Pathways to change","text":"While the National Unity Government has taken steps towards accountability,\nincluding establishing a complaints mechanism for human rights violations committed by its\ncombatants and administrators, OHCHR regularly received calls for enhanced efforts\ntowards transparency across all sectors and levels of government. Interlocutors shared\nconcerns related to the collection and distribution of revenue, status of court proceedings and\ncomplaints of human rights violations, sexual and gender-based violence and decision-\nmaking on political appointments. Anti-military armed groups have also been responsible for\nabuses, including forced recruitment, arrests, killings, extortion, gender-based violence and\nthe imposition of limitations on the rights of other minority communities, including freedom\nof movement.28 As duty bearers, they must fully uphold their human rights obligations and\ntheir actions must be focused on supporting civilian institutions in enhancing protection of\ncivilians and meeting the essential needs of the population in their areas of control.\n2.        Good governance"},{"id":"a-hrc-59-57-p0035","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"35","seq":37,"section":"V. Pathways to change","text":"Interlocutors across all demographics highlighted the continued aspiration of the\npeople of Myanmar for a civilian-led federal democratic society based on strong local\ninstitutions with representatives elected in free and fair electoral processes. These institutions\nshould be transparent and based on inclusiveness and respect for diversity, equality and\nhuman rights. Interlocutors emphasized that this would require a profound transformation in\nState structures, with some calling for the complete dismantling of the current system and the\nestablishment of a fully civilian government with no decision-making roles for the military\nor armed actors."},{"id":"a-hrc-59-57-p0036","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"36","seq":38,"section":"V. Pathways to change","text":"Broad and meaningful public consultations that inform the drafting processes of a\nfederal constitution, as well as state and regional constitutions granting local autonomy and\nrights, are, in general, considered as foundational steps towards democratic progress. Legal\nprofessionals also stressed the need for comprehensive legislative review processes to\nenhance compliance with human rights obligations, in particular by removing the\ndecades-long discriminatory approaches based on race, religion and sex, including the 1982\nCitizenship Law, which had a detrimental impact on the Rohingya and other minority\ncommunities. They highlighted the need to end the practice of instrumentalizing laws - for\nexample, laws on defamation - to silence dissenting opinions."},{"id":"a-hrc-59-57-p0037","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"37","seq":39,"section":"V. Pathways to change","text":"All interlocutors stressed that any future governance system must promote and protect\ncivic space and fundamental freedoms as essential components for accountability and\ndemocracy. Media, human rights groups, women’s groups, student unions and strike\ncommittees are some of the actors that are essential to hold duty bearers, including armed\ngroups, accountable. Interlocutors stressed the importance of peaceful protests in holding\nduty bearers to account, including in relation to environmental protection and natural\nresources management."},{"id":"a-hrc-59-57-p0038","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"38","seq":40,"section":"V. Pathways to change","text":"Many of those consulted identified the long-standing top-down and centralized system\nof governance as a decisive factor that has contributed to instability. Therefore, many\nfavoured a bottom-up approach with an emphasis on decentralization and local autonomy.\nAlthough some interlocutors expressed concerns that this could result in further\nfragmentation and even violence, others recognized that the realization of democratic\naspirations would require time, significant international assistance and adaptability. By way\nof example, they stressed that the ethnic states in Myanmar had a long history of political\norganization and, over decades of responding to the needs of their communities arising from\nthe military’s violence and repression, had developed important capacities for governance."},{"id":"a-hrc-59-57-p0039","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"39","seq":41,"section":"V. Pathways to change","text":"The following examples highlight some of the emerging forms of governance at the\nlocal level, which represent promising possibilities for the future. Some are highly\ndecentralized and emphasize community governance, while others prioritize stronger\nhierarchies with more centralized decision-making. In general, they are focussed on basic\nservice delivery, including education and healthcare, with some introducing multilingual\nlearning, ethnic-based curricula and health services improvements. Some have set up legal\nsystems and specialized institutions, such as the judiciary and the police, while others have\npromoted localized economic activities, such as trade and agriculture."},{"id":"a-hrc-59-57-p0040","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"40","seq":42,"section":"V. Pathways to change","text":"In some areas under its control, the National Unity Government reported having\nestablished administrative structures focused on law enforcement, justice, education and\nhealthcare, thereby emphasizing a firm commitment to the principles of inclusiveness and\ntransparency. Courts reportedly functioned under civilian control, processing 788 criminal\nand 350 civil cases in 2024. In the health sector, 106 hospitals, 808 fixed clinics and 192\nmobile clinics were reported as operational in 2024, offering emergency and long-term\ntreatments. Basic education is reportedly offered to more than 800,000 students in 5,700\nschools employing more than 62,000 teachers. In the higher education sector, degree courses\nare being offered under 198 interim university councils. However, consultations with\nstudents and researchers revealed that, at the time of writing, educational certifications issued\nby the National Unity Government were often not recognized abroad, limiting graduates’\nopportunities for further learning and employment."},{"id":"a-hrc-59-57-p0041","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"41","seq":43,"section":"V. Pathways to change","text":"As previously reported,29 the Karenni State Interim Executive Council has developed\na collective leadership model by which seven political, military and civilian leaders, of whom\ntwo are women, share executive functions. Governance is divided into 10 departments, each\nled by three or four leaders, with representatives from ethnic armed organizations, civil\nservants, members of parliament and activists. The Council reported that, by reorganizing\nand extending administration to 16 townships, it was able to provide healthcare services\nthrough more than 100 clinics in towns and villages. It also stated that it had local judicial\nsystems with nine courts, ensuring civilian-led justice, and a reformed police service, with\nmore than one dozen police stations committed to democratic policing principles."},{"id":"a-hrc-59-57-p0042","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"42","seq":44,"section":"V. Pathways to change","text":"The Palaung State Liberation Front, the political wing of the Ta’ang National\nLiberation Army, reported that it strived to establish governance and administrative\nstructures in recently acquired territories in Shan and Mandalay. The Front established a\ncentralized administration with 13 departments, including departments of defence, health,\neducation, revenue, the judiciary and economic development. Women and youth were\nreportedly more prominently involved in public administration, with youth comprising 80\nper cent of staff in the education and health sectors being youth and women comprising 40\nper cent. Women accounted for nearly half of the participants in the basic police training\nprogramme, a statistic that shows the progress that can be made towards gender equality in\nthe security sector. The Front organized a judiciary system with 4 district courts and 12\ntownship courts handling criminal, narcotics and civil cases. Since the coup, the Front has\nreportedly sought to expand access to education, increasing the number of schools from 374\nin 2022 to more than 650 by 2024 and with plans to further increase the number of schools\nto 700. However, concerns were shared about the fact that education in the Ta’ang language\nis the only available option."},{"id":"a-hrc-59-57-p0043","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"43","seq":45,"section":"V. Pathways to change","text":"In Chin, the Chinland Council established a highly decentralized structure of 18 local\ngovernments across 900 villages that are based on localized decision-making involving\nwomen, youth and ethnic communities. These local governments reportedly deal with matters\nrelating to education, health, the judiciary, law enforcement and economic development and\napply laws on taxation, civil society and the judiciary. In line with their strategic education\nplan, education is reportedly being delivered to more than 60,000 students in more than 600\nschools that are employing 4,000 teachers, and there are plans to open the Chin National\nUniversity in 2025. In relation to healthcare, the Council aims to achieve universal health\ncoverage by operating 18 hospitals, more than 50 primary health centres and 12 mobile\nmedical teams providing services in remote areas."},{"id":"a-hrc-59-57-p0044","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"44","seq":46,"section":"V. Pathways to change","text":"In Mon, the New Mon State Party has organized local structures into three main\ndepartments – political, administrative and military – that cover 3 districts and 11 townships\nand exercise direct governance over special administrative regions. Judicial structures grew\nfrom community-based mechanisms to address disputes and handle local civil and criminal\ncases. Significant progress was reported in education, healthcare and the administration of\njustice. A total of 143 Mon national schools serve more than 14,000 students and employ\nmore than 900 teachers, while seeking to provide multilingual education in Mon, Burmese\nand English. Interlocutors identified challenges faced by students studying at, and graduates\nwith degrees from, non-accredited schools and universities. Healthcare coverage was\nreportedly provided to more than 118,000 people across 157 villages, with doctors, nurses\nand field supervisors delivering primary healthcare, vaccinations and maternal health\nservices."},{"id":"a-hrc-59-57-p0045","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"45","seq":47,"section":"V. Pathways to change","text":"Economic instability, lack of investment in strengthening and repairing infrastructure\nand limited taxation capacities were identified during consultations as additional barriers to\nthe sustainable provision of public services and to economic and social development. In many\ncases, the structures that provide those services and foster that development are affiliated\nwith or dependent on non-State armed groups that have also committed human rights abuses,\nincluding forced recruitment and extortion, or are sometimes involved in illicit economies or\nresource extraction. It will therefore be important to ensure that such structures are civilian\nin nature and entirely separate from any armed groups controlling the territory in which the\nstructures have been established, and to ensure that those groups are held accountable for\ntheir human rights obligations.\n3.     Sustainable development"},{"id":"a-hrc-59-57-p0046","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"46","seq":48,"section":"V. Pathways to change","text":"The military’s decades-long domination and exploitation of the economy and natural\nresources of Myanmar have concentrated wealth in a very small segment of the population,\nnamely, the military and its patronage networks. This domination has been exerted through\nthe control of national institutions, the expropriation of land and natural resources and the\nentrenchment of corruption and cronyism favouring military-affiliated business networks.\nIngrained societal, legal and economic discrimination against religious and ethnic\ncommunities limited their economic opportunities. Since the coup, the military has prioritized\na war economy structured around the extraction, production and allocation of resources to\nsupport military efforts over infrastructural and economic development."},{"id":"a-hrc-59-57-p0047","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"47","seq":49,"section":"V. Pathways to change","text":"Interlocutors stressed that pathways to democracy will require a radical departure\nfrom this predatory form of economy towards a people-centred approach based on policies\naligned with human rights obligations and prioritizing equality, social justice and sustainable\ndevelopment. This would require investment in infrastructure, education, health and social\nprotection and the development of sustainable and inclusive policies on the administration of\nland and natural resources."},{"id":"a-hrc-59-57-p0048","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"48","seq":50,"section":"V. Pathways to change","text":"Priority should be given to ending the military’s economic dominance. Lifting the\nfiscal burden of military spending, ensuring parliamentary oversight, dismantling\nmilitary-controlled businesses and banks, ending all forms of forced conscription and labour\nand enacting legislation preventing the military from re-engaging in business activities are\nsome of the measures necessary to reorient the current war economy towards peaceful and\nsustainable economic development. Experts argued that the nationalization of\nmilitary-controlled conglomerates is essential and that military-owned assets abroad could\nbe used to fund reconstruction and development. Setting up independent anti-corruption and\npublic finance transparency bodies would contribute to ending decades of malpractice."},{"id":"a-hrc-59-57-p0049","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"49","seq":51,"section":"V. Pathways to change","text":"This economic transformation will require multilayered and multisectoral\ninterventions. In reforming the banking and financial sectors, the current system will need to\nbe restructured and recapitalized to restore public trust and ensure financial stability. Such\nmeasures would include restoring consumers’ full access to their own bank accounts,\nreplacing fixed foreign exchange rates with a floating rate and lifting import restrictions.\nBudgetary decision-making should be overseen by a civilian parliament and based on\nconsistent fiscal rules that guarantee debt sustainability. A comprehensive tax reform should\nbe broad-based, simple and transparent, while avoiding regressive taxes, including on food\nand fuel, that burden the most disadvantaged. In a future context free of widespread\nsurveillance, digital financial services should also be strengthened to increase access to the\nformal banking system, transparency and accountability."},{"id":"a-hrc-59-57-p0050","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"50","seq":52,"section":"V. Pathways to change","text":"Respondents stated that just and transparent economic regulation is equally important\nin areas currently governed by non-State actors, underlining the critical importance of\nreforming taxation and natural resources management at all levels. While new duty bearers\nare developing and implementing taxation policies, interlocutors emphasized that a lack of\nconsistent practice was allowing for the arbitrary imposition of fees and discriminatory\napproaches against the most vulnerable. The nexus between non-State armed groups and the\nillicit and extractive economy will need to be brought to an end."},{"id":"a-hrc-59-57-p0051","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"51","seq":53,"section":"V. Pathways to change","text":"Private international investors and businesses will also play a critical role in\nrecovering from the current economic crisis. When conditions allow, investment, job\ncreation, fair wages and respect for workers’ rights will all support democracy and help the\neconomy to flourish. By encouraging an environment where the Guiding Principles on\nBusiness and Human Rights 30 are respected, the private sector can help to transform\nMyanmar. In the short term, international businesses and investors must apply heightened\ndue diligence in any transactions with Myanmar. Unionists expressed concerns about the\npossibility that foreign businesses that have continued to operate in Myanmar, in the absence\nof any rule of law or respect for workers’ rights, could inadvertently enable labour\nexploitation. Experts stressed that foreign investment should be contingent on the respect and\nprotection of labour rights and the ability of unions to operate freely, including setting\nminimum wages commensurate with dignified living conditions and adopting\nanti-discrimination policies to protect workers who are women and workers from minority\ncommunities."},{"id":"a-hrc-59-57-p0052","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"52","seq":54,"section":"V. Pathways to change","text":"Interlocutors also stressed the importance of enhancing environmental governance,\nincluding the sustainable management of natural resources. Adopting policies and measures\nthat promote green energy, climate-resilient agriculture and disaster-resilient infrastructure\nto prevent and mitigate the negative impact of natural disasters could also produce sustainable\nresults for future generations.\n30   See www.ohchr.org/en/publications/reference-publications/guiding-principles-business-and-human-\nrights.\n4.        Actions by international and regional stakeholders"},{"id":"a-hrc-59-57-p0053","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"53","seq":55,"section":"V. Pathways to change","text":"During OHCHR consultations, there was a consistent expression of appreciation for\naction taken by the international community, including the imposition of targeted sanctions\non individuals, the non-recognition of military representation in international and regional\nforums, calls for the referral of the situation to international accountability mechanisms, and\nthe provision of humanitarian support. However, the expectations of the people of Myanmar\nare much higher. People felt that the support they had received to sustain their democratic\naspirations had not been commensurate with their sacrifices in the face of brutality. Owing\nto perceptions of inactivity, appeasement of the military and failure to substantiate statements\nwith action, trust in the United Nations and ASEAN is low. However, their support is still\nconsidered vital to realizing the future goals of the people of Myanmar."},{"id":"a-hrc-59-57-p0054","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"54","seq":56,"section":"V. Pathways to change","text":"A global arms embargo, including on jet fuel, drones and dual-use equipment, to\nhinder the military’s reliance on air power and improve civilian protection, is an urgent\npriority. The reliance of the military on aerial weaponry and its use of drones and paramotors\nhave steadily risen over the years, leading to a near doubling of civilians killed by air strikes\nin 2024 compared with 2023,31 underscoring the need to continually update controls on the\ntransfer of such equipment. Sanctions should also apply to the military-controlled central\nbank to curtail the ability of financial institutions to make and receive international payments.\nAt the same time, fledgling financial institutions created by pro-democracy actors should be\nexempted from international sanctions and assistance provided for their institutional\ndevelopment and regulation.32"},{"id":"a-hrc-59-57-p0055","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"55","seq":57,"section":"V. Pathways to change","text":"There is also a need to enhance international engagement and cooperation with the\nNational Unity Government, ethnic armed organizations and other democratic actors.\nChallenges and divergent interests will continue to characterize the situation in Myanmar,\nwhich requires thinking beyond the traditional State/non-State binary and applying flexible,\ncreative and adaptive approaches. Alternatives to military governance emerging in areas\noutside military control, some of which have been identified in the present report, should be\nencouraged and supported. Efforts by civil society organizations to assist the civilian\npopulation should be acknowledged and provided with strong support to ensure that their\ndemocratic voices continue to shape the country. Small but tangible steps, such as removing\nthe mandatory registration requirement for organizations in Myanmar to apply for funding\nopportunities or adapting to the use of traditional money transfer mechanisms, can result in\nlife-saving impacts. The provision of core and long-term funding with flexible reporting\nrequirements can also produce significant impacts."},{"id":"a-hrc-59-57-p0056","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"56","seq":58,"section":"V. Pathways to change","text":"Violence, persecution and risks of forced recruitment have caused tens of thousands\nof people – in addition to more than 1 million Rohingya refugees already in Bangladesh – to\nflee the country and seek protection abroad, mostly within the region. However, interlocutors\nnearly unanimously indicated their intention to return home once it was safe to do so in order\nto contribute to the establishment of a just and democratic society. At the time of writing,\nmany individuals were unable to return to Myanmar or apply for personal documentation in\nmilitary-controlled embassies owing to security concerns for themselves and for relatives still\nliving in Myanmar. Repatriations can lead to violations of the non-refoulement principle\nbecause individuals are at risk of irreparable harm. 33 A practical way to support these\nindividuals is to provide valid long-term legal status under which they can gain access to\nhealthcare, education and employment. Ensuring protection and humanitarian assistance to\nindividuals seeking refuge abroad and preventing pushback and refoulement are also crucial."},{"id":"a-hrc-59-57-p0057","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"57","seq":59,"section":"V. Pathways to change","text":"This particularly applies to Rohingya refugees, for whom the preconditions of safety,\ncitizenship and rights necessary for any sustainable return do not exist. Owing to deepening\nfood insecurity in Rakhine State and the drastic cuts to humanitarian aid in Bangladesh, it is\nimperative that support be maintained and increased. ASEAN and international stakeholders\nshould explore options for cross-border assistance to alleviate the suffering of the Rohingya.\nThe forthcoming international conference on the situation of Rohingya Muslims and other\nminorities in Myanmar, in the form of a high-level plenary meeting of the General Assembly,\nshould focus on new strategies to achieve comprehensive and durable solutions for the\nRohingya community, both inside and outside the country.34"},{"id":"a-hrc-59-57-p0058","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"58","seq":60,"section":"V. Pathways to change","text":"In the longer term, the international community can also provide technical assistance\nfor institutional and legal reforms, as well as critical support for transitional justice,\nreconciliation and social cohesion processes. Under regional leadership, such support will be\nessential to a Myanmar-led political transition and institutional transformation."},{"id":"a-hrc-59-57-p0059","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"59","seq":61,"section":"VI. Conclusions and recommendations","text":"The extensive consultations conducted for the present report support a\nresounding conclusion: the people of Myanmar have sacrificed their lives, their\nlivelihoods and, in many respects, their futures in the name of rejecting the power grab\nby the military in 2021 and are demanding a new future. In the face of years of suffering\nand abuse, the vast majority of people have remained united in their defiance of military\nauthoritarianism and violence. Once again, at a level not seen in previous decades of\nmilitary rule, they are demanding genuine and inclusive democracy, civilian oversight\nover the military and civilian control over the country, an end to discrimination,\nfederalism and autonomy at the local level and a people-centred and sustainable\neconomy. Since 2021, those voices have only grown louder, given that the military coup\nhas cemented the desire for a profound and irreversible change grounded in\naccountability, human rights, inclusion and non-discrimination and the rule of law.\nDismantling military-controlled institutions and economic structures is a necessary\nprecondition for bringing about and sustaining such a change. The fact that local\nadministrations are emerging across the country demonstrates that the people are\nalready invested in and committed to a bottom-up form of governance and the\npossibilities of decentralization and participatory decision-making."},{"id":"a-hrc-59-57-p0060","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"60","seq":62,"section":"VI. Conclusions and recommendations","text":"The people of Myanmar recognize justice and accountability for past and\nongoing human rights violations and abuses by all parties as central to the country’s\ndemocratic transformation. There is a growing recognition of past human rights\nviolations and abuses, including against the Rohingya and other marginalized\ncommunities. Breaking the entrenched patterns of impunity will be necessary to\nstrengthen the rule of law, establish independent and credible State institutions and\nprevent future crises."},{"id":"a-hrc-59-57-p0061","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"61","seq":63,"section":"VI. Conclusions and recommendations","text":"The people of Myanmar call for a more effective and decisive approach by the\ninternational community, including through targeted sanctions against members of the\nmilitary and military-controlled entities and political engagement with democratic\nforces and emerging governance structures. They call upon the international\ncommunity to address the country’s immediate humanitarian needs and support those\nworking for long-term systemic reforms through Myanmar-led processes to invest in\nthe country’s future."},{"id":"a-hrc-59-57-p0062","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"62","seq":64,"section":"VI. Conclusions and recommendations","text":"In the light of these findings, the High Commissioner reiterates his previous calls\nfor a full referral of the situation in Myanmar to the International Criminal Court by\nthe Security Council and calls upon the military:\n(a)   To respect the demands and the democratic aspirations of the people of\nMyanmar and act to implement, in particular, civilian oversight of the military;\n(b)   To end violence perpetrated against the civilian population, including\nRohingya civilians, and attacks on civilian objects, in line with relevant human rights\nobligations and international humanitarian law and in compliance with Security\nCouncil resolution 2669 (2022) and the provisional measures ordered by the\nInternational Court of Justice;\n34   See General Assembly resolution 79/278.\n(c)     To commit to fundamental security sector reforms to ensure that the post-\ncrisis military will respect human rights;\n(d)    To take all measures necessary, including removing obstacles to free\nmovement and lifting restrictions on the import of goods and supplies, to guarantee that\npeople in need receive and have access to humanitarian aid, both within the country\nand through cross-border assistance."},{"id":"a-hrc-59-57-p0063","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"63","seq":65,"section":"VI. Conclusions and recommendations","text":"The High Commissioner recommends that the National Unity Government and\nethnic armed organizations:\n(a)    Ensure that their governance structures are inclusive, participatory,\ntransparent and non-discriminatory and that they meet the demands of the people for\nequitable sharing of resources;\n(b)    Meticulously document human rights violations and abuses and initiate\nappropriate proceedings with a view to holding perpetrators to account and breaking\nthe cycle of impunity, and impose sanctions to those found responsible commensurate\nwith the violations and abuses committed, providing justice and redress to victims;\n(c)   Proactively involve women, youth and representatives of ethnic\ncommunities in decision-making, including appointing them to leadership roles, in\ngovernance structures that formulate policies and provide services to the public;\n(d)    Maintain efforts to ensure that local governance structures comply with\ninternational human rights law, including through the exchange of information and\nsharing of good practices;\n(e)    Hold frequent and open consultations with local communities, including\nthe Rohingya and other minority groups, to develop a new social contract serving all\nthe people of Myanmar, regardless of their ethnicity or religion, as the basis for a new\nconstitution and political framework;\n(f)    Take urgent steps to remove obstacles to safe, sustainable and dignified\nreturn, in particular in situations of long-term displacement, such as for members of\nthe Rohingya community."},{"id":"a-hrc-59-57-p0064","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"64","seq":66,"section":"VI. Conclusions and recommendations","text":"In addition, the High Commissioner urges ASEAN member States:\n(a)     To demand that the military immediately end violence against civilians,\nrelease all political prisoners and authorize unhindered humanitarian access, including\nthrough the establishment of cross-border operations;\n(b)    To protect the people of Myanmar who are fleeing violence and seeking\nsafety in the region, including by undertaking rescues at sea, granting international\nprotection, providing solutions for long-term legal status and providing access to\nfundamental services, including education, healthcare and employment opportunities;\n(c)     To ensure that procedures for the issuance of personal documents, permits\nto stay, residency documents and work permits are clear, affordable and implemented\nwithout discrimination in order to address the legal and protection concerns of\ndisplaced persons from Myanmar and grant them access to public services and the\nemployment market to enable them to sustain themselves and their families with dignity\nand rights;\n(d)    To take timely and concrete action to allow displaced students from\nMyanmar to have access to educational opportunities abroad and to ensure that\nprofessionals, including medical doctors, teachers, legal professionals and engineers,\nreceive accreditation and permits to continue to work and to assist members of the\nMyanmar community;\n(e)    To engage with the National Unity Government and other relevant\ndemocratic actors, including representatives of emerging local governance structures,\nto support the democratic aspirations of the people of Myanmar and to contribute to\nthe creation of the conditions necessary for sustainable peace, stability and\ndevelopment;\n(f)    To proactively implement ASEAN plans of action on common concerns,\nincluding the ASEAN Plan of Action to Combat Transnational Crimes and the ASEAN\nPlan of Action Against Trafficking in Persons, Especially Women and Children, to\nstrengthen compliance with human rights, promote accountability and prevent a\nrecurrence of crimes."},{"id":"a-hrc-59-57-p0065","rec_id":"recZB0W4o0x2Jd8kl","symbol":"A/HRC/59/57","n":"65","seq":67,"section":"VI. Conclusions and recommendations","text":"Furthermore, the High Commissioner urges Member States and the United\nNations system:\n(a)   To support the democratic aspirations of the people of Myanmar by\nexerting pressure to ensure that the military respects and implements Security Council\nresolution 2669 (2022) and the relevant General Assembly and Human Rights Council\nresolutions;\n(b)   To ensure the protection of civilians fleeing violence in Myanmar and\nseeking safety abroad by granting international protection, providing solutions for\nlong-term legal status and ensuring access to fundamental services, including education,\nhealthcare and employment opportunities;\n(c)    To take timely and concrete action to support youth from Myanmar in\ncontributing to the future democratic development of their country by providing\ndisplaced youth with access to educational opportunities abroad, and displaced\nprofessionals, including medical doctors, teachers, legal professionals and engineers,\nwith the accreditation and permits necessary to continue to work and to assist members\nof the Myanmar community;\n(d)   To engage with new duty bearers and democratic actors, including the\nNational Unity Government, as an essential part of advancing democracy and\ncontributing to the creation and development of conditions for sustainable peace,\nstability and development;\n(e)   To consult with civil society organizations to understand the technical,\nfinancial, humanitarian and protection needs of the civilian population and to co-design\nand implement programmes that effectively address their needs;\n(f)   To plan for future support necessary to sustain the institutional\ntransformation of Myanmar into a democracy, including the provision of expert\nassistance on processes such as local governance, transitional justice and institution-\nbuilding;\n(g)   To provide critical food and non-food assistance to members of the\nRohingya community in Myanmar and in Bangladesh to ensure their survival and\nprotection;\n(h)    To increase efforts to identify sustainable solutions for members of the\nRohingya community, including resettlement to third countries, while working with\ndemocratic actors to create the conditions necessary for voluntary return to Myanmar\nin safety and dignity, with rights and citizenship and on the basis of a free and informed\nchoice;\n(i)    To ensure that the Human Rights Council and other relevant\ninternational bodies and mechanisms remain seized of developments in Myanmar and\nregularly monitor the implementation of the present recommendations."},{"id":"a-hrc-60-18-u0000","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/60/18\nGeneral Assembly                                                          Distr.: General\n14 July 2025","unnumbered":true},{"id":"a-hrc-60-18-u0001","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":null,"seq":1,"section":null,"text":"Summary\nThe present document is the seventh report submitted by the Independent\nInvestigative Mechanism for Myanmar to the Human Rights Council pursuant to Council\nresolution 39/2 of 27 September 2018. It covers the activities carried out by the Mechanism\nbetween 1 July 2024 and 30 June 2025, highlighting progress made on investigations,\nchallenges, and areas for additional support.\nOver the past year, the Mechanism continued to uncover evidence of an escalating\nnumber of war crimes and crimes against humanity committed across Myanmar by multiple\nparties. The Mechanism is examining evidence of alleged crimes, regardless of the affiliation\nor ethnicity of the perpetrators or victims, with new lines of enquiry opened in Rakhine State.\nThe Mechanism made important progress in its investigations into crimes committed\nsince the February 2021 military coup, including aerial attacks resulting in civilian deaths;\nkillings of civilians and detained combatants; and torture, including sexual violence against\npersons in detention. The Mechanism has collected evidence of the identity of perpetrators\nof crimes committed in detention facilities and of individuals in the security forces of\nMyanmar, affiliated militias and opposition armed groups who have perpetrated summary\nexecutions.\nInvestigations into the 2016 and 2017 clearance operations against the Rohingya\nadvanced significantly in the past year. The Mechanism is now prioritizing witnesses who\ncan provide evidence directly linking crimes to specific perpetrators. It is also focusing its\ninvestigations on Rohingya villages where properties were destroyed, community members\nwere forcibly displaced and land was subsequently appropriated by the authorities of\nMyanmar and replaced with security bases and State infrastructure.\nDuring the reporting period, the Mechanism shared over 37 evidence and analytical\npackages concerning crimes committed against the Rohingya, comprised of more than\n24,000 information items and supporting analysis, with the International Court of Justice, the\nInternational Criminal Court and Federal Prosecutor’s Office No. 9 in Argentina. The\nMechanism is now also sharing evidence with a new jurisdiction – the United Kingdom of\nGreat Britain and Northern Ireland – which is investigating crimes against the Rohingya, and\ncrimes committed after the military coup.","unnumbered":true},{"id":"a-hrc-60-18-u0002","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":null,"seq":2,"section":null,"text":"Notable progress has been made in the ongoing proceedings during this period. The\nProsecutor of the International Criminal Court filed a request with the Court for an arrest\nwarrant for Min Aung Hlaing, Commander-in-Chief of the Myanmar military, and the\nFederal Criminal Court of Argentina ordered the issuance of arrest warrants summoning Min\nAung Hlaing and 24 other individuals to appear before the Court. This underscores the\nimportance of the Mechanism’s work in collecting and preserving forensically valuable\nevidence that can be used to hold perpetrators responsible.","unnumbered":true},{"id":"a-hrc-60-18-p0001","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"1","seq":3,"section":"I. Introduction","text":"The present report covers the activities carried out by the Independent Investigative\nMechanism for Myanmar between 1 July 2024 and 30 June 2025."},{"id":"a-hrc-60-18-p0002","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"2","seq":4,"section":"I. Introduction","text":"The Human Rights Council, in its resolution 39/2, created the Mechanism and\nmandated it to carry out two primary functions: to collect, consolidate, preserve and analyse\nevidence of the most serious international crimes and violations of international law\ncommitted in Myanmar since 2011; and to prepare files to facilitate and expedite fair and\nindependent criminal proceedings in national, regional or international courts or tribunals\nthat have or may in the future have jurisdiction over these crimes. In its resolution 73/264,\nthe General Assembly welcomed the establishment of the Mechanism. Subsequently, in its\nresolution 43/26, the Council specifically called upon the Mechanism to engage in close and\ntimely cooperation on any future investigations, including those conducted by the\nInternational Criminal Court and the International Court of Justice."},{"id":"a-hrc-60-18-p0003","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"3","seq":5,"section":"I. Introduction","text":"Over the past year, civilians continued to suffer atrocities, as the conflict between the\narmed forces of Myanmar and various armed organizations showed no signs of abating. The\nMechanism collected evidence of war crimes and crimes against humanity committed with\nincreasing frequency and intensity by multiple parties to the ongoing conflicts. In all cases,\nthe Mechanism is working to identify those most responsible, regardless of their political\naffiliation, beliefs or ethnicity."},{"id":"a-hrc-60-18-p0004","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"4","seq":6,"section":"I. Introduction","text":"During the reporting period, the systematic and escalating use of air strikes by the\nMyanmar military across the country caused widespread death, destruction and displacement,\nand has terrorized communities. As the military continues to lose territory to opposing\ngroups, it frequently bombs lost territories from the air, causing increased casualties among\nnon-combatants. Women, children and elderly people have been particularly vulnerable to\nthe devastating impact of air strikes. Within days of the deadly earthquake of 28 March 2025,\nat a time of heightened humanitarian crisis, the Myanmar military unleashed air strikes\nagainst civilian villages in Mandalay, Sagaing and other regions."},{"id":"a-hrc-60-18-p0005","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"5","seq":7,"section":"I. Introduction","text":"In Rakhine State, ongoing fighting between the military and the Arakan Army has\naffected thousands of civilians. There are credible reports of widespread malnutrition,\nparticularly among young children of all ethnicities. During the reporting period, the Arakan\nArmy seized control of nearly all townships in Rakhine, leaving only the capital Sittwe and\nparts of the southern region under military control. The Mechanism is actively investigating\nreports of killings, torture, rape and the burning of villages. While all ethnic communities in\nRakhine State have endured extreme hardship, the remaining Rohingya population finds\nitself in an especially vulnerable position, caught between the Myanmar military and the\nArakan Army."},{"id":"a-hrc-60-18-p0006","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"6","seq":8,"section":"I. Introduction","text":"In parallel to its increased investigative activities, the Mechanism has shared vast\namounts of evidence and analysis to support three ongoing justice processes related to crimes\ncommitted against the Rohingya population, which are being conducted by the International\nCourt of Justice, the International Criminal Court and Federal Prosecutor’s Office No. 9 in\nArgentina. In November 2024, the Prosecutor of the International Criminal Court announced\nthat he had requested an arrest warrant for Senior General Min Aung Hlaing,\nCommander-in-Chief of the Myanmar military, for the crimes against humanity of\ndeportation and persecution of Rohingya. The Prosecutor stated that he intended to file\nrequests for additional arrest warrants. In February 2025, the Federal Criminal Court of\nArgentina ordered the issuance of arrest warrants summoning Min Aung Hlaing and 24 other\nindividuals to appear before the Court to provide testimony relevant to the ongoing\ninvestigation by Argentinian authorities. These recent developments send a strong message\nto perpetrators that no one stands above the law."},{"id":"a-hrc-60-18-p0007","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"7","seq":9,"section":"II. Progress on investigations and facilitating proceedings","text":"Over the past year, the Mechanism continued to actively monitor the ongoing situation\nthroughout Myanmar and to collect and analyse evidence of alleged serious international\ncrimes committed by the armed forces of Myanmar as well as various armed groups. Since\nit became operational, the Mechanism has maintained two distinct investigative teams: one\ndedicated to crimes against the Rohingya population (both historical and ongoing crimes)\nand another focused on examining crimes committed against other groups, including those\ncommitted since the military coup in 2021."},{"id":"a-hrc-60-18-p0008","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"8","seq":10,"section":"A. Investigating post-coup crimes","text":"Since the military coup in February 2021, the Mechanism has collected and analysed\nsubstantial evidence of serious international crimes committed across the country. During the\nreporting period, the number of such crimes escalated significantly. The Mechanism has been\ncollecting new reports of the imprisonment of thousands of individuals without fundamental\ndue process; indiscriminate air strikes; civilian deaths in artillery and drone attacks; the\nburning or destruction of homes, hospitals, schools and places of worship; and torture and\nabuse committed against those in detention, including sexual violence. These investigations\nhave resulted in various analytical reports establishing and demonstrating the contextual\nelements of crimes against humanity and war crimes, which are available for sharing with\ninvestigative, prosecutorial and judicial authorities.\nCrimes related to ongoing armed conflicts"},{"id":"a-hrc-60-18-p0009","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"9","seq":11,"section":"A. Investigating post-coup crimes","text":"During the reporting period, the Mechanism gathered and examined large quantities\nof evidence of crimes connected to ongoing armed conflicts across Myanmar, including in\nChin, Kachin, Kayah, Kayin, Rakhine and Shan States and in Sagaing and Magway Regions.\nInvestigations into past and new incidents include: (a) indiscriminate or intentional aerial and\nartillery attacks against civilians and/or civilian objects; (b) killings of civilians or combatants\ndetained during operations; and (c) sexual and gender-based crimes."},{"id":"a-hrc-60-18-p0010","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"10","seq":12,"section":"A. Investigating post-coup crimes","text":"More specifically, the Mechanism continued to secure and assess volumes of material\nregarding the escalating use of air strike attacks in various locations throughout the country.\nAs aerial attacks impacting on civilians and civilian objects continued to escalate, the\nMechanism intensified its investigations into those incidents. The Mechanism sought\nevidence of whether the strikes were targeted at military objectives or were primarily or\ndisproportionately targeted at civilians. Among the incidents that the Mechanism has\nexamined are attacks on internally displaced persons’ camps and attacks on schools, religious\nbuildings and health facilities in Kayah State. These incidents have caused large numbers of\ncivilian casualties and significant destruction of civilian infrastructure, without there being\nany apparent military target in the vicinity of the areas attacked. The Mechanism is analysing\nthe composition of the Myanmar Air Force and its chain of command in order to identify the\nperpetrators involved in the air strike attacks. In this context, the Mechanism also continues\nto evaluate information on supply chains for the weapons and equipment used in the air\nstrikes. Moreover, the Mechanism has been examining reports on the alleged use of chemical\nweapons by the Myanmar military."},{"id":"a-hrc-60-18-p0011","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"11","seq":13,"section":"A. Investigating post-coup crimes","text":"The Mechanism has received testimony from civilians in conflict-affected areas, many\nof whom have been displaced several times. They have described the mental terror caused by\nthe sounds of planes, helicopters and drones overhead and the constant fear of being attacked.\nChildren have been particularly traumatized. The Mechanism has gathered credible\ninformation on the increased use of drones and paramotors, in addition to jet fighters and\nhelicopter gunships, to deliver deadly munitions during air strikes against civilians."},{"id":"a-hrc-60-18-p0012","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"12","seq":14,"section":"A. Investigating post-coup crimes","text":"Despite the devastation caused by the earthquake on 28 March 2025, the military\ncontinued to conduct air strikes in the aftermath. The air strikes continued even after the\nmilitary declared a ceasefire to assertedly facilitate rescue and humanitarian relief. The\nMechanism is closely tracking reports of humanitarian aid being blocked or confiscated in\nareas affected by the earthquake. The Mechanism has also assembled credible evidence of\nother instances of humanitarian assistance being blocked, such as in Sittwe in Rakhine State."},{"id":"a-hrc-60-18-p0013","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"13","seq":15,"section":"A. Investigating post-coup crimes","text":"During the reporting period, the volume of evidence detailing killings of civilians or\ncombatants detained during operations increased. The Mechanism obtained evidence of such\nkillings perpetrated by the security forces of Myanmar, affiliated militias and opposition\narmed groups. Credible information indicates that captured soldiers, combatants and civilians\naccused of being informers were summarily executed. Several of these incidents were\nrecorded and disseminated online by perpetrators, demonstrating the perpetrators’ confidence\nthat they would never be held to account for these crimes. The Mechanism collected evidence\non the identity of perpetrators and their superiors and will continue to work to break the\nimpunity of those responsible for such crimes in Myanmar."},{"id":"a-hrc-60-18-p0014","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"14","seq":16,"section":"A. Investigating post-coup crimes","text":"The Mechanism continued to compile and review credible evidence of sexual and\ngender-based crimes against civilians of different ages and genders related to the various\narmed conflicts in Myanmar. This includes evidence of rape (including with objects and gang\nrape), sexual slavery, sexualized torture, sexual mutilation, sexual assault at military\ncheckpoints and forced nudity. However, the Mechanism faces severe challenges in\ncollecting evidence from primary sources. Survivors of sexual and gender-based violence\noften lack adequate support services and frequently suffer from severe psychological trauma,\nand/or cultural and social stigma. Victims’ fear of further harm and distrust in authorities and\nothers often results in delayed reporting and/or underreporting. Despite these difficulties, the\nMechanism has advanced its investigations in identifying persons within military units and\naffiliated militias, as well as People’s Defence Forces and other non-State armed groups, who\nare implicated in the commission of sexual and gender-based crimes."},{"id":"a-hrc-60-18-p0015","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"15","seq":17,"section":"A. Investigating post-coup crimes","text":"During the reporting period, the Mechanism also received reports and collected\neyewitness testimony concerning crimes against or affecting children, an area of investigation\nthat the Mechanism prioritizes. This includes evidence of the enlistment, conscription or use\nin hostilities of children below the age of 15.\nCrimes related to unlawful imprisonment since the military coup in 2021"},{"id":"a-hrc-60-18-p0016","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"16","seq":18,"section":"A. Investigating post-coup crimes","text":"The Mechanism continued to investigate crimes against those who have been detained\nby the military since the coup and the targeting of those perceived as opponents of the military\nregime. The Mechanism has collected significant evidence, including first-hand witness\ntestimony, of systematic torture, killing and other serious abuses during interrogations and in\ndetention facilities operated by the security forces of Myanmar. These include beatings,\nelectric shocks, strangulations, and torture by pulling out fingernails with pliers."},{"id":"a-hrc-60-18-p0017","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"17","seq":19,"section":"A. Investigating post-coup crimes","text":"The Mechanism has made important progress in its analysis of the systematic\ncommission of sexual and gender-based crimes against individuals of different ages and\ngenders in detention settings. Crimes include rape (gang rape and multiple rapes), including\nthrough the insertion of objects into anal and genital openings; sexual slavery; burning of\nsexual body parts with cigarettes or burned objects; sexualized touching or forced full or\npartial nudity; invasive body searches intended to humiliate; the use of sexualized,\nmisogynistic or homophobic slurs, threats of sexual violence, or violence based on gender or\nsexual orientation; and reproductive violence, particularly against women and girls, because\nof inadequate access to menstrual hygiene, to maternal or postnatal healthcare or to nutrition.\nMoreover, the Mechanism has gathered evidence from eyewitnesses indicating that children\n– ranging from 2 to 17 years of age – have been detained, often as proxies for their parents.\nSome of the detained children have been subjected to torture, ill-treatment or sexual and\ngender-based crimes."},{"id":"a-hrc-60-18-p0018","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"18","seq":20,"section":"A. Investigating post-coup crimes","text":"The Mechanism continues to make progress in identifying specific members and units\nof security forces involved in operations at identified detention facilities, including direct\nperpetrators of sexual and gender-based crimes as well as high-level commanders."},{"id":"a-hrc-60-18-p0019","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"19","seq":21,"section":"B. Current situation in Rakhine State","text":"Due to the significant deterioration of the situation in Rakhine State, the Mechanism\nhas opened dedicated lines of inquiry into serious international crimes committed since early\n2024. This includes crimes targeted at Rakhine, Rohingya and other civilian communities\naffected by the armed conflict between the opposing parties."},{"id":"a-hrc-60-18-p0020","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"20","seq":22,"section":"B. Current situation in Rakhine State","text":"The Mechanism is investigating incidents against different civilian communities,\nrelated to: (a) detention, torture and forced transfer of civilians from several villages;\n(b) indiscriminate killing of civilians, including women, children and elderly people;\n(c) restrictions on the entry and exit of civilians and blockades of humanitarian aid and\nessential supplies in Sittwe; and (d) indiscriminate or intentional artillery and aerial attacks\nagainst civilians or civilian objects in Arakan Army-controlled villages across Northern and\nSouthern Rakhine. This also includes an alleged massacre of Rakhine civilians and the\nblocking of humanitarian aid to Rakhine communities affected by the ongoing violence. The\nMechanism has collected credible information that these crimes have been committed by the\nmilitary and/or military-affiliated armed groups."},{"id":"a-hrc-60-18-p0021","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"21","seq":23,"section":"B. Current situation in Rakhine State","text":"The escalating violence has again forced large numbers of displaced Rohingya to flee\nMyanmar and seek refuge in Bangladesh. Despite initial logistical challenges in identifying\nand safely engaging with such individuals, the Mechanism has been able to meet with\nvictims, obtaining critical first-hand evidence of horrific crimes affecting the Rohingya. In\nthis context, the Mechanism has greatly benefited from its close collaboration with national\nand international civil society and documentation organizations, which supported the\ncoordination and collection of evidence from the recently displaced population."},{"id":"a-hrc-60-18-p0022","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"22","seq":24,"section":"B. Current situation in Rakhine State","text":"During the reporting period, the Mechanism initiated investigations into crimes\nallegedly committed by members of the Arakan Army, in military or civilian attire. These\nincluded summary executions, torture and beheadings of military soldiers and civilians\nsuspected of being military informants. In addition, the Mechanism continues to collect\ninformation on sexual violence, including rape, against Chin women."},{"id":"a-hrc-60-18-p0023","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"23","seq":25,"section":"C. Investigating crimes against the Rohingya","text":"During the reporting period, the Mechanism continued its investigations into crimes\nassociated with the 2016 and 2017 clearance operations, which resulted in mass killings,\nwidespread sexual and gender-based violence, large-scale destruction of Rohingya villages\nand the displacement of hundreds of thousands of Rohingya into Bangladesh. Investigations\nhave also continued into the events preceding the clearance operations, including the violence\nof 2012, the subsequent internal displacement of Rohingya communities around Sittwe, and\nthe series of discriminatory and persecutory measures taken against the Rohingya community\nbefore the 2016 and 2017 operations."},{"id":"a-hrc-60-18-p0024","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"24","seq":26,"section":"C. Investigating crimes against the Rohingya","text":"In its investigations, the Mechanism seeks to identify the individuals who are most\nresponsible for the crimes committed against the Rohingya. This includes those who ordered\nthe crimes, those who failed to punish crimes committed by those under their command, those\nwho facilitated the commission of these crimes through material and financial support, and\nthose who actively promoted the hate campaign which fuelled these crimes."},{"id":"a-hrc-60-18-p0025","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"25","seq":27,"section":"C. Investigating crimes against the Rohingya","text":"During the reporting period, the Mechanism continued to interview members of the\nRohingya population who were impacted by the Myanmar military’s clearance operations in\n2016 and 2017, and who are currently living in refugee camps and other locations. These\ninterviews typically canvass the entirety of a survivor’s experience, including information\nand evidence relating to crimes committed prior to the 2016 and 2017 clearance operations\nwhich includes crimes of persecution, forced labour, sexual and gender-based crimes and\ncrimes related to internal forced displacement. Having gathered a substantial volume of\nevidence through its field missions and having reached an advanced stage in incident\ninvestigations, the Mechanism has adopted a more targeted approach to witness identification\nand prioritization. Guided by its case prioritization strategy, the Mechanism is focusing on\nidentifying and interviewing Rohingya witnesses who can provide linkage evidence to\nestablish a link between the actions of specific individuals and the crimes committed. This\nincludes evidence regarding locations, structures and operations of the security forces of\nMyanmar, and also concerning interactions with security officials prior to the clearance\noperations. In all of its interactions with witnesses, the Mechanism has prioritized the\ncollection of information concerning sexual and gender-based crimes and crimes against and\naffecting children."},{"id":"a-hrc-60-18-p0026","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"26","seq":28,"section":"C. Investigating crimes against the Rohingya","text":"The Mechanism continues to strengthen its evidence collection by engaging with civil\nsociety groups, local and international non-governmental organizations, media outlets and\ngovernments. The Mechanism continues, in particular, to seek witnesses with “inside\nknowledge” of the key figures and decision makers behind the clearance operations of 2016\nand 2017. These witnesses include military defectors who have provided crucial information\nregarding the structure and operations of the Myanmar military, including chains of\ncommand, deployments, coordination between various branches of the security forces,\ntraining, weaponry and direct orders."},{"id":"a-hrc-60-18-p0027","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"27","seq":29,"section":"C. Investigating crimes against the Rohingya","text":"The Mechanism’s investigations into the clearance operations include a strong focus\non Rohingya villages where properties were destroyed, community members were forcibly\ndisplaced and land was subsequently appropriated and replaced with security bases and State\ninfrastructure, creating even more challenges for Rohingya communities to repatriate and\nrebuild their lives. A crucial aspect of this investigation involves engaging with members of\nthe Rohingya community who have lost their lands and livelihoods and collecting\ndocumentary evidence, geospatial imagery and other open source evidence regarding the\nconstruction of security bases or other State infrastructure. These materials will form the\nbasis of an analytical product to be shared with investigative, prosecutorial and judicial\nauthorities and could also inform efforts related to reparations for the Rohingya community\nand restitution."},{"id":"a-hrc-60-18-p0028","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"28","seq":30,"section":"C. Investigating crimes against the Rohingya","text":"The Mechanism’s financial investigations led to the development of an analytical\nreport focusing on a private commercial entity that provided material support to the security\nforces of Myanmar at the peak of the 2017 clearance operations. This report draws together\nwitness testimony accounts, audiovisual evidence, and open source and social media posts,\nas well as evidence of corporate ownership and interests. It particularly highlights the role of\ncorporate actors who facilitated, contributed to or benefited from the clearance operations\nagainst the Rohingya population."},{"id":"a-hrc-60-18-p0029","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"29","seq":31,"section":"D. Sharing evidence and facilitating justice opportunities","text":"The primary aim of the Mechanism’s investigations is to enable national and\ninternational authorities to end the impunity of perpetrators and deliver justice for victims of\nserious international crimes committed in Myanmar. For this purpose, the Mechanism shares\nevidence and analysis with competent investigative, prosecutorial and judicial authorities to\nsupport criminal proceedings in national or international courts or tribunals with jurisdiction\nover the crimes within the Mechanism’s mandate. Pursuant to its terms of reference, on a\ncase-by-case basis, the Mechanism may also share information for uses other than criminal\nproceedings to contribute to the interests of justice and deter further crimes."},{"id":"a-hrc-60-18-p0030","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"30","seq":32,"section":"D. Sharing evidence and facilitating justice opportunities","text":"In accordance with the principles of confidentiality and informed consent, the\nMechanism only shares information with authorities when the individuals or entities who\nprovided the information have agreed that their information can be shared with that particular\nentity. Before sharing, the Mechanism also conducts an assessment to ensure that sharing the\ninformation will not compromise the safety or the privacy rights of any persons identified in\nthe material. This requires regular and ongoing engagement with the Mechanism’s witnesses\nand sources. The Mechanism also coordinates closely with the relevant jurisdictions such as\nthe International Criminal Court to facilitate the direct provision of testimony by witnesses\nand to “deconflict” witnesses to ensure that sensitive and vulnerable individuals are not\napproached or asked to be interviewed again by multiple justice institutions."},{"id":"a-hrc-60-18-p0031","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"31","seq":33,"section":"D. Sharing evidence and facilitating justice opportunities","text":"During the reporting period, the Mechanism supported four jurisdictions: ongoing\nproceedings related to crimes committed against the Rohingya in three jurisdictions and an\nongoing proceeding in the United Kingdom covering crimes against both the Rohingya and\nother groups in Myanmar and crimes committed after the coup. In relation to proceedings\nrelated to crimes against the Rohingya, the Mechanism continued to share an\nunprecedentedly high volume of evidence and analysis. Two active investigations are\nfocused on the individual criminal responsibility of perpetrators. These investigations are\nbeing conducted by the Office of the Prosecutor of the International Criminal Court and by\nFederal Prosecutor’s Office No. 9 in Argentina. The continued efforts of the Mechanism were\nreflected in arrest warrant applications by the Prosecutor of the International Criminal Court\nin November 2024 and the Federal Prosecutor of Argentina in February 2025. The third\nproceeding for which the Mechanism is sharing information is the Gambia v. Myanmar case\nbefore the International Court of Justice. This case concerns alleged violations by Myanmar\nof its obligations under the Convention on the Prevention and Punishment of the Crime of\nGenocide. The written submissions phase of this proceeding concluded in late 2024 and the\noral hearings on the merits are expected to begin later in 2025. The Mechanism continues to\nproactively identify information and evidence that could be relevant to these investigations\nand proceedings and is also responding to targeted requests from these authorities for specific\ninformation or analysis."},{"id":"a-hrc-60-18-p0032","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"32","seq":34,"section":"D. Sharing evidence and facilitating justice opportunities","text":"Furthermore, the Mechanism is monitoring complaints regarding post-coup crimes,\nwhich have been filed in national courts on the basis of universal jurisdiction, including\ncomplaints filed in the Philippines and Türkiye. The Mechanism has taken proactive steps to\nengage with additional jurisdictions for potential future investigations and justice\nopportunities. Notably, the Mechanism has engaged with relevant authorities in the\nUnited Kingdom to share information related to crimes under the Mechanism’s mandate,\nincluding with the War Crimes Team – a specialized unit within the Counter Terrorism\nCommand of the Metropolitan Police – which has opened a structural investigation mirroring\nthe situations being investigated by the Prosecutor of the International Criminal Court."},{"id":"a-hrc-60-18-p0033","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"33","seq":35,"section":"D. Sharing evidence and facilitating justice opportunities","text":"In order to facilitate future prosecutions, the Mechanism seeks to identify individuals\nand entities that are responsible for serious international crimes, and additionally to have a\nnexus to countries outside of Myanmar that may be able and willing to exercise jurisdiction\nover such crimes. Thus, the Mechanism has two ongoing investigations focusing on the\nsupply and production of weapons and aircraft used in attacks by the Myanmar military on\ncivilians. These investigations combine financial information with crime base evidence\ncollected by the Mechanism. A vital component of these investigations is the engagement\nwith insider witnesses and the use of open source and social media evidence to follow\nweapons suppliers and other corporate actors who facilitate, contribute to or benefit from\nongoing attacks against civilians. The objective of these investigations is to prepare files\nready to be shared with investigative, prosecutorial and judicial authorities. Most recently,\nthe Mechanism received and responded to a request from a British authority in relation to\npost-coup crimes, involving such information."},{"id":"a-hrc-60-18-p0034","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"34","seq":36,"section":"E. Methodology for collecting, analysing and managing evidence","text":"Despite the lack of access to crime scenes and difficulties in contacting witnesses, the\nMechanism continued to collect large quantities of information and evidence. To date, the\nMechanism has collected and processed millions of items of information and evidence from\nnearly 1,300 sources and information providers, adding hundreds of thousands of items\nduring the reporting period. Throughout these processes, the Mechanism adheres to the\nprinciples of confidentiality and informed consent in order to safeguard the integrity of its\nwork and protect all those with whom it interacts."},{"id":"a-hrc-60-18-p0035","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"35","seq":37,"section":"E. Methodology for collecting, analysing and managing evidence","text":"The Mechanism’s approach to evidence collection has been to combine traditional\ninvestigative techniques with modern investigative technologies. The Mechanism has\ncollected many different types of evidence, ranging from signed statements of witnesses with\nfirst-hand knowledge relevant to serious crimes, to the harvesting, verification and analysis\nof social media, open source and financial information. Evidence is collected through direct\ninteractions with witnesses and sources and with non-governmental organizations, civil\nsociety groups, national authorities and other international organizations, as well as business\nentities. The Mechanism’s evidence collection has been substantially strengthened by the\nintegration of sophisticated open source investigation techniques. These techniques include\nexamining public statements and monitoring media and social media, as well as verifying\nand analysing photographs, videos and geospatial imagery. Given the extensive availability\nof open source materials, the Mechanism’s lack of access to the crime scenes, and security\nand cooperation challenges, open source evidence is increasingly an essential component of\ninternational criminal investigations."},{"id":"a-hrc-60-18-p0036","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"36","seq":38,"section":"E. Methodology for collecting, analysing and managing evidence","text":"The Mechanism applies a multifaceted approach to evidence collection, focusing on\ninformation and evidence related to priority situations and incidents, contextual and overview\ninformation relevant to Myanmar, and information concerning specific individuals, groups\nand structures suspected of perpetrating crimes. As required by its terms of reference, the\nMechanism seeks both inculpatory and exculpatory information from all relevant parties\nregarding serious international crimes committed in Myanmar. The Mechanism seeks to\nensure that a survivor/victim-centred, gender-sensitive and trauma-informed approach\nunderpins its methodologies, processes and systems, particularly in its interactions with\nwitnesses, sources and other information providers."},{"id":"a-hrc-60-18-p0037","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"37","seq":39,"section":"E. Methodology for collecting, analysing and managing evidence","text":"The Mechanism places great importance on the collection of first-hand witness\ntestimony, which is essential to building criminal cases. Thus, in-person interviews and the\ncollection of valuable and probative information through investigative missions are a critical\nelement of the Mechanism’s evidence collection. Investigative missions involve direct\nengagement with victims, witnesses, civil society actors and other stakeholders. Detailed,\nsigned witness statements and other materials are securely collected and transmitted to the\nMechanism’s electronic information management system using encrypted tools. This ensures\nthe protection and confidentiality of the information and of information providers. To date,\nthe Mechanism has collected over 590 witness statements and screening notes. In addition,\nthe Mechanism has prepared more than 500 investigation notes documenting information\ncollected from various sources and leads.\nEvidence analysis and sharing"},{"id":"a-hrc-60-18-p0038","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"38","seq":40,"section":"E. Methodology for collecting, analysing and managing evidence","text":"The Mechanism has further strengthened and refined its methodologies for analysis\nand sharing. Since the establishment of the Mechanism, this has resulted in the preparation\nof 120 packages comprising more than 1.2 million items of supporting evidence, metadata\nauthentication and analysis that have been shared with national and international authorities.\nFurthermore, the Mechanism continues to evolve its use of emerging technologies in\nresponse to the growing scale of evidentiary material and the changing digital landscape.\nAdvances in automation, artificial intelligence and secure tools and technologies are enabling\nthe Mechanism to strengthen and augment its overall analytical capabilities, by ensuring that\nthe evidence collected is accessible and searchable and that materials are preserved in a\nmanner that will allow their use in future legal proceedings according to the Mechanism’s\nmandate."},{"id":"a-hrc-60-18-p0039","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"39","seq":41,"section":"E. Methodology for collecting, analysing and managing evidence","text":"For example, the Mechanism developed the Case Analysis Platform, an evidence\nanalysis tool that enables the Mechanism to systematically extract, organize and annotate\nfacts from evidentiary material. The Case Analysis Platform facilitates the Mechanism’s\nefforts to build coherent files pertaining to key legal and factual elements required to prove\ncrimes. The Mechanism is also developing a tool that utilizes computer vision technology to\ndetect designated items such as weapons and insignia as well as disturbing or graphic content\nin photos and videos to minimize investigative teams’ exposure to material that may lead to\nsecondary trauma."},{"id":"a-hrc-60-18-p0040","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"40","seq":42,"section":"E. Methodology for collecting, analysing and managing evidence","text":"To optimize the Mechanism’s investigations, the Mechanism is also developing a\nsystem based on digital identifiers to enable comparisons of potential connections between\npersons and entities of interest, documented incidents, and digital footprints such as IP\naddresses, email addresses, call data records, social media identifiers and other metadata\nderived from open sources. The Mechanism continues to build its capacity to identify\ntransactions and assets linked to incidents by leveraging information obtained through its\ncollection activities and its engagement with sources, as well as through specialized corporate\nand financial intelligence tools. These efforts have led to an enhanced understanding of\ncommand structures and funding sources, supporting analysis across investigative priorities\nand lines of inquiry."},{"id":"a-hrc-60-18-p0041","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"41","seq":43,"section":"E. Methodology for collecting, analysing and managing evidence","text":"Due to the vast linguistic diversity of Myanmar, where over 100 languages are spoken,\nthe Mechanism continues to face translation challenges. There are also huge challenges in\nevidence processing and analysis due to language and script complexities. The majority of\nthe materials collected are written in the Myanmar language (Burmese) which has distinct\ncharacter encoding – a process of assigning numbers to graphical characters of human\nlanguage – and a variety of file formats. This linguistic complexity requires robust and timely\ntranslation and interpretation capabilities for effective analysis. The Mechanism has\ndeveloped advanced optical character recognition tools that convert scanned or image-based\ndocuments into machine-readable texts. To address the absence of readily available tools for\ntranslating languages used in Myanmar into English, the Mechanism is also actively\nresearching and developing artificial intelligence solutions that can facilitate machine\ntranslation of the Mechanism’s collection of materials in Burmese."},{"id":"a-hrc-60-18-p0042","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"42","seq":44,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism requires the cooperation of numerous entities, including States,\ninternational organizations, civil society organizations, business entities and victims, in order\nto collect information and evidence on the most serious international crimes committed in\nMyanmar. In an effort to strengthen cooperation with all relevant stakeholders, the\nMechanism continued its high-level dialogues and consultations with Member States and\nother actors in Geneva, New York and capitals. These engagements enabled the Mechanism\nto promote its work and to advance important cooperation arrangements to carry out evidence\ncollection and witness interviews in the territories of Member States."},{"id":"a-hrc-60-18-p0043","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"43","seq":45,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism continued to reach out to, and seek information from, the Myanmar\nmilitary and armed groups in the country, in accordance with relevant resolutions of the\nHuman Rights Council and the General Assembly calling upon Myanmar to cooperate and\nengage meaningfully with the Mechanism. To date, the Mechanism has made over two dozen\nrequests to the authorities of Myanmar for information in its possession and for access to the\nterritory of Myanmar. It also requested information relating to alleged crimes – including\nregarding investigations or disciplinary measures undertaken – from both the military\nauthorities and various armed groups. While the National Unity Government has responded,\nand shared detailed information on an investigation it had conducted, the Mechanism has not\nreceived any responses to its requests for information from the military or other armed\ngroups."},{"id":"a-hrc-60-18-p0044","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"44","seq":46,"section":"A. Cooperation with Member States and other partners","text":"In January 2025, the Head of the Mechanism conducted an official visit to\nBangladesh, where he engaged in high-level discussions with government officials in Dhaka\nand outreach activities with the Rohingya community in Cox’s Bazar. The visit focused on\nthe Mechanism’s ongoing investigations into crimes committed against the Rohingya\npopulation, recent developments in accountability efforts, and the evolving situation across\nthe border in Rakhine State. In the lead-up to the High-Level Conference on the Situation of\nRohingya Muslims and Other Minorities in Myanmar scheduled to take place in September\n2025 – an initiative stemming from the seventy-ninth session of the General Assembly – the\nMechanism has underscored the critical importance of addressing issues of justice and\naccountability in order to order achieve any long-term peace and stability for communities in\nRakhine State and throughout Myanmar. The Head of the Mechanism also conveyed the\nMechanism’s deep appreciation for the continued support of the Government of Bangladesh\nin facilitating its investigations and providing access to Rohingya refugees in Cox’s Bazar\nwho have been forcibly displaced from Myanmar. The cooperation of Bangladesh remains\ncrucial in advancing accountability and justice efforts."},{"id":"a-hrc-60-18-p0045","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"45","seq":47,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism continues to call on all Member States seeking to end the spiralling\nviolence and rampant atrocities in Myanmar to cooperate with its efforts to pursue justice for\nthese crimes. Calls for the violence to end have little effect if perpetrators of the most serious\ncrimes feel assured that they will never be held responsible. The Mechanism continues to\nseek the cooperation of relevant States so that investigative teams can interview witnesses on\ntheir territory. Expanding such cooperation continues to be a high priority for the Mechanism,\nespecially with Member States in the Asia-Pacific region where much of the evidence and\nmany of the witnesses are located. The Mechanism welcomes progress on the negotiation of\ncooperation arrangements with some States, which is expected to further enable the\nMechanism’s investigative activities."},{"id":"a-hrc-60-18-p0046","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"46","seq":48,"section":"A. Cooperation with Member States and other partners","text":"The Mechanism’s efforts to establish cooperation arrangements with Member States\nfor the purpose of facilitating the collection of testimonial and documentary evidence in their\nterritory have also been informed by lessons learned and best practices identified through an\ninternal evaluation carried out in 2024. The findings of the evaluation affirmed the\nimportance of regular consultations with national authorities and of pragmatic and flexible\napproaches in advancing the more than a dozen cooperation arrangements to date with a\ndiverse group of Member States. Through this evaluation, the Mechanism also identified\nareas for improving efficiencies, including by proactively exploring opportunities for two-\nway cooperation, adopting alternative or mitigating measures where lack of cooperation is\nlikely to persist, and improving processes for the submission of requests for assistance to\nStates."},{"id":"a-hrc-60-18-p0047","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"47","seq":49,"section":"A. Cooperation with Member States and other partners","text":"During the reporting period, the Mechanism also continued to rely on the support and\ncooperation of United Nations entities that might have information relevant to the\nMechanism’s mandate or that could provide support in other areas of its operations. In line\nwith relevant Human Rights Council resolutions and with its terms of reference, the\nMechanism cooperates closely with the Office of the United Nations High Commissioner for\nHuman Rights (OHCHR) to enhance the complementarity of the respective mandates: for the\nMechanism, conducting criminal investigations into serious international crimes in Myanmar\nconsistent with international law standards, and for OHCHR, carrying out fact-finding,\nmonitoring, documentation, advocacy, and engagement with stakeholders in relation to\nhuman rights violations in Myanmar. The exchange of information and associated\ncooperation is based on a memorandum of understanding between the Mechanism and\nOHCHR. Fully cognizant of the challenging operational environment that the United Nations\nsystem is currently facing in Myanmar, the Mechanism highly values the continued\ncooperation and support of many other United Nations actors."},{"id":"a-hrc-60-18-p0048","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"48","seq":50,"section":"B. Dialogue with civil society and public outreach","text":"The Mechanism believes that it is critically important to inform key audiences of its\nefforts to collect evidence and end impunity for serious crimes in Myanmar. It is essential\nthat victims are aware that efforts are being made to document their experiences and bring\nsome measure of justice for those who have suffered these crimes. It is equally critical that\npotential perpetrators know that evidence is being collected and efforts are being made to\nensure that those responsible will one day be held to account. Consequently, the Mechanism\nundertakes significant efforts to actively engage with individuals and organizations through\ndiverse channels, ensuring that stakeholders have a clear understanding of its complex\nmandate, its operational methods and the scope of its capabilities and limitations. By\nfostering outreach and dialogue, the Mechanism aims to strengthen trust in its role as an\nindependent and impartial entity while encouraging greater support and cooperation for its\ninvestigations. During the reporting period, the Mechanism prioritized several key initiatives,\nincluding the launch of its new website and the production of outreach materials in several\nlanguages of Myanmar."},{"id":"a-hrc-60-18-p0049","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"49","seq":51,"section":"B. Dialogue with civil society and public outreach","text":"Civil society organizations play a vital role in supporting the Mechanism, offering\nvaluable information, documentation, witness access and investigative leads. By engaging\nwith these organizations, the Mechanism not only communicates its mandate and operational\nmethods, but also gains valuable insights into the realities and challenges encountered by\nthose working on the ground."},{"id":"a-hrc-60-18-p0050","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"50","seq":52,"section":"B. Dialogue with civil society and public outreach","text":"During the reporting period, the Mechanism held its third Myanmar Civil Society\nDialogue, which provided another valuable opportunity for Mechanism personnel to directly\nengage with representatives of 20 civil society organizations from diverse communities, all\nworking towards accountability and justice for the people of Myanmar. This annual meeting\nserves as an important in-person platform for fostering mutual understanding and trust and\nresponding to feedback on the Mechanism’s work. Many civil society participants shared the\nchallenges they face because of funding shortfalls, widespread trauma and increased security\nrisks, and made valuable suggestions on how the Mechanism could adapt its engagement\nwith civil society organizations to make it more effective. Before the event, 20 per cent of\ncivil society participants indicated that they had a clear understanding of the Mechanism’s\nmandate. This increased to more than 80 per cent after the event, with all participants\nindicating a willingness to cooperate with the Mechanism in the future. For many\nparticipants, the Myanmar Civil Society Dialogue was a unique opportunity to engage with\nrepresentatives from different ethnic groups, which resulted in increased trust and\ncooperation between the organizations that attended."},{"id":"a-hrc-60-18-p0051","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"51","seq":53,"section":"B. Dialogue with civil society and public outreach","text":"Furthermore, the Mechanism engaged in multiple opportunities for meaningful two-\nway communications with relevant organizations through 33 virtual and in-person events and\nmeetings. During his official visit to Bangladesh in January 2025, the Head of the Mechanism\nengaged with more than 100 Rohingya activists and representatives of community\norganizations from refugee camps in Cox’s Bazar. In these briefings, he updated stakeholders\non the Mechanism’s investigative progress and on recent developments in accountability\nprocesses and addressed key questions regarding accountability for ongoing crimes in\nRakhine State, along with concerns about prospects for justice. The Mechanism also held\nin-person briefings with Myanmar diaspora communities in North America and numerous\nmeetings with different audiences focused on specific thematic issues, such as sexual and\ngender-based crimes."},{"id":"a-hrc-60-18-p0052","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"52","seq":54,"section":"B. Dialogue with civil society and public outreach","text":"The Mechanism expanded its efforts to engage a broader audience by developing and\ndistributing materials with visually engaging, memorable and shareable messaging. During\nthe reporting period, it redesigned its website to feature more accessible content in both\nEnglish and Burmese, along with an improved user experience. Through its triannual\nnewsletter, the Mechanism strives to maintain transparency and keep stakeholders informed,\nby providing substantive content and detailed updates on its progress. It has also produced\nand disseminated videos, fact sheets, infographics and other outreach materials in Burmese,\nRohingya and other languages used in Myanmar. These resources offer clear explanations of\nvarious aspects of the Mechanism’s work and of recent developments in judicial processes.\nIn the next reporting period, additional outreach materials will be created in more languages\nof Myanmar, with a particular emphasis on the Mechanism’s approach to investigating\ncrimes against and affecting children as well as on sexual and gender-based crimes."},{"id":"a-hrc-60-18-p0053","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"53","seq":55,"section":"B. Dialogue with civil society and public outreach","text":"The Mechanism continued to reach out to diverse audiences through press releases,\nstatements, media briefings and interviews, resulting in consistent media and social media\ncoverage of its work in various languages of Myanmar and through global and regional\noutlets. Despite increasing efforts by the Myanmar military to restrict Internet and social\nmedia access, the Mechanism’s Facebook audience continued to grow steadily throughout\nthe reporting period. The number of followers, located primarily in the Asia region, surpassed\n75,500. This growth was largely driven by the Mechanism’s timely responses to events in\nMyanmar and to key developments at the International Court of Justice and the International\nCriminal Court and in Argentina. Looking ahead, the Mechanism plans to further expand its\nsocial media presence by launching a LinkedIn page in the next reporting period to engage a\nwider audience."},{"id":"a-hrc-60-18-p0054","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"54","seq":56,"section":"A. Witness protection and support","text":"The Mechanism places high priority on ensuring the security and well-being of\nwitnesses and those who provide information, and seeks to facilitate access to psychological\nsupport for those who will benefit from such services. Despite significantly reduced resources\nduring the reporting period, the Mechanism has remained steadfast in its witness protection\nand support efforts. It continues to enhance its procedures and working methods, aligning\nthem with international best practices to ensure the effective safeguarding of witnesses."},{"id":"a-hrc-60-18-p0055","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"55","seq":57,"section":"A. Witness protection and support","text":"Investigating serious international crimes presents considerable security, safety and\npsychosocial risks for witnesses, victims and other sources of information. These risks are\nparticularly pronounced for individuals who have been detained and/or tortured, for survivors\nof systemic violence, including sexual and gender-based violence and mass killings, and for\ninsider witnesses. The security situation of potential witnesses has become increasingly\ncomplex with the deteriorating security situation in Myanmar as well as in other locations\nhosting refugees. Many of the Mechanism’s witnesses and sources face serious risks both\ninside and outside Myanmar. Many have been forced to flee Myanmar and have crossed into\nneighbouring countries without any legalized immigration status, placing them in vulnerable\nsituations, which sometimes includes the risk of arrest and deportation to Myanmar, where\nthey may face persecution, detention and even execution. In this context, the Mechanism\nplays a critical role in mitigating these risks by facilitating secure and confidential\ninvestigative interviews, coordinating protection measures for high-risk witnesses and\naddressing identified mental health and other psychosocial concerns. The Mechanism’s\nability to address risks related to the safety and well-being of its witnesses also requires the\ncooperation of Member States."},{"id":"a-hrc-60-18-p0056","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"56","seq":58,"section":"A. Witness protection and support","text":"The Mechanism takes all feasible steps to safeguard the safety and well-being of\nindividuals before, during and after their cooperation with the personnel of the Mechanism.\nThese measures are embedded across all aspects of the Mechanism’s operations, from\ninformation collection to information sharing. Over time, the number of victims and\nwitnesses requiring ongoing protection and support has grown steadily, leading to a yearly\nrise in individuals requiring such support. During the reporting period, the Mechanism\nconducted over 220 contact risk assessments, aimed at identifying specific security risks and\nensuring that witnesses could engage with the Mechanism in a secure manner. However, the\nMechanism is not a security service and does not have the ability to provide physical security\nor to authorize travel and entry into any country. Rather, it relies on the collaboration and\nsupport of Member States to ensure the protection of witnesses."},{"id":"a-hrc-60-18-p0057","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"57","seq":59,"section":"A. Witness protection and support","text":"In an effort to improve psychosocial support for witnesses, the Mechanism conducted\na significant number of psychosocial risk assessments to identify measures that reduce\npotential negative effects on their mental health and retraumatization due to their cooperation\nwith the Mechanism. In addition, numerous individuals have been referred to external service\nproviders to receive medical and psychosocial support, as provided for in the Mechanism’s\nterm of reference."},{"id":"a-hrc-60-18-p0058","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"58","seq":60,"section":"B. Language support","text":"The diversity of linguistic groups in Myanmar adds a layer of complexity to the\nMechanism’s activities. Most of the information and evidence that the Mechanism has\ncollected is in the Myanmar language (Burmese), Rohingya, or other languages used in\nMyanmar, and is written in different scripts and with different file formats. In addition, the\nmajority of victims, witnesses, sources and civil society stakeholders speak Burmese,\nRohingya or other languages used in Myanmar. Accordingly, the Mechanism requires timely\nand accurate language translation and interpretation capabilities to effectively conduct its\ncollection and analytical activities as well as to engage routinely and meaningfully with a\nwide range of stakeholders."},{"id":"a-hrc-60-18-p0059","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"59","seq":61,"section":"B. Language support","text":"The Mechanism’s small Language Support Services Section continues to deliver\ntimely translation, interpretation and language verification services, not only in Burmese but\nalso in the Rakhine, Rohingya, Karen, Mizo Chin, Falam Chin, Jinghpaw and Shan\nlanguages. These services play a crucial role across the Mechanism, supporting ongoing\ninvestigations, public information and outreach efforts, witness protection and support\nactivities and security coordination functions."},{"id":"a-hrc-60-18-p0060","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"60","seq":62,"section":"C. Security of personnel, assets and information technology","text":"The work of the Mechanism is highly sensitive and its activities require the highest\nlevels of discretion and confidentiality to ensure the integrity of the investigations and the\nsafety and security of its personnel, premises, information assets and operations. The\nMechanism continuously monitors the deteriorating security situation in areas that have a\ndirect impact on its work, ensuring effective risk mitigation and adapting to emerging threats\nwhen necessary."},{"id":"a-hrc-60-18-p0061","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"61","seq":63,"section":"C. Security of personnel, assets and information technology","text":"Since the February 2021 coup in Myanmar, there has been a significant rise in security\nthreats and risks to the Mechanism. This rise is the result of the continued increase in serious\ninternational crimes in Myanmar and the accompanying increase in investigative activities in\nhigh-risk locations and in engagement with high-risk witnesses. The Mechanism incorporates\nsecurity considerations before, during and after investigative activities in order to continually\nassess and mitigate complex security challenges and ensure the security of its personnel,\npremises and assets."},{"id":"a-hrc-60-18-p0062","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"62","seq":64,"section":"C. Security of personnel, assets and information technology","text":"The Mechanism is investigating various individuals responsible for serious\ninternational crimes in Myanmar, including members of the Myanmar military. In 2024, the\nProsecutor of the International Criminal Court and the Federal Prosecutor of Argentina\nrequested arrest warrants against some of these individuals. The Myanmar military has shown\na pattern of targeting, threatening, intimidating and even killing individuals working against\nits interests. In this context, Mechanism personnel – especially those with families in\nMyanmar – face significant pressure and fear and are particularly vulnerable to security\nthreats. If their affiliation with the Mechanism is exposed, there is a very real risk that they\nmay be targeted as a result."},{"id":"a-hrc-60-18-p0063","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"63","seq":65,"section":"C. Security of personnel, assets and information technology","text":"To mitigate the risks effectively, the Mechanism integrates robust safety and security\nmeasures tailored to specific security requirements and risk assessments across all aspects of\nits operations, both in Geneva and during missions abroad. These security arrangements\ninclude continuous monitoring and in-depth analysis of an increasing number of threat actors\nand their activities, resulting in the production of detailed and regularly updated country- or\narea-specific threat and risk assessments. These assessments are conducted in close\ncollaboration with entities of the United Nations security management system, the\nDepartment of Safety and Security and key security interlocutors."},{"id":"a-hrc-60-18-p0064","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"64","seq":66,"section":"C. Security of personnel, assets and information technology","text":"The Mechanism’s security efforts have substantially contributed to ensuring that the\nMechanism’s investigative missions, its engagement with stakeholders and its information\nand data are safe and secure. During the reporting period, the Mechanism implemented\nadditional processes and technologies to strengthen its information security by enhancing the\ncontrol and protection of devices used in investigative activities and inquiries."},{"id":"a-hrc-60-18-p0065","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"65","seq":67,"section":"C. Security of personnel, assets and information technology","text":"In addition, the Mechanism operationalized a structured incident response framework\nand online reporting system that allows the Mechanism to report, track, monitor and\neffectively identify and implement mitigation or response measures to security incidents\ninvolving personnel, witnesses and information assets."},{"id":"a-hrc-60-18-p0066","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"66","seq":68,"section":"D. Technology and infrastructure","text":"As the digital information landscape evolves and the Mechanism’s collection\nactivities grow, the continuous advancement and refinement of technologies remains integral\nto its operations. By integrating advanced solutions, the Mechanism constantly optimizes the\nintake, preservation and analysis of its electronic information management system, ensuring\nefficiency and reliability across all aspects of its work."},{"id":"a-hrc-60-18-p0067","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"67","seq":69,"section":"D. Technology and infrastructure","text":"Over the reporting period, the Mechanism identified and adopted new systems and\ntechnologies to better organize, secure and manage its non-evidentiary material. As one of\nits most significant information governance initiatives during this period, the Mechanism\nsuccessfully completed the migration of data from its previous storage system to a more\nadvanced and better suited system, a process that required specialized information\ngovernance expertise from inception to completion. In addition, the Mechanism performed a\ncomprehensive review of its information systems management’s policies and procedures and\nupdated these to align with current technology advances. The Mechanism also leveraged\nvirtualization in its infrastructure to support various aspects of its operations, enabling more\nsecure remote work and improving data management through more cost-effective solutions."},{"id":"a-hrc-60-18-p0068","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"68","seq":70,"section":"D. Technology and infrastructure","text":"The Mechanism remains committed to enhancing its automated processes, in order to\nfurther improve efficiency within its electronic information management system. During the\nreporting period, these efforts have resulted in greater quality control and increased accuracy\nfor the information being processed. The automation has been expanded to include\ntranslations, open source operations and overall analysis capabilities, strengthening the\nMechanism’s ability to manage and utilize information securely and effectively."},{"id":"a-hrc-60-18-p0069","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"69","seq":71,"section":"D. Technology and infrastructure","text":"The Mechanism is proactively exploring various lines of enquiry and research into the\nviability and usability of artificial intelligence for its investigations and analysis. This\nresearch and development is an ongoing effort and is continuously evolving as the available\ntechnologies change at an ever-increasing pace."},{"id":"a-hrc-60-18-p0070","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"70","seq":72,"section":"V. Conclusion: challenges and the way forward","text":"As highlighted throughout the present report, the Mechanism continued to face a\nnumber of complex challenges, including the lack of direct access to victims and witnesses\nin Myanmar and other States in the region; threats to the safety and security of personnel,\nwitnesses and interlocutors; cybersecurity threats to communications and limitations in\nensuring secure access to information; and the need for adequate capacity and resources to\nreinforce language and translation capabilities, technological innovations and specialized\nexpertise. These challenges have been compounded by the unprecedented liquidity crisis and\nausterity measures affecting the United Nations during the reporting period."},{"id":"a-hrc-60-18-p0071","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"71","seq":73,"section":"V. Conclusion: challenges and the way forward","text":"The liquidity crisis and the recently introduced austerity measures have affected\nrecruitment, essential consultancies, investigative mission travel, training, and the acquisition\nof information technology equipment and software. Additionally, the Mechanism has only\nbeen allocated 73 per cent ($11 million) of its approved regular budget for 2025, further\nstraining its operational capacity. Compounding these challenges, the UN80 Initiative has\nintroduced additional cost-cutting measures, requiring the Mechanism to reduce by\n20 per cent the staff positions funded by the regular budget in 2026. Such a reduction will\nhave a particularly significant impact on the Mechanism due to its small size. These financial\npressures threaten the Mechanism’s ability to sustain its critical work and to continue\nsupporting international and national justice efforts. The Mechanism will continue to\nmobilize extrabudgetary funding to sustain its activities in the future and welcomes the\nsupport of diverse Member States and partners."},{"id":"a-hrc-60-18-p0072","rec_id":"recJayYM89kmPO81c","symbol":"A/HRC/60/18","n":"72","seq":74,"section":"V. Conclusion: challenges and the way forward","text":"To address these multifaceted challenges and chart a path forward, the Mechanism\nadopted its Strategic Plan for 2025–2027, which sets out a clear vision and strategic direction\nfor the next three years. The Plan outlines targeted goals and objectives designed to:\n(a) strengthen the Mechanism’s operational resilience; (b) enhance its investigative and\nanalytical capacities; and (c) deepen engagement with stakeholders, including Member\nStates, civil society and affected communities. It emphasizes the need to reinforce digital\nsecurity and invest in technologies to manage and analyse large volumes of evidence. It also\nprioritizes the expanded use of collected evidence by national and international authorities\nby identifying possible proceedings under universal and extraterritorial jurisdiction.\nProtection and support for high-risk witnesses remains central, including by mobilizing\nMember State and organizational cooperation for their relocation through resettlement or\nwitness protection programmes. Finally, the Strategic Plan underscores the value of inclusive\npartnerships to ensure sustained cooperation and resourcing. By aligning its priorities with\nthe evolving situation in Myanmar, the Strategic Plan ensures that the Mechanism’s work\nremains grounded in and guided by its mandate, thereby providing a clear framework to\nnavigate current challenges and advance accountability efforts effectively."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0001","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"1","seq":0,"section":"I. Introduction","text":"In August 2017, the Myanmar military launched a campaign of mass atrocities against\nthe Rohingya population of Rakhine state, marked by the burning of villages, mass killings and\nwidespread sexual violence.The violence resulted in the forced displacement of over 700,000\nRohingya from Rakhine State into Bangladesh. The clearance operations that began on 25\nAugust 2017 were the culmination of decades of systemic persecution and disenfranchisement\nofthe Rohingya population.Long before the 2017 atrocities,the Rohingya had been stripped of\ncitizenship, excluded from education, denied healthcare, and marginalized from political\nparticipation.'"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0002","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"2","seq":1,"section":"I. Introduction","text":"The United Nations Independent Invcstigativc Mechanism for Myanmar(\"Mechanism\"\nor TIMM) has investigated emblematic cases where Rohingya villages were destroyed by the\nMyanmar military during the 2017 clearance operations, demolished and razed, and replaced\nwith Border Guard Police(BGP)Battalion bases.Following this investigation,the Mechanism\nprepared a report titled \"Destruction and Dispossession of Rohingya Land and Property during\nthe 2017 Clearance Operations: Evidence Analysis\" which contains confidential witness and\nPage 1 of 29\nsource information and is available to national and international authorities to facilitate\ninvestigations andjudicial proceedings that have or may in the future havejurisdiction over these\ncrimes, in line with the Mechanism's Terms of Reference. This document is a summary of the\nevidence and analysis contained in the llreport"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0003","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"3","seq":2,"section":"I. Introduction","text":"Tn this investigation, the Mechanism aimed to identify: a) the entities and associated\nindividuals who ordered, oversaw, carried out and financially benefitted from the destruction\nand demolition of Rohingya villages and the construction of BGP Battalion bases on top of the\nrazed villages; b)those entities' andindividuals' contributions to serious international crimes;\nand e)their current locations.2 The Mechanism also aimed to identi and set out the types of\nloss suffered by Rohingya due to these acts,including the dispossession ofland and property,\nand theloss oflivelihoods and the community's connection to their ancestralhomeland through\nthe destruction of cemeteries and mosques"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0004","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"4","seq":3,"section":"I. Introduction","text":"The evidence summarized below is intended to facilitate proceedings in national,\nregional or international courts.It also provides a foundation for reparations.Justice for the\nRohingya requires reparations that go beyond symbolic acknowledgment. Reparations, in\ninternational law and practice, are not merely about compensation but about recognition of\ncrimes, restoration of dignity, and measures to prevent the recurrence of such crimes. The\nprecedent of Wiedergutmachung after the Holocaust underscores that reparations are a moral\nobligation and a necessary foundation for future reconciliation of communities"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0005","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"5","seq":4,"section":"II. Methodology","text":"The analysis conducted by the Mechanism relied on a range of evidentiary sources,\nincluding witness statements collected by the Mechanism, photographic and video\ndocumentation,land and property records including those preserved by Rohingya who fled the\nviolence,geospatialimagery and open-source materialsuch as statements by Myanmar officials\nand corporate executives. The investigation concentrated on seven village tracts in northern\nRakhine State, where Rohingya villages were destroyed during the August 2017 clearance\noperations and subsequently replaced with BGP Battalion bases.These include: 1)Rohingya\nvillages in U Daung village tract,replaced by No.4 BGP Battalion base; 2)Rohingya villages\nin Myo Thu Gyi(Hainda Fara)village tract,replaced by No.5 BGP Battalion base; 3)Rohingya\nvillages in Inn Din (Aung Dung) village tract, replaced by No. 6 BGP Battalion base; 4)\nRohingya villagesin Aung Seik Pyin(Done Paik)village tract,replaced by No.7 BGP Battalion\nbase; 5)Rohingya farmlandin Ah LeI Chaung(Ali Yong)village tract,replaced by No.S BOP\nBattalion base; 6)Rohingya villages in Myin Hlut(May Ruila)village tract,replaced by No.9\nBGP Battalion base; and 7)Rohingya village Hpu KharLi(Fut Hali)in Zin Paing Nyar(Doinor\nZum Boyim Na)village tract,replaced by No.10 BGP Battalion base(See Figure 1: Time/inc\nRohingya village destruction,clearance and construction BGP bases and Figure 2: Map\ncations underinvestigation11MM)."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0006","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"6","seq":5,"section":"II. Methodology","text":"The Mechanism selected these locations because they demonstrate a systematic pattern\nwhereby villages and farmland were destroyed and razed between late 2017 and early 2018 and\nwere rapidly supplanted by BUP Battalion bases. While the Mechanism is investigating\nadditionalsites,the seven villagesidentified provide the strongest evidentiary record to date that\nPage 2 of 29\nthe 2017 clearance operations combined land seizure, targeted destruction of livelihoods, and\nforced displacement to crase Rohingya presence from their ancestral homeland."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0007","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"7","seq":6,"section":"II. Methodology","text":"Tn this investigation, the Mechanism proceeded with the understanding that Myanmar's\nleasehold-based land system, regulated by multiple laws and related regulations, vests land\nownership in the State while granting individuals and communities various use and tenure rights,\nincluding cultivation, inheritance, transfer and mortgage.3 To substantiate Rohingya claims of\nland and property rights, the Mechanism collected a broad set of official documents, reflecting\nboth individual and communal tenure. These included land registration records,4 land tax\ncertificates (horonsor),5 cadastral maps (Forms 105/106)6 and revenue-stamped contracts,7\nalongside evidence of agricultural transactions with state entities such as the Myanmar\nAgricultural Produce Trading agency. 8 Collectively, these documents demonstrate that\nRohingya land rights were formally recognized through administrative channels, even as the\nRohingya were denied citizenship and excluded from broader legal protections. The Mechanism\nalso identified communal documents, such as village applications for water reservoir\nconstruction,9 which indicate state recognition of Rohingya as settled inhabitants with rights to\nuse and manage natural resources.\nFigure 1:Timeline of Rohingya village destruction,demolition,razing and construction\nof BGP Battalion bases\nLocations   Destruction during     Demolition and     Construction of      BGP\nU Daung        the 2017 clearance            razing       BGP Battalion    Battalion\noperations      8 February 2018 -           bases        base\n1 September 2017'     24 February        2016 -201813       No.4\n2018\" - late\nMyo Thu Gyi    A u                   201812             Completed by 28    No.5\n(Hainda Fara)                                           September 201916   No.6\n'                     12 December                           No.7\n2017 -24           February 2018'9 -  No.8\nFebruary 2018's    25 August 201920\nDecember 2017 -                       No.9\n24 February                           No. 10\n201818\nInn Din        g n a - 7 1 325 August - 22\n(Aung Dung) September 201717\nAung Seik      25 August - 25        0ctober 2017 -     Began in early\nPyin(Done      September 201721      April 201822       201823\nPaik)\nAh Lel         Farmland              December2017 -     Completed by 23\nChaung (Ali    confiscation October  24 February        January 202027\nYong)          201724 - 13           201826\nDecember 201725                          B           p r A\nMyin Hhit      25 - 30 August        26 December        e   s 3 i'\n(May Rulla)    201728                201729 -24         2~\nFebruary 201830\nHpu Khar Li    28 August 201732      1 December          B          r p A\n(Fut Hali)                           201733 - April     e\n201834             2~\nPage 3 of29\nFigure 2: Map of locations under investigation by 11MM\no\nBGPS - Myo Thu Gyi\nDakhmpara\nruile raad\n50-mile ruad  \\\nBGP 6 -Inn Din\nPon ria vu n\n9/1 2/2025                                                            1 554,421\nBGP Battalion Bases                                          4.5   9                18 mi\no 50-mile road                                                  r r ' - l1\nRohingya villages razed                                5 l0             20km\nMyanmar Road Network\nSm-roes: Egli. TamTam. Garmn. FAO. 'JOAAUSGS .DperrStreetMap\noerthbrrtors,and tre ois User Cornmerntg\nPage 4 of 29"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0008","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"8","seq":7,"section":"III. International law","text":"The International Court of Justice has held that under the Convention on the Prevention\nand Punishment of the Crime of Genocide (\"Genocide Convention\"),36 deliberately inflicting\nconditions of life calculated to bring about the physical destruction of a group includes the\nsystematic expulsion from and destruction ofhomes.37 Jurisprudence from international criminal\ntribunals also recognizes that forced displacement, destruction of property, and denial of return\nto one's home cause severe physical, psychological and material hann. In Prosecutor y. Zdravko\nToimir, the International Criminal Tribunal for the former Yugoslavia (ICTY) held that the\nundcrlying acts of genocide may include \"methods of destruction that do not immediately kill\nthe members of the group, but ultimately seek their physical destruction\" such as by\n\"systematically expelling members of the group from their homes\". 38 In Prosecutor y\nB/agojevid and Jokid,the ICTY underscored the mental harm suffered due to the prohibition on\nreturn, describing it as a traumatic rupture of the relationship with one's home territory.39 The\nforcible transfer and destruction ofhomes in Srebrenica were seen as a deliberate signal that the\nvictims had no home to return to.4O In Prosecutor y. Kayishema, the International Criminal\nTribunal for Rwanda(ICTR) interpreted the deliberate infliction of\"conditions oflife calculated\nto bring about its physical destruction in whole or in part\" under Article 11(c) of the Genocide\nConvention to include the withholding of adequate living accommodations, contributing to the\ngroup's physical destruction.4'In Prosecutor y. Radovan Karadi, the ICTY recognized the\npsychosocial consequences of displacement, citing long-term feelings of anxiety, helplessness\nand betrayal, which undermined displaced persons' capacity to rebuild their lives.42 In\nconducting this investigation, the Mechanism paid particular attention to internationallaw on\nState responsibility and the individual responsibility of direct perpetrators, their military\ncommanders and civilian superiors,as wellas those who have aided orabettedin the commission\nof these crimes."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0009","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"9","seq":8,"section":"III. International law","text":"Underinternationallaw,victims who suffered direct harm,43 including physical,mental,\nmaterial, 44 or long-term generationalimpacts,45 are eligible for reparations, as are indirect\nvictims such as immediate family members.46 Reparations may take individual or collective\nforms,47 including restitution, monetary compensation, rehabilitation, satisfaction measures\nsuch as truth disclosure and public apologies, and commemorations.48 Asset seizure remains an\nimportant mechanism to ensure reparations are meaningfully implemented. International\njurisprudence such as theICJ's decisionin the ArmedActivities on the Territory ofthe Congo\ncase, provides a framework for quantifying large-scale harm, even where precise valuation is\ndifficult.5O Reparations are centralto justice,aiming to acknowledge harm and provide redress\nin ways that prioritize victims'needs.5'\nIV . Evidence of destruction, demolition and replacement\n4 .UDaung village tractro. 4 BGP Battalion Base"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0010","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"10","seq":9,"section":"III. International law","text":"In 2017,U Daung village tract had six Rohingya villages:Ah Shey(Phuk Fara),Hpar Ti\n(Faskoree Bil),Kon TanIU Daung Ah Nauk(Posim Fara),Myauk(Uttor Fara),Kon Tan(Deil\nFara), Zon Mar(Zome Mar) and one Na Ta La government-established settlement for non-\nPage 5 of 29\nRohingya ethnic communities called U Daung Na Ta La.52 The Rohingya community in U\nDaung were farmers,53 market shopkeepers, operated shrimp and fish hatcheries, and had other\nbusinesses.54"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0011","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"11","seq":10,"section":"III. International law","text":"During the clearance operations that began on 25 August 2017, Myanmar security\nforces55 burned Rohingya villages in U Daung, forcing residents to flee.56 0ne witness told the\nMechanism that after escaping to Bangladesh, he learned from the local Head of 100 Households\nor Ra Eain Muu that all Rohingya homes in U Daung had been destroyed.57 According to the\nwitness, none ofthe Rohingya villages in the U Daung village tract survived the attacks.58"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0012","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"12","seq":11,"section":"III. International law","text":"Tn the aftermath, the remnants of Rohingya homes in U Daung were systematically\ndemolished. Aerial photographs taken in April 2018 show partially razed, barren areas of land\nmarked by bulldozer tracks in U Daung village tract, alongside burned remnants of a Rohingya\nvillage.59 By late 2018,the marketplace,including businesses owned by witnesses who spoke to\nthe Mechanism, was bulldozed. 60 Under a civilian government public-private partnership\nestablished in late 2017 for development projects in Rakhine State, the Union Enterprise for\nHumanitarian Assistance, Resettlement and Development in Rakhine(UEHRD) Repatriation\nand Resettlement project Ngwe Taung Tan Company Limited cleared 30 acres of burned\nRohingya land with heavy machinery and labourers,62 also targeting other destroyed areas in\nMaungdaw township.63 The No.4 BorderGuard Police Battalion base,the construction ofwhich\nbeganin 2016,was extended over a former marketplace,where Rohingya once traded fish and\nvegetables.64"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0013","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"13","seq":12,"section":"III. International law","text":"Following the 2017 clearance operations, Rohingya farmland in U Daung65 that was\ncharacterized by Myanmar authorities as having become \"ownerless\"66 and \"belonging to\nfarmers who fled to Bangladesh\"67 was harvested68 and non-Rohingya communities resettledin\nthe area were given agricultural machinery, seeds and livestock inputs by government\nauthorities.69\nB . Myo Thu Gyivillage tract - No. 5BGP Battalion base"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0014","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"14","seq":13,"section":"III. International law","text":"Myo Thu Gyi(Hainda Fara)village tract is located to the east of Maungdaw town and\nMyo Ma KaNyin Tan(Shidar Fara),west of3-Mile Ward,south ofMyo U (Etaillya),and north\nof Nyaung Chaung (Hadir Bul)in Maungdaw township.The Maungdaw-Buthidaung highway\ndivides Myo Thu Gyi into two parts. On the northern side of the highway there were two\nRohingya villages: Kan Kya North(UttorFara)and Ra ZarBil.On the southern side there were\nthree Rohingya villages: Kan Kya South (Domn Fara), Ywar Haung (Puran Fara) and Thaung\nPaing Nyar (Saun Boinnya) and one Na Ta La government-established settlement for non-\nRohingya ethnic communities called WaiThar Li.7 In the Rohingya villages ofMyo Thu Gyi,\nRohingya engaged in farming,ran shopsin the market,and carried out other business activities.\nThe villages had several schools,mosques,cemeteries and ponds.7'"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0015","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"15","seq":14,"section":"III. International law","text":"Before August 2017, Rohingya residents of Myo Thu Gyi possessed extensive land,\nhomes andbusinesses,substantiatedbyinheritance,purchase and formalregistration documents.\nWitnesses described inheriting and acquiring land, possessing houses, shops and entire market\nareas,and cultivatinglarge tracts offarmland.72 Some families traced back theirpossession over\ngenerations, with supporting documentation from both Myanmar and even British colonial\nPage 6 of 29\nrecords.73 Although many official documents were lost or destroyed during the clearance\noperations, witness accounts confirm that Rohingya land rights were broad and recognized by\nlocal authorities.74 Rohingya actively used their land for agriculture and commerce, cultivating\ncrops, raising livestock, and generating significant income, which supported both their families\nand the local economy.75 Geospatial imagery further confirms the existence of 307 intact\nstructures in Kan Kya North village and 518 intact structures in Kan Kya South prior to the 2017\nviolence.76"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0016","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"16","seq":15,"section":"III. International law","text":"Witness accounts,77 journalist reports,78 video evidence,79 geospatial imagery8o and\ninternal correspondence from the Rakhine State authorities8'collected and analyzed by the\nMechanism all confirm the burning and razing of Rohingya homes, markets and religious\nbuildings in Myo Thu Gyi during the clearance operations that began on 25 August 2017."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0017","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"17","seq":16,"section":"III. International law","text":"After the Rohingya were displaced from their farmland, Rakhine State authorities\ndeployed the Agricultural Mechanisation Department to harvest 934 acres of crops across\nmultiple villages \"where there were terrorist attacks [that] were facing difficulties in harvesting\nmonsoon rice,\" including in Myo Thu Gyi.82"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0018","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"18","seq":17,"section":"III. International law","text":"By early 2018, under the UEHRD Repatriation and Resettlement project, Mayu A Hla\ncompany cleared over 411 acres of burned Rohingya land with heavy machinery and\nlabourers.83 By 2019, the BGP constructed No. 5 BGP Battalion base directly over the fomier\nvillage of Kan Kya South.84 The construction of the base was overseen by the Commander of\nN~. 1 BGP C~mmand Office in Kvce Kan Pvin. Maunudaw.-\n-wirn tngineer     irom A sia w oria uompanyieaaing aieam 01izo workersio\nbuild a base with a guardhouse,ordinance store,barracks forjunior and senior officers.85 Video\nfootage,86 photographs,87 aerial footage and geospatialimagery89 show destroyed Rohingya\nhomes and farmland being flattened to make way forthe construction ofthe No.5 BGP Battalion\nbase90(See Annexi ample referenced magelhmMyo iu l-No.5 BGP Battalion\nbase). Cumulatively,this evidence shows the deliberate destruction,razing and reappropriation\nofRohingyalandin Myo Thu Gyi,leaving its formerinhabitants permanently dispossessed and\nunable to return.\nC . Inn Din village tract -No. 6 BGP Battalion base"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0019","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"19","seq":18,"section":"III. International law","text":"Before August 2017,Inn Din(Aung Dung)village tract consisted offive villages with a\npopulation of about 7,000, the vast majority of whom were Rohingya.During the clearance\noperations, Myanmar security forces working with ethnie Rakhine civilians burned Rohingya\nhomes and expelledthe Rohingyapopulation.91 Geospatialsensors detected multiple active fires\nin Inn Din on 28 August 2017, corroborating 11MM witness accounts of mass burning.92\nGeospatial analysis shows that by 22 September 2017, nearly all of Inn Din (East, Middle,\nRakhine and West)had been destroyed - 719 out of739 structures were reduced to ash - while\nPe Yong(aIVa i 'a La government-established settlement fornon-Rohingya ethnic communities)\nremained untouched.93 Geospatialimagery shows scorched terrain, debris,and burned trees"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0020","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"20","seq":19,"section":"III. International law","text":"Following the destruction,Myanmar authorities repurposed Rohingyaland forBGP use.\nConstruction ofthe No.6 BGP Battalion base beganinlate 2017 and waslargely completed by\nAugust 2019.94 The base, covering approximately 75 hectares, was built directly over the\nPage 7 of 29\nremains of Tnn Din (East and Rakhine) villages, with cleared land replaced by new roads,\npermanent buildings, fortified compounds and two hclipads.95 Around 124 new structures and\nsemi-permanent buildings were also constructed nearby,96 consolidating the BGP's presence\nThis absorption of Rohingya land into the fortified No. 6 BGP Battalion base made permanent\nthe displacement ofRohingya from Inn Din and the erasure oftheir villages."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0021","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"21","seq":20,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Aung Scik Pyin (Donc Paik) village tract in Maungdaw township consists of four\nRohingya villages: Bo Bar(Bois Sawr),Done Paik(Dum Bai),Kyet Kyein (Saadullar Sawr),\nRee Dar and Ran Aung Pyin, and one Na Ta La government-established settlement for non-\nRohingya ethnic communities called Ran Aung Pyin.97 The Rohingya engaged in farming,98\noperated shrimp and fish hatcheries,ran shops both within the village andin the nearby Kyein\nChaung market,and pursued other business activities.They ownedland,houses and businesses\nin the area.99"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0022","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"22","seq":21,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Witness accounts and documentary evidence collected by the Mechanism demonstrate\nthat Rohingya families in Aung Seik Pyin possessed and actively used land for residential,\nagricultural and livelihood purposes prior to the 2017 clearance operations, with formally\ndocumented through government records. One witness detailed his family's inheritance and\npurchase of paddy fields and grazing land, supported by official registration documents,'Oo and\ndescribed using theland forlivestock that sustained his wife and- children,while noting that\npart ofhis residentialland waslater taken after the 2017 clearance operations for the No.7 BGP\nBattalion base.' ' Another witness similarly described extensive family landholdings inherited\nthrough both paternal and maternallines, corroborated by maps of fields and ponds, showing\nactive agricultural use.102 Together, these accounts and documents provide consistent and\ncredible evidence of longstanding Rohingya land possession, inheritance and livelihood\ndependence,underscoring their deeply rooted presencein the arca prior to August 2017."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0023","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"23","seq":22,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"IJ OSAT analysis of available geospatialimagery detected that the villages ofBo Bar,\nDone Paik and Ree Dar were fully destroyed by the Myanmar military,including by burning,on\nor around 25 August 2017.103 Prior to the clearance operations, there were approximately 400\nintact structures in Bo Bar, 364 structures in Ree Dar, and 431 structures in Done Paik.'04\nBetween 25 August and mid-October 2017, Bo Bar, Ree Dar and Done Paik villages were\ndestroyed - first by fire, with available geospatial imagery showing scorched terrain in the\ndamaged arca, as well as visible dark debris and darkened and burned trees in between the\ndamaged structures.'05 The few remaining buildings were destroyed between October 2017 and\nApril2018in a visible demolition process.106"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0024","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"24","seq":23,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"No.7 BGP Battalion base was built onland where Done Paik and Ree Darvillages once\nstood.The construction began in early 2018 and continued until 21 April 2021.'07 No.7 BGP\nBattalion base consisted of a large compound, containing warehouses and large structures,\nobservation towers, and a helipad.108\nPage 8 of 29\nE Ah LeiChaung village tract-No.8 BGP Battalion hase"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0025","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"25","seq":24,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Ah Lei Chaung village tract in Buthidaung township had two Rohingya viilages: Let\nThar (Azoii Fara) and Ah Lei Chaung (Ali Young).'09 Extensive documentary and witness\nevidence confirm that Rohingya residents of Ah LeI Chaung village tract owned, inherited and\ncuitivated land and property for generations prior to the 2017 ciearance operations.\"0 Witnesses\nprovided the Mechanism with officiai land tax eertjficates,\" township-issued documents,\"2\nand video otage, 13 identiing their agricultural piots, homes and communalresources such\nas water ponds.\"4 These records,someissued as recentiy as 2014_2015,115 show that Myanmar\nauthorities formally recognized Rohingya land possession, maintaining detaiied records of\nRohingya property prior to seizing it.Land possession was not only legal and documented but\nalso deeply tied to famiiyinheritanccn6 and community life"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0026","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"26","seq":25,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Witness accounts, photos and video footage collected after August 2017 reveal how\nRohingya farmland was seized for the construction of No. 8 BGP Battalion base in early\nDecember 2017.117 Viilagers reported being dispossessed of hundreds of acres of farmland,\"8\nwith seized areas marked by red flags.\"9 Entire famiiies were displaced when theirland, which\nprovided food, grazing space and income, was seized 120 and razed.121 Some iandhoiders\ndescribed iosing ancestral fields cultivated for three generations,122 whiie business owners\nreported being forced to sell livestock when grazing land was taken.'23 A plan signed off by\nthree separate sections of the Department of Agriculturai Land Management and Statistics\ncontains a map demarcating in red where the No. 8 BUP Battalion base wouid be buiit\naccompanied by a table delineating the iand plots set to be absorbed into the 333-acre base.'24\nThe aforementioned evidence from 2017 through 2020 confirm the construction of permanent\nsecurity infrastructure directly on confiscated Rohingya farmiand, transforming Rohingya-\nfarmed rice paddiesin Ah LeiChaung into the No.8 BGP Battalion base by January 2020.125"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0027","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"27","seq":26,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"These confiscations destroyed the Rohingya community's means of survivai, directly\ndriving displacement into Bangiadesh.'26 Viiiagers consistently expressed that once theirlands\nwere seized, they could no ionger farm, feed their families, or remain in their homes.127\nMyanmar security forces and Rakhine civiiians looted livestock 128 and beat villagers,129\ncompounding theloss ofRohingyaiivelihood.The construction ofthe No.8 BGP Battaiion base\nrendered the iand permanently inaccessibie to Rohingya,leaving survivors with no option but\nflight.'30 0ne man from Ah Lei Chaung linked the confiscation ofiand to his displacement,\nsaying \"Ourlands have been taken away, and we do not have anything to do here and wilinot\nbe able to survive here,so we wilihave to go from here.\"3'\nE 4Hiut -No.9 BGP Battalion base"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0028","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"28","seq":27,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Myin Hiut,knownin Rohingya as May Ruila,is a viilage tractinMaungdaw township,'32\nwhich had a majority Rohingya popuiation spread aiong fertiieland nearthe coast.'33 Myin Hlut\nvillage tract contained Rohingya villages and the vibrant Myin Hlut town,made up ofHpwe Yar\nquarter,A Lac Paing(Middie)quarter,Kyaung Taung quarter,A Nauk Paing(Western)quarter\nand A Shae Paing(Eastern)quarter.'34\nPage 9 of 29"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0029","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"29","seq":28,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Witness statements and official documents collected by the Mechanism demonstrate that\nRohingya residents of Myin 1-hlut possessed, cultivated and transactcd in land and property over\ngenerations prior to August 2017. Their possession extended across agricultural fields,\ncommercial shrimp hatcheries, 135 residential compounds 136 and commercial properties,137\noften secured through inheritance,138 purchase or dowry,139 and recorded in contracts with state\nrevenue stamps and land tax receipts. Witness accounts further show that this land and property\nformed the backbone of Rohingya livelihoods in Myin Hlut. Witnesses described managing\nfarmland,'4 shrimp hatcheries'4' and fishing boats, while others operated shops in the local\nmarket'42 and betel nut gardens.'43"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0030","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"30","seq":29,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"At least 30 documents collected by the Mechanism spanning from 1980 to 2016\ncorroborate these claims,showing a clear pattern oflegal land transactions and intergenerational\npossession that refutes portrayals ofRohingya as temporary or informal occupants.'44 Horonsor\n(land tax) certificates show that Rohingya regularly paid fees to local government offices,\nunderscoring the recognition ofRohingya land use by the authorities.'45 Contracts were recorded\nfor transactions where land was used to secure credit, reinforcing its value as collateral for\nloans. 146 This documentation reveals a diversified local economy rooted in land use and\nmanagement,with Rohingya property providing not only sustenance but also employment,trade,\neconomic assets and security for Rohingya in northern Rakhine State.'47"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0031","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"31","seq":30,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"This established way of life was violently disrupted during and after the August 2017\nclearance operations. Myanmar security forces, often working with ethnic Rakhine civilians,\nburned Rohingya homes,shops and schools,forcing residents to flee.'48"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0032","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"32","seq":31,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Survivors reported that entire areas were bulldozed, leaving only overgrown vegetation\nwhere once the homes, schools and businesses of thriving Rohingya communities had stood.'49\nUEHRD, a government development project, engaged a local company called Kyi Brothersl50\nto clear 418 acres of burned Rohingya land in Myin Hlut.'5'Aerial photographs taken in April\n2018 show barren areas of land marked by bulldozer tracks, machinery next to piles of timber\nand debris, and the three newly constructed buildings of No. 9 BGP Battalion base with a\npartially built perimeter wall.'52 Geospatial imagery confirms the construction ofthe No.9 BGP\nBattalion base on the site of demolished Rohingya villages by 2021. The base, spanning roughly\n85 hectares, now permanently occupies land that was once central to Rohingya life, entrenching\ntheir dispossession and preventing return.153\nG HpuKharLZin Paing Nyar village tract -No.10 BGP Battalion base"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0033","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"33","seq":32,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Zing Paing Nyar is a village tract in Maungdaw township comprised of six Rohingya\nvillages: Kywe Htar Pyin, Haw RiTu Lar, Hpu Khar Li, That Zay Kone, Zin Paing Nyar and\nDoe Tan.154"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0034","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"34","seq":33,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Witness statements collected by the Mechanism contain evidence of Rohingya land\npossession and use in the Rohingya village of Hpu Khar Liin Zin Paing Nyar village tract.'55\nMultiple generations of Rohingya families in Hpu Khar Li engaged in farming and business\nownership; one witness described how his father and uncle had 3-4 kani'56 ofpaddy land and a\nblack shrimp hatchery, all registered under his grandfather.l57 Although high transfer costs\nprevented the land from being formally re-registered in his own name, the witness described\nPage 10 of29\nhow in 2010 he updated the inheritance records through official channels, involving payments\nto the Land Management Office and approval by a police officer.'58 Another former resident and\nlandowner from Hpu Khar Li described how he lost 35 kani ofland that was absorbed into No.\n10 BGP Battalion base.159 Witnesses were consistently able to describe to the Mechanism the\nprecise location of their land in relation to the village mosque, village road and surrounding\npaddy fields."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0035","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"35","seq":34,"section":"D. AungSeiki'in PonePavillage tract -No. 7BGP Battalion base","text":"Under the UEHRD Repatriation and Resettlement project, a local company called 251h\nGroup cleared over 432 acres of Rohingya land that had been burned around 28 August 2017,160\ndeploying heavy machinery and labourers inZinPaing Nyar and adjacent village tracts.'6'Aerial\nfootage taken on 9 April 2018 shows plots of razed land marked with bulldozer tracks\ninterspersed with untouched farmland.'62 No. 10 BGP Battalion base was built over 50 kani of\nRohingya villagers'land in Zin Paing Nyar village tract.'63 Video footage taken after the No. 10\nBGP Battalion base was built shows barbed wire fences and a watch tower along a road in Hpu\nKhar Li.164"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0036","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"36","seq":35,"section":"V. Analysis of evidence","text":"Evidence collected by the Mechanism shows that Myanmar security forces and State-\ncontracted companies deliberately destroyed Rohingya cemeteries, mosques and other\ncommunallandmarks during and after the 2017 clearance operations.Witness accounts describe\nhow villages such as Myo Thu Gyi165 and Ah Lel Chaung 166 once contained mosques,\ncemeteries,schools and markets,which were systematically burned,bulldozed and demolished.\nVideo footage from December 2017 shows bulldozers actively razing mosques in Myo Thu\nGyi'67 and Ah Lei Chaung,'68 while witnesses confirmed that BGP Battaiion bases were built\non the iand on which the mosques and cemeteries once stood.'69"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0037","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"37","seq":36,"section":"V. Analysis of evidence","text":"The replacement of mosques and cemeteries with BGP Battalion bases severed the\nRohingya ancestral connection to their homeland.By paving over sacred and communaispaces,\nthe authorities obliterated materialproofofRohingya history,making future ciaims ofbeionging\norreturn more difficult.By destroying culturaland reiigious property,Myanmar security forces\nand Rakhine State authorities physically displaced Rohingya communities and disrupted their\nculturai continuityin northern Rakhine State.\nB . Myanmarauorilies knew aIRohingyapossessed and used nd andpropertj'\nRakheSlate"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0038","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"38","seq":37,"section":"V. Analysis of evidence","text":"The evidence coliected by the Mechanism establishes that Myanmar authorities had full\nknowledge of Rohingya land rights andland use in Rakhine State.Rohingya landholders held\nmultiple official documents such asland tax receipts,revenue stamps,inheritance transfers and\nusage permits,issuedby township administrations underthe GeneralAdministration Department\n(GAD) of the Ministry of Home Affairs (MOHA ). These documents covered not only\nagricultural and residentiai iand, but also specific resources such as drinking water ponds,\ndemonstrating a granular administrative record of Rohingya property. The cadastral record-\nPage 11 of 29\nkeeping of Rohingya land - registered under the Rohingya Muslim names of the landholders\nrather than adopted Burmese names-through Form 105/106 and consistent issuance ofhoronsor\nland tax certificates rther indicates the State's acknowledgment of Rohingya as taxpaying\nlandholders. Such documentation undermines any claim that Rohingya's rights to land was\ninformalorillegal; rather,it reveals a deliberate and structured system ofrecognition and control\nby Rakhine State and GAD authorities prior to the 2017 clearance operations"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0039","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"39","seq":38,"section":"V. Analysis of evidence","text":"Documentary evidence shows that the Rakhine State authorities and in particular the\nGAD kept detailed records and valuations ofproperty destroyed and damagedin prior outbreaks\nof violence.170 The BGP and Land Management Office also kept records of Rohingya'7' and\nnon-Rohingyalandholders'plots offarmland that would beimpacted by the construction ofBGP\nBattalion bases.'72 This shows Myanmar authorities' ability to register destruction and damage\nto Rohingya property, reference it against the areas on which BGP Battalion bases were built,\nand estimate its value."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0040","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"40","seq":39,"section":"V. Analysis of evidence","text":"Further, witness accounts demonstrate that Myanmar security forces regularly extorted\nRohingyalandholders to pay for the protection oftheirproperty.Witnesses reported that military\nunits threatened to burn entire Rohingya villages unless payments were made, explicitly\ntargeting homes, farmland and other property of value.'73 These extortion practices, carried out\nduring the clearance operations, not only reflect direct acknowledgment by the military of\nRohingya land tenure but also its weaponization as a tool of coercion.The recurring nature of\nsuch extortion across multiple villages indicates an organized practice within Myanmar security\nrces."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0041","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"41","seq":40,"section":"V. Analysis of evidence","text":"Evidence indicates that senior Union and Rakhine State-level officials were aware that\nthe Rohingya population possessed, cultivated and relied upon extensive agriculturalland in\nnorthern Rakhine State.It would also be obvious to all such officials that the 2017 clearance\noperations had caused such widespread flight of the Rohingya population to Bangladesh that\nthere wereinsufficient Rohingya farmers remainingin northern Rakhine to manually harvest the\n2017 crops, thereby necessitating the use of specialized machinery.174 Ellen Goldstein, then\nCountry Director ofthe World Bankin Myanmar,described discussions with the Union Minister\nofAgriculture,Livestock andIrrigation about \"the farmers who grew the grain,who are nowin\nthe refugee camps in Bangladesh\".'75 The Ministry considered proposals to harvest the crops\nusing World Bank-funded machinery,including options to return the grain orits monetary value\nto displaced Rohingyarefugees.176 The Ministry ultimately harvested 5,549 acres ofpaddy fields\nthat had become \"ownerlcss,\"77 and \"belonging to farmers who fled to Bangladesh\"78 using\nmachinery provided by the Mechanized Agriculture Department179 in U Daung,'8O Myo Thu\nGyi,181 Aung Seik Pyin,182 Myin Hlut 183 and otherlocationsin northern Rakhine State,andused\nthe proceeds for other purposes.184 Nonetheless, the engagements with the World Bank further\nconfirm direct state recognition that the lands and agricultural output in question had been\nfarmed by Rohingya,underscoring both priorlivelihood use and state knowledge ofthat fact.'85"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0042","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"42","seq":41,"section":"V. Analysis of evidence","text":"The evidence shows that Myanmar authorities were notignorant ofRohingyaland tenure\nbut intentionally leveraged that knowledge to facilitate financial extraction, destruction, and\nultimately the dispossession ofland and property belonging to the Rohingya community.\nPage 12 of 29"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0043","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"43","seq":42,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Geospatial analysis conducted by UNOSAT documents the extensive and sustained\ndestruction of Rohingya villages in northern Rakhine State during and following the 2017\nclearance operations.Between 25 August 2017 and November 2018, 411 settlements across\nMaungdaw, Buthidaung and Rathedaung townships were damaged or destroyed.186 Updated\nimagery from Fcbruary to April2019 shows continued demolition beyond November2018 until\nApril 2019.187 UNOSAT estimates approximately 40,600 structures were destroyed, though\nlikely undercounted by at least 10%.188 The shift from rapid burning to slow, deliberate razing\nunderscores the systematic and ongoing nature of the destruction.189"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0044","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"44","seq":43,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Photographs taken during visits organized by Myanmar authorities for journalists and\ndiplomatic personnel between February and April 2018 further corroborates the systematic\nerasure ofRohingya villages.'90 Ninety-five such aerialphotographs show villages razed to the\nground,leaving only barren terrain with consistent patterns of bulldozing, parallel tracks, and\nuniformlandlevelling,spanning from Ah LeiThan Kyawin the south to Taung Pyo Let Weain\nthe north of Maungdaw township191(See Annex 1.Example referencedimageiyfrom Myo\nThu Gyi - No.5 BGP Battalion base). The scale and uniformity of this clearance indicate a\ncoordinated and organized operation,aimed not only at destructionbut also at obliterating visible\nevidence of Rohingya habitation."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0045","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"45","seq":44,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Witness accounts identi muitipie actors responsibie for demolition and razing.\nWitnesses described military engineering units involved in clearing the iand in preparation for\nnew BGP Battaiion bases,192 constructing the bases,193 and assisting in the expansion of the\nMaungdaw - Ah Ngu Maw road.'94 -\nobserved engineering units from Kha Maung Seik,Sittwe,NayPyiTaw,and Meiktila bulldozing\nburned villages for police station construction.195 Private companies also participated;-\n-recounted meeting a former mid-ievei military officer serving as a project engineer for\nthe N ional Prosneritv ComDanv (3a8a8gu880GQ8 (e8o-\n`  1 `  t_IL                      I. )O  L                      L  LO  /I -\n-clearing burned villages.196 Another witness,\nconfirmed that the bulldozing was part of a State-implemented ''town reconstruction plan,\"\nrequiring high-level authorization and deliberate planning 197"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0046","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"46","seq":45,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"The Mechanism has alsoidentified atleast eightlocalprivate companies directly cngagcd\nin demolitions.These companies,including Phoe Kan Kaung,'98 Mikko,199 NationalProsperity\nCompany,20O Mayu A Hla,Moe HtiChan Thar,25th Group,Ngwe Taung Tan,and KyiBrothers\nCompany, 201 deployed heavy machinery to raze Rohingya villages under government\nauthorization and supervision.202 For example, Mayu A Hla cleared 411 acres in Maungdaw\nTownship with seven excavators and two bulldozers;203 Moe Hti Chan Thar cleared 200 acres\nin Tha Win Chaung with nine bulldozers and ten dump trucks; 204 and KyiBrothers Company\ncleared 418 acres in Myin Hlut with five bulldozers and eight excavators.205 These demolitions\nwere funded by the UEHRD Repatriation and Resettlement project and Rakhine State, and\nexempted from taxes, with progress reports documenting before-and-after images showing\nPage 13 of 29\nburned Rohingya villages razed to the ground.206 Collectively, these projects erased entire\nvillages, vegetation, and remnants of Rohingya villages.207"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0047","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"47","seq":46,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"The ubiquity and consistency ofthese operations, using bulldozers,excavators and dump\ntrucks to systematically flatten villages across northern Rakhine State, is consistent with an\norganized campaign aimed at permanently erasing Rohingya presence. 208 By transforming\npreviously inhabited villages into barren terrain, Myanmar authorities destroyed property\nmarkers critical for restitution and ensured that displaced Rohingya had no home or property to\nwhich they could return\nI`,ordinadre-approprtion destroyedRohingya villagesforBGP Battalion\nbases,roads and housingfornon-Rohingya ethnic groups"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0048","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"48","seq":47,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Following the 2017 clearance operations in northern Rakhine State and the demolition\nof burned villages, a coordinated effort involving multiple Myanmar state entities initiated\nextensive redevelopment projects that re-appropriated destroyed Rohingya villages for\ninfrastructure, BGP Battalion bases, and the settlement of non-Rohingya ethnic groups.\nLegislation was used to extinguish any claims forland and property restitution.Burnedland was\nreclassified as \"Government-managed land\" under Myanmar's Natural Disaster Management\nLaw,209 effectively stripping Rohingya ofland rights.In 2018, authorities amended the Vacant,\nFallow and Virgin Lands Management Law to impose a six-month deadline for applications to\nretain land rights - a requirement displaced Rohingya could not meet.210 Witness accounts\nconfirmed that these laws had their intended effect: destruction of villages ensured automatic\nstate repossession,21' while new legislative requirements foreclosed avenues for Rohingya to\nreturn.In so doing, the Myanmar authorities not only carried out the physical destruction of\nRohingya villages but also adopted deliberate legislative and administrative acts to terminate all\nland rights ofRohingya formerresidents"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0049","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"49","seq":48,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"The Myanmar military deployed engineering units to clearland for new BGP Battalion\nbases.212 The Rakhine State Government, under Chief Minister U Nyi Pu, advanced a \"town\nreconstruction plan\" requiring bulldozing of burned areas before redevelopment.213 The\nUEHRD Repatriation and Resettlement Project, administered through the GAD and the\nTownship Administration Office in Maungdaw, 214 contracted at least five local companies to\nclear 1,491.733 acres of Rohingya land,215 granting tax exemptions and paying a total of\n2,646,529,600 kyats from the Rakhine State budget.216"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0050","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"50","seq":49,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"The Ministry of Home Affairs (MOHA ), through Union budget allocations to the\nMyanmar Police Force (MPF) in 2017-2018 nded the construction of barracks in BUP\nBattalion bases,including the No.3 BGP Battalion basein Buthidaung township and the No.4\nBGP Battalion base in Maungdaw township, completing projects started during the 2016-2017\nfiscalyear.217 During the 2018-2019 fiscalyear,MOHA funded the construction ofbarracksin\nthe No. 5,, No. 6,, No.7 and No. 8 BGP Battalion bases.'\"18 The BGP litself,i.nncclluuddi.ng senior\ncommanders,oversawland confiscation and demolition,219 withlocalauthoritiesissuing verbal\norders and fencing off areas for new bases.22O The No.1 BGP Command Office oversaw the\nconstruction ofNo.5 and No.8 BGP Battalion bases.221 According to one witness who saw the\nPage 14 of 29\nplans for the BGP Battalion base construction project, each base was projected to cost at least\n150 to 200 million kyat and was lcd by military Garrison Engineers.222"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0051","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"51","seq":50,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Under the authorization of UEHRD and the Rakhine State government,223 Asia World\nCompany Limited spearheaded major projects, including a 50-mile road connecting Ah Ngu\nMaw to Maungdaw,224 the expansion of which required the destruction of Rohingya homes,225\nand constructed security outposts along its route.226 Documentation shows that, beginning in\nJanuary 2018, Engineer-  from Asia World Company was contracted to lead a team\nof326 workers to build No. 5 BGP Battalion base in Myo Thu Gyi village tract.227 0ne witness,\npresent in the area between late 2017 and 2018, confirmed the company's central role and that\nAsia World Company nded the project, which was carried out under the auspices of\nMOHA .228 Travelling up from Ah Ngu Maw to Maungdaw, he saw three to four newly built\npolice outposts and barracks constructed by Asia World Company, in addition to existing\ncheckpoints.229"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0052","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"52","seq":51,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"The Myanmar military exercised a degree of oversight over the construction of the BGP\nBattalion bases.         a senior commander responsible for the area\nmonitor the construction of BGP bases in Taung Pyo Let Wea, could see that the bases were\nbuilt on empty villages formerly inhabited by Rohingya, noticing that only remnants of fences\nremained after the majority of houses had been destroyed.230"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0053","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"53","seq":52,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Following the construction ofthe BOP Battalion bases,the BGP occupied and operated\nthe bases built over Rohingya villages, consolidating territorial control through dispossessing\nRohingya of theirland and property, and foreclosing the possibility of their return.The No.4\nBGP Battalion base was built directly over the former U Daung marketplace, erasing a central\nhub of Rohingya economic and sociallife where families once traded fish and vegetables.23'\nGeospatialimagery captured in 2019232 and video footage from 2020233 show that Kan Kya\nSouth villagein Myo Thu Gyiwas entirely replaced by the No.5 BGP Battalion base.Similarly,\nthe No.6 Battalion base,spanning approximately 75 hectares,was constructed over the remains\nof Inn Din village, where Rohingya land was replaced with fortified compounds, permanent\nstructures,new roads and even helipads,while atleast 124 new semi-permanent buildings were\nerected nearby to consolidate BGP presence.234 The No.7 BGP Battalion base, built between\n2018 and 2021,235 displaced the villages of Done Paik and Ree Dar,replacing them with large\ncompounds, warehouses, observation towers, fences and a helipad.236 Photographic and video\ndocumentation from 2017 through 2020 further demonstrates how the BGP transformed\nRohingya farmland in Ah LeI Chaung into the No. 8 BGP Battalion base, cementing the\ndispossession of Rohingya property.237 Aerial photographs taken in April 2018 show the\nestablishment ofthe No.9 Battalion base over the demolished Rohingya village of Myin Hlut,\nspanning roughly 85 hectares, thereby entrenching the permanent exclusion of Rohingya from\ntheir ancestrallandsin Myin Hlut.238"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0054","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"54","seq":53,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"MOHA financed and directed the expansion of police and BOP facilities; the BOP\ndirectly occupied seized Rohingya lands; and Asia World Company carried out the physical\nconstruction ofbases,roads,and security outposts that entrenched this territorial control.These\nmeasures demonstrate coordinated action by the military,Rakhine State government,UEHRD ,\nPage 15 of29\nMOHA, GAD, BGP, Asia World Company and local companies in northern Rakhine State in\nthe clearance and dispossession of Rohingya land and property."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0055","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"55","seq":54,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Tn addition to constructing infrastructure and BGP Battalion bases, Myanmar authorities\ndirected resources toward the construction of housing for non-Rohingya ethnic communities on\nseized Rohingya land.239 Between April and May 2018, hundreds of new houses nded by\nregionalgovernments and foundations were handed overto ethnic Mro and Daing Net families240\nand recent immigrants from Bangladesh.241 Senior government officials, including Union\nMinisters and the Rakhine State Chief Minister, publicly oversaw and endorsed these\nresettlement efforts, which effectively entrenched demographic changes in Maungdaw\ntownship.242 These actions indicate that the Myanmar authorities carried out demographic\nreplacementunderthe guise ofdevelopment andresettlement ,as documentedby the Mechanism\nin a report on Myanmar government efforts to encourage the resettlement of Buddhists from\nBangladeshinto Rakhine State.243"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0056","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"56","seq":55,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"The Myanmar authorities also facilitated the use of confiscated Rohingya farmland by\nnon-Rohingya ethnic communities. Reports in state media confirmed that agricultural\nmachinery, seeds and livestock inputs were distributed to resettled communities in Maungdaw\nand Buthidaung townships, including in U Daung.244 The UEHRD publicly acknowledged\nharvesting rice from fields abandoned after the displacement of Rohingya, with claims that\nproceeds were recorded and would be returned to \"rightful owners\" if they could establish\nownership.245 In practice, these measures entrenched the dispossession of the Rohingya while\nproviding tangible state support to non-Rohingya communities resettled on theirland."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0057","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"57","seq":56,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Collectively, the redevelopment, militarization and repopulation projects appear\nconsistent with a deliberate policy to erase Rohingya presence,severing their ancestralties,and\nensuring the consolidation of state and security control over formerly Rohingya villages in\nnorthern Rakhine State.\nE . Destruction evidence rough alteration ofphysicalcations"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0058","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"58","seq":57,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"On 23 January 2020, the International Court of Justice (ICJ) ordered Myanmar to take\neffective measures to preserve evidence related to alleged acts ofgenocide against the Rohingya,\nas part of its obligations under the Genocide Convention.246 The Court issued the order, in\nresponse to The Gambia's request forprovisionalmeasures that emphasized that Myanmar must\nnot destroy, alter, or render inaccessible evidence, including the remains of victims or the\nphysical locations where alleged genocidal acts occurred.247 The ICJ recognized that the\npreservation of such evidence was essential to The Gambia's right to seek Myanmar's\ncompliance withits duty to prevent and punish genocide under the Genocide Convention,which\nprohibit killing,causing serious harm,inflicting destructive conditions oflife,preventing births,\nand acts such as conspiracy,incitement,attempt or complicityin genocide.248"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0059","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"59","seq":58,"section":"C. Erasure ofRohingya villagesfollowing e 2017clearance operations was conducd","text":"Myanmar's systematic demolition and razing of Rohingya villages and construction of\nBGP Battalion bases on these sites has destroyed or permanently concealed much evidence of\nwhat occurred during the 2017 clearance operations.These actions have eliminated forensic\nevidence such as mass graves,249 burned structures,250 victims'remains and personal effects25'\nthat could demonstrate patterns of persecution,252 methods of killing,253 and the identities of\nPage 16 of29\nvictims and perpetrators. Such destruction may also eradicate ballistic,254 blast pattern and\nweapons evidence, 255 as well as documentation showing propey ownership, 256 victim\ntargeting,257 or links between military leadership and field operations.258 By fundamentally\naltering or destroying crime scenes, Myanmar authorities have obstructed the possibility of on-\nsite investigations and forensic analysis, making other forms of evidence, such as official\nrecords,geospatialand aerialimagery,crime scene photographs,environmentalspatialevidence,\nand open-source material,indispensablein the investigation of destruction and dispossession of\nRohingya homes,businesses,farms,schools and places ofworship"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0060","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"60","seq":59,"section":"VI. Reparations","text":"For the Rohingya,reparations forland and property loss are particularly significant and\nalign with precedents from international claims bodies such as the Eritrea-Ethiopia Claims\nCommission259 and the UN Compensation Commission.26O However, Rohingya victims face\nunique evidentiary barriers,including decades of systemic discrimination, restricted access to\nproperty records, forced displacement during the 2017 clearance operations, and ongoing\nconflict in Rakhine State.To address these challenges, evidence should extend beyond formal\ndocumentation to include geospatialimagery, witness testimony, and other material proof of\ndestruction and dispossession.Recognizing these barriers is critical to ensuring fair and timely\nreparations that reflect the gravity of crimes suffered.Ultimately,reparations should be victim-\ncentered, proportionate and restorative, offering tangible acknowledgment of harm while\nsupporting the Rohingya's pursuit ofjustice,dignity and connection to their homeland."},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0061","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"61","seq":60,"section":"VII. Conclusion","text":"The evidence summarized above substantiates Rohingya claims that Myanmar state\nauthorities and associated actors destroyed and dispossessed Rohingyaland and property during\nand afterthe 2017 clearance operations.The evidence collected by the Mechanism demonstrates\nthe theft of Rohingya land and property and identifies some beneficiaries of that appropriation,\nthe entities that financed the demolition of Rohingya villages, the entities and units responsible\nfor executing the demolition,and the subsequent construction ofBOP Battalion bases on former\nresidential, agricultural and ancestral sites. Myanmar authorities systematically destroyed\nRohingya villages, mosques, cemeteries and farmland.They had knowledge of Rohingya land\nrights and tenure through official records. The Myanmar military, BGP and Rakhine State\ngovernment coordinated demolitions,resettlement ofnon-Rohingya groups,and construction of\nBGP Battalion bases over seized land.Private companies and associated individuals played a\ndirect role by providing machinery andlabor to bulldoze villages and buildinfrastructure under\nstate contracts.By destroying and repurposing Rohingya farms,homes,businesses andland,the\nauthorities reinforced the effects ofthe clearance operations and forced deportations,and created\nvery seriousimpediments to the ability ofRohingya to everreconstitute the communities where\nthey had lived for generations. As noted in the jurisprudence cited above, these acts could be\nevidence of the commission of an underlying act intended to destroy the group under the\nGenocide Convention.261\nPage 17 of29"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0062","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"62","seq":61,"section":"VII. Conclusion","text":"The United Nations Human Rights Council has affirmed that Myanmar must ensure\nreparations for the victims and survivors of the past and ongoing grave human rights violations\nand atrocity crimes committed at the hands of the Myanmar military.262 The Human Rights\nCouncil emphasized that victims must be afforded \"justice,truth,reparations, and guarantees for\nnon-repetition\" as part of accountability processes, including before the International Court of\nJustice (ICJ) and International Criminal Court (C). The Human Rights Council has also\nendorsed fullimplementation ofthe recommendations ofthe Advisory Commission on Rakhine\nState including on \"reparations for appropriated land.\"263"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0063","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"63","seq":62,"section":"VII. Conclusion","text":"Reparations for the Rohingya must go beyond symbolic recognition or aspirational\npromises ofreturn.Reparations are not solely financial; they serve to acknowledge the crimes\ncommitted and affirm the humanity ofthe victims.They declare that the violations suffered were\nnot simply a tragedy,but a calculated dispossession that must be remedied"},{"id":"iimm-myanmar-unofficial-annex-29-09-2025-p0064","rec_id":"rec6LDYqJvxyoH7to","symbol":null,"n":"64","seq":63,"section":"VII. Conclusion","text":"The Mechanism has conducted comprehensive analysis of extensive documentary and\nwitness evidence and is prepared to provide a full compilation of evidence and its analytical\nfindings, including evidence regarding the roles and criminal responsibilities of certain\nindividuals not included in this public document, to competent national or international\nauthorities upon request.The Mechanism also stands ready to support reparations processes by\nproviding access to its repository of materials and documentation in line with its mandate and\nTerms of Reference.\nPage 18 of29"}]});